hero-waitlist.source:
'use client'

/**
 * <HeroWaitlist> — a pre-launch hero whose only ask is an email address.
 *
 * One field and one button, because every extra control on a waitlist form
 * is a reason to leave. The social proof sits *under* the input rather than
 * above it: it is an argument for finishing, not for starting, and it reads
 * as filler before someone has decided to type.
 *
 * The form is a real `<form>` with a real `type="email"` input, so browser
 * autofill works, the phone keyboard shows the @ key, and the enter key
 * submits. `onSubmit` receives the address; wire it to your list provider.
 * With no handler passed, it resolves locally after a beat — which is what
 * makes the preview honest without a network call.
 *
 * The success state replaces the form rather than sitting beside it, and
 * the live region announces it. A confirmation that only appears visually
 * leaves a screen-reader user staring at a form they think failed.
 */

import * as React from 'react'
import { ArrowRight, Check, Loader2 } from 'lucide-react'

export interface HeroWaitlistProps {
  heading?: string
  subheading?: string
  placeholder?: string
  submitLabel?: string
  successMessage?: string
  note?: string
  /** How many are already on the list. Omit to hide the proof row. */
  waitlistCount?: number
  /** Return a promise to keep the button in its pending state until settled. */
  onSubmit?: (email: string) => void | Promise<void>
  className?: string
}

type Status = 'idle' | 'pending' | 'done'

export function HeroWaitlist({
  heading = 'Be first through the door.',
  subheading =
    'We are letting people in a few hundred at a time. Leave your email and we will send an invite the moment a slot opens.',
  placeholder = 'you@company.com',
  submitLabel = 'Request an invite',
  successMessage = "You're on the list. Watch your inbox.",
  note = 'No spam, and one unsubscribe link in every email.',
  waitlistCount = 4128,
  onSubmit,
  className = '',
}: HeroWaitlistProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [email, setEmail] = React.useState('')
  const [status, setStatus] = React.useState<Status>('idle')

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (status !== 'idle') return

    setStatus('pending')
    try {
      // Without a handler this still resolves — the preview has to show the
      // pending and success states, and a block that only works once it is
      // wired up is a block nobody can evaluate.
      await (onSubmit?.(email) ?? new Promise((r) => setTimeout(r, 700)))
      setStatus('done')
    } catch {
      setStatus('idle')
    }
  }

  return (
    <section className={`relative overflow-hidden ${className}`}>
      <div aria-hidden className="pointer-events-none absolute inset-0 -z-10">
        <div className="absolute -top-32 left-1/2 h-96 w-96 -translate-x-1/2 rounded-full bg-primary/20 blur-3xl" />
      </div>

      <div className="mx-auto w-full max-w-2xl px-4 py-20 text-center sm:px-6 lg:py-28">
        <h1 className="text-balance text-4xl font-extrabold tracking-tight sm:text-5xl lg:text-6xl">
          {heading}
        </h1>
        <p className="mx-auto mt-5 max-w-xl text-pretty leading-relaxed text-muted-foreground sm:text-lg">
          {subheading}
        </p>

        <div className="mt-9" aria-live="polite">
          {status === 'done' ? (
            <p className="inline-flex items-center gap-2 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-5 py-3.5 text-sm font-medium text-emerald-600 dark:text-emerald-400">
              <Check aria-hidden className="h-4 w-4" />
              {successMessage}
            </p>
          ) : (
            <form onSubmit={handleSubmit} className="mx-auto flex max-w-md flex-col gap-2 sm:flex-row">
              <label htmlFor={`${uid}-waitlist-email`} className="sr-only">
                Email address
              </label>
              <input
                id={`${uid}-waitlist-email`}
                type="email"
                required
                autoComplete="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder={placeholder}
                disabled={status === 'pending'}
                className="h-12 flex-1 rounded-xl border border-border/60 bg-card/60 px-4 text-sm backdrop-blur transition-colors placeholder:text-muted-foreground focus:border-primary/50 focus:outline-none focus:ring-2 focus:ring-ring/30 disabled:opacity-60"
              />
              <button
                type="submit"
                disabled={status === 'pending'}
                className="inline-flex h-12 items-center justify-center gap-1.5 rounded-xl bg-primary px-6 text-sm font-semibold text-primary-foreground shadow-lg shadow-primary/25 transition-transform hover:-translate-y-0.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:translate-y-0 disabled:opacity-70"
              >
                {status === 'pending' ? (
                  <>
                    <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" />
                    Joining
                  </>
                ) : (
                  <>
                    {submitLabel}
                    <ArrowRight aria-hidden className="h-4 w-4" />
                  </>
                )}
              </button>
            </form>
          )}
        </div>

        {note ? <p className="mt-3 text-xs text-muted-foreground">{note}</p> : null}

        {waitlistCount ? (
          <div className="mt-8 flex items-center justify-center gap-3">
            {/* Initials, not photographs: a stock-photo avatar row is a
                claim about who your users are, and an obviously synthetic
                one is not. */}
            <div aria-hidden className="flex -space-x-2">
              {['AL', 'RS', 'MK', 'JT', 'PW'].map((initials, i) => (
                <span
                  key={initials}
                  style={{ zIndex: 5 - i }}
                  className="flex h-8 w-8 items-center justify-center rounded-full border-2 border-background bg-gradient-to-br from-primary/70 to-primary text-[10px] font-bold text-primary-foreground"
                >
                  {initials}
                </span>
              ))}
            </div>
            <p className="text-sm text-muted-foreground">
              <span className="font-semibold text-foreground">
                {waitlistCount.toLocaleString('en-US')}
              </span>{' '}
              already waiting
            </p>
          </div>
        ) : null}
      </div>
    </section>
  )
}

hero-terminal.source:
/**
 * <HeroTerminal> — a developer hero whose call to action is an install line.
 *
 * For anything a developer adopts by typing rather than by signing up: a
 * CLI, an SDK, a framework. The primary button is still there, but the
 * install command is the thing most visitors actually came for, so it gets
 * the visual weight and a copy button that works.
 *
 * The terminal is `aria-hidden` where it is decorative — the scrollback
 * lines are a drawing of a session, not a session — but the command itself
 * is not. It sits in a real `<code>` with a real button beside it, because
 * "copy the install line" is the one interaction on this page that has to
 * work with a keyboard and a screen reader.
 *
 * `navigator.clipboard` is feature-detected rather than assumed: it is
 * undefined on insecure origins, and an unguarded call throws where a
 * visitor can see it.
 */

'use client'

import * as React from 'react'
import { ArrowRight, Check, Copy, Terminal } from 'lucide-react'

export interface HeroTerminalProps {
  eyebrow?: string
  heading?: string
  subheading?: string
  /** The install line. Shown verbatim and copied verbatim. */
  command?: string
  primaryLabel?: string
  primaryHref?: string
  secondaryLabel?: string
  secondaryHref?: string
  /** Fake scrollback under the command — purely decorative. */
  output?: string[]
  className?: string
}

const DEFAULT_OUTPUT = [
  'resolving dependencies…',
  'added 3 packages in 1.2s',
  'created hoverlab.config.ts',
  'ready — run `npm run dev`',
]

export function HeroTerminal({
  eyebrow = 'v2.4 — zero-config',
  heading = 'One command. Every component.',
  subheading =
    'Install the CLI and pull any section straight into your project, typed and themed against your own tokens.',
  command = 'npx hoverlab@latest init',
  primaryLabel = 'Read the docs',
  primaryHref = '#',
  secondaryLabel = 'Browse components',
  secondaryHref = '#',
  output = DEFAULT_OUTPUT,
  className = '',
}: HeroTerminalProps) {
  const [copied, setCopied] = React.useState(false)

  // Reset the confirmation, and clear the timer if the block unmounts first.
  React.useEffect(() => {
    if (!copied) return
    const id = window.setTimeout(() => setCopied(false), 2000)
    return () => window.clearTimeout(id)
  }, [copied])

  async function copy() {
    try {
      await navigator.clipboard?.writeText(command)
      setCopied(true)
    } catch {
      // Clipboard denied or unavailable — the command is still selectable.
    }
  }

  return (
    <section className={`relative overflow-hidden ${className}`}>
      <div aria-hidden className="pointer-events-none absolute inset-0 -z-10">
        <div className="absolute left-1/2 top-0 h-72 w-[36rem] -translate-x-1/2 rounded-full bg-primary/15 blur-3xl" />
      </div>

      <div className="mx-auto w-full max-w-4xl px-4 py-20 text-center sm:px-6 lg:px-8 lg:py-28">
        {eyebrow ? (
          <span className="inline-flex items-center gap-1.5 rounded-full border border-border/60 bg-card/60 px-3 py-1 font-mono text-xs text-muted-foreground backdrop-blur">
            <Terminal aria-hidden className="h-3.5 w-3.5" />
            {eyebrow}
          </span>
        ) : null}

        <h1 className="mt-6 text-balance text-4xl font-extrabold tracking-tight sm:text-5xl lg:text-6xl">
          {heading}
        </h1>

        <p className="mx-auto mt-5 max-w-xl text-pretty text-base leading-relaxed text-muted-foreground sm:text-lg">
          {subheading}
        </p>

        {/* -- Terminal ------------------------------------------------- */}
        <div className="mx-auto mt-10 max-w-2xl overflow-hidden rounded-2xl border border-border/60 bg-card/80 text-left shadow-2xl shadow-black/20 backdrop-blur">
          <div aria-hidden className="flex items-center gap-1.5 border-b border-border/60 px-4 py-2.5">
            <span className="h-2.5 w-2.5 rounded-full bg-rose-500/70" />
            <span className="h-2.5 w-2.5 rounded-full bg-amber-500/70" />
            <span className="h-2.5 w-2.5 rounded-full bg-emerald-500/70" />
            <span className="ml-2 font-mono text-[11px] text-muted-foreground">bash</span>
          </div>

          <div className="space-y-1 bg-background/70 p-4 font-mono text-sm">
            <div className="flex items-center gap-3">
              <code className="flex-1 truncate">
                <span aria-hidden className="mr-2 select-none text-primary">
                  $
                </span>
                {command}
              </code>
              <button
                type="button"
                onClick={copy}
                className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1.5 text-xs font-medium transition-colors hover:bg-card focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
              >
                {copied ? (
                  <Check aria-hidden className="h-3.5 w-3.5 text-emerald-500" />
                ) : (
                  <Copy aria-hidden className="h-3.5 w-3.5" />
                )}
                {copied ? 'Copied' : 'Copy'}
              </button>
            </div>

            <div aria-hidden className="space-y-1 pt-2 text-xs text-muted-foreground">
              {output.map((line) => (
                <div key={line}>{line}</div>
              ))}
            </div>
          </div>
        </div>

        <div className="mt-8 flex flex-col justify-center gap-3 sm:flex-row">
          <a
            href={primaryHref}
            className="inline-flex h-12 items-center justify-center gap-1.5 rounded-xl bg-primary px-6 text-sm font-semibold text-primary-foreground shadow-lg shadow-primary/25 transition-transform hover:-translate-y-0.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          >
            {primaryLabel}
            <ArrowRight aria-hidden className="h-4 w-4" />
          </a>
          <a
            href={secondaryHref}
            className="inline-flex h-12 items-center justify-center rounded-xl border border-border/60 bg-card/60 px-6 text-sm font-semibold backdrop-blur transition-colors hover:bg-card focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          >
            {secondaryLabel}
          </a>
        </div>
      </div>
    </section>
  )
}

navbar-simple.source:
'use client'

/**
 * <NavbarSimple> — brand, links, CTAs, and a mobile menu.
 *
 * The navbar most marketing sites actually need. Everything here that looks
 * like decoration is doing a job:
 *
 *  - The mobile panel is toggled by a `<button>` carrying `aria-expanded`
 *    and `aria-controls`, not a checkbox hack. The hack is smaller but it
 *    announces as a checkbox, and "menu, checkbox, not checked" is not what
 *    a screen-reader user needs to hear.
 *  - Escape closes the panel and returns focus to the trigger. Without the
 *    return, a keyboard user who dismisses the menu is dropped at the top
 *    of the document with nothing focused.
 *  - The panel is unmounted when closed rather than hidden with `hidden` or
 *    opacity, so its links are not reachable by tab while invisible — the
 *    classic "tab into nothing" bug in every rolled-by-hand navbar.
 *  - `aria-current="page"` marks the active link. Colour alone does not
 *    survive a screen reader or a colourblind visitor.
 *
 * The bar is sticky and translucent. `backdrop-blur` over `bg-background/70`
 * keeps content legible as it scrolls under, which a solid bar does by
 * hiding it and a fully transparent one fails to do at all.
 */

import * as React from 'react'
import { Menu, X } from 'lucide-react'

export interface NavbarLink {
  label: string
  href: string
}

export interface NavbarSimpleProps {
  brand?: string
  links?: NavbarLink[]
  /** Label of the current page, matched against `links[].label`. */
  activeLabel?: string
  signInLabel?: string
  signInHref?: string
  ctaLabel?: string
  ctaHref?: string
  className?: string
}

const DEFAULT_LINKS: NavbarLink[] = [
  { label: 'Product', href: '#' },
  { label: 'Pricing', href: '#' },
  { label: 'Docs', href: '#' },
  { label: 'Blog', href: '#' },
]

export function NavbarSimple({
  brand = 'Acme',
  links = DEFAULT_LINKS,
  activeLabel = 'Product',
  signInLabel = 'Sign in',
  signInHref = '#',
  ctaLabel = 'Get started',
  ctaHref = '#',
  className = '',
}: NavbarSimpleProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [open, setOpen] = React.useState(false)
  const triggerRef = React.useRef<HTMLButtonElement>(null)

  // Escape closes and hands focus back. Bound only while open, so the
  // listener does not sit on the document for the life of the page.
  React.useEffect(() => {
    if (!open) return
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        setOpen(false)
        triggerRef.current?.focus()
      }
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [open])

  return (
    <header
      className={`sticky top-0 z-40 border-b border-border/40 bg-background/70 backdrop-blur-xl ${className}`}
    >
      <div className="mx-auto flex h-16 w-full max-w-7xl items-center justify-between gap-4 px-4 sm:px-6 lg:px-8">
        {/* Brand */}
        <a href="#" className="flex shrink-0 items-center gap-2.5">
          <span
            aria-hidden
            className="flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-primary to-emerald-600 text-sm font-black text-primary-foreground shadow-lg shadow-primary/25"
          >
            {brand.slice(0, 1)}
          </span>
          <span className="text-base font-bold tracking-tight">{brand}</span>
        </a>

        {/* Desktop links */}
        <nav aria-label="Main" className="hidden lg:block">
          <ul className="flex items-center gap-1">
            {links.map((link) => {
              const active = link.label === activeLabel
              return (
                <li key={link.label}>
                  <a
                    href={link.href}
                    aria-current={active ? 'page' : undefined}
                    className={`rounded-lg px-3 py-2 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
                      active
                        ? 'text-foreground'
                        : 'text-muted-foreground hover:bg-muted/50 hover:text-foreground'
                    }`}
                  >
                    {link.label}
                  </a>
                </li>
              )
            })}
          </ul>
        </nav>

        {/* Desktop actions */}
        <div className="hidden items-center gap-2 lg:flex">
          <a
            href={signInHref}
            className="rounded-lg px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {signInLabel}
          </a>
          <a
            href={ctaHref}
            className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground shadow-sm transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          >
            {ctaLabel}
          </a>
        </div>

        {/* Mobile trigger */}
        <button
          ref={triggerRef}
          type="button"
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          aria-controls={`${uid}-navbar-mobile-panel`}
          aria-label={open ? 'Close menu' : 'Open menu'}
          className="flex h-10 w-10 items-center justify-center rounded-lg border border-border/60 transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring lg:hidden"
        >
          {open ? (
            <X aria-hidden className="h-5 w-5" />
          ) : (
            <Menu aria-hidden className="h-5 w-5" />
          )}
        </button>
      </div>

      {/* Mobile panel */}
      {open ? (
        <div
          id={`${uid}-navbar-mobile-panel`}
          className="border-t border-border/40 bg-background/95 backdrop-blur-xl lg:hidden"
        >
          <nav aria-label="Main" className="mx-auto w-full max-w-7xl px-4 py-4 sm:px-6">
            <ul className="space-y-1">
              {links.map((link) => {
                const active = link.label === activeLabel
                return (
                  <li key={link.label}>
                    <a
                      href={link.href}
                      aria-current={active ? 'page' : undefined}
                      onClick={() => setOpen(false)}
                      className={`block rounded-lg px-3 py-2.5 text-sm font-medium transition-colors ${
                        active ? 'bg-muted text-foreground' : 'text-muted-foreground hover:bg-muted/50'
                      }`}
                    >
                      {link.label}
                    </a>
                  </li>
                )
              })}
            </ul>

            <div className="mt-4 flex flex-col gap-2 border-t border-border/60 pt-4">
              <a
                href={signInHref}
                className="rounded-lg border border-border/60 px-4 py-2.5 text-center text-sm font-semibold transition-colors hover:bg-muted"
              >
                {signInLabel}
              </a>
              <a
                href={ctaHref}
                className="rounded-lg bg-primary px-4 py-2.5 text-center text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90"
              >
                {ctaLabel}
              </a>
            </div>
          </nav>
        </div>
      ) : null}
    </header>
  )
}

navbar-mega-menu.source:
'use client'

/**
 * <NavbarMegaMenu> — a navbar whose top-level items open a full panel.
 *
 * What a mega menu is for: a site with more destinations than fit in a row,
 * where a plain dropdown of eight link labels tells a visitor nothing about
 * which one they want. The panel buys room for a description per link,
 * which is the entire justification for the pattern — a mega menu that is
 * just a wider list of labels is a dropdown with extra steps.
 *
 * The interaction is the hard part, and most hand-rolled versions get one
 * of these wrong:
 *
 *  - Opens on hover *and* on focus, so a keyboard user reaches it at all.
 *    Hover alone is the most common failure; it also strands touch users,
 *    which is why the trigger is a real button that toggles on click.
 *  - Closes on Escape, on click outside, and on focus leaving the group —
 *    tabbing past the last link in the panel closes it rather than leaving
 *    an open panel over content the user is now reading.
 *  - A close timer on pointer-leave, not an instant close. The gap between
 *    a trigger and its panel is a few pixels of nothing, and an instant
 *    close makes the menu impossible to enter diagonally.
 *  - `aria-expanded` on the trigger and `aria-hidden` never used to hide an
 *    open panel's focusable contents.
 *
 * Below `lg` the whole thing collapses to a stacked accordion, because a
 * three-column panel on a phone is a scroll trap.
 */

import * as React from 'react'
import { ChevronDown, Menu, X } from 'lucide-react'

export interface MegaMenuLink {
  label: string
  description: string
  href: string
}

export interface MegaMenuSection {
  label: string
  links: MegaMenuLink[]
  /** Optional promoted card in the panel's right rail. */
  feature?: { title: string; body: string; href: string; cta: string }
}

export interface NavbarMegaMenuProps {
  brand?: string
  sections?: MegaMenuSection[]
  /** Items with no panel, rendered as plain links. */
  plainLinks?: Array<{ label: string; href: string }>
  ctaLabel?: string
  ctaHref?: string
  className?: string
}

const DEFAULT_SECTIONS: MegaMenuSection[] = [
  {
    label: 'Product',
    links: [
      { label: 'Analytics', description: 'Events, funnels and retention', href: '#' },
      { label: 'Experiments', description: 'Ship behind a flag, measure the lift', href: '#' },
      { label: 'Sessions', description: 'Watch what the numbers cannot explain', href: '#' },
      { label: 'Alerts', description: 'Know before your customers tell you', href: '#' },
    ],
    feature: {
      title: 'What shipped in March',
      body: 'Warehouse sync, a rewritten query engine and 40% faster dashboards.',
      href: '#',
      cta: 'Read the changelog',
    },
  },
  {
    label: 'Solutions',
    links: [
      { label: 'For startups', description: 'Free until you raise a Series A', href: '#' },
      { label: 'For enterprise', description: 'SSO, audit logs and a DPA', href: '#' },
      { label: 'For agencies', description: 'One account, every client', href: '#' },
      { label: 'For e-commerce', description: 'Revenue attribution out of the box', href: '#' },
    ],
  },
]

const DEFAULT_PLAIN = [
  { label: 'Pricing', href: '#' },
  { label: 'Docs', href: '#' },
]

export function NavbarMegaMenu({
  brand = 'Acme',
  sections = DEFAULT_SECTIONS,
  plainLinks = DEFAULT_PLAIN,
  ctaLabel = 'Start free',
  ctaHref = '#',
  className = '',
}: NavbarMegaMenuProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [openLabel, setOpenLabel] = React.useState<string | null>(null)
  const [mobileOpen, setMobileOpen] = React.useState(false)
  const groupRef = React.useRef<HTMLDivElement>(null)
  const closeTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null)

  // Cancel any scheduled close — the pointer came back, or focus did.
  const cancelClose = React.useCallback(() => {
    if (closeTimer.current) {
      clearTimeout(closeTimer.current)
      closeTimer.current = null
    }
  }, [])

  // Give the pointer time to cross the gap between trigger and panel.
  const scheduleClose = React.useCallback(() => {
    cancelClose()
    closeTimer.current = setTimeout(() => setOpenLabel(null), 140)
  }, [cancelClose])

  React.useEffect(() => cancelClose, [cancelClose])

  React.useEffect(() => {
    if (!openLabel) return

    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') setOpenLabel(null)
    }
    function onPointerDown(event: PointerEvent) {
      if (!groupRef.current?.contains(event.target as Node)) setOpenLabel(null)
    }

    document.addEventListener('keydown', onKeyDown)
    document.addEventListener('pointerdown', onPointerDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      document.removeEventListener('pointerdown', onPointerDown)
    }
  }, [openLabel])

  const active = sections.find((s) => s.label === openLabel)

  return (
    <header
      className={`sticky top-0 z-40 border-b border-border/40 bg-background/70 backdrop-blur-xl ${className}`}
    >
      <div
        ref={groupRef}
        onMouseLeave={scheduleClose}
        onMouseEnter={cancelClose}
        // Focus leaving the group entirely closes the panel. `blur` bubbles
        // where `focusout` semantics are needed, and relatedTarget tells us
        // whether focus went somewhere still inside.
        onBlur={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setOpenLabel(null)
        }}
      >
        <div className="mx-auto flex h-16 w-full max-w-7xl items-center justify-between gap-4 px-4 sm:px-6 lg:px-8">
          <a href="#" className="flex shrink-0 items-center gap-2.5">
            <span
              aria-hidden
              className="flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-primary to-emerald-600 text-sm font-black text-primary-foreground shadow-lg shadow-primary/25"
            >
              {brand.slice(0, 1)}
            </span>
            <span className="text-base font-bold tracking-tight">{brand}</span>
          </a>

          <nav aria-label="Main" className="hidden lg:block">
            <ul className="flex items-center gap-1">
              {sections.map((section) => {
                const isOpen = openLabel === section.label
                return (
                  <li key={section.label}>
                    <button
                      type="button"
                      aria-expanded={isOpen}
                      onClick={() => setOpenLabel(isOpen ? null : section.label)}
                      onMouseEnter={() => {
                        cancelClose()
                        setOpenLabel(section.label)
                      }}
                      onFocus={() => setOpenLabel(section.label)}
                      className={`flex items-center gap-1 rounded-lg px-3 py-2 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
                        isOpen
                          ? 'bg-muted/60 text-foreground'
                          : 'text-muted-foreground hover:bg-muted/50 hover:text-foreground'
                      }`}
                    >
                      {section.label}
                      <ChevronDown
                        aria-hidden
                        className={`h-3.5 w-3.5 transition-transform ${isOpen ? 'rotate-180' : ''}`}
                      />
                    </button>
                  </li>
                )
              })}

              {plainLinks.map((link) => (
                <li key={link.label}>
                  <a
                    href={link.href}
                    onMouseEnter={scheduleClose}
                    className="rounded-lg px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-muted/50 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    {link.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          <div className="hidden lg:block">
            <a
              href={ctaHref}
              className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground shadow-sm transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            >
              {ctaLabel}
            </a>
          </div>

          <button
            type="button"
            onClick={() => setMobileOpen((v) => !v)}
            aria-expanded={mobileOpen}
            aria-controls={`${uid}-mega-mobile-panel`}
            aria-label={mobileOpen ? 'Close menu' : 'Open menu'}
            className="flex h-10 w-10 items-center justify-center rounded-lg border border-border/60 transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring lg:hidden"
          >
            {mobileOpen ? (
              <X aria-hidden className="h-5 w-5" />
            ) : (
              <Menu aria-hidden className="h-5 w-5" />
            )}
          </button>
        </div>

        {/* -- Desktop panel ------------------------------------------- */}
        {active ? (
          <div className="absolute inset-x-0 hidden border-b border-border/40 bg-background/95 shadow-xl shadow-black/10 backdrop-blur-xl lg:block">
            <div className="mx-auto grid w-full max-w-7xl gap-8 px-4 py-8 sm:px-6 lg:grid-cols-3 lg:px-8">
              <ul className={`grid gap-1 sm:grid-cols-2 ${active.feature ? 'lg:col-span-2' : 'lg:col-span-3'}`}>
                {active.links.map((link) => (
                  <li key={link.label}>
                    <a
                      href={link.href}
                      className="block rounded-xl p-3 transition-colors hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <span className="block text-sm font-semibold">{link.label}</span>
                      <span className="mt-0.5 block text-xs text-muted-foreground">
                        {link.description}
                      </span>
                    </a>
                  </li>
                ))}
              </ul>

              {active.feature ? (
                <div className="rounded-xl border border-border/60 bg-card/60 p-5">
                  <h3 className="text-sm font-semibold">{active.feature.title}</h3>
                  <p className="mt-2 text-xs leading-relaxed text-muted-foreground">
                    {active.feature.body}
                  </p>
                  <a
                    href={active.feature.href}
                    className="mt-4 inline-block text-xs font-semibold text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    {active.feature.cta} →
                  </a>
                </div>
              ) : null}
            </div>
          </div>
        ) : null}
      </div>

      {/* -- Mobile accordion ------------------------------------------ */}
      {mobileOpen ? (
        <div
          id={`${uid}-mega-mobile-panel`}
          className="max-h-[calc(100vh-4rem)] overflow-y-auto border-t border-border/40 bg-background/95 backdrop-blur-xl lg:hidden"
        >
          <nav aria-label="Main" className="mx-auto w-full max-w-7xl px-4 py-4 sm:px-6">
            {sections.map((section) => (
              <details key={section.label} className="border-b border-border/60 py-1">
                <summary className="flex cursor-pointer list-none items-center justify-between py-3 text-sm font-semibold [&::-webkit-details-marker]:hidden">
                  {section.label}
                  <ChevronDown aria-hidden className="h-4 w-4 text-muted-foreground" />
                </summary>
                <ul className="space-y-1 pb-3">
                  {section.links.map((link) => (
                    <li key={link.label}>
                      <a
                        href={link.href}
                        className="block rounded-lg px-3 py-2 hover:bg-muted/50"
                      >
                        <span className="block text-sm font-medium">{link.label}</span>
                        <span className="text-xs text-muted-foreground">{link.description}</span>
                      </a>
                    </li>
                  ))}
                </ul>
              </details>
            ))}

            <ul className="mt-2">
              {plainLinks.map((link) => (
                <li key={link.label} className="border-b border-border/60">
                  <a href={link.href} className="block py-3.5 text-sm font-semibold">
                    {link.label}
                  </a>
                </li>
              ))}
            </ul>

            <a
              href={ctaHref}
              className="mt-4 block rounded-lg bg-primary px-4 py-2.5 text-center text-sm font-semibold text-primary-foreground"
            >
              {ctaLabel}
            </a>
          </nav>
        </div>
      ) : null}
    </header>
  )
}

nav-mobile-drawer.source:
'use client'

/**
 * <NavMobileDrawer> — a slide-in mobile menu with a real focus trap.
 *
 * The inline panel in <NavbarSimple> is enough for four links. This is for
 * when the menu is the whole site map: it covers the page, so it has to
 * behave like a dialog rather than like a dropdown.
 *
 * That distinction is the reason this block exists separately, and it is
 * four behaviours most hand-rolled drawers are missing:
 *
 *  1. `role="dialog"` + `aria-modal`, with `aria-labelledby` pointing at the
 *     drawer's own heading. Without it, a screen reader treats the drawer as
 *     ordinary page content and keeps reading the page behind it.
 *  2. A focus trap. Tab from the last control returns to the first instead
 *     of walking into the page underneath, which is invisible and still
 *     clickable while the drawer is open.
 *  3. Focus restoration. Closing returns focus to the trigger — otherwise
 *     dismissing the menu drops a keyboard user at the top of the document.
 *  4. Body scroll lock. Without it the page scrolls under the drawer on
 *     iOS, and the visitor closes the menu to find themselves somewhere
 *     else entirely.
 *
 * The panel animates with a transform, and the transition is dropped under
 * `prefers-reduced-motion: reduce` (`motion-reduce:transition-none`) — a
 * full-screen slide is exactly the kind of movement that setting exists to
 * suppress.
 *
 * The trap deliberately queries focusables on each Tab rather than caching
 * them at open: sections are collapsible, so what is focusable changes while
 * the drawer is open, and a cached list would trap focus on a hidden link.
 */

import * as React from 'react'
import { ChevronRight, Menu, Search, X } from 'lucide-react'

export interface DrawerLink {
  label: string
  href: string
  badge?: string
}

export interface DrawerSection {
  heading: string
  links: DrawerLink[]
}

export interface NavMobileDrawerProps {
  brand?: string
  sections?: DrawerSection[]
  ctaLabel?: string
  ctaHref?: string
  signInLabel?: string
  signInHref?: string
  showSearch?: boolean
  /**
   * Render as a demo inside a larger page. Suppresses the document-level
   * half of the drawer — background scroll lock, Tab trap, Escape — which
   * belongs to a real overlay and not to a card in a preview grid.
   */
  embedded?: boolean
  className?: string
}

const DEFAULT_SECTIONS: DrawerSection[] = [
  {
    heading: 'Product',
    links: [
      { label: 'Overview', href: '#' },
      { label: 'Analytics', href: '#' },
      { label: 'Integrations', href: '#', badge: 'New' },
      { label: 'Pricing', href: '#' },
    ],
  },
  {
    heading: 'Developers',
    links: [
      { label: 'Documentation', href: '#' },
      { label: 'API reference', href: '#' },
      { label: 'Changelog', href: '#' },
      { label: 'Status', href: '#' },
    ],
  },
  {
    heading: 'Company',
    links: [
      { label: 'About', href: '#' },
      { label: 'Blog', href: '#' },
      { label: 'Careers', href: '#', badge: '3' },
    ],
  },
]

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])'

export function NavMobileDrawer({
  brand = 'Acme',
  sections = DEFAULT_SECTIONS,
  ctaLabel = 'Get started',
  ctaHref = '#',
  signInLabel = 'Sign in',
  signInHref = '#',
  showSearch = true,
  embedded = false,
  className = '',
}: NavMobileDrawerProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [open, setOpen] = React.useState(false)
  const panelRef = React.useRef<HTMLDivElement>(null)
  const triggerRef = React.useRef<HTMLButtonElement>(null)
  const closeRef = React.useRef<HTMLButtonElement>(null)

  const close = React.useCallback(() => {
    setOpen(false)
    triggerRef.current?.focus()
  }, [])

  // Focus into the panel on open, and lock the page behind it.
  React.useEffect(() => {
    if (!open || embedded) return

    closeRef.current?.focus()

    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'

    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        close()
        return
      }
      if (event.key !== 'Tab' || !panelRef.current) return

      const focusables = Array.from(
        panelRef.current.querySelectorAll<HTMLElement>(FOCUSABLE),
      ).filter((el) => el.offsetParent !== null)
      if (focusables.length === 0) return

      const first = focusables[0]
      const last = focusables[focusables.length - 1]
      const activeEl = document.activeElement

      // Wrap in both directions. Focus can also start outside the panel
      // entirely (a click on the backdrop), which the first branch catches.
      if (event.shiftKey && (activeEl === first || !panelRef.current.contains(activeEl))) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && activeEl === last) {
        event.preventDefault()
        first.focus()
      }
    }

    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      document.body.style.overflow = previousOverflow
    }
  }, [open, close, embedded])

  return (
    <header
      className={`sticky top-0 z-40 border-b border-border/40 bg-background/70 backdrop-blur-xl ${className}`}
    >
      <div className="mx-auto flex h-16 w-full max-w-7xl items-center justify-between px-4 sm:px-6 lg:px-8">
        <a href="#" className="flex items-center gap-2.5">
          <span
            aria-hidden
            className="flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-primary to-emerald-600 text-sm font-black text-primary-foreground shadow-lg shadow-primary/25"
          >
            {brand.slice(0, 1)}
          </span>
          <span className="text-base font-bold tracking-tight">{brand}</span>
        </a>

        <button
          ref={triggerRef}
          type="button"
          onClick={() => setOpen(true)}
          aria-expanded={open}
          aria-haspopup="dialog"
          className="flex h-10 items-center gap-2 rounded-lg border border-border/60 px-3 text-sm font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <Menu aria-hidden className="h-4 w-4" />
          Menu
        </button>
      </div>

      {/* Backdrop. Rendered only while open, so it can never swallow a
          click on the page underneath. */}
      {open ? (
        <div
          className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm"
          onClick={close}
          aria-hidden
        />
      ) : null}

      {/* Panel. Kept mounted so the transform can animate, but pushed
          off-screen and made inert to the tab order when closed. */}
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={`${uid}-drawer-title`}
        aria-hidden={!open}
        // `inert` keeps the closed panel out of the tab order without
        // unmounting it — the panel has to stay mounted for the transform
        // to animate, and a translated-off-screen panel is still tabbable.
        // Browsers without `inert` support still get `aria-hidden`.
        inert={!open}
        className={`fixed inset-y-0 right-0 z-50 flex w-full max-w-sm flex-col border-l border-border/60 bg-background shadow-2xl transition-transform duration-300 ease-out motion-reduce:transition-none ${
          open ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        <div className="flex h-16 shrink-0 items-center justify-between border-b border-border/60 px-4">
          <h2 id={`${uid}-drawer-title`} className="text-sm font-semibold">
            {brand} menu
          </h2>
          <button
            ref={closeRef}
            type="button"
            onClick={close}
            aria-label="Close menu"
            className="flex h-9 w-9 items-center justify-center rounded-lg transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <X aria-hidden className="h-5 w-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-4">
          {showSearch ? (
            <div className="relative mb-5">
              <Search
                aria-hidden
                className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
              />
              <label htmlFor={`${uid}-drawer-search`} className="sr-only">
                Search
              </label>
              <input
                id={`${uid}-drawer-search`}
                type="search"
                placeholder="Search…"
                className="h-10 w-full rounded-lg border border-border/60 bg-card/60 pl-9 pr-3 text-sm placeholder:text-muted-foreground focus:border-primary/50 focus:outline-none focus:ring-2 focus:ring-ring/30"
              />
            </div>
          ) : null}

          <nav aria-label="Site" className="space-y-6">
            {sections.map((section) => (
              <div key={section.heading}>
                <h3 className="px-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  {section.heading}
                </h3>
                <ul className="mt-2 space-y-0.5">
                  {section.links.map((link) => (
                    <li key={link.label}>
                      <a
                        href={link.href}
                        onClick={close}
                        className="flex items-center justify-between rounded-lg px-3 py-2.5 text-sm font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        <span className="flex items-center gap-2">
                          {link.label}
                          {link.badge ? (
                            <span className="rounded-full bg-primary/15 px-1.5 py-0.5 text-[10px] font-semibold text-primary">
                              {link.badge}
                            </span>
                          ) : null}
                        </span>
                        <ChevronRight aria-hidden className="h-4 w-4 text-muted-foreground" />
                      </a>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </nav>
        </div>

        <div className="shrink-0 space-y-2 border-t border-border/60 p-4">
          <a
            href={signInHref}
            className="block rounded-lg border border-border/60 px-4 py-2.5 text-center text-sm font-semibold transition-colors hover:bg-muted"
          >
            {signInLabel}
          </a>
          <a
            href={ctaHref}
            className="block rounded-lg bg-primary px-4 py-2.5 text-center text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90"
          >
            {ctaLabel}
          </a>
        </div>
      </div>
    </header>
  )
}

footer-minimal.source:
/**
 * <FooterMinimal> — one row: brand, a few links, socials, copyright.
 *
 * For a site with a handful of pages, where a five-column footer would be
 * mostly whitespace pretending to be structure. A small site with a big
 * footer looks padded; this looks finished.
 *
 * The whole thing is a single flex row that becomes a stack below `sm`,
 * with the copyright ordered *last* visually on mobile and first in the
 * DOM — `flex-col-reverse` handles the flip without duplicating markup or
 * reordering what a screen reader hears.
 *
 * Server component. Nothing here has state.
 */

import * as React from 'react'
import { Github, Twitter } from 'lucide-react'

export interface FooterMinimalLink {
  label: string
  href: string
}

export interface FooterMinimalProps {
  brand?: string
  links?: FooterMinimalLink[]
  socials?: Array<{ label: string; href: string; icon: 'github' | 'twitter' }>
  year?: number
  className?: string
}

const DEFAULT_LINKS: FooterMinimalLink[] = [
  { label: 'Docs', href: '#' },
  { label: 'Pricing', href: '#' },
  { label: 'Blog', href: '#' },
  { label: 'Privacy', href: '#' },
  { label: 'Terms', href: '#' },
]

const DEFAULT_SOCIALS: FooterMinimalProps['socials'] = [
  { label: 'GitHub', href: '#', icon: 'github' },
  { label: 'Twitter', href: '#', icon: 'twitter' },
]

const ICONS = { github: Github, twitter: Twitter } as const

export function FooterMinimal({
  brand = 'Acme',
  links = DEFAULT_LINKS,
  socials = DEFAULT_SOCIALS,
  year = new Date().getFullYear(),
  className = '',
}: FooterMinimalProps) {
  return (
    <footer className={`border-t border-border/60 ${className}`}>
      <div className="mx-auto flex w-full max-w-7xl flex-col-reverse items-center gap-6 px-4 py-8 sm:flex-row sm:justify-between sm:px-6 lg:px-8">
        {/* Brand + copyright */}
        <div className="flex items-center gap-2.5">
          <span
            aria-hidden
            className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-primary to-emerald-600 text-xs font-black text-primary-foreground"
          >
            {brand.slice(0, 1)}
          </span>
          <p className="text-sm text-muted-foreground">
            © {year} {brand}
          </p>
        </div>

        {/* Links */}
        <nav aria-label="Footer">
          <ul className="flex flex-wrap items-center justify-center gap-x-6 gap-y-2">
            {links.map((link) => (
              <li key={link.label}>
                <a
                  href={link.href}
                  className="text-sm text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  {link.label}
                </a>
              </li>
            ))}
          </ul>
        </nav>

        {/* Socials */}
        <div className="flex gap-1">
          {socials?.map(({ label, href, icon }) => {
            const Icon = ICONS[icon]
            return (
              <a
                key={label}
                href={href}
                aria-label={label}
                className="flex h-8 w-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <Icon aria-hidden className="h-4 w-4" />
              </a>
            )
          })}
        </div>
      </div>
    </footer>
  )
}

contact-form-split.source:
'use client'

/**
 * <ContactFormSplit> — a contact form beside the ways to not use it.
 *
 * The channel list is not decoration. A contact form is a black box: you
 * type, you press send, and you have no idea whether anyone will read it.
 * Putting a real email address, a support link and a response-time promise
 * next to the form is what makes the form credible, and it lets the people
 * who would rather not use it leave without bouncing.
 *
 * Form details that matter more than the layout:
 *
 *  - Every input has a real `<label>`, not a placeholder standing in for
 *    one. Placeholder-as-label vanishes the moment someone types, which is
 *    exactly when they need to check what the field was.
 *  - `autoComplete` tokens are set (`name`, `email`, `organization`), so
 *    the browser can fill three of the five fields.
 *  - The submit button keeps its accessible name while pending — the
 *    spinner is `aria-hidden`, so the word beside it is what a screen
 *    reader announces.
 *  - The result is a live region, and it replaces the form rather than
 *    appearing above it, so nobody submits twice.
 *
 * `onSubmit` receives the form values. With no handler the preview
 * resolves locally after a beat, so the pending and success states are
 * demonstrable without a backend.
 */

import * as React from 'react'
import { Check, Loader2, Mail, MapPin, MessageSquare } from 'lucide-react'

export interface ContactValues {
  name: string
  email: string
  company: string
  subject: string
  message: string
}

export interface ContactChannel {
  icon: 'mail' | 'chat' | 'map'
  label: string
  value: string
  href?: string
}

export interface ContactFormSplitProps {
  heading?: string
  subheading?: string
  channels?: ContactChannel[]
  responseNote?: string
  submitLabel?: string
  successMessage?: string
  onSubmit?: (values: ContactValues) => void | Promise<void>
  className?: string
}

const ICONS = { mail: Mail, chat: MessageSquare, map: MapPin } as const

const DEFAULT_CHANNELS: ContactChannel[] = [
  { icon: 'mail', label: 'Email', value: 'hello@acme.com', href: 'mailto:hello@acme.com' },
  { icon: 'chat', label: 'Support', value: 'Open a ticket', href: '#' },
  { icon: 'map', label: 'Office', value: '4 Bridge Street, Bristol' },
]

const EMPTY: ContactValues = { name: '', email: '', company: '', subject: '', message: '' }

type Status = 'idle' | 'pending' | 'done'

export function ContactFormSplit({
  heading = 'Tell us what you need.',
  subheading =
    'Sales questions, support, partnerships — one form, and it reaches a person rather than a queue.',
  channels = DEFAULT_CHANNELS,
  responseNote = 'We reply to everything within one business day.',
  submitLabel = 'Send message',
  successMessage = 'Thanks — your message is in. We will reply by email.',
  onSubmit,
  className = '',
}: ContactFormSplitProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [values, setValues] = React.useState<ContactValues>(EMPTY)
  const [status, setStatus] = React.useState<Status>('idle')

  function set<K extends keyof ContactValues>(key: K, value: ContactValues[K]) {
    setValues((v) => ({ ...v, [key]: value }))
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (status !== 'idle') return
    setStatus('pending')
    try {
      await (onSubmit?.(values) ?? new Promise((r) => setTimeout(r, 800)))
      setStatus('done')
    } catch {
      setStatus('idle')
    }
  }

  return (
    <section className={`mx-auto w-full max-w-7xl px-4 py-16 sm:px-6 lg:px-8 ${className}`}>
      <div className="grid gap-12 lg:grid-cols-5 lg:gap-16">
        {/* -- Copy + channels ----------------------------------------- */}
        <div className="lg:col-span-2">
          <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
            {heading}
          </h2>
          <p className="mt-4 text-pretty leading-relaxed text-muted-foreground">{subheading}</p>

          <ul className="mt-8 space-y-4">
            {channels.map((channel) => {
              const Icon = ICONS[channel.icon]
              return (
                <li key={channel.label} className="flex items-start gap-3">
                  <span className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-border/60 bg-card/60 text-muted-foreground">
                    <Icon aria-hidden className="h-4 w-4" />
                  </span>
                  <span className="min-w-0">
                    <span className="block text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      {channel.label}
                    </span>
                    {channel.href ? (
                      <a
                        href={channel.href}
                        className="text-sm font-semibold hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        {channel.value}
                      </a>
                    ) : (
                      <span className="text-sm font-semibold">{channel.value}</span>
                    )}
                  </span>
                </li>
              )
            })}
          </ul>

          {responseNote ? (
            <p className="mt-8 rounded-xl border border-border/60 bg-card/40 p-4 text-sm text-muted-foreground">
              {responseNote}
            </p>
          ) : null}
        </div>

        {/* -- Form ----------------------------------------------------- */}
        <div className="lg:col-span-3" aria-live="polite">
          {status === 'done' ? (
            <div className="flex h-full min-h-64 flex-col items-center justify-center rounded-2xl border border-emerald-500/30 bg-emerald-500/5 p-10 text-center">
              <span className="flex h-12 w-12 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
                <Check aria-hidden className="h-6 w-6" />
              </span>
              <p className="mt-4 font-semibold">{successMessage}</p>
            </div>
          ) : (
            <form
              onSubmit={handleSubmit}
              className="rounded-2xl border border-border/60 bg-card/40 p-6 sm:p-8"
            >
              <div className="grid gap-4 sm:grid-cols-2">
                <Field
                  id={`${uid}-contact-name`}
                  label="Name"
                  autoComplete="name"
                  required
                  value={values.name}
                  onChange={(v) => set('name', v)}
                />
                <Field
                  id={`${uid}-contact-email`}
                  label="Work email"
                  type="email"
                  autoComplete="email"
                  required
                  value={values.email}
                  onChange={(v) => set('email', v)}
                />
                <Field
                  id={`${uid}-contact-company`}
                  label="Company"
                  autoComplete="organization"
                  value={values.company}
                  onChange={(v) => set('company', v)}
                />
                <Field
                  id={`${uid}-contact-subject`}
                  label="Subject"
                  required
                  value={values.subject}
                  onChange={(v) => set('subject', v)}
                />
              </div>

              <div className="mt-4">
                <label htmlFor={`${uid}-contact-message`} className="block text-sm font-medium">
                  Message
                </label>
                <textarea
                  id={`${uid}-contact-message`}
                  required
                  rows={5}
                  value={values.message}
                  onChange={(e) => set('message', e.target.value)}
                  className="mt-1.5 w-full resize-y rounded-xl border border-border/60 bg-background/60 px-3 py-2.5 text-sm placeholder:text-muted-foreground focus:border-primary/50 focus:outline-none focus:ring-2 focus:ring-ring/30"
                  placeholder="What are you trying to do?"
                />
              </div>

              <button
                type="submit"
                disabled={status === 'pending'}
                className="mt-5 inline-flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-primary px-6 text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:opacity-70 sm:w-auto"
              >
                {status === 'pending' ? (
                  <>
                    <Loader2
                      aria-hidden
                      className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]"
                    />
                    Sending
                  </>
                ) : (
                  submitLabel
                )}
              </button>
            </form>
          )}
        </div>
      </div>
    </section>
  )
}

/** A labelled text input. Extracted only because it repeats four times. */
function Field({
  id,
  label,
  value,
  onChange,
  type = 'text',
  required = false,
  autoComplete,
}: {
  id: string
  label: string
  value: string
  onChange: (value: string) => void
  type?: string
  required?: boolean
  autoComplete?: string
}) {
  return (
    <div>
      <label htmlFor={id} className="block text-sm font-medium">
        {label}
        {required ? null : (
          <span className="ml-1 text-xs font-normal text-muted-foreground">(optional)</span>
        )}
      </label>
      <input
        id={id}
        type={type}
        required={required}
        autoComplete={autoComplete}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="mt-1.5 h-11 w-full rounded-xl border border-border/60 bg-background/60 px-3 text-sm placeholder:text-muted-foreground focus:border-primary/50 focus:outline-none focus:ring-2 focus:ring-ring/30"
      />
    </div>
  )
}

multi-step-form.source:
'use client'

/**
 * <MultiStepForm> — a three-step form with a stepper and per-step validation.
 *
 * The pattern exists to make a long form feel finishable. What makes it
 * work is that each step is genuinely complete on its own: you can answer
 * everything visible, and "Continue" is refused only for a field you can
 * currently see. A wizard that fails on step 1 because of something on
 * step 3 is worse than one long page.
 *
 * The accessibility of a stepper is almost always wrong, so:
 *
 *  - The stepper is an ordered list, not a row of divs. Position in a
 *    sequence is the entire meaning, and `<ol>` is what conveys it.
 *  - The current step carries `aria-current="step"`.
 *  - Completed steps say so in text (`sr-only` "completed"), because a
 *    green tick is colour and shape only.
 *  - Errors use `aria-invalid` plus `aria-describedby` pointing at the
 *    message, so the message is read *with* the field rather than being
 *    a red sentence floating nearby.
 *  - Advancing moves focus to the new step's heading, which is what tells
 *    a screen reader anything happened at all. Without it the user presses
 *    Continue and hears silence.
 *
 * Validation is deliberately trivial (required, and an `@` in the email) —
 * this is a layout and a flow, not a schema library. Swap `validateStep`
 * for Zod or your own rules; nothing else needs to change.
 */

import * as React from 'react'
import { Check, ChevronLeft, ChevronRight } from 'lucide-react'

export interface MultiStepValues {
  name: string
  email: string
  company: string
  teamSize: string
  useCase: string
  referral: string
}

export interface MultiStepFormProps {
  heading?: string
  steps?: string[]
  submitLabel?: string
  successMessage?: string
  onSubmit?: (values: MultiStepValues) => void | Promise<void>
  className?: string
}

const DEFAULT_STEPS = ['Your details', 'Your team', 'Finish']

const EMPTY: MultiStepValues = {
  name: '',
  email: '',
  company: '',
  teamSize: '1–10',
  useCase: '',
  referral: '',
}

type Errors = Partial<Record<keyof MultiStepValues, string>>

/** Which fields each step owns — the reason a step can validate itself. */
const FIELDS_BY_STEP: Array<Array<keyof MultiStepValues>> = [
  ['name', 'email'],
  ['company', 'teamSize'],
  ['useCase'],
]

function validateStep(step: number, values: MultiStepValues): Errors {
  const errors: Errors = {}
  for (const field of FIELDS_BY_STEP[step] ?? []) {
    const value = values[field].trim()
    if (!value) {
      errors[field] = 'This field is required.'
    } else if (field === 'email' && !value.includes('@')) {
      errors[field] = 'Enter a valid email address.'
    }
  }
  return errors
}

export function MultiStepForm({
  heading = 'Set up your workspace',
  steps = DEFAULT_STEPS,
  submitLabel = 'Create workspace',
  successMessage = 'Workspace created. Check your email for the invite link.',
  onSubmit,
  className = '',
}: MultiStepFormProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [step, setStep] = React.useState(0)
  const [values, setValues] = React.useState<MultiStepValues>(EMPTY)
  const [errors, setErrors] = React.useState<Errors>({})
  const [done, setDone] = React.useState(false)
  const headingRef = React.useRef<HTMLHeadingElement>(null)

  function set<K extends keyof MultiStepValues>(key: K, value: MultiStepValues[K]) {
    setValues((v) => ({ ...v, [key]: value }))
    setErrors((e) => ({ ...e, [key]: undefined }))
  }

  // Move focus to the step heading after advancing. Without this the DOM
  // changes and a screen reader says nothing.
  React.useEffect(() => {
    if (step > 0) headingRef.current?.focus()
  }, [step])

  function next() {
    const found = validateStep(step, values)
    if (Object.keys(found).length > 0) {
      setErrors(found)
      return
    }
    setStep((s) => Math.min(s + 1, steps.length - 1))
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const found = validateStep(step, values)
    if (Object.keys(found).length > 0) {
      setErrors(found)
      return
    }
    await (onSubmit?.(values) ?? Promise.resolve())
    setDone(true)
  }

  if (done) {
    return (
      <section className={`mx-auto w-full max-w-2xl px-4 py-16 sm:px-6 ${className}`}>
        <div className="flex flex-col items-center rounded-2xl border border-emerald-500/30 bg-emerald-500/5 p-12 text-center">
          <span className="flex h-12 w-12 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
            <Check aria-hidden className="h-6 w-6" />
          </span>
          <p className="mt-4 font-semibold">{successMessage}</p>
        </div>
      </section>
    )
  }

  const isLast = step === steps.length - 1

  return (
    <section className={`mx-auto w-full max-w-2xl px-4 py-16 sm:px-6 ${className}`}>
      <h2 className="text-center text-2xl font-bold tracking-tight sm:text-3xl">{heading}</h2>

      {/* -- Stepper --------------------------------------------------- */}
      <ol className="mt-8 flex items-center gap-2">
        {steps.map((label, i) => {
          const state = i < step ? 'complete' : i === step ? 'current' : 'upcoming'
          return (
            <li key={label} className="flex flex-1 items-center gap-2">
              <span
                aria-current={state === 'current' ? 'step' : undefined}
                className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full border text-xs font-bold ${
                  state === 'complete'
                    ? 'border-primary bg-primary text-primary-foreground'
                    : state === 'current'
                      ? 'border-primary text-primary'
                      : 'border-border/60 text-muted-foreground'
                }`}
              >
                {state === 'complete' ? <Check aria-hidden className="h-4 w-4" /> : i + 1}
                {state === 'complete' ? <span className="sr-only">completed</span> : null}
              </span>
              <span
                className={`hidden text-xs font-medium sm:block ${
                  state === 'upcoming' ? 'text-muted-foreground' : 'text-foreground'
                }`}
              >
                {label}
              </span>
              {i < steps.length - 1 ? (
                <span
                  aria-hidden
                  className={`h-px flex-1 ${i < step ? 'bg-primary' : 'bg-border'}`}
                />
              ) : null}
            </li>
          )
        })}
      </ol>

      <form
        onSubmit={handleSubmit}
        className="mt-8 rounded-2xl border border-border/60 bg-card/40 p-6 sm:p-8"
      >
        <h3
          ref={headingRef}
          tabIndex={-1}
          className="text-lg font-semibold outline-none"
        >
          {steps[step]}
        </h3>

        <div className="mt-5 space-y-4">
          {step === 0 ? (
            <>
              <TextField
                id={`${uid}-ms-name`}
                label="Full name"
                autoComplete="name"
                value={values.name}
                error={errors.name}
                onChange={(v) => set('name', v)}
              />
              <TextField
                id={`${uid}-ms-email`}
                label="Work email"
                type="email"
                autoComplete="email"
                value={values.email}
                error={errors.email}
                onChange={(v) => set('email', v)}
              />
            </>
          ) : null}

          {step === 1 ? (
            <>
              <TextField
                id={`${uid}-ms-company`}
                label="Company"
                autoComplete="organization"
                value={values.company}
                error={errors.company}
                onChange={(v) => set('company', v)}
              />
              <div>
                <label htmlFor={`${uid}-ms-size`} className="block text-sm font-medium">
                  Team size
                </label>
                <select
                  id={`${uid}-ms-size`}
                  value={values.teamSize}
                  onChange={(e) => set('teamSize', e.target.value)}
                  className="mt-1.5 h-11 w-full rounded-xl border border-border/60 bg-background/60 px-3 text-sm focus:border-primary/50 focus:outline-none focus:ring-2 focus:ring-ring/30"
                >
                  {['1–10', '11–50', '51–200', '200+'].map((size) => (
                    <option key={size}>{size}</option>
                  ))}
                </select>
              </div>
            </>
          ) : null}

          {step === 2 ? (
            <>
              <div>
                <label htmlFor={`${uid}-ms-usecase`} className="block text-sm font-medium">
                  What will you use this for?
                </label>
                <textarea
                  id={`${uid}-ms-usecase`}
                  rows={4}
                  value={values.useCase}
                  aria-invalid={errors.useCase ? true : undefined}
                  aria-describedby={errors.useCase ? 'ms-usecase-error' : undefined}
                  onChange={(e) => set('useCase', e.target.value)}
                  className={`mt-1.5 w-full resize-y rounded-xl border bg-background/60 px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-ring/30 ${
                    errors.useCase ? 'border-destructive' : 'border-border/60 focus:border-primary/50'
                  }`}
                />
                {errors.useCase ? (
                  <p id={`${uid}-ms-usecase-error`} className="mt-1.5 text-xs text-destructive">
                    {errors.useCase}
                  </p>
                ) : null}
              </div>
              <TextField
                id={`${uid}-ms-referral`}
                label="How did you hear about us?"
                optional
                value={values.referral}
                onChange={(v) => set('referral', v)}
              />
            </>
          ) : null}
        </div>

        <div className="mt-7 flex items-center justify-between gap-3">
          <button
            type="button"
            onClick={() => setStep((s) => Math.max(0, s - 1))}
            disabled={step === 0}
            className="inline-flex h-11 items-center gap-1 rounded-xl border border-border/60 px-4 text-sm font-semibold transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40"
          >
            <ChevronLeft aria-hidden className="h-4 w-4" />
            Back
          </button>

          {isLast ? (
            <button
              type="submit"
              className="inline-flex h-11 items-center rounded-xl bg-primary px-6 text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            >
              {submitLabel}
            </button>
          ) : (
            <button
              type="button"
              onClick={next}
              className="inline-flex h-11 items-center gap-1 rounded-xl bg-primary px-6 text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            >
              Continue
              <ChevronRight aria-hidden className="h-4 w-4" />
            </button>
          )}
        </div>
      </form>
    </section>
  )
}

/** Text input wired to an error message via aria-describedby. */
function TextField({
  id,
  label,
  value,
  onChange,
  error,
  type = 'text',
  autoComplete,
  optional = false,
}: {
  id: string
  label: string
  value: string
  onChange: (value: string) => void
  error?: string
  type?: string
  autoComplete?: string
  optional?: boolean
}) {
  const errorId = `${id}-error`
  return (
    <div>
      <label htmlFor={id} className="block text-sm font-medium">
        {label}
        {optional ? (
          <span className="ml-1 text-xs font-normal text-muted-foreground">(optional)</span>
        ) : null}
      </label>
      <input
        id={id}
        type={type}
        autoComplete={autoComplete}
        value={value}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
        onChange={(e) => onChange(e.target.value)}
        className={`mt-1.5 h-11 w-full rounded-xl border bg-background/60 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring/30 ${
          error ? 'border-destructive' : 'border-border/60 focus:border-primary/50'
        }`}
      />
      {error ? (
        <p id={errorId} className="mt-1.5 text-xs text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  )
}

confirm-dialog.source:
'use client'

/**
 * <ConfirmDialog> — the "are you sure" for something you cannot undo.
 *
 * Built on the native `<dialog>` element and `showModal()`, which is the
 * reason this is short. The browser gives you, for free, the four things a
 * hand-rolled modal spends a hundred lines getting wrong: a focus trap, the
 * top layer (so no `z-index` can cover it), inertness of the page behind,
 * and Escape-to-close.
 *
 * What is left to do by hand, and is done here:
 *
 *  - `aria-labelledby` / `aria-describedby` on the dialog, so it announces
 *    as its title and body rather than as an unlabelled group.
 *  - Escape is intercepted while a destructive action is in flight. The
 *    browser's default cancel would close the dialog mid-request and leave
 *    the user unsure whether the delete happened.
 *  - A backdrop click closes it — native `<dialog>` does not do this. The
 *    check is on the event target being the dialog itself, which works
 *    because the backdrop's clicks are reported against the dialog element
 *    while the content sits in a child.
 *  - Focus is placed on Cancel, not Delete. The safe option is the default
 *    for the same reason a "Save changes?" prompt does not focus Discard.
 *
 * Destructive styling is `bg-destructive`, and the word is the verb —
 * "Delete project", not "OK". A confirm dialog whose buttons say OK and
 * Cancel makes the reader re-read the sentence to work out which is which.
 */

import * as React from 'react'
import { AlertTriangle, Loader2 } from 'lucide-react'

export interface ConfirmDialogProps {
  triggerLabel?: string
  title?: string
  description?: string
  /** The verb, repeated on the button. Never "OK". */
  confirmLabel?: string
  cancelLabel?: string
  /** Type-to-confirm guard. When set, the button unlocks only on an exact match. */
  confirmPhrase?: string
  onConfirm?: () => void | Promise<void>
  className?: string
}

export function ConfirmDialog({
  triggerLabel = 'Delete project',
  title = 'Delete this project?',
  description =
    'This removes the project, its deployments and its logs. Team members lose access immediately. This cannot be undone.',
  confirmLabel = 'Delete project',
  cancelLabel = 'Cancel',
  confirmPhrase = 'acme-web',
  onConfirm,
  className = '',
}: ConfirmDialogProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const dialogRef = React.useRef<HTMLDialogElement>(null)
  const cancelRef = React.useRef<HTMLButtonElement>(null)
  const [typed, setTyped] = React.useState('')
  const [busy, setBusy] = React.useState(false)

  const unlocked = !confirmPhrase || typed === confirmPhrase

  function open() {
    setTyped('')
    dialogRef.current?.showModal()
    // Focus the safe action, not the destructive one.
    requestAnimationFrame(() => cancelRef.current?.focus())
  }

  function close() {
    if (busy) return
    dialogRef.current?.close()
  }

  async function confirm() {
    if (!unlocked || busy) return
    setBusy(true)
    try {
      await (onConfirm?.() ?? new Promise((r) => setTimeout(r, 900)))
      dialogRef.current?.close()
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className={`flex justify-center p-10 ${className}`}>
      <button
        type="button"
        onClick={open}
        className="inline-flex h-11 items-center rounded-xl bg-destructive px-5 text-sm font-semibold text-destructive-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
      >
        {triggerLabel}
      </button>

      <dialog
        ref={dialogRef}
        aria-labelledby={`${uid}-confirm-title`}
        aria-describedby={`${uid}-confirm-description`}
        // The browser fires `cancel` for Escape. Blocking it while a
        // request is in flight keeps the dialog up until the outcome is
        // known, rather than leaving the user guessing.
        onCancel={(e) => {
          if (busy) e.preventDefault()
        }}
        // Native <dialog> reports backdrop clicks against the dialog itself;
        // clicks on the content hit a child, so this only fires outside.
        onClick={(e) => {
          if (e.target === dialogRef.current) close()
        }}
        className="max-w-md rounded-2xl border border-border/60 bg-background p-0 text-foreground shadow-2xl backdrop:bg-black/50 backdrop:backdrop-blur-sm"
      >
        <div className="p-6">
          <div className="flex gap-4">
            <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-destructive/10 text-destructive">
              <AlertTriangle aria-hidden className="h-5 w-5" />
            </span>
            <div className="min-w-0">
              <h2 id={`${uid}-confirm-title`} className="text-base font-semibold">
                {title}
              </h2>
              <p id={`${uid}-confirm-description`} className="mt-2 text-sm leading-relaxed text-muted-foreground">
                {description}
              </p>
            </div>
          </div>

          {confirmPhrase ? (
            <div className="mt-5">
              <label htmlFor={`${uid}-confirm-phrase`} className="block text-sm text-muted-foreground">
                Type <span className="font-mono font-semibold text-foreground">{confirmPhrase}</span>{' '}
                to confirm
              </label>
              <input
                id={`${uid}-confirm-phrase`}
                value={typed}
                onChange={(e) => setTyped(e.target.value)}
                autoComplete="off"
                className="mt-1.5 h-10 w-full rounded-lg border border-border/60 bg-card/60 px-3 font-mono text-sm focus:border-destructive/50 focus:outline-none focus:ring-2 focus:ring-destructive/20"
              />
            </div>
          ) : null}

          <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
            <button
              ref={cancelRef}
              type="button"
              onClick={close}
              disabled={busy}
              className="inline-flex h-10 items-center justify-center rounded-lg border border-border/60 px-4 text-sm font-semibold transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50"
            >
              {cancelLabel}
            </button>
            <button
              type="button"
              onClick={confirm}
              disabled={!unlocked || busy}
              className="inline-flex h-10 items-center justify-center gap-2 rounded-lg bg-destructive px-4 text-sm font-semibold text-destructive-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50"
            >
              {busy ? (
                <>
                  <Loader2
                    aria-hidden
                    className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]"
                  />
                  Deleting
                </>
              ) : (
                confirmLabel
              )}
            </button>
          </div>
        </div>
      </dialog>
    </div>
  )
}

slide-over-panel.source:
'use client'

/**
 * <SlideOverPanel> — a side sheet for editing a record without leaving the list.
 *
 * The reason to reach for one over a route: the context behind it is the
 * point. Editing a row in a table is much easier when the table is still
 * visible, and a full-page form loses that.
 *
 * Also built on native `<dialog>` + `showModal()`, so the focus trap, top
 * layer, page inertness and Escape all come from the browser rather than
 * from an effect hook. What that leaves is the animation, which is the one
 * thing `<dialog>` makes awkward:
 *
 *   A modal dialog is `display: none` when closed, and you cannot transition
 *   out of `display: none`. So the open state is driven by a data attribute
 *   set one frame after `showModal()`, and closing waits for `transitionend`
 *   before calling `close()`. `@starting-style` would remove the first half
 *   of that, but it is too new to rely on in copied code.
 *
 * The slide is gated behind `motion-safe:` — a full-height panel flying in
 * from the edge is exactly the movement `prefers-reduced-motion` is for, and
 * under `reduce` it simply appears.
 *
 * The footer is `sticky` inside a scrolling body, so Save never scrolls out
 * of reach on a long form — the single most common complaint about sheets.
 */

import * as React from 'react'
import { X } from 'lucide-react'

export interface SlideOverPanelProps {
  triggerLabel?: string
  title?: string
  description?: string
  saveLabel?: string
  cancelLabel?: string
  /** Panel content. Defaults to a small example form. */
  children?: React.ReactNode
  onSave?: () => void | Promise<void>
  className?: string
}

export function SlideOverPanel({
  triggerLabel = 'Edit customer',
  title = 'Edit customer',
  description = 'Changes apply immediately and are visible to everyone on the team.',
  saveLabel = 'Save changes',
  cancelLabel = 'Cancel',
  children,
  onSave,
  className = '',
}: SlideOverPanelProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const dialogRef = React.useRef<HTMLDialogElement>(null)
  const panelRef = React.useRef<HTMLDivElement>(null)
  const [shown, setShown] = React.useState(false)

  function open() {
    dialogRef.current?.showModal()
    // One frame later, so the transition has a start value to move from.
    requestAnimationFrame(() => setShown(true))
  }

  const close = React.useCallback(() => {
    const panel = panelRef.current
    setShown(false)

    // If motion is reduced there is no transition to wait for, and
    // `transitionend` would never fire — close immediately instead of
    // leaving an invisible modal trapping focus.
    const reduced =
      typeof window !== 'undefined' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches

    if (!panel || reduced) {
      dialogRef.current?.close()
      return
    }

    panel.addEventListener('transitionend', () => dialogRef.current?.close(), { once: true })
  }, [])

  async function save() {
    await (onSave?.() ?? Promise.resolve())
    close()
  }

  return (
    <div className={`flex justify-center p-10 ${className}`}>
      <button
        type="button"
        onClick={open}
        className="inline-flex h-11 items-center rounded-xl border border-border/60 bg-card/60 px-5 text-sm font-semibold transition-colors hover:bg-card focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        {triggerLabel}
      </button>

      <dialog
        ref={dialogRef}
        aria-labelledby={`${uid}-slideover-title`}
        aria-describedby={`${uid}-slideover-description`}
        onCancel={(e) => {
          // Take over Escape so it runs the same exit transition as the
          // buttons rather than snapping shut.
          e.preventDefault()
          close()
        }}
        onClick={(e) => {
          if (e.target === dialogRef.current) close()
        }}
        // The dialog itself is the full-screen surface; the panel inside is
        // what slides. `ml-auto` pins it to the right edge.
        className="m-0 h-full max-h-full w-full max-w-full bg-transparent p-0 text-foreground backdrop:bg-black/50 backdrop:backdrop-blur-sm"
      >
        <div
          ref={panelRef}
          data-shown={shown ? '' : undefined}
          className="ml-auto flex h-full w-full max-w-md flex-col border-l border-border/60 bg-background shadow-2xl motion-safe:translate-x-full motion-safe:transition-transform motion-safe:duration-300 motion-safe:ease-out motion-safe:data-shown:translate-x-0"
        >
          <div className="flex shrink-0 items-start justify-between gap-4 border-b border-border/60 p-5">
            <div className="min-w-0">
              <h2 id={`${uid}-slideover-title`} className="text-base font-semibold">
                {title}
              </h2>
              <p id={`${uid}-slideover-description`} className="mt-1 text-sm text-muted-foreground">
                {description}
              </p>
            </div>
            <button
              type="button"
              onClick={close}
              aria-label="Close panel"
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <X aria-hidden className="h-5 w-5" />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-5">{children ?? <ExampleFields />}</div>

          {/* Sticky, so Save is reachable without scrolling a long form. */}
          <div className="sticky bottom-0 flex shrink-0 justify-end gap-2 border-t border-border/60 bg-background/95 p-5 backdrop-blur">
            <button
              type="button"
              onClick={close}
              className="inline-flex h-10 items-center rounded-lg border border-border/60 px-4 text-sm font-semibold transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {cancelLabel}
            </button>
            <button
              type="button"
              onClick={save}
              className="inline-flex h-10 items-center rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {saveLabel}
            </button>
          </div>
        </div>
      </dialog>
    </div>
  )
}

/** Placeholder body — replace with your own form. */
function ExampleFields() {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  return (
    <div className="space-y-4">
      {[
        { id: 'so-name', label: 'Name', value: 'Ada Lovelace', type: 'text' },
        { id: 'so-email', label: 'Email', value: 'ada@acme.com', type: 'email' },
        { id: 'so-company', label: 'Company', value: 'Acme Inc', type: 'text' },
      ].map((field) => (
        <div key={field.id}>
          <label htmlFor={`${uid}-${field.id}`} className="block text-sm font-medium">
            {field.label}
          </label>
          <input
            id={`${uid}-${field.id}`}
            type={field.type}
            defaultValue={field.value}
            className="mt-1.5 h-11 w-full rounded-xl border border-border/60 bg-card/60 px-3 text-sm focus:border-primary/50 focus:outline-none focus:ring-2 focus:ring-ring/30"
          />
        </div>
      ))}

      <div>
        <label htmlFor={`${uid}-so-notes`} className="block text-sm font-medium">
          Notes
        </label>
        <textarea
          id={`${uid}-so-notes`}
          rows={5}
          className="mt-1.5 w-full resize-y rounded-xl border border-border/60 bg-card/60 px-3 py-2.5 text-sm focus:border-primary/50 focus:outline-none focus:ring-2 focus:ring-ring/30"
        />
      </div>
    </div>
  )
}

onboarding-checklist.source:
'use client'

/**
 * <OnboardingChecklist> — the "get set up" card that follows a new account.
 *
 * The thing that makes a checklist work is that the first item is already
 * ticked. An empty list of six tasks is a bill; a list with one done and a
 * bar showing 1/6 is progress you did not have to earn, and completion
 * rates follow from it. So `steps[0]` ships complete by default here, and
 * it is a real step ("Create your account") rather than a fake one.
 *
 * Details worth keeping:
 *
 *  - It is a `<ul>` of real `<button>`s, not divs with click handlers, so
 *    every row is keyboard-reachable and announces as an action.
 *  - Progress is a native `<progress>` element with a visible label. A
 *    div-with-a-width bar is invisible to assistive tech, and `<progress>`
 *    reports its value without any ARIA.
 *  - Completed rows keep their text legible rather than dropping to 40%
 *    opacity. Struck-through grey is the usual choice and it makes the
 *    record of what you did unreadable.
 *  - The dismiss control appears only once every step is done. Offering
 *    "hide this" on an incomplete checklist is an invitation to abandon it.
 *
 * `onToggle` reports the step id and its new state; wire it to your own
 * persistence. Local state is the default so the preview is interactive.
 */

import * as React from 'react'
import { ArrowRight, Check, X } from 'lucide-react'

export interface ChecklistStep {
  id: string
  label: string
  description: string
  /** Where the step is actually completed. */
  href?: string
  /** Rough time to finish — sets expectations before the click. */
  minutes?: number
}

export interface OnboardingChecklistProps {
  heading?: string
  subheading?: string
  steps?: ChecklistStep[]
  /** Ids that start complete. Defaults to the first step. */
  initialComplete?: string[]
  completeMessage?: string
  onToggle?: (id: string, complete: boolean) => void
  onDismiss?: () => void
  className?: string
}

const DEFAULT_STEPS: ChecklistStep[] = [
  {
    id: 'account',
    label: 'Create your account',
    description: 'Done — welcome aboard.',
    minutes: 1,
  },
  {
    id: 'project',
    label: 'Create your first project',
    description: 'A project holds your environments, keys and deployments.',
    href: '#',
    minutes: 2,
  },
  {
    id: 'install',
    label: 'Install the CLI',
    description: 'One command, and your terminal can deploy.',
    href: '#',
    minutes: 3,
  },
  {
    id: 'invite',
    label: 'Invite a teammate',
    description: 'Projects are more useful with someone to share them with.',
    href: '#',
    minutes: 1,
  },
  {
    id: 'domain',
    label: 'Connect a domain',
    description: 'Point a hostname at your first deployment.',
    href: '#',
    minutes: 5,
  },
]

export function OnboardingChecklist({
  heading = 'Finish setting up',
  subheading = 'Five short steps and your workspace is ready to use.',
  steps = DEFAULT_STEPS,
  initialComplete,
  completeMessage = 'All set. Nice work.',
  onToggle,
  onDismiss,
  className = '',
}: OnboardingChecklistProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [complete, setComplete] = React.useState<Set<string>>(
    () => new Set(initialComplete ?? (steps[0] ? [steps[0].id] : [])),
  )
  const [dismissed, setDismissed] = React.useState(false)

  const done = steps.filter((s) => complete.has(s.id)).length
  const allDone = done === steps.length

  function toggle(id: string) {
    setComplete((prev) => {
      const next = new Set(prev)
      const nowComplete = !next.has(id)
      if (nowComplete) next.add(id)
      else next.delete(id)
      onToggle?.(id, nowComplete)
      return next
    })
  }

  function dismiss() {
    setDismissed(true)
    onDismiss?.()
  }

  if (dismissed) return null

  return (
    <section
      className={`mx-auto w-full max-w-2xl rounded-2xl border border-border/60 bg-card/40 p-6 ${className}`}
    >
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <h2 className="text-lg font-bold tracking-tight">
            {allDone ? completeMessage : heading}
          </h2>
          {!allDone ? (
            <p className="mt-1 text-sm text-muted-foreground">{subheading}</p>
          ) : null}
        </div>

        {/* Only offered once there is nothing left to abandon. */}
        {allDone ? (
          <button
            type="button"
            onClick={dismiss}
            aria-label="Dismiss checklist"
            className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <X aria-hidden className="h-4 w-4" />
          </button>
        ) : null}
      </div>

      {/* Native <progress>: reports its value to assistive tech for free. */}
      <div className="mt-5">
        <div className="flex items-center justify-between text-xs font-medium">
          <label htmlFor={`${uid}-onboarding-progress`} className="text-muted-foreground">
            Setup progress
          </label>
          <span>
            {done} of {steps.length}
          </span>
        </div>
        <progress
          id={`${uid}-onboarding-progress`}
          value={done}
          max={steps.length}
          className="mt-2 h-2 w-full overflow-hidden rounded-full [&::-moz-progress-bar]:bg-primary [&::-webkit-progress-bar]:rounded-full [&::-webkit-progress-bar]:bg-muted [&::-webkit-progress-value]:rounded-full [&::-webkit-progress-value]:bg-primary"
        />
      </div>

      <ul className="mt-6 space-y-2">
        {steps.map((step) => {
          const isDone = complete.has(step.id)
          return (
            <li key={step.id}>
              <div className="flex items-start gap-3 rounded-xl border border-border/60 bg-background/60 p-3 transition-colors hover:border-border">
                <button
                  type="button"
                  onClick={() => toggle(step.id)}
                  aria-pressed={isDone}
                  className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
                    isDone
                      ? 'border-primary bg-primary text-primary-foreground'
                      : 'border-border hover:border-primary'
                  }`}
                >
                  {isDone ? <Check aria-hidden className="h-3 w-3" /> : null}
                  <span className="sr-only">
                    {isDone ? `Mark ${step.label} incomplete` : `Mark ${step.label} complete`}
                  </span>
                </button>

                <div className="min-w-0 flex-1">
                  {/* Completed rows stay readable — no strike-through, no
                      40% opacity. The list is also a record of what you did. */}
                  <p className={`text-sm font-semibold ${isDone ? 'text-muted-foreground' : ''}`}>
                    {step.label}
                  </p>
                  <p className="mt-0.5 text-xs text-muted-foreground">{step.description}</p>
                </div>

                {!isDone && step.href ? (
                  <a
                    href={step.href}
                    className="inline-flex shrink-0 items-center gap-1 rounded-lg px-2.5 py-1.5 text-xs font-semibold text-primary transition-colors hover:bg-primary/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    Start
                    <ArrowRight aria-hidden className="h-3 w-3" />
                  </a>
                ) : null}

                {!isDone && step.minutes ? (
                  <span className="shrink-0 self-center text-[11px] text-muted-foreground">
                    {step.minutes} min
                  </span>
                ) : null}
              </div>
            </li>
          )
        })}
      </ul>
    </section>
  )
}

setup-wizard.source:
'use client'

/**
 * <SetupWizard> — a full-screen guided setup with a side rail.
 *
 * Where <MultiStepForm> collects data, this one makes *choices*: pick a
 * framework, pick a plan, pick what to import. That difference drives the
 * layout — the rail stays visible the whole time so someone four steps in
 * can still see what they picked and what is left, which a horizontal
 * stepper cannot show once labels are truncated on a phone.
 *
 * The rail is an ordered list with `aria-current="step"`. Steps already
 * visited are buttons you can go back to; steps ahead are plain text, and
 * are not focusable — offering a tab stop that does nothing is worse than
 * not offering it.
 *
 * The option groups are real radios (`role` comes free from `type="radio"`),
 * wired into one `<fieldset>` with a `<legend>`. That is what makes arrow
 * keys move between options and what makes the group announce its question
 * before its answers. The card look is a styled `<label>` over a visually
 * hidden input — never a div with `onClick`, which loses all of it.
 */

import * as React from 'react'
import { Check, ChevronLeft, Rocket } from 'lucide-react'

export interface WizardOption {
  value: string
  label: string
  description: string
}

export interface WizardStep {
  id: string
  title: string
  question: string
  options: WizardOption[]
}

export interface SetupWizardProps {
  brand?: string
  steps?: WizardStep[]
  finishLabel?: string
  completeTitle?: string
  completeBody?: string
  onFinish?: (answers: Record<string, string>) => void
  className?: string
}

const DEFAULT_STEPS: WizardStep[] = [
  {
    id: 'framework',
    title: 'Framework',
    question: 'What are you building with?',
    options: [
      { value: 'next', label: 'Next.js', description: 'App Router, server components' },
      { value: 'vite', label: 'Vite + React', description: 'Client-rendered SPA' },
      { value: 'remix', label: 'Remix', description: 'Nested routes and loaders' },
    ],
  },
  {
    id: 'styling',
    title: 'Styling',
    question: 'How do you write styles?',
    options: [
      { value: 'tailwind', label: 'Tailwind CSS', description: 'Utility classes' },
      { value: 'css', label: 'Plain CSS', description: 'Modules or global stylesheets' },
    ],
  },
  {
    id: 'team',
    title: 'Team',
    question: 'Who else needs access?',
    options: [
      { value: 'solo', label: 'Just me', description: 'You can invite people later' },
      { value: 'team', label: 'My team', description: 'We will ask for emails next' },
      { value: 'client', label: 'A client', description: 'Sets up a shared workspace' },
    ],
  },
]

export function SetupWizard({
  brand = 'Acme',
  steps = DEFAULT_STEPS,
  finishLabel = 'Finish setup',
  completeTitle = 'You are ready to go.',
  completeBody = 'We have configured your workspace from your answers. You can change any of it in Settings.',
  onFinish,
  className = '',
}: SetupWizardProps) {
  const [step, setStep] = React.useState(0)
  const [answers, setAnswers] = React.useState<Record<string, string>>({})
  const [done, setDone] = React.useState(false)

  const current = steps[step]
  const answered = current ? answers[current.id] : undefined
  const isLast = step === steps.length - 1

  function choose(value: string) {
    if (!current) return
    setAnswers((a) => ({ ...a, [current.id]: value }))
  }

  function advance() {
    if (!answered) return
    if (isLast) {
      setDone(true)
      onFinish?.(answers)
    } else {
      setStep((s) => s + 1)
    }
  }

  return (
    <section className={`mx-auto w-full max-w-5xl px-4 py-12 sm:px-6 ${className}`}>
      <div className="grid gap-8 rounded-2xl border border-border/60 bg-card/40 p-6 sm:p-8 md:grid-cols-[220px_1fr] md:gap-12">
        {/* -- Rail ---------------------------------------------------- */}
        <div>
          <div className="flex items-center gap-2.5">
            <span
              aria-hidden
              className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-primary to-emerald-600 text-xs font-black text-primary-foreground"
            >
              {brand.slice(0, 1)}
            </span>
            <span className="font-bold tracking-tight">{brand}</span>
          </div>

          <ol className="mt-6 space-y-1">
            {steps.map((s, i) => {
              const state = done || i < step ? 'complete' : i === step ? 'current' : 'upcoming'
              const row = (
                <>
                  <span
                    className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border text-[11px] font-bold ${
                      state === 'complete'
                        ? 'border-primary bg-primary text-primary-foreground'
                        : state === 'current'
                          ? 'border-primary text-primary'
                          : 'border-border/60 text-muted-foreground'
                    }`}
                  >
                    {state === 'complete' ? <Check aria-hidden className="h-3 w-3" /> : i + 1}
                  </span>
                  <span className="text-sm font-medium">{s.title}</span>
                  {state === 'complete' ? <span className="sr-only">completed</span> : null}
                </>
              )

              return (
                <li key={s.id}>
                  {/* Visited steps are navigable; steps ahead are not
                      focusable, because a tab stop that does nothing is
                      worse than no tab stop. */}
                  {state === 'complete' && !done ? (
                    <button
                      type="button"
                      onClick={() => setStep(i)}
                      className="flex w-full items-center gap-2.5 rounded-lg px-2 py-2 text-left transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {row}
                    </button>
                  ) : (
                    <div
                      aria-current={state === 'current' ? 'step' : undefined}
                      className={`flex items-center gap-2.5 px-2 py-2 ${
                        state === 'upcoming' ? 'text-muted-foreground' : ''
                      }`}
                    >
                      {row}
                    </div>
                  )}
                </li>
              )
            })}
          </ol>
        </div>

        {/* -- Panel --------------------------------------------------- */}
        <div className="min-h-80">
          {done || !current ? (
            <div className="flex h-full flex-col items-center justify-center text-center">
              <span className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/15 text-primary">
                <Rocket aria-hidden className="h-6 w-6" />
              </span>
              <h2 className="mt-4 text-xl font-bold tracking-tight">{completeTitle}</h2>
              <p className="mt-2 max-w-sm text-sm text-muted-foreground">{completeBody}</p>
            </div>
          ) : (
            <>
              <fieldset>
                <legend className="text-xl font-bold tracking-tight">{current.question}</legend>

                <div className="mt-6 space-y-3">
                  {current.options.map((option) => {
                    const id = `${current.id}-${option.value}`
                    const selected = answered === option.value
                    return (
                      <label
                        key={option.value}
                        htmlFor={id}
                        className={`flex cursor-pointer items-start gap-3 rounded-xl border p-4 transition-colors has-focus-visible:ring-2 has-focus-visible:ring-ring ${
                          selected
                            ? 'border-primary bg-primary/5'
                            : 'border-border/60 hover:border-border hover:bg-muted/40'
                        }`}
                      >
                        <input
                          id={id}
                          type="radio"
                          name={current.id}
                          value={option.value}
                          checked={selected}
                          onChange={() => choose(option.value)}
                          className="sr-only"
                        />
                        <span
                          aria-hidden
                          className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border ${
                            selected ? 'border-primary bg-primary' : 'border-border'
                          }`}
                        >
                          {selected ? (
                            <span className="h-2 w-2 rounded-full bg-primary-foreground" />
                          ) : null}
                        </span>
                        <span className="min-w-0">
                          <span className="block text-sm font-semibold">{option.label}</span>
                          <span className="mt-0.5 block text-xs text-muted-foreground">
                            {option.description}
                          </span>
                        </span>
                      </label>
                    )
                  })}
                </div>
              </fieldset>

              <div className="mt-8 flex items-center justify-between gap-3">
                <button
                  type="button"
                  onClick={() => setStep((s) => Math.max(0, s - 1))}
                  disabled={step === 0}
                  className="inline-flex h-11 items-center gap-1 rounded-xl border border-border/60 px-4 text-sm font-semibold transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40"
                >
                  <ChevronLeft aria-hidden className="h-4 w-4" />
                  Back
                </button>
                <button
                  type="button"
                  onClick={advance}
                  disabled={!answered}
                  className="inline-flex h-11 items-center rounded-xl bg-primary px-6 text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:opacity-40"
                >
                  {isLast ? finishLabel : 'Continue'}
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </section>
  )
}

toast-stack.source:
'use client'

/**
 * <ToastStack> — a corner notification stack with a working timer.
 *
 * Toasts are the component most often shipped inaccessible, because the
 * hard parts are invisible:
 *
 *  - The container is a permanent `aria-live` region that exists *before*
 *    any toast does. A live region added to the DOM at the same moment as
 *    its first message is usually not announced at all — the screen reader
 *    has nothing registered to watch.
 *  - Severity picks the politeness. Errors use `role="alert"`
 *    (assertive, interrupts); everything else is polite and waits its turn.
 *    Making a success message interrupt what someone is reading is rude,
 *    and making an error wait is dangerous.
 *  - Auto-dismiss pauses on hover *and* on focus, and stops entirely while
 *    the pointer is anywhere in the stack. A message that vanishes while
 *    being read is the same bug whether the reader uses a mouse or a
 *    keyboard.
 *  - Every toast has a real close button with a name. Auto-dismiss is a
 *    convenience, not a substitute — WCAG 2.2.1 wants a way to dismiss.
 *
 * The enter animation is gated behind `motion-safe:`; under `reduce` the
 * toast simply appears. The timer is unaffected — reduced motion is about
 * movement, not about taking things away.
 */

import * as React from 'react'
import { AlertTriangle, CheckCircle2, Info, X, XCircle } from 'lucide-react'

export type ToastVariant = 'success' | 'error' | 'warning' | 'info'

export interface Toast {
  id: number
  variant: ToastVariant
  title: string
  body?: string
}

export interface ToastStackProps {
  /** Milliseconds before a toast dismisses itself. 0 disables the timer. */
  duration?: number
  className?: string
}

const VARIANTS: Record<
  ToastVariant,
  { Icon: typeof Info; tone: string; ring: string }
> = {
  success: {
    Icon: CheckCircle2,
    tone: 'text-emerald-600 dark:text-emerald-400',
    ring: 'border-emerald-500/30',
  },
  error: { Icon: XCircle, tone: 'text-destructive', ring: 'border-destructive/30' },
  warning: {
    Icon: AlertTriangle,
    tone: 'text-amber-600 dark:text-amber-400',
    ring: 'border-amber-500/30',
  },
  info: { Icon: Info, tone: 'text-primary', ring: 'border-primary/30' },
}

const SAMPLES: Array<Omit<Toast, 'id'>> = [
  { variant: 'success', title: 'Deployment live', body: 'acme-web is serving from 14 regions.' },
  { variant: 'error', title: 'Build failed', body: 'Type error in app/page.tsx line 42.' },
  { variant: 'warning', title: 'Usage at 80%', body: 'You have used 8,000 of 10,000 requests.' },
  { variant: 'info', title: 'New version available', body: 'v2.4.0 is ready to install.' },
]

export function ToastStack({ duration = 5000, className = '' }: ToastStackProps) {
  const [toasts, setToasts] = React.useState<Toast[]>([])
  const [paused, setPaused] = React.useState(false)
  const nextId = React.useRef(0)

  const dismiss = React.useCallback((id: number) => {
    setToasts((list) => list.filter((t) => t.id !== id))
  }, [])

  function push(variant: ToastVariant) {
    const sample = SAMPLES.find((s) => s.variant === variant) ?? SAMPLES[0]!
    setToasts((list) => [...list, { ...sample, id: nextId.current++ }])
  }

  // One timer for the whole stack rather than one per toast: the pause is a
  // property of the stack (the pointer is over *it*), and a per-toast timer
  // would need the same paused flag threaded into every one of them.
  React.useEffect(() => {
    if (paused || duration <= 0 || toasts.length === 0) return
    const timer = setTimeout(() => {
      setToasts((list) => list.slice(1))
    }, duration)
    return () => clearTimeout(timer)
  }, [paused, duration, toasts])

  return (
    <div className={`relative min-h-96 p-10 ${className}`}>
      <div className="mx-auto max-w-md text-center">
        <h2 className="text-lg font-semibold">Toast notifications</h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Fire one to see the stack. Hover or focus a toast to hold it open.
        </p>
        <div className="mt-5 flex flex-wrap justify-center gap-2">
          {(Object.keys(VARIANTS) as ToastVariant[]).map((variant) => (
            <button
              key={variant}
              type="button"
              onClick={() => push(variant)}
              className="rounded-lg border border-border/60 bg-card/60 px-3 py-1.5 text-xs font-semibold capitalize transition-colors hover:bg-card focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {variant}
            </button>
          ))}
        </div>
      </div>

      {/*
        The live region is mounted always, empty or not. Creating it at the
        same time as its first message is the classic reason toasts are
        never announced.
      */}
      <div
        aria-live="polite"
        aria-label="Notifications"
        onMouseEnter={() => setPaused(true)}
        onMouseLeave={() => setPaused(false)}
        onFocusCapture={() => setPaused(true)}
        onBlurCapture={() => setPaused(false)}
        className="pointer-events-none absolute bottom-6 right-6 flex w-full max-w-sm flex-col gap-2"
      >
        {toasts.map((toast) => {
          const { Icon, tone, ring } = VARIANTS[toast.variant]
          return (
            <div
              key={toast.id}
              // Errors interrupt; everything else waits its turn.
              role={toast.variant === 'error' ? 'alert' : 'status'}
              className={`pointer-events-auto flex items-start gap-3 rounded-xl border bg-background/95 p-3.5 shadow-lg backdrop-blur motion-safe:animate-[toast-in_180ms_ease-out] ${ring}`}
            >
              <Icon aria-hidden className={`mt-0.5 h-4 w-4 shrink-0 ${tone}`} />
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold">{toast.title}</p>
                {toast.body ? (
                  <p className="mt-0.5 text-xs text-muted-foreground">{toast.body}</p>
                ) : null}
              </div>
              <button
                type="button"
                onClick={() => dismiss(toast.id)}
                aria-label={`Dismiss: ${toast.title}`}
                className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <X aria-hidden className="h-3.5 w-3.5" />
              </button>
            </div>
          )
        })}
      </div>

      {/* Keyframes travel with the component so it works wherever it lands. */}
      <style>{`
        @keyframes toast-in {
          from { opacity: 0; transform: translateY(8px) scale(0.98); }
          to   { opacity: 1; transform: none; }
        }
      `}</style>
    </div>
  )
}

notification-inbox.source:
'use client'

/**
 * <NotificationInbox> — the bell panel: a filterable list with read state.
 *
 * A toast is for right now; this is for what you missed. The difference
 * drives every decision here — nothing auto-dismisses, everything is
 * scannable, and unread is a state you can act on rather than a colour
 * that fades.
 *
 * Worth keeping:
 *
 *  - The unread count is in the trigger's accessible name ("Notifications,
 *    3 unread"), not only in a badge. A number rendered in a coloured
 *    circle is invisible to a screen reader.
 *  - The filter is a `<fieldset>` of radios styled as a segmented control,
 *    so arrow keys move between All and Unread and the group announces as
 *    one control instead of three unrelated buttons.
 *  - Unread is marked by a dot *and* by `sr-only` text, never by colour
 *    alone.
 *  - Timestamps are `<time dateTime>` with a machine-readable value beside
 *    the human "2h ago", so the real time survives copy-paste and is
 *    available to assistive tech.
 *  - "Mark all read" is announced through a polite live region, because
 *    otherwise the only feedback is dots disappearing.
 */

import * as React from 'react'
import { Bell, CheckCheck, GitPullRequest, MessageSquare, TriangleAlert, UserPlus } from 'lucide-react'

export type NotificationKind = 'mention' | 'review' | 'alert' | 'invite'

export interface NotificationItem {
  id: string
  kind: NotificationKind
  actor: string
  text: string
  /** ISO timestamp — the `datetime` attribute value. */
  at: string
  /** Human relative label. Kept as data so this component stays dependency-free. */
  ago: string
  read?: boolean
  href?: string
}

export interface NotificationInboxProps {
  items?: NotificationItem[]
  emptyMessage?: string
  onMarkAllRead?: () => void
  className?: string
}

const KIND_ICON: Record<NotificationKind, typeof Bell> = {
  mention: MessageSquare,
  review: GitPullRequest,
  alert: TriangleAlert,
  invite: UserPlus,
}

const DEFAULT_ITEMS: NotificationItem[] = [
  {
    id: '1',
    kind: 'mention',
    actor: 'Ada Lovelace',
    text: 'mentioned you in “Q3 roadmap”',
    at: '2026-08-08T09:12:00Z',
    ago: '18m ago',
    href: '#',
  },
  {
    id: '2',
    kind: 'review',
    actor: 'Grace Hopper',
    text: 'requested your review on #482',
    at: '2026-08-08T07:40:00Z',
    ago: '2h ago',
    href: '#',
  },
  {
    id: '3',
    kind: 'alert',
    actor: 'System',
    text: 'Usage reached 80% of your monthly quota',
    at: '2026-08-07T22:05:00Z',
    ago: '11h ago',
    href: '#',
  },
  {
    id: '4',
    kind: 'invite',
    actor: 'Alan Turing',
    text: 'invited you to the Platform team',
    at: '2026-08-07T15:30:00Z',
    ago: '18h ago',
    read: true,
    href: '#',
  },
  {
    id: '5',
    kind: 'mention',
    actor: 'Katherine Johnson',
    text: 'replied to your comment on #470',
    at: '2026-08-06T11:02:00Z',
    ago: '2d ago',
    read: true,
    href: '#',
  },
]

type Filter = 'all' | 'unread'

export function NotificationInbox({
  items = DEFAULT_ITEMS,
  emptyMessage = 'Nothing unread. You are caught up.',
  onMarkAllRead,
  className = '',
}: NotificationInboxProps) {
  const [read, setRead] = React.useState<Set<string>>(
    () => new Set(items.filter((i) => i.read).map((i) => i.id)),
  )
  const [filter, setFilter] = React.useState<Filter>('all')
  const [announcement, setAnnouncement] = React.useState('')

  const unreadCount = items.filter((i) => !read.has(i.id)).length
  const shown = filter === 'unread' ? items.filter((i) => !read.has(i.id)) : items

  function markAllRead() {
    setRead(new Set(items.map((i) => i.id)))
    setAnnouncement('All notifications marked as read.')
    onMarkAllRead?.()
  }

  function toggleRead(id: string) {
    setRead((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  return (
    <div className={`mx-auto w-full max-w-md ${className}`}>
      <div className="overflow-hidden rounded-2xl border border-border/60 bg-card/60 shadow-lg">
        {/* -- Header -------------------------------------------------- */}
        <div className="flex items-center justify-between gap-3 border-b border-border/60 px-4 py-3">
          <h2 className="flex items-center gap-2 text-sm font-semibold">
            <Bell aria-hidden className="h-4 w-4" />
            Notifications
            {/* The count is in the text, not only in the badge. */}
            <span className="sr-only">, {unreadCount} unread</span>
            {unreadCount > 0 ? (
              <span
                aria-hidden
                className="rounded-full bg-primary px-1.5 py-0.5 text-[10px] font-bold text-primary-foreground"
              >
                {unreadCount}
              </span>
            ) : null}
          </h2>

          <button
            type="button"
            onClick={markAllRead}
            disabled={unreadCount === 0}
            className="inline-flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-semibold text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40"
          >
            <CheckCheck aria-hidden className="h-3.5 w-3.5" />
            Mark all read
          </button>
        </div>

        {/* -- Filter: one radio group, not three loose buttons -------- */}
        <fieldset className="border-b border-border/60 px-4 py-2.5">
          <legend className="sr-only">Filter notifications</legend>
          <div className="inline-flex rounded-lg border border-border/60 p-0.5">
            {(['all', 'unread'] as const).map((value) => (
              <label
                key={value}
                className={`cursor-pointer rounded-md px-3 py-1 text-xs font-semibold capitalize transition-colors has-focus-visible:ring-2 has-focus-visible:ring-ring ${
                  filter === value ? 'bg-primary text-primary-foreground' : 'text-muted-foreground'
                }`}
              >
                <input
                  type="radio"
                  name="notification-filter"
                  value={value}
                  checked={filter === value}
                  onChange={() => setFilter(value)}
                  className="sr-only"
                />
                {value}
                {value === 'unread' ? ` (${unreadCount})` : ''}
              </label>
            ))}
          </div>
        </fieldset>

        {/* -- List ---------------------------------------------------- */}
        {shown.length === 0 ? (
          <p className="px-4 py-12 text-center text-sm text-muted-foreground">{emptyMessage}</p>
        ) : (
          <ul className="max-h-96 divide-y divide-border/60 overflow-y-auto">
            {shown.map((item) => {
              const Icon = KIND_ICON[item.kind]
              const isUnread = !read.has(item.id)
              return (
                <li key={item.id} className={isUnread ? 'bg-primary/[0.04]' : undefined}>
                  <div className="flex gap-3 px-4 py-3">
                    <span className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-border/60 bg-background text-muted-foreground">
                      <Icon aria-hidden className="h-4 w-4" />
                    </span>

                    <div className="min-w-0 flex-1">
                      <p className="text-sm leading-snug">
                        <span className="font-semibold">{item.actor}</span>{' '}
                        <span className="text-muted-foreground">{item.text}</span>
                      </p>
                      <time dateTime={item.at} className="mt-0.5 block text-xs text-muted-foreground">
                        {item.ago}
                      </time>
                    </div>

                    <button
                      type="button"
                      onClick={() => toggleRead(item.id)}
                      className="mt-1 flex h-4 w-4 shrink-0 items-center justify-center rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {/* Dot plus text — never colour alone. */}
                      <span
                        aria-hidden
                        className={`h-2 w-2 rounded-full ${
                          isUnread ? 'bg-primary' : 'border border-border'
                        }`}
                      />
                      <span className="sr-only">
                        {isUnread ? 'Unread — mark as read' : 'Read — mark as unread'}
                      </span>
                    </button>
                  </div>
                </li>
              )
            })}
          </ul>
        )}
      </div>

      {/* Bulk actions have no visible feedback beyond dots vanishing. */}
      <p aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  )
}

stats-band.source:
/**
 * <StatsBand> — a four-up numeric strip for a landing page.
 *
 * Hairline-separated cells built from a single `gap-px` grid over a
 * background, so the dividers stay 1px on every display without a border
 * on each child fighting its neighbour.
 */

import * as React from 'react'

export interface Stat {
  value: string
  label: string
  caption?: string
}

export interface StatsBandProps {
  stats?: Stat[]
  className?: string
}

const DEFAULT_STATS: Stat[] = [
  { value: '12,000+', label: 'Developers', caption: 'Shipping with it weekly' },
  { value: '99.99%', label: 'Uptime', caption: 'Trailing twelve months' },
  { value: '<40ms', label: 'Median latency', caption: 'Measured at the edge' },
  { value: '24/7', label: 'Support', caption: 'Real humans, every timezone' },
]

export function StatsBand({ stats = DEFAULT_STATS, className = '' }: StatsBandProps) {
  return (
    <section className={`mx-auto w-full max-w-7xl px-4 py-12 sm:px-6 lg:px-8 ${className}`}>
      <div className="grid grid-cols-2 gap-px overflow-hidden rounded-2xl border border-border/60 bg-border/60 lg:grid-cols-4">
        {stats.map((s) => (
          <div
            key={s.label}
            className="bg-background/80 p-5 text-center backdrop-blur transition-colors hover:bg-background sm:p-6"
          >
            <div className="text-3xl font-extrabold tracking-tight text-foreground sm:text-4xl">
              {s.value}
            </div>
            <div className="mt-1 text-sm font-semibold text-foreground/80">{s.label}</div>
            {s.caption ? (
              <div className="mt-0.5 text-xs text-muted-foreground">{s.caption}</div>
            ) : null}
          </div>
        ))}
      </div>
    </section>
  )
}

logo-cloud.source:
/**
 * <LogoCloud> — an infinite horizontal marquee of customer logos.
 *
 * The track holds the list twice and translates by exactly -50%, so the
 * second copy lands where the first began and the loop has no seam. Edges
 * fade out with a mask rather than a gradient overlay, which keeps it
 * correct on any page background.
 *
 * Honours `prefers-reduced-motion` by stopping the scroll and wrapping
 * instead — a permanent horizontal crawl is a vestibular trigger, and it is
 * also unreadable.
 */

import * as React from 'react'

export interface LogoCloudProps {
  logos?: string[]
  caption?: string
  /** Seconds for one full pass. Longer reads calmer. */
  duration?: number
  className?: string
}

const DEFAULT_LOGOS = [
  'Northwind',
  'Contoso',
  'Initech',
  'Umbrella',
  'Globex',
  'Soylent',
  'Hooli',
  'Vandelay',
]

export function LogoCloud({
  logos = DEFAULT_LOGOS,
  caption = 'Trusted by teams shipping every day',
  duration = 40,
  className = '',
}: LogoCloudProps) {
  return (
    <section className={`w-full py-12 ${className}`}>
      {caption ? (
        <p className="mb-8 text-center text-sm font-medium text-muted-foreground">
          {caption}
        </p>
      ) : null}

      <div
        className="group relative overflow-hidden"
        style={{
          maskImage:
            'linear-gradient(to right, transparent, black 12%, black 88%, transparent)',
          WebkitMaskImage:
            'linear-gradient(to right, transparent, black 12%, black 88%, transparent)',
        }}
      >
        <div
          className="flex w-max items-center gap-14 motion-safe:animate-[logo-marquee_var(--logo-duration)_linear_infinite] motion-reduce:flex-wrap motion-reduce:justify-center group-hover:[animation-play-state:paused]"
          style={{ ['--logo-duration' as string]: `${duration}s` }}
        >
          {[...logos, ...logos].map((name, i) => (
            <span
              key={`${name}-${i}`}
              aria-hidden={i >= logos.length}
              className="shrink-0 text-xl font-bold tracking-tight text-muted-foreground/60 transition-colors hover:text-foreground"
            >
              {name}
            </span>
          ))}
        </div>
      </div>

      <style>{`
        @keyframes logo-marquee {
          from { transform: translateX(0); }
          to   { transform: translateX(-50%); }
        }
      `}</style>
    </section>
  )
}

bento-features.source:
/**
 * <BentoFeatures> — an asymmetric feature grid.
 *
 * Six tiles on a 4-column × 3-row grid at `lg`, each declaring its own span
 * so the layout reads as composed rather than tiled. Below `lg` every tile
 * collapses to full width in source order, which is why the most important
 * tile is first in the array rather than positioned by grid placement.
 */

import * as React from 'react'
import { Sparkles, Shield, Zap, Layers, Globe, Quote } from 'lucide-react'

export interface BentoTile {
  title: string
  body: string
  icon?: React.ReactNode
  /** Tailwind span classes applied at `lg` and up. */
  span?: string
  accent?: string
}

export interface BentoFeaturesProps {
  tiles?: BentoTile[]
  heading?: string
  subheading?: string
  className?: string
}

const DEFAULT_TILES: BentoTile[] = [
  {
    title: 'Fast by default',
    body: 'No runtime, no hydration cost, no waterfall. What you paste is what the browser paints.',
    icon: <Sparkles className="h-5 w-5" />,
    span: 'sm:col-span-2 lg:row-span-2',
    accent: 'text-primary',
  },
  {
    title: 'Yours to keep',
    body: 'Copied code lives in your repo. Nothing phones home and nothing breaks when we ship.',
    icon: <Shield className="h-5 w-5" />,
    span: 'sm:col-span-2',
    accent: 'text-emerald-500',
  },
  {
    title: 'Zero dependencies',
    body: 'Nothing to audit.',
    icon: <Zap className="h-5 w-5" />,
    span: 'lg:row-span-2',
    accent: 'text-amber-500',
  },
  {
    title: 'Composable',
    body: 'Every piece works alone or nested inside the next one up.',
    icon: <Layers className="h-5 w-5" />,
    accent: 'text-sky-500',
  },
  {
    title: 'Accessible',
    body: 'Keyboard paths, focus rings and reduced-motion fallbacks included.',
    icon: <Globe className="h-5 w-5" />,
    accent: 'text-rose-500',
  },
  {
    title: '"It replaced our design system backlog."',
    body: 'Priya R., Staff Engineer',
    icon: <Quote className="h-5 w-5" />,
    span: 'sm:col-span-2',
    accent: 'text-violet-500',
  },
]

export function BentoFeatures({
  tiles = DEFAULT_TILES,
  heading = 'Everything, in one place',
  subheading = 'The parts you would otherwise rebuild on every project.',
  className = '',
}: BentoFeaturesProps) {
  return (
    <section className={`mx-auto w-full max-w-7xl px-4 py-16 sm:px-6 lg:px-8 ${className}`}>
      <div className="mx-auto mb-12 max-w-2xl text-center">
        <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
          {heading}
        </h2>
        {subheading ? <p className="mt-3 text-muted-foreground">{subheading}</p> : null}
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 lg:grid-rows-3">
        {tiles.map((tile) => (
          <div
            key={tile.title}
            className={`group relative overflow-hidden rounded-2xl border border-border/60 bg-card/80 p-6 backdrop-blur transition-all hover:-translate-y-0.5 hover:shadow-lg ${tile.span ?? ''}`}
          >
            <div
              aria-hidden
              className="pointer-events-none absolute -right-12 -top-12 h-40 w-40 rounded-full bg-primary/10 opacity-0 blur-3xl transition-opacity duration-500 group-hover:opacity-100"
            />
            <div className="relative flex h-full flex-col">
              {tile.icon ? (
                <div
                  className={`mb-3 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-muted ${tile.accent ?? 'text-foreground'}`}
                >
                  {tile.icon}
                </div>
              ) : null}
              <h3 className="text-lg font-bold tracking-tight">{tile.title}</h3>
              <p className="mt-2 text-sm leading-relaxed text-muted-foreground">{tile.body}</p>
            </div>
          </div>
        ))}
      </div>
    </section>
  )
}

persona-cards.source:
/**
 * <PersonaCards> — a "who this is for" grid.
 *
 * Four cards, each naming an audience, the outcome they want, and the
 * bullets that get them there. The point is self-identification: a visitor
 * should find their own job title in the first screenful and stop
 * wondering whether the product is aimed at them.
 */

import * as React from 'react'
import { Code2, Palette, Rocket, GraduationCap, ArrowRight } from 'lucide-react'

export interface Persona {
  name: string
  headline: string
  bullets: string[]
  icon?: React.ReactNode
  /** Tailwind text-color class; the bullet marker derives from it. */
  accent?: string
  href?: string
  ctaLabel?: string
}

export interface PersonaCardsProps {
  personas?: Persona[]
  heading?: string
  subheading?: string
  className?: string
}

const DEFAULT_PERSONAS: Persona[] = [
  {
    icon: <Code2 className="h-5 w-5" />,
    name: 'Frontend developers',
    headline: 'Ship polish without the busywork',
    bullets: [
      'Stop rewriting the same hover and focus states',
      'Drop a whole section in instead of assembling one',
      'No runtime means no bundle-size regression',
    ],
    accent: 'text-sky-500',
  },
  {
    icon: <Palette className="h-5 w-5" />,
    name: 'Designers',
    headline: 'Close the gap between the mock and the build',
    bullets: [
      'Show stakeholders something live, not a screenshot',
      'Tune spacing, colour and motion against real markup',
      'Hand over a link instead of a spec document',
    ],
    accent: 'text-rose-500',
  },
  {
    icon: <Rocket className="h-5 w-5" />,
    name: 'Founders',
    headline: 'Make an MVP feel like a funded product',
    bullets: [
      'A credible landing page in an afternoon',
      'No design hire required to launch',
      'Commercial use covered — ship it and charge for it',
    ],
    accent: 'text-amber-500',
  },
  {
    icon: <GraduationCap className="h-5 w-5" />,
    name: 'Learners',
    headline: 'Read patterns that are actually in production',
    bullets: [
      'Every source is commented and idiomatic',
      'Learn layout and motion by working example',
      'Fork a piece and break it — nothing to set up',
    ],
    accent: 'text-emerald-500',
  },
]

export function PersonaCards({
  personas = DEFAULT_PERSONAS,
  heading = 'Built for everyone who ships UI',
  subheading = 'Whichever seat you are in, the work starts further along.',
  className = '',
}: PersonaCardsProps) {
  return (
    <section className={`mx-auto w-full max-w-7xl px-4 py-16 sm:px-6 lg:px-8 ${className}`}>
      <div className="mx-auto mb-12 max-w-2xl text-center">
        <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
          {heading}
        </h2>
        {subheading ? <p className="mt-3 text-muted-foreground">{subheading}</p> : null}
      </div>

      <div className="grid grid-cols-1 gap-5 sm:grid-cols-2">
        {personas.map((p) => {
          const accent = p.accent ?? 'text-primary'
          return (
            <div
              key={p.name}
              className="group relative overflow-hidden rounded-2xl border border-border/60 bg-card/80 p-6 backdrop-blur transition-all hover:-translate-y-0.5 hover:shadow-lg"
            >
              <div
                aria-hidden
                className="pointer-events-none absolute -right-12 -top-12 h-40 w-40 rounded-full bg-primary/10 opacity-0 blur-3xl transition-opacity duration-500 group-hover:opacity-100"
              />
              <div className="relative">
                {p.icon ? (
                  <div
                    className={`mb-4 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-muted ${accent}`}
                  >
                    {p.icon}
                  </div>
                ) : null}
                <h3 className="text-lg font-bold tracking-tight">{p.name}</h3>
                <p className="mt-1 text-sm font-medium text-foreground/80">{p.headline}</p>

                <ul className="mt-4 space-y-2">
                  {p.bullets.map((b) => (
                    <li key={b} className="flex items-start gap-2 text-sm text-muted-foreground">
                      <span
                        aria-hidden
                        className={`mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full ${accent.replace('text-', 'bg-')}`}
                      />
                      <span>{b}</span>
                    </li>
                  ))}
                </ul>

                {p.href ? (
                  <a
                    href={p.href}
                    className={`mt-5 inline-flex items-center gap-1 text-sm font-semibold transition-all hover:gap-2 ${accent}`}
                  >
                    {p.ctaLabel ?? 'Get started'}
                    <ArrowRight aria-hidden className="h-3.5 w-3.5" />
                  </a>
                ) : null}
              </div>
            </div>
          )
        })}
      </div>
    </section>
  )
}

code-showcase.source:
'use client'

/**
 * <CodeShowcase> — a feature section with a fake editor window beside it.
 *
 * Tabs switch the visible file. The window chrome is decorative and marked
 * `aria-hidden`; the code itself sits in a real <pre> so it can be selected
 * and copied, which is the entire point of showing code on a landing page.
 *
 * Line numbers are generated from the source rather than typed into it, so
 * copying picks up the code without the gutter coming along.
 */

import * as React from 'react'
import { Copy, Check } from 'lucide-react'

export interface CodeFile {
  name: string
  code: string
}

export interface CodeShowcaseProps {
  files?: CodeFile[]
  heading?: string
  subheading?: string
  bullets?: string[]
  className?: string
}

const DEFAULT_FILES: CodeFile[] = [
  {
    name: 'page.tsx',
    code: `import { PricingTiers } from '@/components/pricing-tiers'
import { FaqAccordion } from '@/components/faq-accordion'

export default function Page() {
  return (
    <main>
      <PricingTiers />
      <FaqAccordion />
    </main>
  )
}`,
  },
  {
    name: 'theme.css',
    code: `:root {
  --background: 0 0% 100%;
  --foreground: 240 10% 4%;
  --primary: 243 75% 59%;
  --muted: 240 5% 96%;
  --border: 240 6% 90%;
}

.dark {
  --background: 240 10% 4%;
  --foreground: 0 0% 98%;
  --primary: 234 89% 74%;
}`,
  },
]

export function CodeShowcase({
  files = DEFAULT_FILES,
  heading = 'Paste it. Ship it.',
  subheading = 'No install step, no configuration file, no build plugin.',
  bullets = [
    'Copy the section straight into your project',
    'Restyle it with your own tokens, not our overrides',
    'Delete what you do not need — it is your code now',
  ],
  className = '',
}: CodeShowcaseProps) {
  const [active, setActive] = React.useState(0)
  const [copied, setCopied] = React.useState(false)

  const file = files[active] ?? files[0]

  async function copy() {
    await navigator.clipboard.writeText(file.code)
    setCopied(true)
    window.setTimeout(() => setCopied(false), 1600)
  }

  return (
    <section className={`mx-auto w-full max-w-7xl px-4 py-16 sm:px-6 lg:px-8 ${className}`}>
      <div className="grid grid-cols-1 items-center gap-10 lg:grid-cols-2 lg:gap-16">
        <div>
          <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
            {heading}
          </h2>
          {subheading ? <p className="mt-3 text-muted-foreground">{subheading}</p> : null}

          <ul className="mt-6 space-y-3">
            {bullets.map((b) => (
              <li key={b} className="flex items-start gap-2.5 text-sm">
                <Check aria-hidden className="mt-0.5 h-4 w-4 shrink-0 text-emerald-500" />
                <span className="text-muted-foreground">{b}</span>
              </li>
            ))}
          </ul>
        </div>

        <div className="overflow-hidden rounded-2xl border border-border/60 bg-zinc-950 shadow-xl">
          {/* Window chrome */}
          <div className="flex items-center gap-2 border-b border-white/10 px-4 py-3">
            <div aria-hidden className="flex gap-1.5">
              <span className="h-3 w-3 rounded-full bg-red-500/80" />
              <span className="h-3 w-3 rounded-full bg-amber-500/80" />
              <span className="h-3 w-3 rounded-full bg-emerald-500/80" />
            </div>

            <div role="tablist" className="ml-3 flex gap-1">
              {files.map((f, i) => (
                <button
                  key={f.name}
                  role="tab"
                  type="button"
                  aria-selected={i === active}
                  onClick={() => setActive(i)}
                  className={`rounded-md px-2.5 py-1 font-mono text-xs transition-colors ${
                    i === active
                      ? 'bg-white/10 text-white'
                      : 'text-white/50 hover:text-white/80'
                  }`}
                >
                  {f.name}
                </button>
              ))}
            </div>

            <button
              type="button"
              onClick={copy}
              aria-label={`Copy ${file.name}`}
              className="ml-auto inline-flex items-center gap-1.5 rounded-md px-2 py-1 text-xs text-white/50 transition-colors hover:bg-white/10 hover:text-white"
            >
              {copied ? (
                <Check aria-hidden className="h-3.5 w-3.5 text-emerald-400" />
              ) : (
                <Copy aria-hidden className="h-3.5 w-3.5" />
              )}
              {copied ? 'Copied' : 'Copy'}
            </button>
          </div>

          <pre className="overflow-x-auto p-4 text-xs leading-relaxed">
            <code className="font-mono text-zinc-300">
              {file.code.split('\n').map((line, i) => (
                <span key={i} className="grid grid-cols-[2rem_1fr]">
                  <span aria-hidden className="select-none text-right text-white/20">
                    {i + 1}
                  </span>
                  <span className="pl-4">{line || ' '}</span>
                </span>
              ))}
            </code>
          </pre>
        </div>
      </div>
    </section>
  )
}

comparison-table.source:
/**
 * <ComparisonTable> — a feature matrix across plans or competitors.
 *
 * A real <table> with a <caption> and scoped headers, so a screen reader
 * can announce "Priority support, Pro, included" instead of reading a grid
 * of disembodied checkmarks. The check and dash carry `<span class="sr-only">`
 * text for the same reason.
 *
 * The first column is sticky on small screens: a matrix you have to scroll
 * horizontally is useless once the row label has slid out of view.
 */

import * as React from 'react'
import { Check, Minus } from 'lucide-react'

/** `true`/`false` render as icons; a string renders verbatim. */
export type CellValue = boolean | string

export interface ComparisonRow {
  feature: string
  values: CellValue[]
}

export interface ComparisonTableProps {
  columns?: string[]
  rows?: ComparisonRow[]
  heading?: string
  subheading?: string
  /** Index into `columns` to emphasise. */
  highlightColumn?: number
  className?: string
}

const DEFAULT_COLUMNS = ['Free', 'Pro', 'Team']

const DEFAULT_ROWS: ComparisonRow[] = [
  { feature: 'Projects', values: ['3', 'Unlimited', 'Unlimited'] },
  { feature: 'Commercial license', values: [false, true, true] },
  { feature: 'Full component library', values: [false, true, true] },
  { feature: 'Figma source files', values: [false, true, true] },
  { feature: 'Seats', values: ['1', '1', 'Up to 10'] },
  { feature: 'SSO and audit log', values: [false, false, true] },
  { feature: 'Support', values: ['Community', 'Priority email', 'Dedicated'] },
]

export function ComparisonTable({
  columns = DEFAULT_COLUMNS,
  rows = DEFAULT_ROWS,
  heading = 'Compare plans',
  subheading = 'Every line, side by side.',
  highlightColumn = 1,
  className = '',
}: ComparisonTableProps) {
  return (
    <section className={`mx-auto w-full max-w-5xl px-4 py-16 sm:px-6 lg:px-8 ${className}`}>
      <div className="mx-auto mb-10 max-w-2xl text-center">
        <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
          {heading}
        </h2>
        {subheading ? <p className="mt-3 text-muted-foreground">{subheading}</p> : null}
      </div>

      <div className="overflow-x-auto rounded-2xl border border-border/60">
        <table className="w-full border-collapse text-sm">
          <caption className="sr-only">
            {heading} — features by plan
          </caption>
          <thead>
            <tr className="border-b border-border/60 bg-muted/40">
              <th scope="col" className="sticky left-0 z-10 bg-muted/40 p-4 text-left font-semibold">
                Feature
              </th>
              {columns.map((col, i) => (
                <th
                  key={col}
                  scope="col"
                  className={`p-4 text-center font-semibold ${
                    i === highlightColumn ? 'text-primary' : ''
                  }`}
                >
                  {col}
                  {i === highlightColumn ? (
                    <span className="ml-1.5 rounded-full bg-primary/15 px-2 py-0.5 text-xs">
                      Popular
                    </span>
                  ) : null}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.feature} className="border-b border-border/40 last:border-0 hover:bg-muted/20">
                <th
                  scope="row"
                  className="sticky left-0 z-10 bg-background p-4 text-left font-medium"
                >
                  {row.feature}
                </th>
                {row.values.map((value, i) => (
                  <td
                    key={i}
                    className={`p-4 text-center ${
                      i === highlightColumn ? 'bg-primary/5' : ''
                    }`}
                  >
                    <Cell value={value} />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </section>
  )
}

function Cell({ value }: { value: CellValue }) {
  if (typeof value === 'string') {
    return <span className="text-muted-foreground">{value}</span>
  }
  return value ? (
    <>
      <Check aria-hidden className="mx-auto h-4 w-4 text-emerald-500" />
      <span className="sr-only">Included</span>
    </>
  ) : (
    <>
      <Minus aria-hidden className="mx-auto h-4 w-4 text-muted-foreground/40" />
      <span className="sr-only">Not included</span>
    </>
  )
}

testimonial-grid.source:
/**
 * <TestimonialGrid> — a masonry-ish wall of customer quotes.
 *
 * Uses CSS multi-column rather than a grid: quotes vary in length, and
 * columns pack them by height instead of leaving the ragged bottom edge a
 * row-based grid produces. `break-inside: avoid` keeps a card from being
 * split across a column boundary.
 */

import * as React from 'react'
import { Star } from 'lucide-react'

export interface Testimonial {
  quote: string
  name: string
  role: string
  /** 1–5. Omit to hide the row of stars. */
  rating?: number
}

export interface TestimonialGridProps {
  testimonials?: Testimonial[]
  heading?: string
  subheading?: string
  className?: string
}

const DEFAULT_TESTIMONIALS: Testimonial[] = [
  {
    quote:
      'We replaced a week of design polish with an afternoon. The parts that used to get cut for time are just there now.',
    name: 'Priya Raman',
    role: 'Staff Engineer, Northwind',
    rating: 5,
  },
  {
    quote: 'Dropped it in on a Friday and shipped Monday. No dependency argument with my team for once.',
    name: 'Marco Silva',
    role: 'Founder, Ferrytale',
    rating: 5,
  },
  {
    quote:
      'The thing I did not expect: it made our junior engineers faster, because the patterns are readable. They learn from what they paste.',
    name: 'Alex Chen',
    role: 'Engineering Manager, Contoso',
    rating: 5,
  },
  {
    quote: 'Our marketing site went from three weeks to four days. Same designer, same headcount.',
    name: 'Dana Whitfield',
    role: 'Head of Design, Globex',
    rating: 4,
  },
  {
    quote:
      'I stopped keeping a personal snippets file. That file had been following me between jobs for six years.',
    name: 'Samir Haddad',
    role: 'Frontend Lead, Initech',
    rating: 5,
  },
]

export function TestimonialGrid({
  testimonials = DEFAULT_TESTIMONIALS,
  heading = 'What people say',
  subheading = 'From teams that ship on a deadline.',
  className = '',
}: TestimonialGridProps) {
  return (
    <section className={`mx-auto w-full max-w-7xl px-4 py-16 sm:px-6 lg:px-8 ${className}`}>
      <div className="mx-auto mb-12 max-w-2xl text-center">
        <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
          {heading}
        </h2>
        {subheading ? <p className="mt-3 text-muted-foreground">{subheading}</p> : null}
      </div>

      <div className="gap-5 sm:columns-2 lg:columns-3 [&>*]:mb-5">
        {testimonials.map((t) => (
          <figure
            key={t.name}
            className="break-inside-avoid rounded-2xl border border-border/60 bg-card/80 p-6 backdrop-blur transition-shadow hover:shadow-lg"
          >
            {t.rating ? (
              <div className="mb-3 flex gap-0.5" aria-label={`${t.rating} out of 5`}>
                {Array.from({ length: 5 }, (_, i) => (
                  <Star
                    key={i}
                    aria-hidden
                    className={
                      i < t.rating!
                        ? 'h-3.5 w-3.5 fill-amber-400 text-amber-400'
                        : 'h-3.5 w-3.5 text-muted-foreground/30'
                    }
                  />
                ))}
              </div>
            ) : null}

            <blockquote className="text-sm leading-relaxed text-foreground/90">
              &ldquo;{t.quote}&rdquo;
            </blockquote>

            <figcaption className="mt-4 flex items-center gap-3 border-t border-border/60 pt-4">
              <span
                aria-hidden
                className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-bold text-foreground/70"
              >
                {initials(t.name)}
              </span>
              <span className="min-w-0">
                <span className="block truncate text-sm font-semibold">{t.name}</span>
                <span className="block truncate text-xs text-muted-foreground">{t.role}</span>
              </span>
            </figcaption>
          </figure>
        ))}
      </div>
    </section>
  )
}

function initials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((w) => w[0] ?? '')
    .join('')
    .toUpperCase()
}

faq-accordion.source:
/**
 * <FaqAccordion> — a frequently-asked-questions list.
 *
 * Built on <details>/<summary> with a shared `name`, which gives real
 * accordion behaviour — opening one closes the rest — with no state, no
 * effect hook and no JavaScript at all. Keyboard support and the
 * open/closed state exposed to screen readers come free from the elements.
 *
 * Pass `exclusive={false}` for an list where several answers can sit open
 * at once.
 */

import * as React from 'react'
import { Plus } from 'lucide-react'

export interface FaqItem {
  question: string
  answer: string
}

export interface FaqAccordionProps {
  items?: FaqItem[]
  heading?: string
  subheading?: string
  /** Only one answer open at a time. */
  exclusive?: boolean
  className?: string
}

const DEFAULT_ITEMS: FaqItem[] = [
  {
    question: 'Can I use this in a commercial project?',
    answer:
      'Yes. Everything here is yours to ship in client work and paid products, with no attribution required.',
  },
  {
    question: 'Do I need a specific framework?',
    answer:
      'No. The markup is plain HTML and the styling is utility classes, so it drops into any stack that can render an element.',
  },
  {
    question: 'How do updates work?',
    answer:
      'Copied code is yours — nothing reaches back into your project. Pull a newer version whenever you want it.',
  },
  {
    question: 'Is there a free tier?',
    answer:
      'There is. A large part of the catalog is free forever; the paid plan unlocks the rest and removes usage limits.',
  },
]

export function FaqAccordion({
  items = DEFAULT_ITEMS,
  heading = 'Frequently asked questions',
  subheading = 'Everything people ask before getting started.',
  exclusive = true,
  className = '',
}: FaqAccordionProps) {
  return (
    <section className={`mx-auto w-full max-w-3xl px-4 py-16 sm:px-6 ${className}`}>
      <div className="mx-auto mb-10 max-w-2xl text-center">
        <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
          {heading}
        </h2>
        {subheading ? (
          <p className="mt-3 text-muted-foreground">{subheading}</p>
        ) : null}
      </div>

      <div className="divide-y divide-border/60 overflow-hidden rounded-2xl border border-border/60 bg-card/60">
        {items.map((item) => (
          <details
            key={item.question}
            name={exclusive ? 'faq' : undefined}
            className="group px-5 py-1 [&_summary::-webkit-details-marker]:hidden"
          >
            <summary className="flex cursor-pointer list-none items-center justify-between gap-4 py-4 text-left font-semibold transition-colors hover:text-foreground/80">
              {item.question}
              <Plus
                aria-hidden
                className="h-4 w-4 shrink-0 text-muted-foreground transition-transform duration-200 group-open:rotate-45"
              />
            </summary>
            <p className="pb-5 pr-8 text-sm leading-relaxed text-muted-foreground">
              {item.answer}
            </p>
          </details>
        ))}
      </div>
    </section>
  )
}

changelog-timeline.source:
/**
 * <ChangelogTimeline> — a dated release list on a vertical rail.
 *
 * The rail is a `border-l` on the list with dots absolutely positioned over
 * it, rather than a separate spine element. That way the line ends exactly
 * where the last entry does instead of running past it, and it stays
 * aligned when an entry's height changes.
 *
 * Dates use <time datetime> so the machine-readable value is the ISO
 * string, whatever human format the label is written in.
 */

import * as React from 'react'

export type ReleaseKind = 'added' | 'changed' | 'fixed'

export interface ReleaseEntry {
  /** ISO date — `2026-07-14`. */
  date: string
  version: string
  title: string
  items: { kind: ReleaseKind; text: string }[]
}

export interface ChangelogTimelineProps {
  entries?: ReleaseEntry[]
  heading?: string
  subheading?: string
  className?: string
}

const KIND_STYLE: Record<ReleaseKind, string> = {
  added: 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400',
  changed: 'bg-sky-500/15 text-sky-600 dark:text-sky-400',
  fixed: 'bg-amber-500/15 text-amber-600 dark:text-amber-400',
}

const DEFAULT_ENTRIES: ReleaseEntry[] = [
  {
    date: '2026-07-14',
    version: 'v2.4.0',
    title: 'Dashboard blocks',
    items: [
      { kind: 'added', text: 'Twelve dashboard and data-table sections' },
      { kind: 'added', text: 'Keyboard navigation across every table block' },
      { kind: 'changed', text: 'Sidebar collapses below 1024px instead of 768px' },
    ],
  },
  {
    date: '2026-06-02',
    version: 'v2.3.1',
    title: 'Accessibility pass',
    items: [
      { kind: 'fixed', text: 'Focus ring clipped inside overflow containers' },
      { kind: 'fixed', text: 'Marquee ignored prefers-reduced-motion' },
    ],
  },
  {
    date: '2026-05-19',
    version: 'v2.3.0',
    title: 'Theming',
    items: [
      { kind: 'added', text: 'Token generator with contrast validation' },
      { kind: 'changed', text: 'All blocks now read semantic colour tokens' },
    ],
  },
]

export function ChangelogTimeline({
  entries = DEFAULT_ENTRIES,
  heading = 'What shipped recently',
  subheading = 'Every release, in plain language.',
  className = '',
}: ChangelogTimelineProps) {
  return (
    <section className={`mx-auto w-full max-w-3xl px-4 py-16 sm:px-6 ${className}`}>
      <div className="mx-auto mb-12 max-w-2xl text-center">
        <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
          {heading}
        </h2>
        {subheading ? <p className="mt-3 text-muted-foreground">{subheading}</p> : null}
      </div>

      <ol className="relative ml-3 space-y-10 border-l border-border/60 pl-8">
        {entries.map((entry) => (
          <li key={entry.version} className="relative">
            <span
              aria-hidden
              className="absolute -left-[2.3rem] top-1.5 h-3 w-3 rounded-full border-2 border-background bg-primary ring-4 ring-primary/15"
            />

            <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
              <h3 className="text-lg font-bold tracking-tight">{entry.title}</h3>
              <span className="rounded-md bg-muted px-2 py-0.5 font-mono text-xs font-semibold text-muted-foreground">
                {entry.version}
              </span>
              <time
                dateTime={entry.date}
                className="text-xs text-muted-foreground"
              >
                {formatDate(entry.date)}
              </time>
            </div>

            <ul className="mt-4 space-y-2">
              {entry.items.map((item) => (
                <li key={item.text} className="flex items-start gap-2.5 text-sm">
                  <span
                    className={`mt-0.5 shrink-0 rounded px-1.5 py-0.5 text-[0.65rem] font-bold uppercase tracking-wide ${KIND_STYLE[item.kind]}`}
                  >
                    {item.kind}
                  </span>
                  <span className="text-muted-foreground">{item.text}</span>
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ol>
    </section>
  )
}

function formatDate(iso: string): string {
  // Parsed as UTC and formatted as UTC — a bare `new Date('2026-07-14')` is
  // midnight UTC, which renders as the previous day for anyone west of it.
  return new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  })
}

roadmap-columns.source:
/**
 * <RoadmapColumns> — a three-column public roadmap.
 *
 * Shipped / In progress / Planned, each column a list of cards. Status is
 * carried by an icon plus a colour, never colour alone, so the columns stay
 * distinguishable in greyscale and for the ~8% of men with a colour vision
 * deficiency.
 */

import * as React from 'react'
import { CircleCheck, CircleDot, Circle } from 'lucide-react'

export type RoadmapStatus = 'shipped' | 'in-progress' | 'planned'

export interface RoadmapItem {
  title: string
  description?: string
  status: RoadmapStatus
  /** e.g. "Q3 2026". Shown as a small tag. */
  eta?: string
}

export interface RoadmapColumnsProps {
  items?: RoadmapItem[]
  heading?: string
  subheading?: string
  className?: string
}

const COLUMNS: { status: RoadmapStatus; label: string; icon: React.ReactNode; accent: string }[] = [
  {
    status: 'shipped',
    label: 'Shipped',
    icon: <CircleCheck className="h-4 w-4" />,
    accent: 'text-emerald-500',
  },
  {
    status: 'in-progress',
    label: 'In progress',
    icon: <CircleDot className="h-4 w-4" />,
    accent: 'text-sky-500',
  },
  {
    status: 'planned',
    label: 'Planned',
    icon: <Circle className="h-4 w-4" />,
    accent: 'text-muted-foreground',
  },
]

const DEFAULT_ITEMS: RoadmapItem[] = [
  { title: 'Marketing sections', status: 'shipped', description: 'Heroes, pricing, FAQ, footers.' },
  { title: 'Dark mode tokens', status: 'shipped', description: 'Every block reads semantic colours.' },
  { title: 'Dashboard blocks', status: 'in-progress', description: 'Shells, tables, settings.', eta: 'Q3 2026' },
  { title: 'CLI install', status: 'in-progress', description: 'Add a block straight to your repo.', eta: 'Q3 2026' },
  { title: 'Full page layouts', status: 'planned', description: 'Composed screens, not sections.', eta: 'Q4 2026' },
  { title: 'Starter templates', status: 'planned', description: 'Multi-page projects, ready to deploy.', eta: 'Q4 2026' },
  { title: 'Vue and Svelte ports', status: 'planned', eta: '2027' },
]

export function RoadmapColumns({
  items = DEFAULT_ITEMS,
  heading = 'Roadmap',
  subheading = 'What is done, what is being built, and what is next.',
  className = '',
}: RoadmapColumnsProps) {
  return (
    <section className={`mx-auto w-full max-w-7xl px-4 py-16 sm:px-6 lg:px-8 ${className}`}>
      <div className="mx-auto mb-12 max-w-2xl text-center">
        <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
          {heading}
        </h2>
        {subheading ? <p className="mt-3 text-muted-foreground">{subheading}</p> : null}
      </div>

      <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
        {COLUMNS.map((col) => {
          const columnItems = items.filter((i) => i.status === col.status)
          return (
            <div key={col.status}>
              <div className="mb-4 flex items-center gap-2">
                <span className={col.accent}>{col.icon}</span>
                <h3 className="font-semibold tracking-tight">{col.label}</h3>
                <span className="ml-auto rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground">
                  {columnItems.length}
                </span>
              </div>

              <ul className="space-y-3">
                {columnItems.map((item) => (
                  <li
                    key={item.title}
                    className="rounded-xl border border-border/60 bg-card/80 p-4 backdrop-blur transition-all hover:-translate-y-0.5 hover:shadow-md"
                  >
                    <div className="flex items-start justify-between gap-2">
                      <span className="font-medium leading-snug">{item.title}</span>
                      {item.eta ? (
                        <span className="shrink-0 rounded-md bg-muted px-1.5 py-0.5 text-[0.65rem] font-semibold text-muted-foreground">
                          {item.eta}
                        </span>
                      ) : null}
                    </div>
                    {item.description ? (
                      <p className="mt-1.5 text-sm text-muted-foreground">{item.description}</p>
                    ) : null}
                  </li>
                ))}

                {columnItems.length === 0 ? (
                  <li className="rounded-xl border border-dashed border-border/60 p-4 text-center text-sm text-muted-foreground">
                    Nothing here yet
                  </li>
                ) : null}
              </ul>
            </div>
          )
        })}
      </div>
    </section>
  )
}

team-grid.source:
/**
 * <TeamGrid> — the about-page team section, without the photo shoot.
 *
 * Initials avatars instead of photos is the load-bearing decision. Photos
 * mean an asset pipeline, a cropping convention, a retina variant, and a
 * broken-image state for the person who joined last week — the grid looks
 * unfinished until everyone has sat for the same photographer. Initials
 * drawn from the design tokens are correct on day one, theme with the
 * page, and never 404. The palette varies by person but stays inside the
 * token system, so both themes hold without a single hex value.
 *
 * Social links are real anchors with accessible names — an icon-only link
 * with no label is a mystery button to a screen reader.
 */

import * as React from 'react'
import { Github, Linkedin, Twitter } from 'lucide-react'

export interface TeamMember {
  name: string
  role: string
  bio: string
  /** Overrides the initials derived from the name. */
  initials?: string
  twitter?: string
  linkedin?: string
  github?: string
}

export interface TeamGridProps {
  heading?: string
  intro?: string
  members?: TeamMember[]
  className?: string
}

/** Token/opacity combos only — no hex, so both themes stay coherent. */
const AVATAR_STYLES = [
  'bg-primary/15 text-primary',
  'bg-secondary text-secondary-foreground',
  'bg-muted text-foreground',
  'bg-primary/10 text-primary',
  'bg-accent text-accent-foreground',
  'bg-muted/60 text-muted-foreground',
]

const DEFAULT_MEMBERS: TeamMember[] = [
  {
    name: 'Priya Raghavan',
    role: 'Co-founder & CEO',
    bio: 'Previously led platform at a payments unicorn; still reviews PRs.',
    twitter: '#', linkedin: '#', github: '#',
  },
  {
    name: 'Marcus Okafor',
    role: 'Co-founder & CTO',
    bio: 'Wrote the first commit in March 2023 and the incident runbook the week after.',
    twitter: '#', github: '#',
  },
  {
    name: 'Elena Sokolova',
    role: 'Head of Design',
    bio: 'Believes every empty state deserves as much care as the dashboard.',
    twitter: '#', linkedin: '#',
  },
  {
    name: 'Tom Whitfield',
    role: 'Staff Engineer',
    bio: 'Owns the sync engine; measures success in p99s, not features.',
    github: '#', linkedin: '#',
  },
  {
    name: 'Aisha Diallo',
    role: 'Product Manager',
    bio: 'Turns forty support tickets a week into a roadmap the team believes in.',
    twitter: '#', linkedin: '#',
  },
  {
    name: 'Daniel Kim',
    role: 'Developer Advocate',
    bio: 'If you found us through a conference talk in 2026, it was probably his.',
    twitter: '#', github: '#', linkedin: '#',
  },
]

function initialsOf(name: string): string {
  const parts = name.trim().split(/\s+/)
  const first = parts[0]?.[0] ?? ''
  const last = parts.length > 1 ? parts[parts.length - 1][0] : ''
  return (first + last).toUpperCase()
}

export function TeamGrid({
  heading = 'The people building it',
  intro = 'A small team spread across four time zones, shipping every week since 2023.',
  members = DEFAULT_MEMBERS,
  className = '',
}: TeamGridProps) {
  return (
    <section className={`mx-auto w-full max-w-5xl px-6 py-16 ${className}`}>
      <h2 className="text-2xl font-bold tracking-tight sm:text-3xl">{heading}</h2>
      <p className="mt-2 max-w-2xl text-sm text-muted-foreground sm:text-base">{intro}</p>

      <ul className="mt-10 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {members.map((member, index) => (
          <li
            key={member.name}
            className="flex flex-col rounded-2xl border border-border/60 bg-card/60 p-5 text-card-foreground"
          >
            <div className="flex items-center gap-3">
              <span
                aria-hidden
                className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-full text-sm font-bold ${
                  AVATAR_STYLES[index % AVATAR_STYLES.length]
                }`}
              >
                {member.initials ?? initialsOf(member.name)}
              </span>
              <div className="min-w-0">
                <h3 className="truncate text-sm font-semibold">{member.name}</h3>
                <p className="truncate text-xs text-muted-foreground">{member.role}</p>
              </div>
            </div>

            <p className="mt-3 flex-1 text-sm leading-relaxed text-muted-foreground">
              {member.bio}
            </p>

            <div className="mt-4 flex gap-1">
              {member.twitter ? (
                <a
                  href={member.twitter}
                  aria-label={`${member.name} on X`}
                  className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                >
                  <Twitter aria-hidden className="h-4 w-4" />
                </a>
              ) : null}
              {member.linkedin ? (
                <a
                  href={member.linkedin}
                  aria-label={`${member.name} on LinkedIn`}
                  className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                >
                  <Linkedin aria-hidden className="h-4 w-4" />
                </a>
              ) : null}
              {member.github ? (
                <a
                  href={member.github}
                  aria-label={`${member.name} on GitHub`}
                  className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                >
                  <Github aria-hidden className="h-4 w-4" />
                </a>
              ) : null}
            </div>
          </li>
        ))}
      </ul>
    </section>
  )
}

code-tabs-panel.source:
'use client'

/**
 * <CodeTabsPanel> — one install command, four package managers, real tabs.
 *
 * Every reader uses exactly one package manager, so printing all four
 * commands at once wastes three lines and forces a mental filter on every
 * snippet down the page. The tab remembers the choice the reader already
 * made everywhere else in their life — they click "pnpm" once and stop
 * seeing npm.
 *
 * This block keeps that memory local on purpose. Syncing the selection
 * across every instance on a page (and into localStorage) is a docs-
 * framework concern; wiring it here would smuggle in global state.
 */

import * as React from 'react'
import { Copy, Check } from 'lucide-react'

export interface CodeTab {
  label: string
  code: string
  language?: string
}

export interface CodeTabsPanelProps {
  tabs?: CodeTab[]
  title?: string
  className?: string
}

const DEFAULT_TABS: CodeTab[] = [
  { label: 'npm', code: 'npm install @acme/sdk', language: 'bash' },
  { label: 'pnpm', code: 'pnpm add @acme/sdk', language: 'bash' },
  { label: 'yarn', code: 'yarn add @acme/sdk', language: 'bash' },
  { label: 'bun', code: 'bun add @acme/sdk', language: 'bash' },
]

export function CodeTabsPanel({
  tabs = DEFAULT_TABS,
  title = 'Install the SDK',
  className = '',
}: CodeTabsPanelProps) {
  const [active, setActive] = React.useState(0)
  const [copied, setCopied] = React.useState(false)
  const tabRefs = React.useRef<(HTMLButtonElement | null)[]>([])
  const baseId = React.useId()

  const tab = tabs[active] ?? tabs[0]

  function select(index: number) {
    setActive(index)
    setCopied(false)
    tabRefs.current[index]?.focus()
  }

  function onKeyDown(event: React.KeyboardEvent) {
    const last = tabs.length - 1
    if (event.key === 'ArrowRight') select(active === last ? 0 : active + 1)
    else if (event.key === 'ArrowLeft') select(active === 0 ? last : active - 1)
    else if (event.key === 'Home') select(0)
    else if (event.key === 'End') select(last)
    else return
    event.preventDefault()
  }

  function copy() {
    if (typeof navigator === 'undefined' || !navigator.clipboard) return
    void navigator.clipboard.writeText(tab.code).then(() => {
      setCopied(true)
      window.setTimeout(() => setCopied(false), 2000)
    })
  }

  return (
    <div
      className={`w-full max-w-2xl overflow-hidden rounded-2xl border border-border/60 bg-zinc-950 ${className}`}
    >
      <div className="flex items-center gap-3 border-b border-white/10 px-4 py-2.5">
        <div aria-hidden className="flex gap-1.5">
          <span className="h-2.5 w-2.5 rounded-full bg-red-500/80" />
          <span className="h-2.5 w-2.5 rounded-full bg-amber-500/80" />
          <span className="h-2.5 w-2.5 rounded-full bg-emerald-500/80" />
        </div>
        <span className="truncate font-mono text-xs text-white/40">{title}</span>

        <div
          role="tablist"
          aria-label="Package manager"
          onKeyDown={onKeyDown}
          className="ml-auto flex gap-1"
        >
          {tabs.map((t, i) => (
            <button
              key={t.label}
              ref={(el) => {
                tabRefs.current[i] = el
              }}
              role="tab"
              type="button"
              id={`${baseId}-tab-${i}`}
              aria-selected={i === active}
              aria-controls={`${baseId}-panel-${i}`}
              tabIndex={i === active ? 0 : -1}
              onClick={() => select(i)}
              className={`rounded-md px-2.5 py-1 font-mono text-xs transition-colors ${
                i === active
                  ? 'bg-white/10 text-white'
                  : 'text-white/50 hover:text-white/80'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </div>

      <div
        role="tabpanel"
        id={`${baseId}-panel-${active}`}
        aria-labelledby={`${baseId}-tab-${active}`}
        className="relative"
      >
        <pre className="overflow-x-auto p-4 pr-14 text-sm leading-relaxed">
          <code
            className="font-mono text-zinc-300"
            data-language={tab.language ?? 'bash'}
          >
            <span aria-hidden className="select-none text-white/30">
              ${' '}
            </span>
            {tab.code}
          </code>
        </pre>

        <button
          type="button"
          onClick={copy}
          aria-label={copied ? 'Copied' : `Copy ${tab.label} command`}
          className="absolute right-3 top-3 inline-flex items-center rounded-md p-1.5 text-white/50 transition-colors hover:bg-white/10 hover:text-white"
        >
          {copied ? (
            <Check aria-hidden className="h-4 w-4 text-emerald-400" />
          ) : (
            <Copy aria-hidden className="h-4 w-4" />
          )}
        </button>
      </div>
    </div>
  )
}

newsletter-signup.source:
'use client'

/**
 * <NewsletterSignup> — an email capture band with inline status.
 *
 * Submission state is a small machine (`idle → submitting → done | error`)
 * rather than a pair of booleans, which is what stops the "sending" and
 * "sent" messages from ever being on screen together.
 *
 * The status line is `aria-live="polite"` and the input owns a real
 * <label>, so the outcome is announced rather than only shown — a success
 * message no one hears is a form that appears to have done nothing.
 */

import * as React from 'react'
import { Mail, Loader2, Check, AlertCircle } from 'lucide-react'

type Status = 'idle' | 'submitting' | 'done' | 'error'

export interface NewsletterSignupProps {
  heading?: string
  subheading?: string
  placeholder?: string
  ctaLabel?: string
  note?: string
  /** Resolve to subscribe, reject to show the error state. */
  onSubmit?: (email: string) => Promise<void>
  className?: string
}

export function NewsletterSignup({
  heading = 'Get the monthly digest',
  subheading = 'New sections, patterns worth stealing, and the occasional teardown. No spam.',
  placeholder = 'you@company.com',
  ctaLabel = 'Subscribe',
  note = 'Unsubscribe in one click. We never share your address.',
  onSubmit,
  className = '',
}: NewsletterSignupProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [email, setEmail] = React.useState('')
  const [status, setStatus] = React.useState<Status>('idle')

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (status === 'submitting') return

    setStatus('submitting')
    try {
      await onSubmit?.(email)
      setStatus('done')
      setEmail('')
    } catch {
      setStatus('error')
    }
  }

  return (
    <section className={`mx-auto w-full max-w-4xl px-4 py-16 sm:px-6 ${className}`}>
      <div className="relative overflow-hidden rounded-2xl border border-border/60 bg-card/80 p-8 text-center backdrop-blur sm:p-12">
        <div
          aria-hidden
          className="pointer-events-none absolute -top-24 left-1/2 h-64 w-64 -translate-x-1/2 rounded-full bg-primary/10 blur-3xl"
        />

        <div className="relative">
          <div className="mx-auto mb-4 inline-flex h-11 w-11 items-center justify-center rounded-xl bg-primary/15 text-primary">
            <Mail className="h-5 w-5" />
          </div>

          <h2 className="text-balance text-2xl font-bold tracking-tight sm:text-3xl">
            {heading}
          </h2>
          {subheading ? (
            <p className="mx-auto mt-3 max-w-lg text-muted-foreground">{subheading}</p>
          ) : null}

          <form
            onSubmit={handleSubmit}
            className="mx-auto mt-8 flex max-w-md flex-col gap-3 sm:flex-row"
          >
            <label htmlFor={`${uid}-newsletter-email`} className="sr-only">
              Email address
            </label>
            <input
              id={`${uid}-newsletter-email`}
              type="email"
              required
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder={placeholder}
              disabled={status === 'submitting'}
              className="flex-1 rounded-xl border border-border/60 bg-background px-4 py-2.5 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary disabled:opacity-60"
            />
            <button
              type="submit"
              disabled={status === 'submitting'}
              className="inline-flex shrink-0 items-center justify-center gap-2 rounded-xl bg-primary px-5 py-2.5 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-60"
            >
              {status === 'submitting' ? (
                <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" />
              ) : null}
              {status === 'submitting' ? 'Subscribing' : ctaLabel}
            </button>
          </form>

          <p aria-live="polite" className="mt-3 min-h-5 text-sm">
            {status === 'done' ? (
              <span className="inline-flex items-center gap-1.5 font-medium text-emerald-600 dark:text-emerald-400">
                <Check aria-hidden className="h-4 w-4" />
                You are on the list — check your inbox to confirm.
              </span>
            ) : null}
            {status === 'error' ? (
              <span className="inline-flex items-center gap-1.5 font-medium text-destructive">
                <AlertCircle aria-hidden className="h-4 w-4" />
                That did not go through. Try again in a moment.
              </span>
            ) : null}
          </p>

          {note && status === 'idle' ? (
            <p className="mt-2 text-xs text-muted-foreground">{note}</p>
          ) : null}
        </div>
      </div>
    </section>
  )
}

community-band.source:
/**
 * <CommunityBand> — a closing CTA that points at the places people gather.
 *
 * Three link cards plus a headline. Sits at the foot of a landing page,
 * where the job is no longer to convert but to give a visitor who is not
 * ready somewhere to go that is not "back".
 */

import * as React from 'react'
import { Github, MessagesSquare, Twitter, ArrowUpRight } from 'lucide-react'

export interface CommunityLink {
  label: string
  description: string
  href: string
  icon?: React.ReactNode
  /** Shown as a small tag — star counts, member counts. */
  meta?: string
}

export interface CommunityBandProps {
  links?: CommunityLink[]
  heading?: string
  subheading?: string
  className?: string
}

const DEFAULT_LINKS: CommunityLink[] = [
  {
    label: 'GitHub',
    description: 'Read the source, file an issue, send a pull request.',
    href: 'https://github.com',
    icon: <Github className="h-5 w-5" />,
    meta: '4.2k stars',
  },
  {
    label: 'Discord',
    description: 'Ask a question and get an answer the same day.',
    href: 'https://discord.com',
    icon: <MessagesSquare className="h-5 w-5" />,
    meta: '3.1k members',
  },
  {
    label: 'X',
    description: 'Release notes, new sections, and work in progress.',
    href: 'https://x.com',
    icon: <Twitter className="h-5 w-5" />,
    meta: '@handle',
  },
]

export function CommunityBand({
  links = DEFAULT_LINKS,
  heading = 'Come build with us',
  subheading = 'Most of what ships started as someone asking for it.',
  className = '',
}: CommunityBandProps) {
  return (
    <section className={`mx-auto w-full max-w-7xl px-4 py-16 sm:px-6 lg:px-8 ${className}`}>
      <div className="mx-auto mb-10 max-w-2xl text-center">
        <h2 className="text-balance text-3xl font-bold tracking-tight sm:text-4xl">
          {heading}
        </h2>
        {subheading ? <p className="mt-3 text-muted-foreground">{subheading}</p> : null}
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        {links.map((link) => (
          <a
            key={link.label}
            href={link.href}
            target="_blank"
            rel="noreferrer noopener"
            className="group relative flex flex-col overflow-hidden rounded-2xl border border-border/60 bg-card/80 p-6 backdrop-blur transition-all hover:-translate-y-0.5 hover:border-primary/40 hover:shadow-lg"
          >
            <div className="flex items-center gap-3">
              <span className="inline-flex h-10 w-10 items-center justify-center rounded-xl bg-muted text-foreground/80 transition-colors group-hover:bg-primary/15 group-hover:text-primary">
                {link.icon}
              </span>
              <span className="font-semibold tracking-tight">{link.label}</span>
              <ArrowUpRight
                aria-hidden
                className="ml-auto h-4 w-4 text-muted-foreground transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-primary"
              />
            </div>

            <p className="mt-3 text-sm text-muted-foreground">{link.description}</p>

            {link.meta ? (
              <span className="mt-4 self-start rounded-full bg-muted px-2.5 py-1 text-xs font-medium text-muted-foreground">
                {link.meta}
              </span>
            ) : null}
          </a>
        ))}
      </div>
    </section>
  )
}

auth-login-card.source:
'use client'

/**
 * <AuthLoginCard> — a centred email/password sign-in card.
 *
 * The password field's reveal toggle is a real <button> with an aria-label
 * that changes with state, not an icon swapped inside the input. A reveal
 * control that screen readers announce as "button" and nothing else is the
 * single most common accessibility defect in sign-in forms.
 *
 * `autoComplete` values matter more here than anywhere else in an app:
 * `username` and `current-password` are what tell a password manager this
 * is a login rather than a registration, and getting them wrong is why
 * saved credentials silently stop filling.
 */

import * as React from 'react'
import { Eye, EyeOff, Loader2, Github, Chrome } from 'lucide-react'

export interface AuthLoginCardProps {
  heading?: string
  subheading?: string
  /** Reject to surface the error message. */
  onSubmit?: (values: { email: string; password: string }) => Promise<void>
  onSocial?: (provider: 'github' | 'google') => void
  signupHref?: string
  forgotHref?: string
  className?: string
}

export function AuthLoginCard({
  heading = 'Welcome back',
  subheading = 'Sign in to pick up where you left off.',
  onSubmit,
  onSocial,
  signupHref = '/signup',
  forgotHref = '/forgot-password',
  className = '',
}: AuthLoginCardProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [email, setEmail] = React.useState('')
  const [password, setPassword] = React.useState('')
  const [visible, setVisible] = React.useState(false)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (busy) return

    setBusy(true)
    setError(null)
    try {
      await onSubmit?.({ email, password })
    } catch {
      // Deliberately vague: naming which half was wrong tells an attacker
      // whether the address exists.
      setError('That email and password combination did not work.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className={`flex min-h-96 w-full items-center justify-center p-6 ${className}`}>
      <div className="w-full max-w-sm rounded-2xl border border-border/60 bg-card/80 p-7 shadow-sm backdrop-blur">
        <div className="text-center">
          <h1 className="text-2xl font-bold tracking-tight">{heading}</h1>
          {subheading ? (
            <p className="mt-1.5 text-sm text-muted-foreground">{subheading}</p>
          ) : null}
        </div>

        {/* Social first — most returning users came in that way. */}
        <div className="mt-6 grid grid-cols-2 gap-3">
          <button
            type="button"
            onClick={() => onSocial?.('github')}
            className="inline-flex items-center justify-center gap-2 rounded-xl border border-border/60 bg-background px-3 py-2 text-sm font-medium transition-colors hover:bg-muted"
          >
            <Github aria-hidden className="h-4 w-4" />
            GitHub
          </button>
          <button
            type="button"
            onClick={() => onSocial?.('google')}
            className="inline-flex items-center justify-center gap-2 rounded-xl border border-border/60 bg-background px-3 py-2 text-sm font-medium transition-colors hover:bg-muted"
          >
            <Chrome aria-hidden className="h-4 w-4" />
            Google
          </button>
        </div>

        <div className="my-6 flex items-center gap-3">
          <span aria-hidden className="h-px flex-1 bg-border/60" />
          <span className="text-xs text-muted-foreground">or continue with email</span>
          <span aria-hidden className="h-px flex-1 bg-border/60" />
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label htmlFor={`${uid}-login-email`} className="mb-1.5 block text-sm font-medium">
              Email
            </label>
            <input
              id={`${uid}-login-email`}
              type="email"
              required
              autoComplete="username"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@company.com"
              className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
            />
          </div>

          <div>
            <div className="mb-1.5 flex items-baseline justify-between">
              <label htmlFor={`${uid}-login-password`} className="block text-sm font-medium">
                Password
              </label>
              <a
                href={forgotHref}
                className="text-xs font-medium text-muted-foreground transition-colors hover:text-foreground"
              >
                Forgot?
              </a>
            </div>

            <div className="relative">
              <input
                id={`${uid}-login-password`}
                type={visible ? 'text' : 'password'}
                required
                autoComplete="current-password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 pr-11 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
              />
              <button
                type="button"
                onClick={() => setVisible((v) => !v)}
                aria-label={visible ? 'Hide password' : 'Show password'}
                aria-pressed={visible}
                className="absolute right-1.5 top-1/2 -translate-y-1/2 rounded-lg p-2 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              >
                {visible ? (
                  <EyeOff aria-hidden className="h-4 w-4" />
                ) : (
                  <Eye aria-hidden className="h-4 w-4" />
                )}
              </button>
            </div>
          </div>

          {/* Reserved space, so an error does not shove the button down. */}
          <p aria-live="polite" className="min-h-5 text-sm text-destructive">
            {error}
          </p>

          <button
            type="submit"
            disabled={busy}
            className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-60"
          >
            {busy ? <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" /> : null}
            {busy ? 'Signing in' : 'Sign in'}
          </button>
        </form>

        <p className="mt-6 text-center text-sm text-muted-foreground">
          New here?{' '}
          <a href={signupHref} className="font-semibold text-foreground hover:underline">
            Create an account
          </a>
        </p>
      </div>
    </div>
  )
}

auth-signup-split.source:
'use client'

/**
 * <AuthSignupSplit> — registration form beside a proof panel.
 *
 * The panel is `hidden lg:flex`: below that width it is dropped entirely
 * rather than stacked above the form. Pushing a testimonial above the
 * fields on a phone means the first thing a user who came to sign up has to
 * do is scroll past marketing.
 *
 * Password rules are stated up front and validated live. Hiding the
 * requirements until submission rejects the form is how you get users who
 * try four passwords and leave.
 */

import * as React from 'react'
import { Check, Loader2, Quote, Sparkles } from 'lucide-react'

export interface AuthSignupSplitProps {
  heading?: string
  subheading?: string
  quote?: { text: string; name: string; role: string }
  onSubmit?: (values: { name: string; email: string; password: string }) => Promise<void>
  loginHref?: string
  className?: string
}

/** Each rule is a predicate so the checklist and the submit gate agree. */
const RULES: { label: string; test: (v: string) => boolean }[] = [
  { label: 'At least 8 characters', test: (v) => v.length >= 8 },
  { label: 'One number', test: (v) => /\d/.test(v) },
  { label: 'One uppercase letter', test: (v) => /[A-Z]/.test(v) },
]

export function AuthSignupSplit({
  heading = 'Create your account',
  subheading = 'Free to start. No card required.',
  quote = {
    text: 'We shipped our marketing site in four days instead of three weeks. Same team, same headcount.',
    name: 'Dana Whitfield',
    role: 'Head of Design, Globex',
  },
  onSubmit,
  loginHref = '/login',
  className = '',
}: AuthSignupSplitProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [name, setName] = React.useState('')
  const [email, setEmail] = React.useState('')
  const [password, setPassword] = React.useState('')
  const [busy, setBusy] = React.useState(false)

  const passed = RULES.map((r) => r.test(password))
  const allPassed = passed.every(Boolean)

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (busy || !allPassed) return
    setBusy(true)
    try {
      await onSubmit?.({ name, email, password })
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className={`grid min-h-96 w-full grid-cols-1 lg:grid-cols-2 ${className}`}>
      {/* ---------------------------------------------------------- *
       *  Form
       * ---------------------------------------------------------- */}
      <div className="flex items-center justify-center p-8">
        <div className="w-full max-w-sm">
          <h1 className="text-2xl font-bold tracking-tight">{heading}</h1>
          {subheading ? (
            <p className="mt-1.5 text-sm text-muted-foreground">{subheading}</p>
          ) : null}

          <form onSubmit={handleSubmit} className="mt-7 space-y-4">
            <div>
              <label htmlFor={`${uid}-signup-name`} className="mb-1.5 block text-sm font-medium">
                Full name
              </label>
              <input
                id={`${uid}-signup-name`}
                required
                autoComplete="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ada Lovelace"
                className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
              />
            </div>

            <div>
              <label htmlFor={`${uid}-signup-email`} className="mb-1.5 block text-sm font-medium">
                Work email
              </label>
              <input
                id={`${uid}-signup-email`}
                type="email"
                required
                autoComplete="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="you@company.com"
                className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
              />
            </div>

            <div>
              <label htmlFor={`${uid}-signup-password`} className="mb-1.5 block text-sm font-medium">
                Password
              </label>
              <input
                id={`${uid}-signup-password`}
                type="password"
                required
                autoComplete="new-password"
                aria-describedby={`${uid}-signup-rules`}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-primary"
              />

              <ul id={`${uid}-signup-rules`} className="mt-3 space-y-1.5">
                {RULES.map((rule, i) => (
                  <li
                    key={rule.label}
                    className={`flex items-center gap-2 text-xs transition-colors ${
                      passed[i] ? 'text-emerald-600 dark:text-emerald-400' : 'text-muted-foreground'
                    }`}
                  >
                    <span
                      aria-hidden
                      className={`flex h-4 w-4 shrink-0 items-center justify-center rounded-full transition-colors ${
                        passed[i] ? 'bg-emerald-500/15' : 'bg-muted'
                      }`}
                    >
                      {passed[i] ? <Check className="h-2.5 w-2.5" /> : null}
                    </span>
                    {rule.label}
                    <span className="sr-only">{passed[i] ? '— met' : '— not yet met'}</span>
                  </li>
                ))}
              </ul>
            </div>

            <button
              type="submit"
              disabled={busy || !allPassed}
              className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-50"
            >
              {busy ? <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" /> : null}
              {busy ? 'Creating account' : 'Create account'}
            </button>

            <p className="text-center text-xs text-muted-foreground">
              By continuing you agree to the Terms and Privacy Policy.
            </p>
          </form>

          <p className="mt-6 text-center text-sm text-muted-foreground">
            Already have an account?{' '}
            <a href={loginHref} className="font-semibold text-foreground hover:underline">
              Sign in
            </a>
          </p>
        </div>
      </div>

      {/* ---------------------------------------------------------- *
       *  Proof panel — dropped below lg rather than stacked
       * ---------------------------------------------------------- */}
      <div className="relative hidden items-center justify-center overflow-hidden border-l border-border/60 bg-gradient-to-br from-primary/10 via-card to-emerald-500/5 p-10 lg:flex">
        <div
          aria-hidden
          className="pointer-events-none absolute -right-16 -top-16 h-64 w-64 rounded-full bg-primary/20 blur-3xl"
        />

        <figure className="relative max-w-sm">
          <Quote aria-hidden className="h-8 w-8 text-primary/40" />
          <blockquote className="mt-4 text-lg font-medium leading-relaxed text-balance">
            {quote.text}
          </blockquote>
          <figcaption className="mt-5 text-sm">
            <span className="block font-semibold">{quote.name}</span>
            <span className="block text-muted-foreground">{quote.role}</span>
          </figcaption>

          <div className="mt-8 flex items-center gap-2 rounded-xl border border-border/60 bg-background/60 px-4 py-3 text-sm backdrop-blur">
            <Sparkles aria-hidden className="h-4 w-4 shrink-0 text-primary" />
            <span className="text-muted-foreground">
              Set up in under two minutes — nothing to configure.
            </span>
          </div>
        </figure>
      </div>
    </div>
  )
}

auth-otp-verify.source:
'use client'

/**
 * <AuthOtpVerify> — a six-box one-time-code input.
 *
 * The fiddly parts, all of which are why this is a block and not three
 * lines of JSX:
 *
 *  - Paste. Users paste the whole code from an email or SMS. Splitting a
 *    pasted string across the boxes is handled in `onPaste`, because
 *    without it the paste lands entirely in box one.
 *  - Backspace on an empty box moves focus back and clears the previous
 *    one, which is what every native implementation does.
 *  - Arrow keys move between boxes.
 *  - `inputMode="numeric"` and `autoComplete="one-time-code"` between them
 *    get the numeric keypad on mobile and let iOS autofill the code from
 *    the Messages app.
 *
 * The boxes are six inputs rather than one masked field because that is
 * what users expect to see; the cost is all of the above.
 */

import * as React from 'react'
import { Loader2, ShieldCheck } from 'lucide-react'

export interface AuthOtpVerifyProps {
  length?: number
  heading?: string
  /** Where the code went — shown so the user can catch a wrong address. */
  destination?: string
  onComplete?: (code: string) => Promise<void>
  onResend?: () => void
  className?: string
}

export function AuthOtpVerify({
  length = 6,
  heading = 'Check your email',
  destination = 'you@company.com',
  onComplete,
  onResend,
  className = '',
}: AuthOtpVerifyProps) {
  const [digits, setDigits] = React.useState<string[]>(() => Array(length).fill(''))
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const refs = React.useRef<Array<HTMLInputElement | null>>([])

  const code = digits.join('')

  function focusBox(index: number) {
    refs.current[Math.max(0, Math.min(length - 1, index))]?.focus()
  }

  async function submit(value: string) {
    setBusy(true)
    setError(null)
    try {
      await onComplete?.(value)
    } catch {
      setError('That code is not right. Check it and try again.')
      setDigits(Array(length).fill(''))
      focusBox(0)
    } finally {
      setBusy(false)
    }
  }

  function setDigit(index: number, value: string) {
    const next = [...digits]
    next[index] = value
    setDigits(next)

    if (value && index < length - 1) focusBox(index + 1)

    const joined = next.join('')
    if (joined.length === length && !joined.includes('')) void submit(joined)
  }

  function handleChange(index: number, raw: string) {
    // Keep only the last digit typed: typing into a filled box should
    // replace it, not be ignored because maxLength is already reached.
    const digit = raw.replace(/\D/g, '').slice(-1)
    setDigit(index, digit)
  }

  function handleKeyDown(index: number, event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Backspace' && !digits[index] && index > 0) {
      event.preventDefault()
      const next = [...digits]
      next[index - 1] = ''
      setDigits(next)
      focusBox(index - 1)
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault()
      focusBox(index - 1)
    } else if (event.key === 'ArrowRight') {
      event.preventDefault()
      focusBox(index + 1)
    }
  }

  function handlePaste(event: React.ClipboardEvent) {
    event.preventDefault()
    const pasted = event.clipboardData.getData('text').replace(/\D/g, '').slice(0, length)
    if (!pasted) return

    const next = Array(length).fill('')
    for (let i = 0; i < pasted.length; i += 1) next[i] = pasted[i]
    setDigits(next)
    focusBox(pasted.length)

    if (pasted.length === length) void submit(pasted)
  }

  return (
    <div className={`flex min-h-96 w-full items-center justify-center p-6 ${className}`}>
      <div className="w-full max-w-sm rounded-2xl border border-border/60 bg-card/80 p-7 text-center shadow-sm backdrop-blur">
        <div className="mx-auto mb-4 inline-flex h-11 w-11 items-center justify-center rounded-xl bg-primary/15 text-primary">
          <ShieldCheck className="h-5 w-5" />
        </div>

        <h1 className="text-2xl font-bold tracking-tight">{heading}</h1>
        <p className="mt-1.5 text-sm text-muted-foreground">
          We sent a {length}-digit code to{' '}
          <span className="font-medium text-foreground">{destination}</span>
        </p>

        <div
          role="group"
          aria-label={`${length}-digit verification code`}
          className="mt-7 flex justify-center gap-2"
          onPaste={handlePaste}
        >
          {digits.map((digit, i) => (
            <input
              key={i}
              ref={(el) => {
                refs.current[i] = el
              }}
              type="text"
              inputMode="numeric"
              autoComplete={i === 0 ? 'one-time-code' : 'off'}
              aria-label={`Digit ${i + 1}`}
              maxLength={1}
              disabled={busy}
              value={digit}
              onChange={(e) => handleChange(i, e.target.value)}
              onKeyDown={(e) => handleKeyDown(i, e)}
              onFocus={(e) => e.target.select()}
              className="h-12 w-11 rounded-xl border border-border/60 bg-background text-center text-lg font-semibold outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-primary disabled:opacity-60"
            />
          ))}
        </div>

        <p aria-live="polite" className="mt-4 min-h-5 text-sm">
          {busy ? (
            <span className="inline-flex items-center gap-1.5 text-muted-foreground">
              <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" />
              Verifying
            </span>
          ) : null}
          {error ? <span className="text-destructive">{error}</span> : null}
        </p>

        <p className="mt-2 text-sm text-muted-foreground">
          Did not get it?{' '}
          <button
            type="button"
            onClick={onResend}
            className="font-semibold text-foreground hover:underline"
          >
            Send another
          </button>
        </p>

        <p className="sr-only" aria-live="polite">
          {code.length} of {length} digits entered
        </p>
      </div>
    </div>
  )
}

auth-forgot-password.source:
'use client'

/**
 * <AuthForgotPassword> — request a reset link.
 *
 * The success state confirms that a link was sent *if the account exists*,
 * and says so in those words. Confirming outright that mail went to an
 * address turns this form into an account-enumeration oracle, and it is
 * the one place where the honest-sounding message is the insecure one.
 *
 * The whole card swaps to the sent state rather than showing a banner above
 * the form — leaving the field in place invites a second submit, and a
 * resend is a different action with its own cooldown.
 */

import * as React from 'react'
import { ArrowLeft, Loader2, MailCheck } from 'lucide-react'

export interface AuthForgotPasswordProps {
  heading?: string
  subheading?: string
  onSubmit?: (email: string) => Promise<void>
  loginHref?: string
  /**
   * Render as a demo inside a larger page, which drops the email field's
   * `autoFocus`. Focusing an input scrolls the browser to it, so a card in
   * a preview grid would drag the visitor down the page on load.
   */
  embedded?: boolean
  className?: string
}

export function AuthForgotPassword({
  heading = 'Reset your password',
  subheading = 'Enter your email and we will send you a link to set a new one.',
  onSubmit,
  loginHref = '/login',
  embedded = false,
  className = '',
}: AuthForgotPasswordProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [email, setEmail] = React.useState('')
  const [busy, setBusy] = React.useState(false)
  const [sent, setSent] = React.useState(false)

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (busy) return
    setBusy(true)
    try {
      await onSubmit?.(email)
      setSent(true)
    } catch {
      // Same outcome either way — see the note above.
      setSent(true)
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className={`flex min-h-96 w-full items-center justify-center p-6 ${className}`}>
      <div className="w-full max-w-sm rounded-2xl border border-border/60 bg-card/80 p-7 shadow-sm backdrop-blur">
        {sent ? (
          <div className="text-center">
            <div className="mx-auto mb-4 inline-flex h-11 w-11 items-center justify-center rounded-xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
              <MailCheck className="h-5 w-5" />
            </div>
            <h1 className="text-2xl font-bold tracking-tight">Check your inbox</h1>
            <p className="mt-2 text-sm text-muted-foreground">
              If an account exists for{' '}
              <span className="font-medium text-foreground">{email}</span>, a reset
              link is on its way. It expires in 30 minutes.
            </p>

            <button
              type="button"
              onClick={() => setSent(false)}
              className="mt-6 text-sm font-semibold hover:underline"
            >
              Use a different address
            </button>
          </div>
        ) : (
          <>
            <h1 className="text-2xl font-bold tracking-tight">{heading}</h1>
            <p className="mt-1.5 text-sm text-muted-foreground">{subheading}</p>

            <form onSubmit={handleSubmit} className="mt-6 space-y-4">
              <div>
                <label htmlFor={`${uid}-forgot-email`} className="mb-1.5 block text-sm font-medium">
                  Email
                </label>
                <input
                  id={`${uid}-forgot-email`}
                  type="email"
                  required
                  autoFocus={!embedded}
                  autoComplete="username"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="you@company.com"
                  className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
                />
              </div>

              <button
                type="submit"
                disabled={busy}
                className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-60"
              >
                {busy ? <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" /> : null}
                {busy ? 'Sending' : 'Send reset link'}
              </button>
            </form>
          </>
        )}

        <a
          href={loginHref}
          className="mt-6 inline-flex w-full items-center justify-center gap-1.5 text-sm text-muted-foreground transition-colors hover:text-foreground"
        >
          <ArrowLeft aria-hidden className="h-4 w-4" />
          Back to sign in
        </a>
      </div>
    </div>
  )
}

auth-reset-password.source:
'use client'

/**
 * <AuthResetPassword> — set a new password, with a strength meter.
 *
 * Strength is scored from character-class variety and length. That is a
 * rough heuristic and deliberately presented as one — the meter is advice,
 * and the only hard gate is the minimum length plus the confirm match.
 * Blocking submission on a strength score frustrates users with genuinely
 * strong passphrases that happen to be all lowercase.
 *
 * The confirmation mismatch is announced through `aria-live` and marked
 * with `aria-invalid`, so it is not conveyed by a red border alone.
 */

import * as React from 'react'
import { Eye, EyeOff, Loader2, KeyRound } from 'lucide-react'

export interface AuthResetPasswordProps {
  heading?: string
  minLength?: number
  onSubmit?: (password: string) => Promise<void>
  className?: string
}

const LEVELS = [
  { label: 'Too short', bar: 'bg-border', text: 'text-muted-foreground' },
  { label: 'Weak', bar: 'bg-red-500', text: 'text-red-500' },
  { label: 'Fair', bar: 'bg-amber-500', text: 'text-amber-500' },
  { label: 'Good', bar: 'bg-sky-500', text: 'text-sky-500' },
  { label: 'Strong', bar: 'bg-emerald-500', text: 'text-emerald-500' },
]

/** 0–4. Length gets the most weight; variety breaks the ties. */
function scorePassword(value: string, minLength: number): number {
  if (value.length < minLength) return 0

  let score = 1
  if (value.length >= minLength + 4) score += 1
  if (/[A-Z]/.test(value) && /[a-z]/.test(value)) score += 1
  if (/\d/.test(value) && /[^A-Za-z0-9]/.test(value)) score += 1

  return Math.min(4, score)
}

export function AuthResetPassword({
  heading = 'Choose a new password',
  minLength = 8,
  onSubmit,
  className = '',
}: AuthResetPasswordProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [password, setPassword] = React.useState('')
  const [confirm, setConfirm] = React.useState('')
  const [visible, setVisible] = React.useState(false)
  const [busy, setBusy] = React.useState(false)

  const score = scorePassword(password, minLength)
  const level = LEVELS[score]
  const longEnough = password.length >= minLength
  const mismatch = confirm.length > 0 && confirm !== password
  const canSubmit = longEnough && confirm === password && !busy

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (!canSubmit) return
    setBusy(true)
    try {
      await onSubmit?.(password)
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className={`flex min-h-96 w-full items-center justify-center p-6 ${className}`}>
      <div className="w-full max-w-sm rounded-2xl border border-border/60 bg-card/80 p-7 shadow-sm backdrop-blur">
        <div className="mb-5 inline-flex h-11 w-11 items-center justify-center rounded-xl bg-primary/15 text-primary">
          <KeyRound className="h-5 w-5" />
        </div>

        <h1 className="text-2xl font-bold tracking-tight">{heading}</h1>
        <p className="mt-1.5 text-sm text-muted-foreground">
          It needs at least {minLength} characters. Longer beats complicated.
        </p>

        <form onSubmit={handleSubmit} className="mt-6 space-y-4">
          <div>
            <label htmlFor={`${uid}-reset-password`} className="mb-1.5 block text-sm font-medium">
              New password
            </label>
            <div className="relative">
              <input
                id={`${uid}-reset-password`}
                type={visible ? 'text' : 'password'}
                required
                autoComplete="new-password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 pr-11 text-sm outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-primary"
              />
              <button
                type="button"
                onClick={() => setVisible((v) => !v)}
                aria-label={visible ? 'Hide password' : 'Show password'}
                aria-pressed={visible}
                className="absolute right-1.5 top-1/2 -translate-y-1/2 rounded-lg p-2 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              >
                {visible ? (
                  <EyeOff aria-hidden className="h-4 w-4" />
                ) : (
                  <Eye aria-hidden className="h-4 w-4" />
                )}
              </button>
            </div>

            {/* Strength meter */}
            <div className="mt-2.5 flex items-center gap-2">
              <div aria-hidden className="flex flex-1 gap-1">
                {[1, 2, 3, 4].map((step) => (
                  <span
                    key={step}
                    className={`h-1 flex-1 rounded-full transition-colors ${
                      score >= step ? level.bar : 'bg-border/60'
                    }`}
                  />
                ))}
              </div>
              <span className={`w-16 text-right text-xs font-medium ${level.text}`}>
                {password.length > 0 ? level.label : ''}
              </span>
            </div>
          </div>

          <div>
            <label htmlFor={`${uid}-reset-confirm`} className="mb-1.5 block text-sm font-medium">
              Confirm password
            </label>
            <input
              id={`${uid}-reset-confirm`}
              type={visible ? 'text' : 'password'}
              required
              autoComplete="new-password"
              aria-invalid={mismatch}
              aria-describedby={`${uid}-reset-confirm-error`}
              value={confirm}
              onChange={(e) => setConfirm(e.target.value)}
              className={`w-full rounded-xl border bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow focus-visible:ring-2 ${
                mismatch
                  ? 'border-destructive focus-visible:ring-destructive'
                  : 'border-border/60 focus-visible:ring-primary'
              }`}
            />
            <p
              id={`${uid}-reset-confirm-error`}
              aria-live="polite"
              className="mt-1.5 min-h-4 text-xs text-destructive"
            >
              {mismatch ? 'The two passwords do not match.' : ''}
            </p>
          </div>

          <button
            type="submit"
            disabled={!canSubmit}
            className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-50"
          >
            {busy ? <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" /> : null}
            {busy ? 'Saving' : 'Set new password'}
          </button>
        </form>
      </div>
    </div>
  )
}

auth-two-factor.source:
'use client'

/**
 * <AuthTwoFactor> — the authenticator-app challenge, with a backup route.
 *
 * The backup-code escape hatch is the point of this block. A 2FA screen
 * without one locks out every user who changes phone, and support tickets
 * for account recovery are the most expensive kind there is. It is a mode
 * switch rather than a second form so only one input is ever submittable.
 *
 * "Trust this device" is off by default. A checkbox that weakens a security
 * control should never be pre-ticked.
 */

import * as React from 'react'
import { Loader2, Smartphone, KeySquare } from 'lucide-react'

export interface AuthTwoFactorProps {
  heading?: string
  onVerify?: (value: { code: string; mode: Mode; trustDevice: boolean }) => Promise<void>
  /**
   * Render as a demo inside a larger page, which drops the code field's
   * `autoFocus`. Focusing an input scrolls the browser to it, so a card in
   * a preview grid would drag the visitor down the page on load.
   */
  embedded?: boolean
  className?: string
}

type Mode = 'app' | 'backup'

export function AuthTwoFactor({
  heading = 'Two-factor authentication',
  onVerify,
  embedded = false,
  className = '',
}: AuthTwoFactorProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [mode, setMode] = React.useState<Mode>('app')
  const [code, setCode] = React.useState('')
  const [trustDevice, setTrustDevice] = React.useState(false)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)

  const isApp = mode === 'app'
  const expected = isApp ? 6 : 10
  const ready = code.trim().length >= (isApp ? expected : 8)

  function switchMode(next: Mode) {
    setMode(next)
    setCode('')
    setError(null)
  }

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (!ready || busy) return

    setBusy(true)
    setError(null)
    try {
      await onVerify?.({ code, mode, trustDevice })
    } catch {
      setError(isApp ? 'That code is not valid or has expired.' : 'That backup code was not recognised.')
      setCode('')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className={`flex min-h-96 w-full items-center justify-center p-6 ${className}`}>
      <div className="w-full max-w-sm rounded-2xl border border-border/60 bg-card/80 p-7 shadow-sm backdrop-blur">
        <div className="mb-5 inline-flex h-11 w-11 items-center justify-center rounded-xl bg-primary/15 text-primary">
          {isApp ? <Smartphone className="h-5 w-5" /> : <KeySquare className="h-5 w-5" />}
        </div>

        <h1 className="text-2xl font-bold tracking-tight">{heading}</h1>
        <p className="mt-1.5 text-sm text-muted-foreground">
          {isApp
            ? 'Enter the 6-digit code from your authenticator app.'
            : 'Enter one of the backup codes you saved when you set 2FA up.'}
        </p>

        <form onSubmit={handleSubmit} className="mt-6 space-y-4">
          <div>
            <label htmlFor={`${uid}-tfa-code`} className="mb-1.5 block text-sm font-medium">
              {isApp ? 'Authentication code' : 'Backup code'}
            </label>
            <input
              id={`${uid}-tfa-code`}
              // Backup codes contain letters and dashes, so only the app
              // code gets the numeric keypad and the OTP autofill hint.
              inputMode={isApp ? 'numeric' : 'text'}
              autoComplete={isApp ? 'one-time-code' : 'off'}
              autoFocus={!embedded}
              required
              maxLength={expected}
              value={code}
              onChange={(e) => setCode(isApp ? e.target.value.replace(/\D/g, '') : e.target.value)}
              placeholder={isApp ? '123456' : 'xxxx-xxxx'}
              className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 text-center font-mono text-lg tracking-[0.3em] outline-none transition-shadow placeholder:tracking-normal placeholder:font-sans placeholder:text-sm placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
            />
          </div>

          <p aria-live="polite" className="min-h-5 text-sm text-destructive">
            {error}
          </p>

          <label className="flex items-start gap-2.5 text-sm">
            <input
              type="checkbox"
              checked={trustDevice}
              onChange={(e) => setTrustDevice(e.target.checked)}
              className="mt-0.5 h-4 w-4 shrink-0 rounded border-border/60 accent-[hsl(var(--primary))]"
            />
            <span className="text-muted-foreground">
              Trust this device for 30 days
            </span>
          </label>

          <button
            type="submit"
            disabled={!ready || busy}
            className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-50"
          >
            {busy ? <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" /> : null}
            {busy ? 'Verifying' : 'Verify'}
          </button>
        </form>

        <div className="mt-6 border-t border-border/60 pt-4 text-center">
          <button
            type="button"
            onClick={() => switchMode(isApp ? 'backup' : 'app')}
            className="text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
          >
            {isApp ? 'Lost your device? Use a backup code' : 'Use your authenticator app instead'}
          </button>
        </div>
      </div>
    </div>
  )
}

dashboard-stat-cards.source:
/**
 * <DashboardStatCards> — a KPI row with period-over-period deltas.
 *
 * Two things this gets right that hand-rolled versions usually do not:
 *
 *  - Direction is an arrow *and* a colour, and "up" is not assumed to be
 *    good. Churn rising is red while revenue rising is green, so each stat
 *    declares whether an increase is positive via `higherIsBetter`.
 *  - The delta reads "+12.5% vs last month", not a bare "+12.5%". A
 *    percentage with no baseline is the most common lie on a dashboard.
 *
 * Server component — nothing here holds state.
 */

import * as React from 'react'
import { TrendingUp, TrendingDown, Users, DollarSign, Activity, UserMinus } from 'lucide-react'

export interface Stat {
  label: string
  value: string
  /** Signed percentage change, e.g. `-2.4`. */
  delta: number
  /** False for metrics where a rise is bad — churn, latency, cost. */
  higherIsBetter?: boolean
  icon?: React.ReactNode
  /** Baseline the delta is measured against. */
  comparedTo?: string
}

export interface DashboardStatCardsProps {
  stats?: Stat[]
  className?: string
}

const DEFAULT_STATS: Stat[] = [
  {
    label: 'Monthly revenue',
    value: '$48,290',
    delta: 12.5,
    icon: <DollarSign className="h-4 w-4" />,
  },
  {
    label: 'Active users',
    value: '2,847',
    delta: 8.2,
    icon: <Users className="h-4 w-4" />,
  },
  {
    label: 'Avg. session',
    value: '4m 32s',
    delta: -3.1,
    icon: <Activity className="h-4 w-4" />,
  },
  {
    label: 'Churn rate',
    value: '1.8%',
    delta: -0.4,
    higherIsBetter: false,
    icon: <UserMinus className="h-4 w-4" />,
  },
]

export function DashboardStatCards({
  stats = DEFAULT_STATS,
  className = '',
}: DashboardStatCardsProps) {
  return (
    <div className={`grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 ${className}`}>
      {stats.map((stat) => {
        const rising = stat.delta >= 0
        const higherIsBetter = stat.higherIsBetter ?? true
        const good = rising === higherIsBetter

        return (
          <div
            key={stat.label}
            className="rounded-2xl border border-border/60 bg-card/80 p-5 backdrop-blur transition-shadow hover:shadow-md"
          >
            <div className="flex items-center justify-between gap-3">
              <span className="text-sm font-medium text-muted-foreground">{stat.label}</span>
              {stat.icon ? (
                <span className="inline-flex h-8 w-8 items-center justify-center rounded-lg bg-muted text-muted-foreground">
                  {stat.icon}
                </span>
              ) : null}
            </div>

            <div className="mt-3 text-3xl font-extrabold tracking-tight">{stat.value}</div>

            <div className="mt-2 flex items-center gap-1.5 text-xs">
              <span
                className={`inline-flex items-center gap-0.5 font-semibold ${
                  good ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-600 dark:text-red-400'
                }`}
              >
                {rising ? (
                  <TrendingUp aria-hidden className="h-3.5 w-3.5" />
                ) : (
                  <TrendingDown aria-hidden className="h-3.5 w-3.5" />
                )}
                {rising ? '+' : ''}
                {stat.delta}%
              </span>
              <span className="text-muted-foreground">
                vs {stat.comparedTo ?? 'last month'}
              </span>
            </div>
          </div>
        )
      })}
    </div>
  )
}

dashboard-activity-feed.source:
/**
 * <DashboardActivityFeed> — a "what just happened" panel.
 *
 * Timestamps render as relative text ("2h ago") inside a <time> carrying
 * the absolute ISO value, so hovering gives the exact moment and a screen
 * reader is not left with a figure that silently goes stale.
 *
 * Each row's actor avatar is initials rather than an image. An activity
 * feed is the worst place for avatar images: a dozen network requests for
 * decoration, each one a layout shift when it lands.
 */

import * as React from 'react'
import { GitCommit, MessageSquare, UserPlus, CreditCard, ArrowRight } from 'lucide-react'

export type ActivityKind = 'commit' | 'comment' | 'signup' | 'payment'

export interface ActivityEvent {
  id: string
  kind: ActivityKind
  actor: string
  /** Verb phrase — the actor's name is prefixed automatically. */
  action: string
  target?: string
  /** ISO timestamp. */
  at: string
}

export interface DashboardActivityFeedProps {
  events?: ActivityEvent[]
  heading?: string
  /** "now" for relative formatting. Pass a fixed value to keep it testable. */
  now?: Date
  viewAllHref?: string
  className?: string
}

const KIND_STYLE: Record<ActivityKind, { icon: React.ReactNode; tone: string }> = {
  commit: { icon: <GitCommit className="h-3.5 w-3.5" />, tone: 'bg-sky-500/15 text-sky-500' },
  comment: {
    icon: <MessageSquare className="h-3.5 w-3.5" />,
    tone: 'bg-violet-500/15 text-violet-500',
  },
  signup: { icon: <UserPlus className="h-3.5 w-3.5" />, tone: 'bg-emerald-500/15 text-emerald-500' },
  payment: { icon: <CreditCard className="h-3.5 w-3.5" />, tone: 'bg-amber-500/15 text-amber-500' },
}

const DEFAULT_NOW = new Date('2026-08-08T12:00:00Z')

const DEFAULT_EVENTS: ActivityEvent[] = [
  {
    id: '1',
    kind: 'payment',
    actor: 'Northwind Ltd',
    action: 'upgraded to',
    target: 'Team annual',
    at: '2026-08-08T11:42:00Z',
  },
  {
    id: '2',
    kind: 'signup',
    actor: 'Marco Silva',
    action: 'created an account',
    at: '2026-08-08T09:15:00Z',
  },
  {
    id: '3',
    kind: 'comment',
    actor: 'Priya Raman',
    action: 'commented on',
    target: 'Billing migration',
    at: '2026-08-07T16:30:00Z',
  },
  {
    id: '4',
    kind: 'commit',
    actor: 'Alex Chen',
    action: 'pushed 3 commits to',
    target: 'main',
    at: '2026-08-07T08:05:00Z',
  },
  {
    id: '5',
    kind: 'signup',
    actor: 'Dana Whitfield',
    action: 'created an account',
    at: '2026-08-05T13:20:00Z',
  },
]

/** Coarse relative time — exact enough for a feed, no dependency needed. */
function relativeTime(iso: string, now: Date): string {
  const seconds = Math.round((now.getTime() - new Date(iso).getTime()) / 1000)
  const units: [number, Intl.RelativeTimeFormatUnit][] = [
    [60, 'second'],
    [3600, 'minute'],
    [86400, 'hour'],
    [604800, 'day'],
    [2629800, 'week'],
    [Infinity, 'month'],
  ]

  const divisors = [1, 60, 3600, 86400, 604800, 2629800]
  const format = new Intl.RelativeTimeFormat('en', { numeric: 'auto' })

  for (let i = 0; i < units.length; i += 1) {
    if (Math.abs(seconds) < units[i][0]) {
      return format.format(-Math.round(seconds / divisors[i]), units[i][1])
    }
  }
  return format.format(-Math.round(seconds / 2629800), 'month')
}

export function DashboardActivityFeed({
  events = DEFAULT_EVENTS,
  heading = 'Recent activity',
  now = DEFAULT_NOW,
  viewAllHref,
  className = '',
}: DashboardActivityFeedProps) {
  return (
    <section
      className={`rounded-2xl border border-border/60 bg-card/80 backdrop-blur ${className}`}
    >
      <div className="flex items-center justify-between gap-4 border-b border-border/60 px-5 py-4">
        <h2 className="font-semibold tracking-tight">{heading}</h2>
        {viewAllHref ? (
          <a
            href={viewAllHref}
            className="inline-flex items-center gap-1 text-sm text-muted-foreground transition-all hover:gap-2 hover:text-foreground"
          >
            View all
            <ArrowRight aria-hidden className="h-3.5 w-3.5" />
          </a>
        ) : null}
      </div>

      <ul className="divide-y divide-border/40">
        {events.map((event) => {
          const style = KIND_STYLE[event.kind]
          return (
            <li key={event.id} className="flex items-start gap-3 px-5 py-3.5 transition-colors hover:bg-muted/30">
              <span
                aria-hidden
                className={`mt-0.5 inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-lg ${style.tone}`}
              >
                {style.icon}
              </span>

              <div className="min-w-0 flex-1">
                <p className="text-sm leading-snug">
                  <span className="font-medium">{event.actor}</span>{' '}
                  <span className="text-muted-foreground">{event.action}</span>
                  {event.target ? <span className="font-medium"> {event.target}</span> : null}
                </p>
                <time
                  dateTime={event.at}
                  title={new Date(event.at).toUTCString()}
                  className="mt-0.5 block text-xs text-muted-foreground"
                >
                  {relativeTime(event.at, now)}
                </time>
              </div>
            </li>
          )
        })}
      </ul>
    </section>
  )
}

dashboard-page-header.source:
/**
 * <DashboardPageHeader> — title, breadcrumb, tabs and page actions.
 *
 * The strip that sits above every inner page of an admin tool. Worth having
 * as one block because the alignment is fiddly: the title and the action
 * buttons share a baseline on wide screens and must stack cleanly on
 * narrow ones, and the tab row has to sit flush with the bottom border so
 * the active indicator lands on the rule rather than floating above it.
 *
 * The active tab uses `aria-current="page"`, not just a colour change.
 */

import * as React from 'react'
import { ChevronRight, Plus, Download } from 'lucide-react'

export interface Crumb {
  label: string
  href?: string
}

export interface HeaderTab {
  label: string
  href?: string
  count?: number
}

export interface DashboardPageHeaderProps {
  title?: string
  description?: string
  crumbs?: Crumb[]
  tabs?: HeaderTab[]
  activeTab?: string
  primaryAction?: { label: string; icon?: React.ReactNode }
  secondaryAction?: { label: string; icon?: React.ReactNode }
  className?: string
}

const DEFAULT_CRUMBS: Crumb[] = [
  { label: 'Dashboard', href: '#' },
  { label: 'Customers' },
]

const DEFAULT_TABS: HeaderTab[] = [
  { label: 'All', count: 2847 },
  { label: 'Active', count: 2401 },
  { label: 'Trialing', count: 312 },
  { label: 'Churned', count: 134 },
]

export function DashboardPageHeader({
  title = 'Customers',
  description = 'Everyone who has ever signed up, and where they stand today.',
  crumbs = DEFAULT_CRUMBS,
  tabs = DEFAULT_TABS,
  activeTab = 'All',
  primaryAction = { label: 'Add customer', icon: <Plus className="h-4 w-4" /> },
  secondaryAction = { label: 'Export', icon: <Download className="h-4 w-4" /> },
  className = '',
}: DashboardPageHeaderProps) {
  return (
    <header className={`border-b border-border/60 ${className}`}>
      {crumbs.length > 0 ? (
        <nav aria-label="Breadcrumb">
          <ol className="flex flex-wrap items-center gap-1 text-sm text-muted-foreground">
            {crumbs.map((crumb, i) => {
              const last = i === crumbs.length - 1
              return (
                <li key={crumb.label} className="flex items-center gap-1">
                  {crumb.href && !last ? (
                    <a href={crumb.href} className="transition-colors hover:text-foreground">
                      {crumb.label}
                    </a>
                  ) : (
                    <span aria-current={last ? 'page' : undefined} className={last ? 'text-foreground' : ''}>
                      {crumb.label}
                    </span>
                  )}
                  {!last ? <ChevronRight aria-hidden className="h-3.5 w-3.5" /> : null}
                </li>
              )
            })}
          </ol>
        </nav>
      ) : null}

      <div className="mt-3 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <h1 className="text-2xl font-bold tracking-tight">{title}</h1>
          {description ? (
            <p className="mt-1 text-sm text-muted-foreground">{description}</p>
          ) : null}
        </div>

        <div className="flex shrink-0 items-center gap-2">
          {secondaryAction ? (
            <button
              type="button"
              className="inline-flex items-center gap-2 rounded-xl border border-border/60 bg-background px-3.5 py-2 text-sm font-medium transition-colors hover:bg-muted"
            >
              {secondaryAction.icon}
              {secondaryAction.label}
            </button>
          ) : null}

          {primaryAction ? (
            <button
              type="button"
              className="inline-flex items-center gap-2 rounded-xl bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90"
            >
              {primaryAction.icon}
              {primaryAction.label}
            </button>
          ) : null}
        </div>
      </div>

      {tabs.length > 0 ? (
        <nav aria-label="Views" className="-mb-px mt-5 flex gap-1 overflow-x-auto">
          {tabs.map((tab) => {
            const active = tab.label === activeTab
            return (
              <a
                key={tab.label}
                href={tab.href ?? '#'}
                aria-current={active ? 'page' : undefined}
                className={`inline-flex shrink-0 items-center gap-2 border-b-2 px-3.5 py-2.5 text-sm font-medium transition-colors ${
                  active
                    ? 'border-primary text-foreground'
                    : 'border-transparent text-muted-foreground hover:border-border hover:text-foreground'
                }`}
              >
                {tab.label}
                {typeof tab.count === 'number' ? (
                  <span
                    className={`rounded-full px-1.5 py-0.5 text-xs ${
                      active ? 'bg-primary/15 text-primary' : 'bg-muted text-muted-foreground'
                    }`}
                  >
                    {tab.count.toLocaleString('en-US')}
                  </span>
                ) : null}
              </a>
            )
          })}
        </nav>
      ) : null}
    </header>
  )
}

kanban-board.source:
/**
 * <KanbanBoard> — a four-column project board.
 *
 * This is the layout contract, not the interaction. Dragging is behavior
 * you wire to your own state and whichever dnd library you already use —
 * shipping one here would mean shipping a store too, and ripping a store
 * out is harder than adding one. What the markup does settle: column
 * width, horizontal overflow on small screens, and everything a card must
 * carry — priority, tags, owner, date or PR — without growing past a
 * glance, because a card you have to read line by line defeats the board.
 *
 * "Blocked" is a tint plus an icon and a reason, never colour alone.
 */

import * as React from 'react'
import { Plus, GitPullRequest, OctagonAlert, CalendarDays } from 'lucide-react'

export type KanbanPriority = 'high' | 'medium' | 'low'

export interface KanbanTask {
  id: string
  title: string
  priority: KanbanPriority
  tags: string[]
  assignee: { name: string; initials: string }
  /** ISO date — rendered as a short due date. */
  due?: string
  /** Pull request number — rendered as a PR link instead of a date. */
  pr?: number
  /** Short reason the task is stuck, e.g. "Waiting on DNS". */
  blocked?: string
}

export interface KanbanColumn {
  id: string
  label: string
  tasks: KanbanTask[]
}

export interface KanbanBoardProps {
  columns?: KanbanColumn[]
  className?: string
}

const PRIORITY: Record<KanbanPriority, { label: string; dot: string }> = {
  high: { label: 'High', dot: 'bg-rose-500' },
  medium: { label: 'Medium', dot: 'bg-amber-500' },
  low: { label: 'Low', dot: 'bg-sky-500' },
}

const ALEX = { name: 'Alex Chen', initials: 'AC' }
const DANA = { name: 'Dana Whitfield', initials: 'DW' }
const ROSA = { name: 'Rosa Martínez', initials: 'RM' }
const PRIYA = { name: 'Priya Raman', initials: 'PR' }
const SAM = { name: 'Sam Okafor', initials: 'SO' }
const JONAS = { name: 'Jonas Weber', initials: 'JW' }

const DEFAULT_COLUMNS: KanbanColumn[] = [
  {
    id: 'backlog',
    label: 'Backlog',
    tasks: [
      { id: 'HL-341', title: 'Rate-limit the export endpoint', priority: 'high', tags: ['api', 'infra'], assignee: ALEX, due: '2026-08-19' },
      { id: 'HL-338', title: 'Empty-state illustrations for search', priority: 'medium', tags: ['design'], assignee: DANA, due: '2026-08-21' },
      { id: 'HL-329', title: 'Migrate billing webhooks to v2', priority: 'low', tags: ['billing'], assignee: ROSA, due: '2026-08-25' },
    ],
  },
  {
    id: 'in-progress',
    label: 'In progress',
    tasks: [
      { id: 'HL-322', title: 'Checkout: support SEPA direct debit', priority: 'high', tags: ['payments'], assignee: PRIYA, pr: 482 },
      { id: 'HL-318', title: 'Rotate staging TLS certificates', priority: 'medium', tags: ['infra'], assignee: SAM, due: '2026-08-14', blocked: 'Waiting on DNS delegation' },
      { id: 'HL-325', title: 'New onboarding checklist', priority: 'medium', tags: ['growth'], assignee: JONAS, due: '2026-08-15' },
    ],
  },
  {
    id: 'in-review',
    label: 'In review',
    tasks: [
      { id: 'HL-314', title: 'Fix duplicate invoice emails', priority: 'high', tags: ['billing'], assignee: ROSA, pr: 479 },
      { id: 'HL-311', title: 'Dashboard loading skeletons', priority: 'low', tags: ['design'], assignee: DANA, pr: 476 },
    ],
  },
  {
    id: 'done',
    label: 'Done',
    tasks: [
      { id: 'HL-306', title: 'Upgrade CI runners to Node 22', priority: 'medium', tags: ['infra'], assignee: ALEX, due: '2026-08-11' },
      { id: 'HL-302', title: 'Search relevance tuning', priority: 'high', tags: ['search'], assignee: PRIYA, due: '2026-08-12' },
    ],
  },
]

const DATE_FORMAT = new Intl.DateTimeFormat('en', {
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
})

export function KanbanBoard({ columns = DEFAULT_COLUMNS, className = '' }: KanbanBoardProps) {
  return (
    <div className={`overflow-x-auto ${className}`}>
      <div className="flex min-w-max items-start gap-4 p-1">
        {columns.map((column) => (
          <section key={column.id} aria-label={column.label} className="w-72 shrink-0">
            <div className="mb-3 flex items-center gap-2 px-1">
              <h2 className="text-sm font-semibold tracking-tight">{column.label}</h2>
              <span className="rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground">
                {column.tasks.length}
              </span>
              <button
                type="button"
                aria-label={`Add task to ${column.label}`}
                className="ml-auto inline-flex h-6 w-6 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              >
                <Plus aria-hidden className="h-4 w-4" />
              </button>
            </div>

            <ul className="space-y-2.5">
              {column.tasks.map((task) => {
                const priority = PRIORITY[task.priority]
                return (
                  <li
                    key={task.id}
                    className={`rounded-xl border p-3 transition-colors ${
                      task.blocked
                        ? 'border-destructive/40 bg-destructive/5'
                        : 'border-border/60 bg-card hover:border-border'
                    }`}
                  >
                    <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                      <span aria-hidden className={`h-2 w-2 rounded-full ${priority.dot}`} />
                      <span>{priority.label}</span>
                      <span className="ml-auto font-mono text-[0.65rem]">{task.id}</span>
                    </div>

                    <p className="mt-1.5 text-sm font-medium leading-snug">{task.title}</p>

                    {task.blocked ? (
                      <p className="mt-1.5 flex items-center gap-1.5 text-xs font-medium text-destructive">
                        <OctagonAlert aria-hidden className="h-3.5 w-3.5" />
                        Blocked — {task.blocked}
                      </p>
                    ) : null}

                    <div className="mt-2 flex flex-wrap gap-1">
                      {task.tags.map((tag) => (
                        <span
                          key={tag}
                          className="rounded-md bg-secondary px-1.5 py-0.5 text-[0.65rem] font-medium text-secondary-foreground"
                        >
                          {tag}
                        </span>
                      ))}
                    </div>

                    <div className="mt-2.5 flex items-center justify-between">
                      <span
                        title={task.assignee.name}
                        className="inline-flex h-6 w-6 items-center justify-center rounded-full bg-muted text-[0.6rem] font-semibold text-muted-foreground"
                      >
                        {task.assignee.initials}
                        <span className="sr-only">{task.assignee.name}</span>
                      </span>

                      {task.pr ? (
                        <a
                          href={`https://github.com/acme/hoverlab/pull/${task.pr}`}
                          className="inline-flex items-center gap-1 text-xs text-muted-foreground transition-colors hover:text-foreground"
                        >
                          <GitPullRequest aria-hidden className="h-3.5 w-3.5" />
                          #{task.pr}
                        </a>
                      ) : task.due ? (
                        <time
                          dateTime={task.due}
                          className="inline-flex items-center gap-1 text-xs text-muted-foreground"
                        >
                          <CalendarDays aria-hidden className="h-3.5 w-3.5" />
                          {DATE_FORMAT.format(new Date(task.due))}
                        </time>
                      ) : null}
                    </div>
                  </li>
                )
              })}
            </ul>
          </section>
        ))}
      </div>
    </div>
  )
}

activity-timeline.source:
/**
 * <ActivityTimeline> — an audit log grouped by day.
 *
 * Forty events in a flat list of identical grey dots is technically a
 * timeline and practically unreadable. Two decisions carry all the weight
 * here: events sit under day headings, so "when" is answered by position
 * before you read a single row; and the node icon varies by event type,
 * so a deploy, an incident and a settings change stay distinguishable
 * mid-scroll. Detail attaches inline, in a card under its own row — never
 * a modal, which would cost the reader their place in the sequence.
 */

import * as React from 'react'
import { Rocket, MessageSquare, UserPlus, Settings2, Siren } from 'lucide-react'

export type TimelineKind = 'deploy' | 'comment' | 'member' | 'settings' | 'incident'

export interface TimelineEvent {
  id: string
  kind: TimelineKind
  actor: string
  /** Verb phrase — the actor's name is prefixed automatically. */
  action: string
  target?: string
  /** ISO timestamp; the visible label is the short form. */
  at: string
  timeLabel: string
  /** Optional inline detail card, e.g. a two-line config diff. */
  detail?: { removed: string; added: string }
}

export interface TimelineGroup {
  label: string
  events: TimelineEvent[]
}

export interface ActivityTimelineProps {
  groups?: TimelineGroup[]
  heading?: string
  className?: string
}

const KIND_STYLE: Record<TimelineKind, { icon: React.ReactNode; tone: string }> = {
  deploy: { icon: <Rocket className="h-3.5 w-3.5" />, tone: 'bg-sky-500/15 text-sky-500' },
  comment: {
    icon: <MessageSquare className="h-3.5 w-3.5" />,
    tone: 'bg-violet-500/15 text-violet-500',
  },
  member: { icon: <UserPlus className="h-3.5 w-3.5" />, tone: 'bg-emerald-500/15 text-emerald-500' },
  settings: {
    icon: <Settings2 className="h-3.5 w-3.5" />,
    tone: 'bg-amber-500/15 text-amber-500',
  },
  incident: { icon: <Siren className="h-3.5 w-3.5" />, tone: 'bg-destructive/15 text-destructive' },
}

const DEFAULT_GROUPS: TimelineGroup[] = [
  {
    label: 'Today, Aug 13',
    events: [
      {
        id: '1',
        kind: 'deploy',
        actor: 'Alex Chen',
        action: 'deployed',
        target: 'web@2026.08.13-r2',
        at: '2026-08-13T14:05:00Z',
        timeLabel: '14:05',
      },
      {
        id: '2',
        kind: 'settings',
        actor: 'Priya Raman',
        action: 'changed retention in',
        target: 'audit-log config',
        at: '2026-08-13T11:20:00Z',
        timeLabel: '11:20',
        detail: { removed: 'retention_days: 30', added: 'retention_days: 90' },
      },
      {
        id: '3',
        kind: 'comment',
        actor: 'Dana Whitfield',
        action: 'commented on',
        target: 'Billing migration RFC',
        at: '2026-08-13T09:42:00Z',
        timeLabel: '09:42',
      },
    ],
  },
  {
    label: 'Yesterday',
    events: [
      {
        id: '4',
        kind: 'member',
        actor: 'Rosa Martínez',
        action: 'invited',
        target: 'jonas@acme.dev',
        at: '2026-08-12T16:30:00Z',
        timeLabel: '16:30',
      },
      {
        id: '5',
        kind: 'incident',
        actor: 'Sam Okafor',
        action: 'resolved',
        target: 'INC-208: elevated 5xx on api-eu',
        at: '2026-08-12T08:15:00Z',
        timeLabel: '08:15',
      },
    ],
  },
  {
    label: 'Aug 10',
    events: [
      {
        id: '6',
        kind: 'deploy',
        actor: 'Alex Chen',
        action: 'rolled back',
        target: 'web@2026.08.10-r1',
        at: '2026-08-10T19:47:00Z',
        timeLabel: '19:47',
      },
      {
        id: '7',
        kind: 'settings',
        actor: 'Priya Raman',
        action: 'enabled',
        target: 'SSO enforcement',
        at: '2026-08-10T10:05:00Z',
        timeLabel: '10:05',
      },
    ],
  },
]

export function ActivityTimeline({
  groups = DEFAULT_GROUPS,
  heading = 'Activity',
  className = '',
}: ActivityTimelineProps) {
  return (
    <section className={`rounded-2xl border border-border/60 bg-card/80 p-5 backdrop-blur ${className}`}>
      <h2 className="font-semibold tracking-tight">{heading}</h2>

      <div className="mt-4 space-y-6">
        {groups.map((group) => (
          <div key={group.label}>
            <h3 className="mb-3 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
              {group.label}
            </h3>

            <ul className="relative ml-3.5 space-y-4 border-l border-border/60 pl-6">
              {group.events.map((event) => {
                const style = KIND_STYLE[event.kind]
                return (
                  <li key={event.id} className="relative">
                    <span
                      aria-hidden
                      className={`absolute -left-[2.35rem] top-0 inline-flex h-7 w-7 items-center justify-center rounded-full ring-4 ring-background ${style.tone}`}
                    >
                      {style.icon}
                    </span>

                    <p className="text-sm leading-snug">
                      <span className="font-medium">{event.actor}</span>{' '}
                      <span className="text-muted-foreground">{event.action}</span>
                      {event.target ? (
                        <span className="font-medium text-primary underline-offset-2 hover:underline">
                          {' '}
                          {event.target}
                        </span>
                      ) : null}
                    </p>
                    <time dateTime={event.at} className="mt-0.5 block text-xs text-muted-foreground">
                      {event.timeLabel}
                    </time>

                    {event.detail ? (
                      <div className="mt-2 rounded-lg border border-border/60 bg-muted/40 p-3 font-mono text-xs leading-relaxed">
                        <p className="text-destructive">- {event.detail.removed}</p>
                        <p className="text-emerald-600 dark:text-emerald-400">
                          + {event.detail.added}
                        </p>
                      </div>
                    ) : null}
                  </li>
                )
              })}
            </ul>
          </div>
        ))}
      </div>
    </section>
  )
}

calendar-month.source:
/**
 * <CalendarMonth> — a month grid for August 2026.
 *
 * A month view's job is density without noise. Event chips truncate to a
 * single line and never wrap, so every week keeps the same row height;
 * when a day holds more than the cell can carry, the overflow collapses
 * to "+2 more" instead of stretching one row and knocking the whole
 * month out of rhythm. Out-of-month days render muted but present —
 * hiding them would break the weekday columns. Colour marks which
 * calendar an event belongs to, and the legend above the grid states
 * that mapping instead of leaving it to be guessed.
 */

import * as React from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'

export type CalendarId = 'product' | 'design' | 'personal'

export interface CalendarEvent {
  label: string
  calendar: CalendarId
}

export interface CalendarMonthProps {
  /** Events keyed by ISO date (YYYY-MM-DD). */
  events?: Record<string, CalendarEvent[]>
  className?: string
}

const CAL_STYLE: Record<CalendarId, { label: string; chip: string; dot: string }> = {
  product: { label: 'Product', chip: 'bg-primary/15 text-primary', dot: 'bg-primary' },
  design: { label: 'Design', chip: 'bg-sky-500/15 text-sky-500', dot: 'bg-sky-500' },
  personal: { label: 'Personal', chip: 'bg-emerald-500/15 text-emerald-500', dot: 'bg-emerald-500' },
}

const DEFAULT_EVENTS: Record<string, CalendarEvent[]> = {
  '2026-08-03': [{ label: 'Sprint 42 kickoff', calendar: 'product' }],
  '2026-08-06': [{ label: 'Design crit', calendar: 'design' }],
  '2026-08-13': [{ label: 'v3.1 release', calendar: 'product' }],
  '2026-08-17': [{ label: 'Flight to Lisbon', calendar: 'personal' }],
  '2026-08-20': [
    { label: 'Roadmap review', calendar: 'product' },
    { label: 'Portfolio review', calendar: 'design' },
    { label: 'Dentist, 15:30', calendar: 'personal' },
    { label: '1:1 with Sam', calendar: 'product' },
  ],
  '2026-08-27': [{ label: 'Q3 planning', calendar: 'product' }],
}

const WEEKDAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
]

const TODAY_ISO = '2026-08-13'
/** Monday before Aug 1, 2026 (a Saturday) — the grid's first cell. */
const FIRST_CELL_UTC = Date.UTC(2026, 6, 27)
const MAX_CHIPS = 2

interface DayCell {
  iso: string
  day: number
  monthName: string
  inMonth: boolean
}

function buildWeeks(): DayCell[][] {
  const cells: DayCell[] = Array.from({ length: 42 }, (_, i) => {
    const date = new Date(FIRST_CELL_UTC + i * 86_400_000)
    return {
      iso: date.toISOString().slice(0, 10),
      day: date.getUTCDate(),
      monthName: MONTHS[date.getUTCMonth()],
      inMonth: date.getUTCMonth() === 7,
    }
  })
  return Array.from({ length: 6 }, (_, w) => cells.slice(w * 7, w * 7 + 7))
}

const WEEKS = buildWeeks()

export function CalendarMonth({ events = DEFAULT_EVENTS, className = '' }: CalendarMonthProps) {
  return (
    <section className={`w-full ${className}`}>
      <div className="mb-4 flex flex-wrap items-center gap-3">
        <h2 className="text-lg font-bold tracking-tight">August 2026</h2>

        <ul className="flex items-center gap-3 text-xs text-muted-foreground sm:ml-4">
          {(Object.keys(CAL_STYLE) as CalendarId[]).map((id) => (
            <li key={id} className="flex items-center gap-1.5">
              <span aria-hidden className={`h-2 w-2 rounded-full ${CAL_STYLE[id].dot}`} />
              {CAL_STYLE[id].label}
            </li>
          ))}
        </ul>

        <div className="ml-auto flex items-center gap-1">
          <button
            type="button"
            aria-label="Previous month"
            className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-border/60 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
          >
            <ChevronLeft aria-hidden className="h-4 w-4" />
          </button>
          <button
            type="button"
            aria-label="Next month"
            className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-border/60 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
          >
            <ChevronRight aria-hidden className="h-4 w-4" />
          </button>
          <button
            type="button"
            className="ml-1 rounded-lg border border-border/60 px-3 py-1.5 text-sm font-medium transition-colors hover:bg-muted"
          >
            Today
          </button>
        </div>
      </div>

      <div
        role="grid"
        aria-label="August 2026"
        className="overflow-hidden rounded-xl border border-border/60"
      >
        <div role="row" className="grid grid-cols-7 gap-px bg-border/60">
          {WEEKDAYS.map((weekday) => (
            <span
              key={weekday}
              role="columnheader"
              className="bg-muted/60 px-2 py-2 text-center text-xs font-semibold text-muted-foreground"
            >
              {weekday}
            </span>
          ))}
        </div>

        {WEEKS.map((week) => (
          <div key={week[0].iso} role="row" className="grid grid-cols-7 gap-px border-t border-border/60 bg-border/60">
            {week.map((cell) => {
              const dayEvents = events[cell.iso] ?? []
              const overflow = dayEvents.length - MAX_CHIPS
              const isToday = cell.iso === TODAY_ISO
              return (
                <div key={cell.iso} role="gridcell" className={cell.inMonth ? 'bg-card' : 'bg-muted/30'}>
                  <button
                    type="button"
                    aria-label={`${cell.day} ${cell.monthName} 2026${
                      dayEvents.length ? `, ${dayEvents.length} event${dayEvents.length > 1 ? 's' : ''}` : ''
                    }`}
                    aria-current={isToday ? 'date' : undefined}
                    className="flex min-h-[5.25rem] w-full flex-col items-stretch gap-1 p-1.5 text-left transition-colors hover:bg-muted/50"
                  >
                    <span
                      className={`inline-flex h-6 w-6 items-center justify-center self-start rounded-full text-xs ${
                        isToday
                          ? 'font-bold ring-2 ring-primary'
                          : cell.inMonth
                            ? 'font-medium'
                            : 'text-muted-foreground/60'
                      }`}
                    >
                      {cell.day}
                    </span>

                    {dayEvents.slice(0, MAX_CHIPS).map((event) => (
                      <span
                        key={event.label}
                        className={`block truncate rounded px-1.5 py-0.5 text-[0.65rem] font-medium ${CAL_STYLE[event.calendar].chip}`}
                      >
                        {event.label}
                      </span>
                    ))}

                    {overflow > 0 ? (
                      <span className="px-1.5 text-[0.65rem] font-medium text-muted-foreground">
                        +{overflow} more
                      </span>
                    ) : null}
                  </button>
                </div>
              )
            })}
          </div>
        ))}
      </div>
    </section>
  )
}

data-table-sortable.source:
'use client'

/**
 * <DataTableSortable> — a sortable, selectable table.
 *
 * The details that make this worth lifting rather than rewriting:
 *
 *  - `aria-sort` on the sorted column header. Without it a screen reader
 *    user has no way to know the table is ordered at all, let alone by what.
 *  - The header checkbox goes *indeterminate* when the selection is
 *    partial. `indeterminate` is a DOM property with no HTML attribute, so
 *    it has to be set through a ref — which is exactly why hand-rolled
 *    versions skip it and end up with a header box that lies.
 *  - Sorting is stable and type-aware: numbers compare numerically, strings
 *    through `localeCompare`. A numeric column sorted lexically puts 100
 *    before 9, and it is always caught late.
 *  - Selection survives sorting, because it is keyed by row id rather than
 *    by index.
 */

import * as React from 'react'
import { ChevronUp, ChevronDown, ChevronsUpDown, MoreHorizontal } from 'lucide-react'

export interface Column<T> {
  key: keyof T & string
  header: string
  sortable?: boolean
  align?: 'left' | 'right'
  /** Custom cell rendering — falls back to the raw value. */
  render?: (row: T) => React.ReactNode
}

export interface Row {
  id: string
  name: string
  email: string
  plan: string
  mrr: number
  status: 'active' | 'trialing' | 'churned'
}

export interface DataTableSortableProps {
  rows?: Row[]
  columns?: Column<Row>[]
  className?: string
}

const STATUS_TONE: Record<Row['status'], string> = {
  active: 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400',
  trialing: 'bg-sky-500/15 text-sky-600 dark:text-sky-400',
  churned: 'bg-muted text-muted-foreground',
}

const DEFAULT_ROWS: Row[] = [
  { id: '1', name: 'Northwind Ltd', email: 'ops@northwind.com', plan: 'Team', mrr: 490, status: 'active' },
  { id: '2', name: 'Contoso', email: 'billing@contoso.io', plan: 'Pro', mrr: 190, status: 'active' },
  { id: '3', name: 'Initech', email: 'admin@initech.dev', plan: 'Pro', mrr: 190, status: 'trialing' },
  { id: '4', name: 'Globex', email: 'finance@globex.co', plan: 'Team', mrr: 980, status: 'active' },
  { id: '5', name: 'Umbrella', email: 'it@umbrella.org', plan: 'Free', mrr: 0, status: 'churned' },
  { id: '6', name: 'Vandelay', email: 'george@vandelay.com', plan: 'Pro', mrr: 90, status: 'trialing' },
]

const DEFAULT_COLUMNS: Column<Row>[] = [
  { key: 'name', header: 'Customer', sortable: true },
  { key: 'plan', header: 'Plan', sortable: true },
  {
    key: 'mrr',
    header: 'MRR',
    sortable: true,
    align: 'right',
    render: (row) => (row.mrr === 0 ? '—' : `$${row.mrr.toLocaleString('en-US')}`),
  },
  {
    key: 'status',
    header: 'Status',
    sortable: true,
    render: (row) => (
      <span
        className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium capitalize ${STATUS_TONE[row.status]}`}
      >
        {row.status}
      </span>
    ),
  },
]

type Direction = 'asc' | 'desc'

export function DataTableSortable({
  rows = DEFAULT_ROWS,
  columns = DEFAULT_COLUMNS,
  className = '',
}: DataTableSortableProps) {
  const [sortKey, setSortKey] = React.useState<keyof Row & string>('name')
  const [direction, setDirection] = React.useState<Direction>('asc')
  const [selected, setSelected] = React.useState<Set<string>>(() => new Set())

  const headerBox = React.useRef<HTMLInputElement>(null)

  const allSelected = rows.length > 0 && selected.size === rows.length
  const someSelected = selected.size > 0 && !allSelected

  // `indeterminate` has no HTML attribute — React cannot set it as a prop,
  // so it has to be written to the DOM node directly.
  React.useEffect(() => {
    if (headerBox.current) headerBox.current.indeterminate = someSelected
  }, [someSelected])

  const sorted = React.useMemo(() => {
    const copy = [...rows]
    copy.sort((a, b) => {
      const left = a[sortKey]
      const right = b[sortKey]

      const result =
        typeof left === 'number' && typeof right === 'number'
          ? left - right
          : String(left).localeCompare(String(right))

      return direction === 'asc' ? result : -result
    })
    return copy
  }, [rows, sortKey, direction])

  function toggleSort(key: keyof Row & string) {
    if (key === sortKey) {
      setDirection((d) => (d === 'asc' ? 'desc' : 'asc'))
    } else {
      setSortKey(key)
      setDirection('asc')
    }
  }

  function toggleRow(id: string) {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  function toggleAll() {
    setSelected(allSelected ? new Set() : new Set(rows.map((r) => r.id)))
  }

  return (
    <div className={`overflow-hidden rounded-2xl border border-border/60 bg-card/60 ${className}`}>
      {selected.size > 0 ? (
        <div
          aria-live="polite"
          className="flex items-center gap-3 border-b border-border/60 bg-primary/5 px-4 py-2.5 text-sm"
        >
          <span className="font-medium">{selected.size} selected</span>
          <button type="button" className="text-muted-foreground hover:text-foreground">
            Export
          </button>
          <button type="button" className="text-destructive hover:underline">
            Delete
          </button>
          <button
            type="button"
            onClick={() => setSelected(new Set())}
            className="ml-auto text-muted-foreground hover:text-foreground"
          >
            Clear
          </button>
        </div>
      ) : null}

      <div className="overflow-x-auto">
        <table className="w-full border-collapse text-sm">
          <thead>
            <tr className="border-b border-border/60 bg-muted/30">
              <th scope="col" className="w-10 px-4 py-3">
                <input
                  ref={headerBox}
                  type="checkbox"
                  checked={allSelected}
                  onChange={toggleAll}
                  aria-label={allSelected ? 'Deselect all rows' : 'Select all rows'}
                  className="h-4 w-4 rounded border-border/60 accent-[hsl(var(--primary))]"
                />
              </th>

              {columns.map((col) => {
                const isSorted = col.key === sortKey
                return (
                  <th
                    key={col.key}
                    scope="col"
                    aria-sort={
                      isSorted ? (direction === 'asc' ? 'ascending' : 'descending') : 'none'
                    }
                    className={`px-4 py-3 font-semibold ${
                      col.align === 'right' ? 'text-right' : 'text-left'
                    }`}
                  >
                    {col.sortable ? (
                      <button
                        type="button"
                        onClick={() => toggleSort(col.key)}
                        className={`inline-flex items-center gap-1 transition-colors hover:text-foreground ${
                          col.align === 'right' ? 'flex-row-reverse' : ''
                        } ${isSorted ? '' : 'text-muted-foreground'}`}
                      >
                        {col.header}
                        {isSorted ? (
                          direction === 'asc' ? (
                            <ChevronUp aria-hidden className="h-3.5 w-3.5" />
                          ) : (
                            <ChevronDown aria-hidden className="h-3.5 w-3.5" />
                          )
                        ) : (
                          <ChevronsUpDown aria-hidden className="h-3.5 w-3.5 opacity-40" />
                        )}
                      </button>
                    ) : (
                      col.header
                    )}
                  </th>
                )
              })}

              <th scope="col" className="w-10 px-4 py-3">
                <span className="sr-only">Actions</span>
              </th>
            </tr>
          </thead>

          <tbody>
            {sorted.map((row) => {
              const isSelected = selected.has(row.id)
              return (
                <tr
                  key={row.id}
                  data-state={isSelected ? 'selected' : undefined}
                  className={`border-b border-border/40 last:border-0 transition-colors ${
                    isSelected ? 'bg-primary/5' : 'hover:bg-muted/30'
                  }`}
                >
                  <td className="px-4 py-3">
                    <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={() => toggleRow(row.id)}
                      aria-label={`Select ${row.name}`}
                      className="h-4 w-4 rounded border-border/60 accent-[hsl(var(--primary))]"
                    />
                  </td>

                  {columns.map((col) => (
                    <td
                      key={col.key}
                      className={`px-4 py-3 ${col.align === 'right' ? 'text-right tabular-nums' : ''}`}
                    >
                      {col.render ? (
                        col.render(row)
                      ) : col.key === 'name' ? (
                        <span>
                          <span className="block font-medium">{row.name}</span>
                          <span className="block text-xs text-muted-foreground">{row.email}</span>
                        </span>
                      ) : (
                        String(row[col.key])
                      )}
                    </td>
                  ))}

                  <td className="px-4 py-3">
                    <button
                      type="button"
                      aria-label={`Actions for ${row.name}`}
                      className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                    >
                      <MoreHorizontal aria-hidden className="h-4 w-4" />
                    </button>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>
    </div>
  )
}

data-table-toolbar.source:
'use client'

/**
 * <DataTableToolbar> — search, filter chips and a view switch.
 *
 * The row that sits above a table and does the work nobody budgets for.
 *
 * Active filters render as removable chips rather than staying hidden
 * inside dropdowns. A filtered table that looks identical to an unfiltered
 * one is how users conclude their data has vanished — the chips, and the
 * "Clear all" beside them, are the fix.
 *
 * The search input is `type="search"` with a label, so it gets the native
 * clear affordance and is announced as a search field.
 */

import * as React from 'react'
import { Search, SlidersHorizontal, X, LayoutGrid, List, Plus } from 'lucide-react'

export interface FilterChip {
  id: string
  label: string
  value: string
}

export interface DataTableToolbarProps {
  placeholder?: string
  initialFilters?: FilterChip[]
  resultCount?: number
  onSearch?: (term: string) => void
  onFiltersChange?: (filters: FilterChip[]) => void
  className?: string
}

const DEFAULT_FILTERS: FilterChip[] = [
  { id: 'status', label: 'Status', value: 'Active' },
  { id: 'plan', label: 'Plan', value: 'Pro or Team' },
]

export function DataTableToolbar({
  placeholder = 'Search customers',
  initialFilters = DEFAULT_FILTERS,
  resultCount = 2847,
  onSearch,
  onFiltersChange,
  className = '',
}: DataTableToolbarProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [term, setTerm] = React.useState('')
  const [filters, setFilters] = React.useState<FilterChip[]>(initialFilters)
  const [view, setView] = React.useState<'list' | 'grid'>('list')

  function updateFilters(next: FilterChip[]) {
    setFilters(next)
    onFiltersChange?.(next)
  }

  function handleSearch(value: string) {
    setTerm(value)
    onSearch?.(value)
  }

  return (
    <div className={`space-y-3 ${className}`}>
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
        <div className="relative flex-1">
          <label htmlFor={`${uid}-table-search`} className="sr-only">
            {placeholder}
          </label>
          <Search
            aria-hidden
            className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
          />
          <input
            id={`${uid}-table-search`}
            type="search"
            value={term}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder={placeholder}
            className="w-full rounded-xl border border-border/60 bg-background py-2 pl-9 pr-3 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
          />
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            className="inline-flex items-center gap-2 rounded-xl border border-border/60 bg-background px-3 py-2 text-sm font-medium transition-colors hover:bg-muted"
          >
            <SlidersHorizontal aria-hidden className="h-4 w-4" />
            Filters
            {filters.length > 0 ? (
              <span className="rounded-full bg-primary/15 px-1.5 py-0.5 text-xs font-semibold text-primary">
                {filters.length}
              </span>
            ) : null}
          </button>

          {/* View switch — a radio group, since the options are exclusive. */}
          <div
            role="radiogroup"
            aria-label="View mode"
            className="flex rounded-xl border border-border/60 bg-background p-0.5"
          >
            {(
              [
                { id: 'list', icon: <List className="h-4 w-4" />, label: 'List' },
                { id: 'grid', icon: <LayoutGrid className="h-4 w-4" />, label: 'Grid' },
              ] as const
            ).map((option) => (
              <button
                key={option.id}
                type="button"
                role="radio"
                aria-checked={view === option.id}
                aria-label={`${option.label} view`}
                onClick={() => setView(option.id)}
                className={`rounded-lg p-1.5 transition-colors ${
                  view === option.id
                    ? 'bg-muted text-foreground'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                {option.icon}
              </button>
            ))}
          </div>

          <button
            type="button"
            className="inline-flex items-center gap-2 rounded-xl bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90"
          >
            <Plus aria-hidden className="h-4 w-4" />
            Add
          </button>
        </div>
      </div>

      {/* Active filters — never leave a filtered table looking unfiltered. */}
      {filters.length > 0 ? (
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-xs text-muted-foreground">Filtered by</span>

          {filters.map((filter) => (
            <span
              key={filter.id}
              className="inline-flex items-center gap-1.5 rounded-full border border-border/60 bg-card px-2.5 py-1 text-xs"
            >
              <span className="text-muted-foreground">{filter.label}:</span>
              <span className="font-medium">{filter.value}</span>
              <button
                type="button"
                onClick={() => updateFilters(filters.filter((f) => f.id !== filter.id))}
                aria-label={`Remove ${filter.label} filter`}
                className="rounded-full p-0.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              >
                <X aria-hidden className="h-3 w-3" />
              </button>
            </span>
          ))}

          <button
            type="button"
            onClick={() => updateFilters([])}
            className="text-xs font-medium text-muted-foreground underline-offset-2 transition-colors hover:text-foreground hover:underline"
          >
            Clear all
          </button>

          <span aria-live="polite" className="ml-auto text-xs text-muted-foreground">
            {resultCount.toLocaleString('en-US')} results
          </span>
        </div>
      ) : null}
    </div>
  )
}

data-table-pagination.source:
'use client'

/**
 * <DataTablePagination> — page size, range summary and page controls.
 *
 * The page-number window is the fiddly part: with 200 pages you cannot
 * render 200 buttons, and naive slicing makes the control jump around as
 * you move through it. `pageWindow()` keeps a fixed-width run of numbers
 * centred on the current page, clamped at both ends, with ellipses only
 * where pages are genuinely skipped — so the control stays the same width
 * from page 1 to page 200.
 *
 * The "Showing 1–25 of 2,847" line is announced through `aria-live`,
 * because for a keyboard or screen-reader user the only feedback that a
 * page change worked is the range text.
 */

import * as React from 'react'
import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react'

export interface DataTablePaginationProps {
  totalItems?: number
  pageSizeOptions?: number[]
  initialPageSize?: number
  onChange?: (state: { page: number; pageSize: number }) => void
  className?: string
}

/**
 * A fixed-width run of page numbers centred on `page`.
 * Returns numbers and `'gap'` markers, never more than `span + 2` entries.
 */
function pageWindow(page: number, pageCount: number, span = 5): Array<number | 'gap'> {
  if (pageCount <= span + 2) {
    return Array.from({ length: pageCount }, (_, i) => i + 1)
  }

  const half = Math.floor(span / 2)
  let start = Math.max(1, page - half)
  const end = Math.min(pageCount, start + span - 1)

  // Re-clamp so the window keeps its width at the top end.
  start = Math.max(1, end - span + 1)

  const out: Array<number | 'gap'> = []
  if (start > 1) out.push(1, 'gap')
  for (let i = start; i <= end; i += 1) out.push(i)
  if (end < pageCount) out.push('gap', pageCount)

  return out
}

export function DataTablePagination({
  totalItems = 2847,
  pageSizeOptions = [10, 25, 50, 100],
  initialPageSize = 25,
  onChange,
  className = '',
}: DataTablePaginationProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [page, setPage] = React.useState(1)
  const [pageSize, setPageSize] = React.useState(initialPageSize)

  const pageCount = Math.max(1, Math.ceil(totalItems / pageSize))
  const first = totalItems === 0 ? 0 : (page - 1) * pageSize + 1
  const last = Math.min(page * pageSize, totalItems)

  function goTo(next: number) {
    const clamped = Math.max(1, Math.min(pageCount, next))
    setPage(clamped)
    onChange?.({ page: clamped, pageSize })
  }

  function changeSize(size: number) {
    // Keep the first visible record in view rather than resetting to page 1
    // — jumping back to the top after "show 100" loses the user's place.
    const anchor = (page - 1) * pageSize
    const nextPage = Math.floor(anchor / size) + 1
    setPageSize(size)
    setPage(nextPage)
    onChange?.({ page: nextPage, pageSize: size })
  }

  // Named `pages`, not `window` — shadowing the global inside a component
  // is legal and reliably confusing.
  const pages = pageWindow(page, pageCount)

  return (
    <div
      className={`flex flex-col items-center justify-between gap-4 border-t border-border/60 px-4 py-3 sm:flex-row ${className}`}
    >
      <div className="flex items-center gap-2 text-sm">
        <label htmlFor={`${uid}-page-size`} className="text-muted-foreground">
          Rows per page
        </label>
        <select
          id={`${uid}-page-size`}
          value={pageSize}
          onChange={(e) => changeSize(Number(e.target.value))}
          className="rounded-lg border border-border/60 bg-background px-2 py-1 text-sm outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          {pageSizeOptions.map((size) => (
            <option key={size} value={size}>
              {size}
            </option>
          ))}
        </select>
      </div>

      <p aria-live="polite" className="text-sm text-muted-foreground">
        Showing <span className="font-medium text-foreground">{first.toLocaleString('en-US')}</span>–
        <span className="font-medium text-foreground">{last.toLocaleString('en-US')}</span> of{' '}
        <span className="font-medium text-foreground">{totalItems.toLocaleString('en-US')}</span>
      </p>

      <nav aria-label="Pagination" className="flex items-center gap-1">
        <PageButton onClick={() => goTo(1)} disabled={page === 1} label="First page">
          <ChevronsLeft aria-hidden className="h-4 w-4" />
        </PageButton>
        <PageButton onClick={() => goTo(page - 1)} disabled={page === 1} label="Previous page">
          <ChevronLeft aria-hidden className="h-4 w-4" />
        </PageButton>

        {pages.map((entry, i) =>
          entry === 'gap' ? (
            <span key={`gap-${i}`} aria-hidden className="px-1.5 text-sm text-muted-foreground">
              …
            </span>
          ) : (
            <button
              key={entry}
              type="button"
              onClick={() => goTo(entry)}
              aria-label={`Page ${entry}`}
              aria-current={entry === page ? 'page' : undefined}
              className={`h-8 min-w-8 rounded-lg px-2 text-sm font-medium transition-colors ${
                entry === page
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:bg-muted hover:text-foreground'
              }`}
            >
              {entry}
            </button>
          ),
        )}

        <PageButton onClick={() => goTo(page + 1)} disabled={page === pageCount} label="Next page">
          <ChevronRight aria-hidden className="h-4 w-4" />
        </PageButton>
        <PageButton onClick={() => goTo(pageCount)} disabled={page === pageCount} label="Last page">
          <ChevronsRight aria-hidden className="h-4 w-4" />
        </PageButton>
      </nav>
    </div>
  )
}

function PageButton({
  onClick,
  disabled,
  label,
  children,
}: {
  onClick: () => void
  disabled: boolean
  label: string
  children: React.ReactNode
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      aria-label={label}
      className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
    >
      {children}
    </button>
  )
}

data-table-expandable.source:
'use client'

/**
 * <DataTableExpandable> — rows that open to reveal detail.
 *
 * The alternative to a detail drawer when the extra fields are few enough
 * to read in place. Two things worth copying rather than reinventing:
 *
 *  - The detail lives in its own <tr> with a `colSpan` covering the table,
 *    which is the only way to put a full-width panel inside a table without
 *    breaking column alignment.
 *  - The trigger carries `aria-expanded` and `aria-controls` pointing at
 *    the detail row's id. A chevron that rotates but announces nothing
 *    leaves a screen-reader user unable to tell the row opened.
 *
 * Multiple rows can be open at once — this is for comparing, and an
 * accordion that closes the row you were reading defeats the purpose.
 */

import * as React from 'react'
import { ChevronRight, Mail, Calendar, CreditCard } from 'lucide-react'

export interface ExpandableRow {
  id: string
  name: string
  email: string
  plan: string
  status: string
  joined: string
  lastPayment: string
  notes: string
}

export interface DataTableExpandableProps {
  rows?: ExpandableRow[]
  className?: string
}

const DEFAULT_ROWS: ExpandableRow[] = [
  {
    id: '1',
    name: 'Northwind Ltd',
    email: 'ops@northwind.com',
    plan: 'Team',
    status: 'Active',
    joined: '12 Mar 2024',
    lastPayment: '$490 on 1 Aug 2026',
    notes: 'Migrated from the legacy plan in June. Renewal is annual.',
  },
  {
    id: '2',
    name: 'Contoso',
    email: 'billing@contoso.io',
    plan: 'Pro',
    status: 'Active',
    joined: '3 Jan 2025',
    lastPayment: '$190 on 28 Jul 2026',
    notes: 'Requested SSO — flagged for the Team upgrade conversation.',
  },
  {
    id: '3',
    name: 'Initech',
    email: 'admin@initech.dev',
    plan: 'Pro',
    status: 'Trialing',
    joined: '22 Jul 2026',
    lastPayment: '—',
    notes: 'Trial ends 21 Aug. Two seats active out of five.',
  },
]

export function DataTableExpandable({
  rows = DEFAULT_ROWS,
  className = '',
}: DataTableExpandableProps) {
  const [open, setOpen] = React.useState<Set<string>>(() => new Set())

  function toggle(id: string) {
    setOpen((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  return (
    <div className={`overflow-hidden rounded-2xl border border-border/60 bg-card/60 ${className}`}>
      <div className="overflow-x-auto">
        <table className="w-full border-collapse text-sm">
          <thead>
            <tr className="border-b border-border/60 bg-muted/30">
              <th scope="col" className="w-10 px-4 py-3">
                <span className="sr-only">Expand</span>
              </th>
              <th scope="col" className="px-4 py-3 text-left font-semibold">
                Customer
              </th>
              <th scope="col" className="px-4 py-3 text-left font-semibold">
                Plan
              </th>
              <th scope="col" className="px-4 py-3 text-left font-semibold">
                Status
              </th>
            </tr>
          </thead>

          <tbody>
            {rows.map((row) => {
              const expanded = open.has(row.id)
              const detailId = `row-detail-${row.id}`

              return (
                <React.Fragment key={row.id}>
                  <tr
                    className={`border-b border-border/40 transition-colors ${
                      expanded ? 'bg-muted/20' : 'hover:bg-muted/30'
                    }`}
                  >
                    <td className="px-4 py-3">
                      <button
                        type="button"
                        onClick={() => toggle(row.id)}
                        aria-expanded={expanded}
                        aria-controls={detailId}
                        aria-label={`${expanded ? 'Collapse' : 'Expand'} details for ${row.name}`}
                        className="rounded-lg p-1 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                      >
                        <ChevronRight
                          aria-hidden
                          className={`h-4 w-4 transition-transform duration-200 ${
                            expanded ? 'rotate-90' : ''
                          }`}
                        />
                      </button>
                    </td>

                    <td className="px-4 py-3">
                      <span className="block font-medium">{row.name}</span>
                      <span className="block text-xs text-muted-foreground">{row.email}</span>
                    </td>
                    <td className="px-4 py-3 text-muted-foreground">{row.plan}</td>
                    <td className="px-4 py-3 text-muted-foreground">{row.status}</td>
                  </tr>

                  {expanded ? (
                    <tr id={detailId} className="border-b border-border/40 bg-muted/10">
                      {/* Spans every column so the panel is full width without
                          disturbing the header's column widths. */}
                      <td colSpan={4} className="px-4 py-4">
                        <div className="grid gap-4 sm:grid-cols-3">
                          <DetailField
                            icon={<Calendar className="h-3.5 w-3.5" />}
                            label="Joined"
                            value={row.joined}
                          />
                          <DetailField
                            icon={<CreditCard className="h-3.5 w-3.5" />}
                            label="Last payment"
                            value={row.lastPayment}
                          />
                          <DetailField
                            icon={<Mail className="h-3.5 w-3.5" />}
                            label="Billing contact"
                            value={row.email}
                          />
                        </div>

                        <p className="mt-4 rounded-xl bg-background/60 p-3 text-sm text-muted-foreground">
                          {row.notes}
                        </p>
                      </td>
                    </tr>
                  ) : null}
                </React.Fragment>
              )
            })}
          </tbody>
        </table>
      </div>
    </div>
  )
}

function DetailField({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode
  label: string
  value: string
}) {
  return (
    <div>
      <span className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
        {icon}
        {label}
      </span>
      <span className="mt-1 block text-sm">{value}</span>
    </div>
  )
}

settings-nav-layout.source:
'use client'

/**
 * <SettingsNavLayout> — the sidebar-and-panel shell for a settings area.
 *
 * The nav is a vertical list on desktop and a horizontal scroller on
 * mobile, not a <select>. A native select is smaller, but it hides the
 * available sections behind a tap and loses the current-page indicator —
 * and settings is precisely where users are hunting for a section whose
 * name they half-remember.
 *
 * Sections are grouped with a heading each, because a flat run of a dozen
 * links is a wall. The grouping is data, so consumers can re-cut it.
 */

import * as React from 'react'
import { User, Bell, CreditCard, Users, KeyRound, Shield, Palette } from 'lucide-react'

export interface SettingsSection {
  label: string
  icon: React.ReactNode
  group: string
}

export interface SettingsNavLayoutProps {
  sections?: SettingsSection[]
  initialSection?: string
  heading?: string
  children?: React.ReactNode
  className?: string
}

const DEFAULT_SECTIONS: SettingsSection[] = [
  { label: 'Profile', icon: <User className="h-4 w-4" />, group: 'Account' },
  { label: 'Appearance', icon: <Palette className="h-4 w-4" />, group: 'Account' },
  { label: 'Notifications', icon: <Bell className="h-4 w-4" />, group: 'Account' },
  { label: 'Members', icon: <Users className="h-4 w-4" />, group: 'Workspace' },
  { label: 'Billing', icon: <CreditCard className="h-4 w-4" />, group: 'Workspace' },
  { label: 'API keys', icon: <KeyRound className="h-4 w-4" />, group: 'Developer' },
  { label: 'Security', icon: <Shield className="h-4 w-4" />, group: 'Developer' },
]

export function SettingsNavLayout({
  sections = DEFAULT_SECTIONS,
  initialSection = 'Profile',
  heading = 'Settings',
  children,
  className = '',
}: SettingsNavLayoutProps) {
  const [active, setActive] = React.useState(initialSection)

  // Preserve the authored order of both groups and their items.
  const groups = React.useMemo(() => {
    const map = new Map<string, SettingsSection[]>()
    for (const section of sections) {
      const list = map.get(section.group)
      if (list) list.push(section)
      else map.set(section.group, [section])
    }
    return [...map.entries()]
  }, [sections])

  return (
    <div className={`mx-auto w-full max-w-5xl p-6 ${className}`}>
      <h1 className="text-2xl font-bold tracking-tight">{heading}</h1>
      <p className="mt-1 text-sm text-muted-foreground">
        Manage your account, your workspace and how you sign in.
      </p>

      <div className="mt-8 flex flex-col gap-8 lg:flex-row">
        <nav aria-label="Settings sections" className="lg:w-52 lg:shrink-0">
          {/* Horizontal scroller below lg, stacked groups above it. */}
          <div className="flex gap-1 overflow-x-auto pb-2 lg:block lg:space-y-5 lg:overflow-visible lg:pb-0">
            {groups.map(([group, items]) => (
              <div key={group} className="contents lg:block">
                <h2 className="hidden px-3 pb-1.5 text-xs font-bold uppercase tracking-wider text-muted-foreground lg:block">
                  {group}
                </h2>

                {items.map((section) => {
                  const isActive = section.label === active
                  return (
                    <button
                      key={section.label}
                      type="button"
                      onClick={() => setActive(section.label)}
                      aria-current={isActive ? 'page' : undefined}
                      className={`flex shrink-0 items-center gap-2.5 rounded-xl px-3 py-2 text-sm font-medium transition-colors lg:w-full ${
                        isActive
                          ? 'bg-primary/10 text-primary'
                          : 'text-muted-foreground hover:bg-muted hover:text-foreground'
                      }`}
                    >
                      {section.icon}
                      {section.label}
                    </button>
                  )
                })}
              </div>
            ))}
          </div>
        </nav>

        <div className="min-w-0 flex-1">
          {children ?? (
            <div className="rounded-2xl border border-border/60 bg-card/60 p-6">
              <h2 className="font-semibold tracking-tight">{active}</h2>
              <p className="mt-1 text-sm text-muted-foreground">
                The panel for “{active}” goes here. Pass it as{' '}
                <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-xs">children</code>.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

settings-profile-form.source:
'use client'

/**
 * <SettingsProfileForm> — name, email, bio and avatar, with a save bar.
 *
 * The save bar only appears once something has actually changed, and it is
 * sticky to the bottom of the panel. A form with a permanently enabled
 * Save button gives no signal about unsaved work; one where the button
 * scrolls off the end of a long form gives no way to reach it.
 *
 * "Dirty" is computed by comparing against the initial values rather than
 * being set by every onChange, so typing a character and deleting it
 * correctly returns the form to clean.
 */

import * as React from 'react'
import { Loader2, Upload, Check } from 'lucide-react'

export interface ProfileValues {
  name: string
  email: string
  bio: string
}

export interface SettingsProfileFormProps {
  initial?: ProfileValues
  onSave?: (values: ProfileValues) => Promise<void>
  bioLimit?: number
  className?: string
}

const DEFAULT_VALUES: ProfileValues = {
  name: 'Ada Lovelace',
  email: 'ada@acme.com',
  bio: 'Working on compilers and the occasional analytical engine.',
}

export function SettingsProfileForm({
  initial = DEFAULT_VALUES,
  onSave,
  bioLimit = 160,
  className = '',
}: SettingsProfileFormProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [values, setValues] = React.useState(initial)
  const [busy, setBusy] = React.useState(false)
  const [saved, setSaved] = React.useState(false)

  const dirty =
    values.name !== initial.name ||
    values.email !== initial.email ||
    values.bio !== initial.bio

  const overLimit = values.bio.length > bioLimit

  function set<K extends keyof ProfileValues>(key: K, value: ProfileValues[K]) {
    setValues((v) => ({ ...v, [key]: value }))
    setSaved(false)
  }

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (!dirty || overLimit || busy) return

    setBusy(true)
    try {
      await onSave?.(values)
      setSaved(true)
    } finally {
      setBusy(false)
    }
  }

  return (
    <form
      onSubmit={handleSubmit}
      className={`overflow-hidden rounded-2xl border border-border/60 bg-card/60 ${className}`}
    >
      <div className="border-b border-border/60 px-6 py-4">
        <h2 className="font-semibold tracking-tight">Profile</h2>
        <p className="mt-0.5 text-sm text-muted-foreground">
          This is how you appear to everyone else in the workspace.
        </p>
      </div>

      <div className="space-y-6 p-6">
        {/* Avatar */}
        <div className="flex items-center gap-4">
          <span
            aria-hidden
            className="flex h-16 w-16 shrink-0 items-center justify-center rounded-full bg-muted text-lg font-bold text-foreground/70"
          >
            {values.name
              .split(' ')
              .slice(0, 2)
              .map((w) => w[0] ?? '')
              .join('')
              .toUpperCase()}
          </span>

          <div>
            <button
              type="button"
              className="inline-flex items-center gap-2 rounded-xl border border-border/60 bg-background px-3 py-2 text-sm font-medium transition-colors hover:bg-muted"
            >
              <Upload aria-hidden className="h-4 w-4" />
              Upload photo
            </button>
            <p className="mt-1.5 text-xs text-muted-foreground">
              JPG, PNG or GIF. 2 MB maximum.
            </p>
          </div>
        </div>

        <div className="grid gap-5 sm:grid-cols-2">
          <div>
            <label htmlFor={`${uid}-profile-name`} className="mb-1.5 block text-sm font-medium">
              Full name
            </label>
            <input
              id={`${uid}-profile-name`}
              autoComplete="name"
              value={values.name}
              onChange={(e) => set('name', e.target.value)}
              className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-primary"
            />
          </div>

          <div>
            <label htmlFor={`${uid}-profile-email`} className="mb-1.5 block text-sm font-medium">
              Email
            </label>
            <input
              id={`${uid}-profile-email`}
              type="email"
              autoComplete="email"
              value={values.email}
              onChange={(e) => set('email', e.target.value)}
              className="w-full rounded-xl border border-border/60 bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-primary"
            />
            <p className="mt-1.5 text-xs text-muted-foreground">
              Changing this sends a confirmation link to the new address.
            </p>
          </div>
        </div>

        <div>
          <div className="mb-1.5 flex items-baseline justify-between">
            <label htmlFor={`${uid}-profile-bio`} className="block text-sm font-medium">
              Bio
            </label>
            <span
              className={`text-xs tabular-nums ${
                overLimit ? 'font-medium text-destructive' : 'text-muted-foreground'
              }`}
            >
              {values.bio.length}/{bioLimit}
            </span>
          </div>
          <textarea
            id={`${uid}-profile-bio`}
            rows={3}
            aria-invalid={overLimit}
            value={values.bio}
            onChange={(e) => set('bio', e.target.value)}
            className={`w-full resize-y rounded-xl border bg-background px-3.5 py-2.5 text-sm outline-none transition-shadow focus-visible:ring-2 ${
              overLimit
                ? 'border-destructive focus-visible:ring-destructive'
                : 'border-border/60 focus-visible:ring-primary'
            }`}
          />
        </div>
      </div>

      {/* Save bar — only present when there is something to save. */}
      {dirty || saved ? (
        <div
          aria-live="polite"
          className="sticky bottom-0 flex items-center justify-between gap-4 border-t border-border/60 bg-card/95 px-6 py-3 backdrop-blur"
        >
          <span className="text-sm text-muted-foreground">
            {saved ? (
              <span className="inline-flex items-center gap-1.5 text-emerald-600 dark:text-emerald-400">
                <Check aria-hidden className="h-4 w-4" />
                Saved
              </span>
            ) : (
              'You have unsaved changes'
            )}
          </span>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => {
                setValues(initial)
                setSaved(false)
              }}
              className="rounded-xl border border-border/60 bg-background px-3.5 py-2 text-sm font-medium transition-colors hover:bg-muted"
            >
              Discard
            </button>
            <button
              type="submit"
              disabled={!dirty || overLimit || busy}
              className="inline-flex items-center gap-2 rounded-xl bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-50"
            >
              {busy ? <Loader2 aria-hidden className="h-4 w-4 animate-spin motion-reduce:[animation-duration:1.6s]" /> : null}
              Save changes
            </button>
          </div>
        </div>
      ) : null}
    </form>
  )
}

settings-team-members.source:
'use client'

/**
 * <SettingsTeamMembers> — the member list, with roles and invites.
 *
 * Two rules encoded here that every team-management screen needs and most
 * get wrong:
 *
 *  - The last owner cannot be demoted or removed. Allowing it orphans the
 *    workspace, and it is an easy mistake to make at 5pm on a Friday, so
 *    the control is disabled with a `title` explaining why rather than
 *    failing after the click.
 *  - Pending invites are listed alongside members but visually distinct.
 *    Hiding them in a separate tab is how the same person gets invited
 *    three times.
 */

import * as React from 'react'
import { MoreHorizontal, Mail, UserPlus } from 'lucide-react'

export type Role = 'Owner' | 'Admin' | 'Member'

export interface Member {
  id: string
  name: string
  email: string
  role: Role
  /** Invited but not yet accepted. */
  pending?: boolean
}

export interface SettingsTeamMembersProps {
  members?: Member[]
  seatLimit?: number
  onInvite?: (email: string, role: Role) => void
  className?: string
}

const ROLES: Role[] = ['Owner', 'Admin', 'Member']

const DEFAULT_MEMBERS: Member[] = [
  { id: '1', name: 'Ada Lovelace', email: 'ada@acme.com', role: 'Owner' },
  { id: '2', name: 'Marco Silva', email: 'marco@acme.com', role: 'Admin' },
  { id: '3', name: 'Priya Raman', email: 'priya@acme.com', role: 'Member' },
  { id: '4', name: 'Alex Chen', email: 'alex@contractor.dev', role: 'Member', pending: true },
]

export function SettingsTeamMembers({
  members: initialMembers = DEFAULT_MEMBERS,
  seatLimit = 10,
  onInvite,
  className = '',
}: SettingsTeamMembersProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [members, setMembers] = React.useState(initialMembers)
  const [inviteEmail, setInviteEmail] = React.useState('')
  const [inviteRole, setInviteRole] = React.useState<Role>('Member')

  const ownerCount = members.filter((m) => m.role === 'Owner' && !m.pending).length

  function changeRole(id: string, role: Role) {
    setMembers((prev) => prev.map((m) => (m.id === id ? { ...m, role } : m)))
  }

  function handleInvite(event: React.FormEvent) {
    event.preventDefault()
    if (!inviteEmail) return
    onInvite?.(inviteEmail, inviteRole)
    setInviteEmail('')
  }

  return (
    <div className={`overflow-hidden rounded-2xl border border-border/60 bg-card/60 ${className}`}>
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border/60 px-6 py-4">
        <div>
          <h2 className="font-semibold tracking-tight">Members</h2>
          <p className="mt-0.5 text-sm text-muted-foreground">
            {members.length} of {seatLimit} seats used
          </p>
        </div>

        <form onSubmit={handleInvite} className="flex items-center gap-2">
          <label htmlFor={`${uid}-invite-email`} className="sr-only">
            Email to invite
          </label>
          <input
            id={`${uid}-invite-email`}
            type="email"
            value={inviteEmail}
            onChange={(e) => setInviteEmail(e.target.value)}
            placeholder="colleague@acme.com"
            className="w-48 rounded-xl border border-border/60 bg-background px-3 py-2 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
          />

          <label htmlFor={`${uid}-invite-role`} className="sr-only">
            Role for the invitee
          </label>
          <select
            id={`${uid}-invite-role`}
            value={inviteRole}
            onChange={(e) => setInviteRole(e.target.value as Role)}
            className="rounded-xl border border-border/60 bg-background px-2 py-2 text-sm outline-none focus-visible:ring-2 focus-visible:ring-primary"
          >
            {ROLES.filter((r) => r !== 'Owner').map((role) => (
              <option key={role} value={role}>
                {role}
              </option>
            ))}
          </select>

          <button
            type="submit"
            className="inline-flex items-center gap-2 rounded-xl bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90"
          >
            <UserPlus aria-hidden className="h-4 w-4" />
            Invite
          </button>
        </form>
      </div>

      <ul className="divide-y divide-border/40">
        {members.map((member) => {
          // The workspace must keep at least one owner who has accepted.
          const isLastOwner = member.role === 'Owner' && ownerCount <= 1 && !member.pending
          const lockReason = isLastOwner
            ? 'A workspace needs at least one owner'
            : undefined

          return (
            <li key={member.id} className="flex items-center gap-3 px-6 py-3.5">
              <span
                aria-hidden
                className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-xs font-bold ${
                  member.pending ? 'bg-muted/60 text-muted-foreground' : 'bg-muted text-foreground/70'
                }`}
              >
                {member.pending ? (
                  <Mail className="h-4 w-4" />
                ) : (
                  member.name
                    .split(' ')
                    .slice(0, 2)
                    .map((w) => w[0] ?? '')
                    .join('')
                    .toUpperCase()
                )}
              </span>

              <div className="min-w-0 flex-1">
                <p className="flex items-center gap-2 text-sm font-medium">
                  <span className="truncate">{member.pending ? member.email : member.name}</span>
                  {member.pending ? (
                    <span className="shrink-0 rounded-full bg-amber-500/15 px-2 py-0.5 text-xs font-medium text-amber-600 dark:text-amber-400">
                      Invite pending
                    </span>
                  ) : null}
                </p>
                {!member.pending ? (
                  <p className="truncate text-xs text-muted-foreground">{member.email}</p>
                ) : null}
              </div>

              <label htmlFor={`role-${member.id}`} className="sr-only">
                Role for {member.name}
              </label>
              <select
                id={`role-${member.id}`}
                value={member.role}
                disabled={isLastOwner}
                title={lockReason}
                onChange={(e) => changeRole(member.id, e.target.value as Role)}
                className="rounded-lg border border-border/60 bg-background px-2 py-1.5 text-sm outline-none focus-visible:ring-2 focus-visible:ring-primary disabled:cursor-not-allowed disabled:opacity-60"
              >
                {ROLES.map((role) => (
                  <option key={role} value={role}>
                    {role}
                  </option>
                ))}
              </select>

              <button
                type="button"
                disabled={isLastOwner}
                title={lockReason}
                aria-label={`Actions for ${member.name}`}
                className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
              >
                <MoreHorizontal aria-hidden className="h-4 w-4" />
              </button>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

settings-danger-zone.source:
'use client'

/**
 * <SettingsDangerZone> — the irreversible actions, gated properly.
 *
 * Destructive confirmation done the way GitHub and Stripe do it: the user
 * types the resource's exact name before the button unlocks. A plain
 * "Are you sure?" dialog is dismissed by reflex; typing `acme-production`
 * cannot be.
 *
 * The comparison is deliberately exact — not trimmed, not case-folded.
 * Loosening it defeats the point, which is to force the user to look at
 * what they are about to destroy.
 *
 * Each action states its consequence and whether it can be undone, because
 * "Delete workspace" and "Transfer ownership" carry very different risk and
 * a shared red border tells the user nothing about which is which.
 */

import * as React from 'react'
import { TriangleAlert } from 'lucide-react'

export interface DangerAction {
  id: string
  title: string
  description: string
  buttonLabel: string
  /** Requires typing `confirmValue` before the button unlocks. */
  requiresTyping?: boolean
  onConfirm?: () => void
}

export interface SettingsDangerZoneProps {
  /** The exact string a user must type — usually the workspace name. */
  confirmValue?: string
  actions?: DangerAction[]
  className?: string
}

const DEFAULT_ACTIONS: DangerAction[] = [
  {
    id: 'transfer',
    title: 'Transfer ownership',
    description:
      'Hand this workspace to another member. You keep admin access, but billing and deletion move to them.',
    buttonLabel: 'Transfer',
  },
  {
    id: 'archive',
    title: 'Archive workspace',
    description:
      'Make everything read-only and stop billing at the end of the period. You can un-archive at any time.',
    buttonLabel: 'Archive',
  },
  {
    id: 'delete',
    title: 'Delete workspace',
    description:
      'Permanently removes all projects, members and history. This cannot be undone and support cannot recover it.',
    buttonLabel: 'Delete workspace',
    requiresTyping: true,
  },
]

export function SettingsDangerZone({
  confirmValue = 'acme-production',
  actions = DEFAULT_ACTIONS,
  className = '',
}: SettingsDangerZoneProps) {
  const [openId, setOpenId] = React.useState<string | null>(null)
  const [typed, setTyped] = React.useState('')

  // Exact match. Trimming or case-folding would undo the whole mechanism.
  const confirmed = typed === confirmValue

  function toggle(id: string) {
    setOpenId((current) => (current === id ? null : id))
    setTyped('')
  }

  return (
    <section
      className={`overflow-hidden rounded-2xl border border-destructive/40 bg-card/60 ${className}`}
    >
      <div className="flex items-center gap-2 border-b border-destructive/30 bg-destructive/5 px-6 py-4">
        <TriangleAlert aria-hidden className="h-4 w-4 shrink-0 text-destructive" />
        <div>
          <h2 className="font-semibold tracking-tight text-destructive">Danger zone</h2>
          <p className="mt-0.5 text-sm text-muted-foreground">
            These actions affect everyone in the workspace.
          </p>
        </div>
      </div>

      <ul className="divide-y divide-border/40">
        {actions.map((action) => {
          const open = openId === action.id

          return (
            <li key={action.id} className="px-6 py-4">
              <div className="flex flex-wrap items-start justify-between gap-4">
                <div className="min-w-0 flex-1">
                  <h3 className="text-sm font-semibold">{action.title}</h3>
                  <p className="mt-1 text-sm text-muted-foreground">{action.description}</p>
                </div>

                <button
                  type="button"
                  onClick={() => toggle(action.id)}
                  aria-expanded={open}
                  className="shrink-0 rounded-xl border border-destructive/50 px-3.5 py-2 text-sm font-semibold text-destructive transition-colors hover:bg-destructive/10"
                >
                  {action.buttonLabel}
                </button>
              </div>

              {open ? (
                <div className="mt-4 rounded-xl border border-destructive/30 bg-destructive/5 p-4">
                  {action.requiresTyping ? (
                    <>
                      <label
                        htmlFor={`confirm-${action.id}`}
                        className="block text-sm font-medium"
                      >
                        Type{' '}
                        <code className="rounded bg-background px-1.5 py-0.5 font-mono text-xs">
                          {confirmValue}
                        </code>{' '}
                        to confirm
                      </label>
                      <input
                        id={`confirm-${action.id}`}
                        autoComplete="off"
                        autoFocus
                        value={typed}
                        onChange={(e) => setTyped(e.target.value)}
                        className="mt-2 w-full max-w-sm rounded-xl border border-border/60 bg-background px-3 py-2 font-mono text-sm outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-destructive"
                      />
                    </>
                  ) : (
                    <p className="text-sm">
                      This will {action.title.toLowerCase()}. Continue?
                    </p>
                  )}

                  <div className="mt-4 flex items-center gap-2">
                    <button
                      type="button"
                      disabled={action.requiresTyping && !confirmed}
                      onClick={() => {
                        action.onConfirm?.()
                        toggle(action.id)
                      }}
                      className="rounded-xl bg-destructive px-3.5 py-2 text-sm font-semibold text-destructive-foreground transition-opacity hover:opacity-90 disabled:opacity-40"
                    >
                      I understand — {action.buttonLabel.toLowerCase()}
                    </button>
                    <button
                      type="button"
                      onClick={() => toggle(action.id)}
                      className="rounded-xl px-3.5 py-2 text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              ) : null}
            </li>
          )
        })}
      </ul>
    </section>
  )
}

error-state-retry.source:
'use client'

/**
 * <ErrorStateRetry> — a failed-to-load panel that can actually recover.
 *
 * What separates a usable error state from a dead end:
 *
 *  - A retry that shows it is retrying. A button that silently re-fires and
 *    fails again reads as broken, so the busy state is explicit.
 *  - The technical detail behind a <details>, not on the surface. Users do
 *    not want a stack trace; the one person who does need it — the
 *    colleague they forward the screenshot to — needs it to be there.
 *  - A copyable error id. "Something went wrong" with no reference is
 *    unactionable for support.
 *
 * `role="alert"` announces the failure immediately, since a section that
 * silently swaps from spinner to error is invisible to a screen reader.
 */

import * as React from 'react'
import { RefreshCw, CircleAlert, Copy, Check } from 'lucide-react'

export interface ErrorStateRetryProps {
  title?: string
  description?: string
  /** Shown behind a disclosure — stack, response body, whatever helps. */
  detail?: string
  errorId?: string
  onRetry?: () => Promise<void>
  supportHref?: string
  className?: string
}

export function ErrorStateRetry({
  title = 'We could not load this',
  description = 'The request failed before it finished. Your data is safe — nothing was changed.',
  detail = 'GET /api/v1/projects → 503 Service Unavailable\n  upstream: projects-api\n  duration: 30012ms (timeout)',
  errorId = 'err_7f3a92c4b81e',
  onRetry,
  supportHref,
  className = '',
}: ErrorStateRetryProps) {
  const [busy, setBusy] = React.useState(false)
  const [copied, setCopied] = React.useState(false)

  async function retry() {
    if (busy) return
    setBusy(true)
    try {
      await onRetry?.()
    } finally {
      setBusy(false)
    }
  }

  async function copyId() {
    if (!navigator.clipboard) return
    await navigator.clipboard.writeText(errorId)
    setCopied(true)
    window.setTimeout(() => setCopied(false), 1600)
  }

  return (
    <div
      role="alert"
      className={`flex flex-col items-center justify-center rounded-2xl border border-border/60 bg-card/60 px-6 py-12 text-center ${className}`}
    >
      <span className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-destructive/10 text-destructive">
        <CircleAlert className="h-6 w-6" />
      </span>

      <h2 className="mt-5 text-lg font-bold tracking-tight">{title}</h2>
      <p className="mx-auto mt-2 max-w-md text-sm text-muted-foreground">{description}</p>

      <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
        <button
          type="button"
          onClick={retry}
          disabled={busy}
          className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-60"
        >
          <RefreshCw
            aria-hidden
            className={`h-4 w-4 ${busy ? 'motion-safe:animate-spin motion-reduce:[animation-duration:1.6s]' : ''}`}
          />
          {busy ? 'Retrying' : 'Try again'}
        </button>

        {supportHref ? (
          <a
            href={supportHref}
            className="rounded-xl border border-border/60 bg-background px-4 py-2.5 text-sm font-medium transition-colors hover:bg-muted"
          >
            Contact support
          </a>
        ) : null}
      </div>

      {errorId ? (
        <div className="mt-5 flex items-center gap-2 text-xs text-muted-foreground">
          <span>Reference</span>
          <code className="rounded bg-muted px-1.5 py-0.5 font-mono">{errorId}</code>
          <button
            type="button"
            onClick={copyId}
            aria-label="Copy error reference"
            className="rounded p-1 transition-colors hover:bg-muted hover:text-foreground"
          >
            {copied ? (
              <Check aria-hidden className="h-3.5 w-3.5 text-emerald-500" />
            ) : (
              <Copy aria-hidden className="h-3.5 w-3.5" />
            )}
          </button>
        </div>
      ) : null}

      {detail ? (
        <details className="mt-6 w-full max-w-lg text-left [&_summary::-webkit-details-marker]:hidden">
          <summary className="cursor-pointer list-none text-center text-xs font-medium text-muted-foreground transition-colors hover:text-foreground">
            Technical details
          </summary>
          <pre className="mt-3 overflow-x-auto rounded-xl bg-muted/60 p-3 text-left font-mono text-xs text-muted-foreground">
            {detail}
          </pre>
        </details>
      ) : null}
    </div>
  )
}

skeleton-list.source:
/**
 * <SkeletonList> — loading placeholders for a list or table.
 *
 * Three things this gets right:
 *
 *  - The shimmer is `motion-safe:` only. A sweeping gradient that never
 *    stops is exactly the kind of animation `prefers-reduced-motion` exists
 *    to suppress, and a skeleton is on screen at the moment a user is least
 *    able to look away from it. Reduced motion falls back to a flat tint.
 *  - Row widths vary. Identical bars read as a broken UI; a ragged right
 *    edge reads as text.
 *  - The container is `aria-busy` with a visually hidden status, so a
 *    screen reader hears "Loading" instead of silence — and the bars
 *    themselves are `aria-hidden` so they are not announced one by one.
 *
 * Server component — no state, no effects.
 */

import * as React from 'react'

export interface SkeletonListProps {
  rows?: number
  /** Include a leading circle per row. */
  avatar?: boolean
  label?: string
  className?: string
}

/** Varied widths, cycled — so ten rows do not look like one row ten times. */
const WIDTHS = ['w-3/5', 'w-4/5', 'w-2/5', 'w-3/4', 'w-1/2']

export function SkeletonList({
  rows = 5,
  avatar = true,
  label = 'Loading',
  className = '',
}: SkeletonListProps) {
  return (
    <div
      aria-busy="true"
      className={`overflow-hidden rounded-2xl border border-border/60 bg-card/60 ${className}`}
    >
      <span className="sr-only" role="status">
        {label}
      </span>

      {/* Declared once for the whole list, not once per bar. */}
      <style>{`
        @keyframes skeleton-sweep {
          from { background-position: 200% 0; }
          to   { background-position: -200% 0; }
        }
      `}</style>

      <ul className="divide-y divide-border/40">
        {Array.from({ length: rows }, (_, i) => (
          <li key={i} aria-hidden className="flex items-center gap-4 px-5 py-4">
            {avatar ? <Bar className="h-9 w-9 shrink-0 rounded-full" /> : null}

            <div className="min-w-0 flex-1 space-y-2">
              <Bar className={`h-3 rounded ${WIDTHS[i % WIDTHS.length]}`} />
              <Bar className={`h-2.5 rounded ${WIDTHS[(i + 2) % WIDTHS.length]} opacity-70`} />
            </div>

            <Bar className="h-6 w-16 shrink-0 rounded-full" />
          </li>
        ))}
      </ul>
    </div>
  )
}

/**
 * One placeholder bar.
 *
 * The sweep is a background gradient translated across a 200%-wide
 * background, which animates compositor-side and does not touch layout.
 * Under reduced motion the animation is simply absent and the flat
 * `bg-muted` shows through.
 */
function Bar({ className = '' }: { className?: string }) {
  return (
    <span
      className={`block bg-muted motion-safe:animate-[skeleton-sweep_1.6s_ease-in-out_infinite] motion-safe:bg-[linear-gradient(90deg,transparent,hsl(var(--foreground)/0.06),transparent)] motion-safe:bg-[length:200%_100%] ${className}`}
    />
  )
}

metric-sparkline-cards.source:
/**
 * <MetricSparklineCards> — KPI cards with an inline trend line.
 *
 * The sparkline is hand-built SVG, not a charting library. For a 40-point
 * trend line that is the right call: a charting dependency is ~50 KB to
 * draw a path this file computes in twelve lines, and it would be the only
 * runtime dependency in the whole catalog.
 *
 * `preserveAspectRatio="none"` with a viewBox in data space lets the path
 * stretch to whatever width the card gives it, so no measurement and no
 * resize observer is needed. The line is `vector-effect="non-scaling-stroke"`
 * so that stretch does not smear the stroke width along with it.
 *
 * Server component — the whole thing is derived from props.
 */

import * as React from 'react'

export interface Metric {
  label: string
  value: string
  delta: number
  /** Newest last. Any length ≥ 2. */
  series: number[]
  higherIsBetter?: boolean
}

export interface MetricSparklineCardsProps {
  metrics?: Metric[]
  className?: string
}

const DEFAULT_METRICS: Metric[] = [
  {
    label: 'Requests',
    value: '1.24M',
    delta: 18.2,
    series: [12, 14, 13, 17, 16, 19, 22, 21, 25, 24, 28, 31],
  },
  {
    label: 'Error rate',
    value: '0.12%',
    delta: -34.5,
    higherIsBetter: false,
    series: [9, 8, 8, 7, 9, 6, 5, 5, 4, 3, 3, 2],
  },
  {
    label: 'p95 latency',
    value: '184ms',
    delta: -8.1,
    higherIsBetter: false,
    series: [22, 21, 23, 20, 19, 20, 18, 17, 18, 16, 15, 15],
  },
]

/**
 * Points → an SVG path in a 100×32 box.
 * Normalised against the series' own min/max so a flat-but-high line
 * still fills the card rather than pinning to the top edge.
 */
function toPath(series: number[]): string {
  if (series.length < 2) return ''

  const min = Math.min(...series)
  const max = Math.max(...series)
  const span = max - min || 1

  return series
    .map((value, i) => {
      const x = (i / (series.length - 1)) * 100
      const y = 32 - ((value - min) / span) * 28 - 2
      return `${i === 0 ? 'M' : 'L'}${x.toFixed(2)},${y.toFixed(2)}`
    })
    .join(' ')
}

export function MetricSparklineCards({
  metrics = DEFAULT_METRICS,
  className = '',
}: MetricSparklineCardsProps) {
  return (
    <div className={`grid grid-cols-1 gap-4 sm:grid-cols-3 ${className}`}>
      {metrics.map((metric) => {
        const rising = metric.delta >= 0
        const good = rising === (metric.higherIsBetter ?? true)
        const stroke = good ? 'text-emerald-500' : 'text-red-500'
        const path = toPath(metric.series)

        return (
          <div
            key={metric.label}
            className="rounded-2xl border border-border/60 bg-card/80 p-5 backdrop-blur transition-shadow hover:shadow-md"
          >
            <p className="text-sm font-medium text-muted-foreground">{metric.label}</p>

            <div className="mt-2 flex items-baseline gap-2">
              <span className="text-2xl font-extrabold tracking-tight">{metric.value}</span>
              <span
                className={`text-xs font-semibold ${
                  good ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-600 dark:text-red-400'
                }`}
              >
                {rising ? '+' : ''}
                {metric.delta}%
              </span>
            </div>

            <svg
              aria-hidden
              viewBox="0 0 100 32"
              preserveAspectRatio="none"
              className={`mt-4 h-10 w-full ${stroke}`}
            >
              {/* Fill under the line, closed back along the baseline. */}
              <path
                d={`${path} L100,32 L0,32 Z`}
                fill="currentColor"
                opacity="0.08"
                stroke="none"
              />
              <path
                d={path}
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                vectorEffect="non-scaling-stroke"
              />
            </svg>

            <p className="sr-only">
              Trend over the last {metric.series.length} periods, {rising ? 'rising' : 'falling'}{' '}
              {Math.abs(metric.delta)} percent.
            </p>
          </div>
        )
      })}
    </div>
  )
}

bar-chart-panel.source:
/**
 * <BarChartPanel> — a categorical bar chart in CSS grid, no SVG.
 *
 * Bars are grid rows sized as a percentage of the maximum, which means the
 * chart reflows with its container for free and every bar is a real DOM
 * element that can carry a tooltip, a link or a focus ring.
 *
 * The accessible fallback is a real <table> in `sr-only`, not `aria-label`
 * text on the chart. A chart described as "bar chart showing revenue" tells
 * a screen-reader user nothing; the table gives them the actual numbers.
 *
 * Gridlines sit behind the bars at fixed fractions, so the eye can read a
 * value off the chart without every bar needing its own printed figure.
 *
 * Server component.
 */

import * as React from 'react'

export interface Bar {
  label: string
  value: number
  /** Optional second series, drawn as a lighter bar behind. */
  compare?: number
}

export interface BarChartPanelProps {
  bars?: Bar[]
  heading?: string
  caption?: string
  /** Formats values in the tooltip, the table and the axis. */
  format?: (value: number) => string
  className?: string
}

const DEFAULT_BARS: Bar[] = [
  { label: 'Mon', value: 4200, compare: 3800 },
  { label: 'Tue', value: 5100, compare: 4400 },
  { label: 'Wed', value: 4800, compare: 4900 },
  { label: 'Thu', value: 6300, compare: 5200 },
  { label: 'Fri', value: 7100, compare: 5800 },
  { label: 'Sat', value: 3900, compare: 3600 },
  { label: 'Sun', value: 3100, compare: 3000 },
]

const currency = (value: number) => `$${value.toLocaleString('en-US')}`

export function BarChartPanel({
  bars = DEFAULT_BARS,
  heading = 'Revenue this week',
  caption = 'Solid is this week. Faded is the week before.',
  format = currency,
  className = '',
}: BarChartPanelProps) {
  const max = Math.max(...bars.map((b) => Math.max(b.value, b.compare ?? 0)), 1)
  const total = bars.reduce((sum, b) => sum + b.value, 0)

  return (
    <section
      className={`rounded-2xl border border-border/60 bg-card/80 p-6 backdrop-blur ${className}`}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-3">
        <div>
          <h2 className="font-semibold tracking-tight">{heading}</h2>
          {caption ? (
            <p className="mt-0.5 text-sm text-muted-foreground">{caption}</p>
          ) : null}
        </div>
        <span className="text-2xl font-extrabold tracking-tight">{format(total)}</span>
      </div>

      <div className="relative mt-8">
        {/* Gridlines behind the bars. */}
        <div aria-hidden className="absolute inset-0 flex flex-col justify-between">
          {[1, 0.75, 0.5, 0.25, 0].map((fraction) => (
            <div key={fraction} className="flex items-center gap-2">
              <span className="w-12 shrink-0 text-right text-[0.65rem] text-muted-foreground">
                {format(Math.round(max * fraction))}
              </span>
              <span className="h-px flex-1 bg-border/50" />
            </div>
          ))}
        </div>

        {/* Bars, offset past the axis labels. */}
        <div aria-hidden className="relative ml-14 flex h-48 items-end gap-2">
          {bars.map((bar) => (
            <div key={bar.label} className="group flex h-full flex-1 flex-col justify-end gap-1">
              <div className="relative flex h-full items-end justify-center gap-0.5">
                {typeof bar.compare === 'number' ? (
                  <span
                    className="w-1/3 rounded-t bg-muted-foreground/20 transition-all"
                    style={{ height: `${(bar.compare / max) * 100}%` }}
                  />
                ) : null}

                <span
                  className="w-1/2 rounded-t bg-primary transition-all group-hover:bg-primary/80"
                  style={{ height: `${(bar.value / max) * 100}%` }}
                />

                {/* Value on hover — keeps the chart clean at rest. */}
                <span className="pointer-events-none absolute -top-6 left-1/2 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-1.5 py-0.5 text-[0.65rem] font-medium text-background opacity-0 transition-opacity group-hover:opacity-100">
                  {format(bar.value)}
                </span>
              </div>

              <span className="text-center text-xs text-muted-foreground">{bar.label}</span>
            </div>
          ))}
        </div>
      </div>

      {/* The real accessible representation. */}
      <table className="sr-only">
        <caption>{heading}</caption>
        <thead>
          <tr>
            <th scope="col">Period</th>
            <th scope="col">This week</th>
            {bars.some((b) => typeof b.compare === 'number') ? (
              <th scope="col">Previous week</th>
            ) : null}
          </tr>
        </thead>
        <tbody>
          {bars.map((bar) => (
            <tr key={bar.label}>
              <th scope="row">{bar.label}</th>
              <td>{format(bar.value)}</td>
              {typeof bar.compare === 'number' ? <td>{format(bar.compare)}</td> : null}
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  )
}

usage-meter-panel.source:
/**
 * <UsageMeterPanel> — quota consumption against plan limits.
 *
 * The panel a user opens when they want to know whether they are about to
 * be charged, so it is built to answer that first.
 *
 *  - Bars change tone as they approach the limit, and the threshold is
 *    stated ("80% of your limit"), not just implied by turning amber.
 *  - Unlimited quotas render as a dash rather than a full bar. A metered
 *    bar for something with no ceiling is actively misleading.
 *  - Overage is drawn past the 100% mark in the destructive tone rather
 *    than clamped, because a bar pinned at full hides how far over you are.
 *
 * `<progress>` would be the semantic element, but it cannot be styled
 * consistently across engines. The `role="progressbar"` div with explicit
 * `aria-valuenow`/`min`/`max` carries the same information.
 *
 * Server component.
 */

import * as React from 'react'
import { TriangleAlert, Infinity as InfinityIcon } from 'lucide-react'

export interface Quota {
  label: string
  used: number
  /** `null` for an unmetered allowance. */
  limit: number | null
  unit?: string
  /** Formats both the used and limit figures. */
  format?: (value: number) => string
}

export interface UsageMeterPanelProps {
  quotas?: Quota[]
  heading?: string
  periodEnds?: string
  /** Fraction above which a quota is flagged as running out. */
  warnAt?: number
  upgradeHref?: string
  className?: string
}

const DEFAULT_QUOTAS: Quota[] = [
  { label: 'API requests', used: 842_000, limit: 1_000_000 },
  { label: 'Team seats', used: 8, limit: 10 },
  { label: 'Storage', used: 47, limit: 50, unit: 'GB' },
  { label: 'Bandwidth', used: 128, limit: 100, unit: 'GB' },
  { label: 'Projects', used: 23, limit: null },
]

export function UsageMeterPanel({
  quotas = DEFAULT_QUOTAS,
  heading = 'Usage this period',
  periodEnds = 'Resets 1 September',
  warnAt = 0.8,
  upgradeHref,
  className = '',
}: UsageMeterPanelProps) {
  const anyOver = quotas.some((q) => q.limit !== null && q.used > q.limit)

  return (
    <section
      className={`overflow-hidden rounded-2xl border border-border/60 bg-card/80 backdrop-blur ${className}`}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-3 border-b border-border/60 px-6 py-4">
        <div>
          <h2 className="font-semibold tracking-tight">{heading}</h2>
          <p className="mt-0.5 text-sm text-muted-foreground">{periodEnds}</p>
        </div>

        {upgradeHref ? (
          <a
            href={upgradeHref}
            className="rounded-xl bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90"
          >
            Upgrade plan
          </a>
        ) : null}
      </div>

      {anyOver ? (
        <p className="flex items-start gap-2 border-b border-border/60 bg-destructive/5 px-6 py-3 text-sm text-destructive">
          <TriangleAlert aria-hidden className="mt-0.5 h-4 w-4 shrink-0" />
          You are over the limit on at least one quota. Overage is billed at the
          end of the period.
        </p>
      ) : null}

      <ul className="divide-y divide-border/40">
        {quotas.map((quota) => {
          const format = quota.format ?? ((v: number) => v.toLocaleString('en-US'))
          const unlimited = quota.limit === null
          const fraction = unlimited ? 0 : quota.used / quota.limit!
          const over = !unlimited && quota.used > quota.limit!
          const warning = !unlimited && !over && fraction >= warnAt

          const tone = over
            ? 'bg-destructive'
            : warning
              ? 'bg-amber-500'
              : 'bg-primary'

          return (
            <li key={quota.label} className="px-6 py-4">
              <div className="flex items-baseline justify-between gap-3">
                <span className="text-sm font-medium">{quota.label}</span>

                <span className="text-sm tabular-nums text-muted-foreground">
                  {format(quota.used)}
                  {quota.unit ? ` ${quota.unit}` : ''}
                  {unlimited ? (
                    <span className="ml-1 inline-flex items-center gap-1 text-xs">
                      <span aria-hidden>/</span>
                      <InfinityIcon aria-hidden className="h-3.5 w-3.5" />
                      <span className="sr-only">of unlimited</span>
                    </span>
                  ) : (
                    <>
                      {' / '}
                      {format(quota.limit!)}
                      {quota.unit ? ` ${quota.unit}` : ''}
                    </>
                  )}
                </span>
              </div>

              {unlimited ? (
                <p className="mt-2 text-xs text-muted-foreground">
                  No limit on this plan
                </p>
              ) : (
                <>
                  <div
                    role="progressbar"
                    aria-valuenow={Math.round(fraction * 100)}
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-label={`${quota.label} usage`}
                    className="relative mt-2 h-2 overflow-hidden rounded-full bg-muted"
                  >
                    <span
                      className={`block h-full rounded-full transition-all ${tone}`}
                      style={{ width: `${Math.min(100, fraction * 100)}%` }}
                    />
                  </div>

                  <p
                    className={`mt-1.5 text-xs ${
                      over
                        ? 'font-medium text-destructive'
                        : warning
                          ? 'font-medium text-amber-600 dark:text-amber-400'
                          : 'text-muted-foreground'
                    }`}
                  >
                    {over
                      ? `${format(quota.used - quota.limit!)}${quota.unit ? ` ${quota.unit}` : ''} over your limit`
                      : warning
                        ? `${Math.round(fraction * 100)}% of your limit used`
                        : `${Math.round(fraction * 100)}% used`}
                  </p>
                </>
              )}
            </li>
          )
        })}
      </ul>
    </section>
  )
}

command-palette.source:
'use client'

/**
 * <CommandPalette> — the ⌘K quick-switcher.
 *
 * Deceptively hard, which is why it is worth lifting whole. What is handled
 * here and usually is not:
 *
 *  - Roving focus stays in the input while the *highlight* moves through the
 *    list. Moving real DOM focus to each item breaks typing, so the input
 *    keeps focus and `aria-activedescendant` points at the highlighted row —
 *    the combobox pattern.
 *  - Arrow keys wrap at both ends, and the highlight resets to the first
 *    result whenever the query changes. Leaving it at index 7 after the list
 *    shrinks to two results is how palettes select the wrong thing.
 *  - The highlighted item is scrolled into view with `block: 'nearest'`, so
 *    keyboard travel does not jump the list around.
 *  - ⌘K / Ctrl-K toggles, Escape closes, and the shortcut calls
 *    `preventDefault` — otherwise Firefox steals it for its search bar.
 *
 * Rendered inline rather than in a portal so it previews in place; move it
 * into a portal with a focus trap when you drop it into a real app.
 */

import * as React from 'react'
import {
  Search,
  FileText,
  Settings,
  Users,
  CreditCard,
  Plus,
  CornerDownLeft,
  ArrowUp,
  ArrowDown,
} from 'lucide-react'

export interface CommandItem {
  id: string
  label: string
  group: string
  icon?: React.ReactNode
  shortcut?: string
  onSelect?: () => void
}

export interface CommandPaletteProps {
  items?: CommandItem[]
  placeholder?: string
  /** Start open — the default, so the block previews as something visible. */
  defaultOpen?: boolean
  /**
   * Render as a demo inside a larger page. Drops the document-level
   * Ctrl/Cmd-K and Escape binding, which a preview has no business owning —
   * on a page of previews it would fight the host app for the same keys —
   * and the search field's `autoFocus`, which would scroll the browser to
   * this card on load.
   */
  embedded?: boolean
  className?: string
}

const DEFAULT_ITEMS: CommandItem[] = [
  { id: 'new-project', label: 'Create new project', group: 'Actions', icon: <Plus className="h-4 w-4" />, shortcut: 'N' },
  { id: 'invite', label: 'Invite a teammate', group: 'Actions', icon: <Users className="h-4 w-4" /> },
  { id: 'docs', label: 'Search documentation', group: 'Navigation', icon: <FileText className="h-4 w-4" /> },
  { id: 'billing', label: 'Go to billing', group: 'Navigation', icon: <CreditCard className="h-4 w-4" /> },
  { id: 'settings', label: 'Open settings', group: 'Navigation', icon: <Settings className="h-4 w-4" />, shortcut: ',' },
  { id: 'members', label: 'Manage members', group: 'Navigation', icon: <Users className="h-4 w-4" /> },
]

export function CommandPalette({
  items = DEFAULT_ITEMS,
  placeholder = 'Type a command or search',
  defaultOpen = true,
  embedded = false,
  className = '',
}: CommandPaletteProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [open, setOpen] = React.useState(defaultOpen)
  const [query, setQuery] = React.useState('')
  const [highlight, setHighlight] = React.useState(0)

  const listRef = React.useRef<HTMLDivElement>(null)

  const results = React.useMemo(() => {
    const term = query.trim().toLowerCase()
    if (!term) return items
    return items.filter((item) => item.label.toLowerCase().includes(term))
  }, [items, query])

  // A stale highlight after the list shrinks selects the wrong row.
  React.useEffect(() => {
    setHighlight(0)
  }, [query])

  // Keep the highlighted row visible without yanking the list around.
  //
  // Skipped on the first commit. `scrollIntoView` walks up *every* scrollable
  // ancestor, the document included, so running it on mount scrolls the whole
  // page to wherever this palette happens to sit. On mount the highlight is
  // row 0, which is already in view, so there was never anything to correct.
  const settled = React.useRef(false)
  React.useEffect(() => {
    if (!settled.current) {
      settled.current = true
      return
    }
    const node = listRef.current?.querySelector<HTMLElement>('[data-highlighted="true"]')
    node?.scrollIntoView({ block: 'nearest' })
  }, [highlight])

  React.useEffect(() => {
    if (embedded) return

    function onKey(event: KeyboardEvent) {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
        // Firefox binds Ctrl-K to its search bar unless we take it.
        event.preventDefault()
        setOpen((v) => !v)
      } else if (event.key === 'Escape') {
        setOpen(false)
      }
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [embedded])

  function handleKeyDown(event: React.KeyboardEvent) {
    if (results.length === 0) return

    if (event.key === 'ArrowDown') {
      event.preventDefault()
      setHighlight((i) => (i + 1) % results.length)
    } else if (event.key === 'ArrowUp') {
      event.preventDefault()
      setHighlight((i) => (i - 1 + results.length) % results.length)
    } else if (event.key === 'Enter') {
      event.preventDefault()
      const item = results[highlight]
      item?.onSelect?.()
      setOpen(false)
    }
  }

  // Preserve authored group order.
  const grouped = React.useMemo(() => {
    const map = new Map<string, CommandItem[]>()
    for (const item of results) {
      const list = map.get(item.group)
      if (list) list.push(item)
      else map.set(item.group, [item])
    }
    return [...map.entries()]
  }, [results])

  if (!open) {
    return (
      <div className={`flex items-center justify-center p-10 ${className}`}>
        <button
          type="button"
          onClick={() => setOpen(true)}
          className="inline-flex items-center gap-2 rounded-xl border border-border/60 bg-background px-4 py-2 text-sm text-muted-foreground transition-colors hover:bg-muted"
        >
          <Search aria-hidden className="h-4 w-4" />
          Search
          <kbd className="ml-2 rounded border border-border/60 bg-muted px-1.5 py-0.5 font-mono text-xs">
            ⌘K
          </kbd>
        </button>
      </div>
    )
  }

  let flatIndex = -1

  return (
    <div className={`flex justify-center p-6 ${className}`}>
      <div className="w-full max-w-lg overflow-hidden rounded-2xl border border-border/60 bg-card shadow-2xl">
        <div className="flex items-center gap-3 border-b border-border/60 px-4">
          <Search aria-hidden className="h-4 w-4 shrink-0 text-muted-foreground" />

          <input
            autoFocus={!embedded}
            type="text"
            role="combobox"
            aria-expanded="true"
            aria-controls={`${uid}-command-list`}
            aria-activedescendant={
              results[highlight] ? `command-item-${results[highlight].id}` : undefined
            }
            aria-label={placeholder}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            className="flex-1 bg-transparent py-3.5 text-sm outline-none placeholder:text-muted-foreground"
          />

          <kbd className="shrink-0 rounded border border-border/60 bg-muted px-1.5 py-0.5 font-mono text-xs text-muted-foreground">
            esc
          </kbd>
        </div>

        <div
          ref={listRef}
          id={`${uid}-command-list`}
          role="listbox"
          aria-label="Commands"
          className="max-h-72 overflow-y-auto p-2"
        >
          {results.length === 0 ? (
            <p className="px-3 py-8 text-center text-sm text-muted-foreground">
              No commands match “{query}”
            </p>
          ) : (
            grouped.map(([group, groupItems]) => (
              <div key={group} className="mb-1 last:mb-0">
                <p className="px-2 py-1.5 text-xs font-bold uppercase tracking-wider text-muted-foreground">
                  {group}
                </p>

                {groupItems.map((item) => {
                  flatIndex += 1
                  const active = flatIndex === highlight

                  return (
                    <button
                      key={item.id}
                      id={`command-item-${item.id}`}
                      type="button"
                      role="option"
                      aria-selected={active}
                      data-highlighted={active}
                      onMouseEnter={() => setHighlight(results.indexOf(item))}
                      onClick={() => {
                        item.onSelect?.()
                        setOpen(false)
                      }}
                      className={`flex w-full items-center gap-3 rounded-xl px-3 py-2 text-left text-sm transition-colors ${
                        active ? 'bg-primary/10 text-foreground' : 'text-muted-foreground'
                      }`}
                    >
                      <span className={active ? 'text-primary' : ''}>{item.icon}</span>
                      <span className="flex-1 truncate">{item.label}</span>
                      {item.shortcut ? (
                        <kbd className="rounded border border-border/60 bg-muted px-1.5 py-0.5 font-mono text-xs">
                          {item.shortcut}
                        </kbd>
                      ) : null}
                    </button>
                  )
                })}
              </div>
            ))
          )}
        </div>

        <div className="flex items-center gap-4 border-t border-border/60 px-4 py-2 text-xs text-muted-foreground">
          <span className="inline-flex items-center gap-1">
            <ArrowUp aria-hidden className="h-3 w-3" />
            <ArrowDown aria-hidden className="h-3 w-3" />
            navigate
          </span>
          <span className="inline-flex items-center gap-1">
            <CornerDownLeft aria-hidden className="h-3 w-3" />
            select
          </span>
          <span className="ml-auto">
            {results.length} {results.length === 1 ? 'result' : 'results'}
          </span>
        </div>
      </div>
    </div>
  )
}

search-results-panel.source:
/**
 * <SearchResultsPanel> — the page-level search surface, grouped by section.
 *
 * A flat ranked list makes users read snippets to figure out what each
 * result even is. Grouping by section with a visible breadcrumb path
 * flips that: people recognise *where* a result lives ("Docs › Auth")
 * far faster than they parse a sentence of context, so the eye jumps to
 * the right group and reads two rows instead of ten. The match itself is
 * a real <mark> — semantic highlighting, styled with tokens so it
 * survives dark mode instead of becoming browser-default yellow on navy.
 *
 * The footer row is deliberate: the worst search outcome is a dead end,
 * so "no luck" always routes somewhere a human answers.
 */

import * as React from 'react'
import { ChevronRight, LifeBuoy, Search } from 'lucide-react'

export interface SearchResult {
  title: string
  /** Breadcrumb segments, e.g. ['Docs', 'Authentication']. */
  path: string[]
  /** Snippet split around the matched term: [before, match, after]. */
  snippet: [string, string, string]
  href?: string
}

export interface SearchResultGroup {
  section: string
  results: SearchResult[]
}

export interface SearchResultsPanelProps {
  query?: string
  groups?: SearchResultGroup[]
  supportHref?: string
  className?: string
}

const DEFAULT_GROUPS: SearchResultGroup[] = [
  {
    section: 'Docs',
    results: [
      {
        title: 'Rotating API keys without downtime',
        path: ['Docs', 'Authentication'],
        snippet: ['Create the replacement ', 'API key', ' first, then revoke the old one after the grace window.'],
        href: '#',
      },
      {
        title: 'Environment variables and secrets',
        path: ['Docs', 'Configuration'],
        snippet: ['Never commit an ', 'API key', ' to source control; load it from the environment at boot.'],
        href: '#',
      },
    ],
  },
  {
    section: 'API reference',
    results: [
      {
        title: 'POST /v1/keys',
        path: ['API', 'Keys'],
        snippet: ['Issues a new ', 'API key', ' scoped to the requesting workspace. Returns the secret once.'],
        href: '#',
      },
      {
        title: 'Error 401: invalid_key',
        path: ['API', 'Errors'],
        snippet: ['Returned when the ', 'API key', ' is missing, expired, or was revoked on 12 Jul 2026.'],
        href: '#',
      },
    ],
  },
  {
    section: 'Guides',
    results: [
      {
        title: 'Shipping your first integration',
        path: ['Guides', 'Getting started'],
        snippet: ['Grab a test-mode ', 'API key', ' from the dashboard — it takes about two minutes.'],
        href: '#',
      },
    ],
  },
]

const FILTERS: Array<{ label: string; count: number; active?: boolean }> = [
  { label: 'All', count: 5, active: true },
  { label: 'Docs', count: 2 },
  { label: 'API', count: 2 },
  { label: 'Guides', count: 1 },
]

export function SearchResultsPanel({
  query = 'API key',
  groups = DEFAULT_GROUPS,
  supportHref = '#',
  className = '',
}: SearchResultsPanelProps) {
  const total = groups.reduce((sum, group) => sum + group.results.length, 0)

  return (
    <section className={`mx-auto w-full max-w-2xl ${className}`}>
      <div className="relative">
        <Search
          aria-hidden
          className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
        />
        <input
          type="search"
          defaultValue={query}
          aria-label="Search documentation"
          className="w-full rounded-xl border border-border/60 bg-background py-3 pl-11 pr-24 text-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring"
        />
        <span className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-xs tabular-nums text-muted-foreground">
          {total} results
        </span>
      </div>

      <ul className="mt-3 flex flex-wrap gap-2">
        {FILTERS.map((filter) => (
          <li key={filter.label}>
            <a
              href="#"
              aria-current={filter.active ? 'true' : undefined}
              className={`inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-semibold transition-colors ${
                filter.active
                  ? 'border-primary/40 bg-primary/10 text-primary'
                  : 'border-border/60 text-muted-foreground hover:bg-muted hover:text-foreground'
              }`}
            >
              {filter.label}
              <span className="tabular-nums opacity-70">{filter.count}</span>
            </a>
          </li>
        ))}
      </ul>

      <div className="mt-6 space-y-6">
        {groups.map((group) => (
          <div key={group.section}>
            <h3 className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
              {group.section}
            </h3>
            <ul className="mt-2 divide-y divide-border/60 overflow-hidden rounded-xl border border-border/60 bg-card/60">
              {group.results.map((result) => (
                <li key={result.title}>
                  <a
                    href={result.href ?? '#'}
                    className="block px-4 py-3 transition-colors hover:bg-muted/40"
                  >
                    <p className="text-sm font-semibold text-card-foreground">{result.title}</p>
                    <p className="mt-0.5 flex items-center gap-1 text-xs text-muted-foreground">
                      {result.path.map((segment, i) => (
                        <React.Fragment key={segment}>
                          {i > 0 ? (
                            <ChevronRight aria-hidden className="h-3 w-3 shrink-0" />
                          ) : null}
                          <span>{segment}</span>
                        </React.Fragment>
                      ))}
                    </p>
                    <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
                      {result.snippet[0]}
                      <mark className="rounded-sm bg-primary/15 px-0.5 font-medium text-foreground">
                        {result.snippet[1]}
                      </mark>
                      {result.snippet[2]}
                    </p>
                  </a>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>

      <a
        href={supportHref}
        className="mt-6 flex items-center gap-3 rounded-xl border border-dashed border-border/60 px-4 py-3 text-sm text-muted-foreground transition-colors hover:bg-muted/40 hover:text-foreground"
      >
        <LifeBuoy aria-hidden className="h-4 w-4 shrink-0" />
        No luck? Ask support — a human replies within a working day.
      </a>
    </section>
  )
}

file-dropzone.source:
'use client'

/**
 * <FileDropzone> — drag-and-drop upload with per-file progress.
 *
 * The drag counter is the part everyone gets wrong. `dragleave` fires when
 * the pointer crosses into a *child* element, so a naive
 * `onDragLeave={() => setActive(false)}` makes the highlight flicker as you
 * move across the zone's own contents. Counting enter/leave pairs and only
 * clearing at zero is the fix.
 *
 * The zone is also a real <label> wrapping a file input, so clicking and
 * keyboard activation both work without re-implementing either — a div with
 * an onClick that opens a file picker is unreachable by keyboard.
 *
 * Rejected files stay listed with the reason rather than being dropped
 * silently, which is how users end up believing an upload succeeded.
 */

import * as React from 'react'
import { CloudUpload, File as FileIcon, X, CircleCheck, TriangleAlert } from 'lucide-react'

export interface UploadItem {
  id: string
  name: string
  size: number
  /** 0–100. */
  progress: number
  error?: string
}

export interface FileDropzoneProps {
  accept?: string
  maxSizeMb?: number
  initialFiles?: UploadItem[]
  onFiles?: (files: File[]) => void
  className?: string
}

const DEFAULT_FILES: UploadItem[] = [
  { id: '1', name: 'brand-guidelines.pdf', size: 2_411_724, progress: 100 },
  { id: '2', name: 'hero-render.png', size: 8_930_112, progress: 64 },
  { id: '3', name: 'archive.zip', size: 148_930_112, progress: 0, error: 'Larger than the 20 MB limit' },
]

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export function FileDropzone({
  accept = 'image/*,application/pdf',
  maxSizeMb = 20,
  initialFiles = DEFAULT_FILES,
  onFiles,
  className = '',
}: FileDropzoneProps) {
  const [files, setFiles] = React.useState(initialFiles)
  const [active, setActive] = React.useState(false)

  // Enter/leave fire per element crossed, not per zone — count the pairs.
  const depth = React.useRef(0)

  function handleDragEnter(event: React.DragEvent) {
    event.preventDefault()
    depth.current += 1
    setActive(true)
  }

  function handleDragLeave(event: React.DragEvent) {
    event.preventDefault()
    depth.current -= 1
    if (depth.current <= 0) {
      depth.current = 0
      setActive(false)
    }
  }

  function handleDrop(event: React.DragEvent) {
    event.preventDefault()
    depth.current = 0
    setActive(false)
    addFiles(Array.from(event.dataTransfer.files))
  }

  function addFiles(incoming: File[]) {
    if (incoming.length === 0) return
    onFiles?.(incoming)

    setFiles((prev) => [
      ...prev,
      ...incoming.map((file, i) => ({
        id: `${Date.now()}-${i}`,
        name: file.name,
        size: file.size,
        progress: 0,
        error:
          file.size > maxSizeMb * 1024 * 1024
            ? `Larger than the ${maxSizeMb} MB limit`
            : undefined,
      })),
    ])
  }

  return (
    <div className={`w-full ${className}`}>
      {/* A label wrapping the input — click and keyboard both work natively. */}
      <label
        onDragEnter={handleDragEnter}
        onDragLeave={handleDragLeave}
        onDragOver={(e) => e.preventDefault()}
        onDrop={handleDrop}
        className={`flex cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed px-6 py-12 text-center transition-colors focus-within:ring-2 focus-within:ring-primary ${
          active
            ? 'border-primary bg-primary/5'
            : 'border-border/60 bg-card/40 hover:border-primary/40 hover:bg-muted/30'
        }`}
      >
        <input
          type="file"
          multiple
          accept={accept}
          onChange={(e) => addFiles(Array.from(e.target.files ?? []))}
          className="sr-only"
        />

        <span
          aria-hidden
          className={`inline-flex h-12 w-12 items-center justify-center rounded-2xl transition-colors ${
            active ? 'bg-primary/15 text-primary' : 'bg-muted text-muted-foreground'
          }`}
        >
          <CloudUpload className="h-6 w-6" />
        </span>

        <span className="mt-4 block text-sm font-semibold">
          {active ? 'Drop to upload' : 'Drag files here, or click to browse'}
        </span>
        <span className="mt-1 block text-xs text-muted-foreground">
          Images and PDFs up to {maxSizeMb} MB each
        </span>
      </label>

      {files.length > 0 ? (
        <ul className="mt-4 space-y-2">
          {files.map((file) => {
            const done = !file.error && file.progress >= 100

            return (
              <li
                key={file.id}
                className="flex items-center gap-3 rounded-xl border border-border/60 bg-card/60 px-4 py-3"
              >
                <span
                  aria-hidden
                  className={`inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                    file.error
                      ? 'bg-destructive/10 text-destructive'
                      : done
                        ? 'bg-emerald-500/15 text-emerald-500'
                        : 'bg-muted text-muted-foreground'
                  }`}
                >
                  {file.error ? (
                    <TriangleAlert className="h-4 w-4" />
                  ) : done ? (
                    <CircleCheck className="h-4 w-4" />
                  ) : (
                    <FileIcon className="h-4 w-4" />
                  )}
                </span>

                <div className="min-w-0 flex-1">
                  <p className="flex items-baseline justify-between gap-3">
                    <span className="truncate text-sm font-medium">{file.name}</span>
                    <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
                      {formatSize(file.size)}
                    </span>
                  </p>

                  {file.error ? (
                    <p className="mt-0.5 text-xs text-destructive">{file.error}</p>
                  ) : done ? (
                    <p className="mt-0.5 text-xs text-muted-foreground">Uploaded</p>
                  ) : (
                    <div
                      role="progressbar"
                      aria-valuenow={file.progress}
                      aria-valuemin={0}
                      aria-valuemax={100}
                      aria-label={`Uploading ${file.name}`}
                      className="mt-1.5 h-1 overflow-hidden rounded-full bg-muted"
                    >
                      <span
                        className="block h-full rounded-full bg-primary transition-all"
                        style={{ width: `${file.progress}%` }}
                      />
                    </div>
                  )}
                </div>

                <button
                  type="button"
                  onClick={() => setFiles((prev) => prev.filter((f) => f.id !== file.id))}
                  aria-label={`Remove ${file.name}`}
                  className="shrink-0 rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                >
                  <X aria-hidden className="h-4 w-4" />
                </button>
              </li>
            )
          })}
        </ul>
      ) : null}
    </div>
  )
}

upload-progress-list.source:
'use client'

/**
 * <UploadProgressList> — the list that follows the dropzone.
 *
 * The dropzone is the easy half of an uploader; this list is where the
 * real work lives, because it is the only place cancel, retry and
 * failure can exist. The classic bug is hiding the failed row — the
 * upload dies, the row vanishes, and the user walks away certain their
 * file went up. Here a failure stays visible, says why, and carries a
 * retry button, which is the entire contract of the component.
 *
 * Progress bars are real `role="progressbar"` elements with
 * `aria-valuenow`, not styled divs — a screen reader should hear 62%,
 * not silence. The shimmer on active rows is `motion-safe:` gated.
 */

import * as React from 'react'
import {
  CircleCheck,
  FileArchive,
  FileImage,
  FileText,
  File as FileIcon,
  RotateCcw,
  X,
} from 'lucide-react'

export type UploadState = 'complete' | 'uploading' | 'queued' | 'failed'

export interface UploadRow {
  id: string
  name: string
  size: string
  state: UploadState
  /** 0–100, meaningful only while uploading. */
  progress?: number
  error?: string
}

export interface UploadProgressListProps {
  files?: UploadRow[]
  className?: string
}

const DEFAULT_FILES: UploadRow[] = [
  { id: 'f1', name: 'onboarding-deck.pdf', size: '4.2 MB', state: 'complete' },
  { id: 'f2', name: 'team-offsite-photos.zip', size: '212 MB', state: 'uploading', progress: 62 },
  { id: 'f3', name: 'homepage-hero.png', size: '8.7 MB', state: 'uploading', progress: 18 },
  { id: 'f4', name: 'q3-financials.xlsx', size: '318 KB', state: 'queued' },
  { id: 'f5', name: 'launch-video-draft.mp4', size: '1.4 GB', state: 'failed', error: 'Connection lost at 34%' },
]

function iconFor(name: string) {
  const ext = name.split('.').pop()?.toLowerCase() ?? ''
  if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'].includes(ext)) return FileImage
  if (['zip', 'tar', 'gz', 'rar', '7z'].includes(ext)) return FileArchive
  if (['pdf', 'doc', 'docx', 'txt', 'md'].includes(ext)) return FileText
  return FileIcon
}

export function UploadProgressList({
  files = DEFAULT_FILES,
  className = '',
}: UploadProgressListProps) {
  const [rows, setRows] = React.useState(files)

  function cancel(id: string) {
    setRows((prev) => prev.filter((row) => row.id !== id))
  }

  function retry(id: string) {
    setRows((prev) =>
      prev.map((row) =>
        row.id === id
          ? { ...row, state: 'uploading' as const, progress: 12, error: undefined }
          : row,
      ),
    )
  }

  return (
    <ul className={`mx-auto w-full max-w-lg space-y-2 ${className}`}>
      {rows.map((row) => {
        const Icon = iconFor(row.name)
        return (
          <li
            key={row.id}
            className="flex items-center gap-3 rounded-xl border border-border/60 bg-card/60 px-4 py-3"
          >
            <span
              aria-hidden
              className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                row.state === 'failed'
                  ? 'bg-destructive/10 text-destructive'
                  : row.state === 'complete'
                    ? 'bg-primary/10 text-primary'
                    : 'bg-muted text-muted-foreground'
              }`}
            >
              {row.state === 'complete' ? (
                <CircleCheck className="h-4 w-4" />
              ) : (
                <Icon className="h-4 w-4" />
              )}
            </span>

            <div className="min-w-0 flex-1">
              <p className="flex items-baseline justify-between gap-3">
                <span className="truncate text-sm font-medium text-card-foreground">
                  {row.name}
                </span>
                <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
                  {row.size}
                </span>
              </p>

              {row.state === 'complete' ? (
                <p className="mt-0.5 text-xs text-muted-foreground">Uploaded</p>
              ) : row.state === 'queued' ? (
                <p className="mt-0.5 text-xs text-muted-foreground">Queued — waiting for a slot</p>
              ) : row.state === 'failed' ? (
                <p className="mt-0.5 text-xs text-destructive">{row.error ?? 'Upload failed'}</p>
              ) : (
                <div className="mt-1.5 flex items-center gap-2">
                  <div
                    role="progressbar"
                    aria-valuenow={row.progress ?? 0}
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-label={`Uploading ${row.name}`}
                    className="h-1 flex-1 overflow-hidden rounded-full bg-muted"
                  >
                    <span
                      className="block h-full rounded-full bg-primary motion-safe:animate-pulse"
                      style={{ width: `${row.progress ?? 0}%` }}
                    />
                  </div>
                  <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
                    {row.progress ?? 0}%
                  </span>
                </div>
              )}
            </div>

            {row.state === 'failed' ? (
              <button
                type="button"
                onClick={() => retry(row.id)}
                className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1.5 text-xs font-semibold transition-colors hover:bg-muted"
              >
                <RotateCcw aria-hidden className="h-3.5 w-3.5" />
                Retry
              </button>
            ) : row.state !== 'complete' ? (
              <button
                type="button"
                onClick={() => cancel(row.id)}
                aria-label={`Cancel upload of ${row.name}`}
                className="shrink-0 rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              >
                <X aria-hidden className="h-4 w-4" />
              </button>
            ) : null}
          </li>
        )
      })}
    </ul>
  )
}

chat-thread-panel.source:
/**
 * <ChatThreadPanel> — the conversation itself: a scrolling thread with a
 * composer pinned under it.
 *
 * The part every hand-rolled chat gets wrong is the announcement. A thread
 * is a log, so it wants `role="log"` with `aria-live="polite"` — new turns
 * are read when they arrive and the reader is not interrupted mid-sentence.
 * What it must NOT be is `aria-live="assertive"`, which is what most
 * examples reach for and which makes a screen reader talk over the user
 * while they are still typing the next message.
 *
 * `aria-relevant="additions"` matters just as much: without it, a streaming
 * assistant message re-announces the whole answer on every token, because
 * every token is a text mutation inside the live region. Restricting the
 * region to additions is the difference between "one new message" and the
 * same paragraph read forty times.
 *
 * The other half is scroll. Pinning to the bottom on every new message is
 * correct only while the user is already at the bottom; doing it
 * unconditionally yanks them out of the message they scrolled up to read.
 * `stuck` tracks that, and the jump-to-latest button appears when it is
 * false, which is the affordance the auto-scroll replaced.
 */

'use client'

import * as React from 'react'
import { ArrowDown, Bot, Copy, RefreshCw, Send, ThumbsDown, ThumbsUp, User } from 'lucide-react'

export interface ChatMessage {
  id: string
  role: 'user' | 'assistant'
  content: string
  /** Shown under an assistant turn, e.g. "Searched 3 sources · 1.4s". */
  meta?: string
}

export interface ChatThreadPanelProps {
  title?: string
  subtitle?: string
  messages?: ChatMessage[]
  placeholder?: string
  /**
   * Skip the mount-time scroll to the newest message. A thread previewing
   * itself inside a grid would otherwise scroll the host page to this card.
   */
  embedded?: boolean
  className?: string
}

const DEFAULT_MESSAGES: ChatMessage[] = [
  {
    id: '1',
    role: 'user',
    content: 'Which of our regions missed their Q3 target, and by how much?',
  },
  {
    id: '2',
    role: 'assistant',
    content:
      'Two of the five missed. EMEA came in at 91% of target (−$412k) and APAC at 88% (−$260k). AMER, LATAM and ANZ all cleared, with LATAM the strongest at 118%. The EMEA gap is almost entirely one deal that slipped into October.',
    meta: 'Queried 2 tables · 1.4s',
  },
  {
    id: '3',
    role: 'user',
    content: 'Is that slipped deal still open?',
  },
  {
    id: '4',
    role: 'assistant',
    content:
      'Yes — it moved to Contracting on 4 October and is forecast to close this quarter. Booking it in Q3 would have put EMEA at 103%.',
    meta: 'Queried 1 table · 0.8s',
  },
]

export function ChatThreadPanel({
  title = 'Revenue assistant',
  subtitle = 'Connected to Warehouse · gpt-class model',
  messages = DEFAULT_MESSAGES,
  placeholder = 'Ask a follow-up…',
  embedded = false,
  className = '',
}: ChatThreadPanelProps) {
  const [draft, setDraft] = React.useState('')
  const [stuck, setStuck] = React.useState(true)
  const scrollRef = React.useRef<HTMLDivElement>(null)

  // "Near" rather than "at" — subpixel scroll heights mean an exact equality
  // check is false on a thread the user is, visually, at the bottom of.
  function onScroll() {
    const el = scrollRef.current
    if (!el) return
    setStuck(el.scrollHeight - el.scrollTop - el.clientHeight < 32)
  }

  function scrollToLatest(behavior: ScrollBehavior = 'smooth') {
    const el = scrollRef.current
    if (!el) return
    el.scrollTo({ top: el.scrollHeight, behavior })
  }

  React.useEffect(() => {
    // `scrollTo` on the container, never `scrollIntoView` on the message —
    // the latter walks every scrollable ancestor including the document.
    if (!embedded) scrollToLatest('auto')
  }, [embedded])

  return (
    <div
      className={`mx-auto flex h-[34rem] w-full max-w-2xl flex-col overflow-hidden rounded-2xl border border-border/60 bg-card ${className}`}
    >
      {/* -- Header ----------------------------------------------------- */}
      <div className="flex items-center gap-3 border-b border-border/60 px-5 py-3.5">
        <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary/10 text-primary">
          <Bot aria-hidden className="h-4 w-4" />
        </span>
        <div className="min-w-0">
          <p className="truncate text-sm font-semibold">{title}</p>
          <p className="truncate text-xs text-muted-foreground">{subtitle}</p>
        </div>
      </div>

      {/* -- Thread ----------------------------------------------------- */}
      <div className="relative min-h-0 flex-1">
        <div
          ref={scrollRef}
          onScroll={onScroll}
          role="log"
          aria-live="polite"
          aria-relevant="additions"
          aria-label="Conversation"
          className="h-full space-y-5 overflow-y-auto px-5 py-5"
        >
          {messages.map((message) =>
            message.role === 'user' ? (
              <div key={message.id} className="flex justify-end gap-3">
                <div className="max-w-[80%] rounded-2xl rounded-br-md bg-primary px-4 py-2.5 text-sm leading-relaxed text-primary-foreground">
                  {/* Named for a reader that lands here out of context. */}
                  <span className="sr-only">You said: </span>
                  {message.content}
                </div>
                <span
                  aria-hidden
                  className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-full border border-border/60 bg-muted text-muted-foreground"
                >
                  <User className="h-3.5 w-3.5" />
                </span>
              </div>
            ) : (
              <div key={message.id} className="flex gap-3">
                <span
                  aria-hidden
                  className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary"
                >
                  <Bot className="h-3.5 w-3.5" />
                </span>

                <div className="min-w-0 max-w-[85%]">
                  <div className="rounded-2xl rounded-bl-md border border-border/60 bg-background px-4 py-2.5 text-sm leading-relaxed">
                    <span className="sr-only">Assistant said: </span>
                    {message.content}
                  </div>

                  <div className="mt-1.5 flex items-center gap-1">
                    {message.meta ? (
                      <span className="mr-1 text-xs text-muted-foreground">{message.meta}</span>
                    ) : null}
                    <TurnAction icon={<Copy className="h-3.5 w-3.5" />} label="Copy reply" />
                    <TurnAction icon={<RefreshCw className="h-3.5 w-3.5" />} label="Regenerate" />
                    <TurnAction icon={<ThumbsUp className="h-3.5 w-3.5" />} label="Good reply" />
                    <TurnAction icon={<ThumbsDown className="h-3.5 w-3.5" />} label="Bad reply" />
                  </div>
                </div>
              </div>
            ),
          )}
        </div>

        {/* Only offered while it is needed — a permanent button here reads
            as a broken scroll position. */}
        {stuck ? null : (
          <button
            type="button"
            onClick={() => scrollToLatest()}
            className="absolute bottom-3 left-1/2 inline-flex -translate-x-1/2 items-center gap-1.5 rounded-full border border-border/60 bg-card px-3 py-1.5 text-xs font-medium shadow-lg transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <ArrowDown aria-hidden className="h-3.5 w-3.5" />
            Jump to latest
          </button>
        )}
      </div>

      {/* -- Composer --------------------------------------------------- */}
      <form
        onSubmit={(e) => {
          e.preventDefault()
          setDraft('')
        }}
        className="border-t border-border/60 p-3"
      >
        <div className="flex items-end gap-2 rounded-xl border border-border/60 bg-background p-2 focus-within:ring-2 focus-within:ring-ring">
          <textarea
            rows={1}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              // Enter sends, Shift-Enter breaks the line — and the IME guard
              // stops Enter-to-commit-a-candidate from firing a send in
              // Japanese, Chinese and Korean input.
              if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
                e.preventDefault()
                e.currentTarget.form?.requestSubmit()
              }
            }}
            placeholder={placeholder}
            aria-label={placeholder}
            className="max-h-32 min-h-9 flex-1 resize-none bg-transparent px-1.5 py-1.5 text-sm outline-none placeholder:text-muted-foreground"
          />
          <button
            type="submit"
            disabled={draft.trim().length === 0}
            className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-primary text-primary-foreground transition-opacity disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          >
            <Send aria-hidden className="h-4 w-4" />
            <span className="sr-only">Send message</span>
          </button>
        </div>
      </form>
    </div>
  )
}

/**
 * An icon-only action under an assistant turn.
 *
 * The label is `sr-only` rather than a `title`: a tooltip attribute is not
 * reliably read, and an icon button with no accessible name is announced as
 * "button" four times in a row.
 */
function TurnAction({ icon, label }: { icon: React.ReactNode; label: string }) {
  return (
    <button
      type="button"
      className="rounded-md p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      <span aria-hidden>{icon}</span>
      <span className="sr-only">{label}</span>
    </button>
  )
}

chat-prompt-bar.source:
/**
 * <ChatPromptBar> — the composer, with `@` sources, `/` commands, a model
 * picker and attachment chips.
 *
 * This is the block people underestimate. A textarea and a send button take
 * five minutes; the trigger menus take a day, and this is what they need:
 *
 *  - The menu opens only when the trigger character starts a *token* — after
 *    a space or at position zero. Without that check, typing an email
 *    address opens the mention menu halfway through `you@example.com`, and
 *    every `and/or` opens the command menu.
 *  - The query is the text between the trigger and the caret, so the menu
 *    closes by itself when the user types past a match or backspaces over
 *    the trigger. No separate "is the menu open" state to get out of sync.
 *  - Focus never leaves the textarea. The menu is a `listbox` addressed by
 *    `aria-activedescendant`, the combobox pattern — moving real focus into
 *    the list would stop the user typing to filter it.
 *  - Arrow keys, Enter and Tab are intercepted only while the menu is open,
 *    and Escape closes the menu rather than clearing the draft.
 *  - Enter sends, Shift-Enter breaks the line, and `isComposing` is checked
 *    so committing an IME candidate does not send a half-typed message.
 *
 * The textarea grows with its content by resetting `height` to `auto` before
 * reading `scrollHeight` — skip the reset and it only ever grows, never
 * shrinks back when the draft is deleted.
 */

'use client'

import * as React from 'react'
import {
  ArrowUp,
  AtSign,
  ChevronDown,
  Database,
  FileText,
  Globe,
  Mic,
  Paperclip,
  Slash,
  Sparkles,
  X,
} from 'lucide-react'

export interface PromptSource {
  id: string
  label: string
  hint?: string
  kind?: 'file' | 'table' | 'web'
}

export interface PromptCommand {
  id: string
  label: string
  hint?: string
}

export interface ChatPromptBarProps {
  placeholder?: string
  sources?: PromptSource[]
  commands?: PromptCommand[]
  models?: string[]
  /** Chips shown above the field, as if already attached. */
  attachments?: string[]
  className?: string
}

const DEFAULT_SOURCES: PromptSource[] = [
  { id: 'q3-report', label: 'Q3-forecast.xlsx', hint: 'Sheet · 3 tabs', kind: 'file' },
  { id: 'orders', label: 'warehouse.orders', hint: 'Table · 2.1M rows', kind: 'table' },
  { id: 'accounts', label: 'warehouse.accounts', hint: 'Table · 48k rows', kind: 'table' },
  { id: 'handbook', label: 'Pricing handbook', hint: 'Doc · updated Tuesday', kind: 'file' },
  { id: 'status', label: 'status.acme.com', hint: 'Web · live', kind: 'web' },
]

const DEFAULT_COMMANDS: PromptCommand[] = [
  { id: 'summarise', label: '/summarise', hint: 'Condense the attached sources' },
  { id: 'chart', label: '/chart', hint: 'Plot the last result' },
  { id: 'compare', label: '/compare', hint: 'Diff two periods' },
  { id: 'explain', label: '/explain', hint: 'Walk through the reasoning' },
]

const DEFAULT_MODELS = ['Fast', 'Balanced', 'Deep reasoning']

const KIND_ICON = {
  file: FileText,
  table: Database,
  web: Globe,
} as const

export function ChatPromptBar({
  placeholder = 'Ask anything — @ for sources, / for commands',
  sources = DEFAULT_SOURCES,
  commands = DEFAULT_COMMANDS,
  models = DEFAULT_MODELS,
  attachments = ['Q3-forecast.xlsx'],
  className = '',
}: ChatPromptBarProps) {
  const [draft, setDraft] = React.useState('')
  const [caret, setCaret] = React.useState(0)
  const [highlight, setHighlight] = React.useState(0)
  /** Trigger position the user pressed Escape on, so it stays closed. */
  const [dismissed, setDismissed] = React.useState<number | null>(null)
  const [model, setModel] = React.useState(models[1] ?? models[0] ?? '')
  const [modelOpen, setModelOpen] = React.useState(false)
  const [chips, setChips] = React.useState(attachments)
  const [dictating, setDictating] = React.useState(false)

  const fieldRef = React.useRef<HTMLTextAreaElement>(null)

  /**
   * The active trigger, derived from the draft and caret rather than stored.
   *
   * Deriving it is what makes the menu close on its own: backspace over the
   * `@` and there is no trigger to find, so there is no state left behind
   * claiming the menu is open.
   */
  const trigger = React.useMemo(() => {
    const before = draft.slice(0, caret)
    const match = /(^|\s)([@/])([^\s@/]*)$/.exec(before)
    if (!match) return null
    return { char: match[2] as '@' | '/', query: match[3], start: caret - match[3].length - 1 }
  }, [draft, caret])

  const results = React.useMemo(() => {
    if (!trigger) return []
    const term = trigger.query.toLowerCase()
    const pool =
      trigger.char === '@'
        ? sources.map((s) => ({ id: s.id, label: s.label, hint: s.hint, kind: s.kind }))
        : commands.map((c) => ({ id: c.id, label: c.label, hint: c.hint, kind: undefined }))
    return pool.filter((item) => item.label.toLowerCase().includes(term))
  }, [trigger, sources, commands])

  const open = trigger !== null && results.length > 0 && trigger.start !== dismissed

  // A highlight left at index 4 after the list filters down to two selects
  // the wrong row on Enter.
  React.useEffect(() => {
    setHighlight(0)
  }, [trigger?.char, trigger?.query])

  function grow(el: HTMLTextAreaElement) {
    el.style.height = 'auto'
    el.style.height = `${Math.min(el.scrollHeight, 160)}px`
  }

  function accept(index: number) {
    const item = results[index]
    if (!item || !trigger) return

    if (trigger.char === '@') {
      // Sources become chips, not text — the model gets a reference and the
      // user gets something they can remove without editing their sentence.
      setChips((list) => (list.includes(item.label) ? list : [...list, item.label]))
    }

    const inserted = trigger.char === '@' ? '' : `${item.label} `
    const next = draft.slice(0, trigger.start) + inserted + draft.slice(caret)
    setDraft(next)

    const position = trigger.start + inserted.length
    setCaret(position)
    requestAnimationFrame(() => {
      const el = fieldRef.current
      if (!el) return
      el.focus()
      el.setSelectionRange(position, position)
      grow(el)
    })
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (open) {
      if (event.key === 'ArrowDown') {
        event.preventDefault()
        setHighlight((i) => (i + 1) % results.length)
        return
      }
      if (event.key === 'ArrowUp') {
        event.preventDefault()
        setHighlight((i) => (i - 1 + results.length) % results.length)
        return
      }
      if (event.key === 'Enter' || event.key === 'Tab') {
        event.preventDefault()
        accept(highlight)
        return
      }
      if (event.key === 'Escape') {
        // Dismiss this one trigger. Escape must never clear the draft, and
        // it must not simply toggle a flag either — starting a *new* `@`
        // later has to reopen the menu without any extra bookkeeping, which
        // recording the dismissed position gives for free.
        event.preventDefault()
        setDismissed(trigger.start)
        return
      }
    }

    if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing) {
      event.preventDefault()
      setDraft('')
      requestAnimationFrame(() => {
        if (fieldRef.current) grow(fieldRef.current)
      })
    }
  }

  /** Keep the derived trigger in step with every caret move, not just typing. */
  function syncCaret(event: React.SyntheticEvent<HTMLTextAreaElement>) {
    setCaret(event.currentTarget.selectionStart ?? 0)
  }

  const listId = React.useId()

  return (
    <div className={`mx-auto w-full max-w-2xl p-6 ${className}`}>
      <div className="relative">
        {/* -- Trigger menu, above the field so it never covers the draft -- */}
        {open ? (
          <div
            id={listId}
            role="listbox"
            aria-label={trigger?.char === '@' ? 'Sources' : 'Commands'}
            className="absolute bottom-full left-0 z-20 mb-2 max-h-60 w-full overflow-y-auto rounded-xl border border-border/60 bg-card p-1.5 shadow-2xl"
          >
            <p className="px-2.5 py-1.5 text-xs font-bold uppercase tracking-wider text-muted-foreground">
              {trigger?.char === '@' ? 'Attach a source' : 'Run a command'}
            </p>

            {results.map((item, i) => {
              const Icon = item.kind ? KIND_ICON[item.kind] : Slash
              const active = i === highlight

              return (
                <div
                  key={item.id}
                  id={`${listId}-${item.id}`}
                  role="option"
                  aria-selected={active}
                  onMouseEnter={() => setHighlight(i)}
                  // Mouse down, not click: click fires after blur, and blur
                  // has already torn the menu down.
                  onMouseDown={(e) => {
                    e.preventDefault()
                    accept(i)
                  }}
                  className={`flex cursor-pointer items-center gap-3 rounded-lg px-2.5 py-2 text-sm ${
                    active ? 'bg-primary/10 text-foreground' : 'text-muted-foreground'
                  }`}
                >
                  <Icon aria-hidden className={`h-4 w-4 shrink-0 ${active ? 'text-primary' : ''}`} />
                  <span className="truncate font-medium text-foreground">{item.label}</span>
                  {item.hint ? (
                    <span className="ml-auto shrink-0 truncate text-xs text-muted-foreground">
                      {item.hint}
                    </span>
                  ) : null}
                </div>
              )
            })}
          </div>
        ) : null}

        <div className="rounded-2xl border border-border/60 bg-card p-2 shadow-sm focus-within:ring-2 focus-within:ring-ring">
          {/* -- Attachment chips ------------------------------------- */}
          {chips.length > 0 ? (
            <ul className="flex flex-wrap gap-1.5 px-1.5 pb-2 pt-1">
              {chips.map((chip) => (
                <li key={chip}>
                  <span className="inline-flex items-center gap-1.5 rounded-lg border border-border/60 bg-muted/60 py-1 pl-2 pr-1 text-xs">
                    <FileText aria-hidden className="h-3 w-3 text-muted-foreground" />
                    {chip}
                    <button
                      type="button"
                      onClick={() => setChips((list) => list.filter((c) => c !== chip))}
                      className="rounded p-0.5 text-muted-foreground transition-colors hover:bg-background hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <X aria-hidden className="h-3 w-3" />
                      <span className="sr-only">Remove {chip}</span>
                    </button>
                  </span>
                </li>
              ))}
            </ul>
          ) : null}

          <textarea
            ref={fieldRef}
            rows={1}
            value={draft}
            role="combobox"
            aria-expanded={open}
            aria-controls={open ? listId : undefined}
            aria-activedescendant={open ? `${listId}-${results[highlight]?.id}` : undefined}
            aria-autocomplete="list"
            aria-label={placeholder}
            placeholder={placeholder}
            onChange={(e) => {
              setDraft(e.target.value)
              setCaret(e.target.selectionStart ?? 0)
              grow(e.target)
            }}
            onKeyUp={syncCaret}
            onClick={syncCaret}
            onKeyDown={onKeyDown}
            className="max-h-40 w-full resize-none bg-transparent px-2 py-1.5 text-sm leading-relaxed outline-none placeholder:text-muted-foreground"
          />

          {/* -- Toolbar ---------------------------------------------- */}
          <div className="flex items-center gap-1 px-1 pt-1">
            <ToolbarButton icon={<Paperclip className="h-4 w-4" />} label="Attach a file" />
            <ToolbarButton
              icon={<AtSign className="h-4 w-4" />}
              label="Mention a source"
              onClick={() => {
                const next = `${draft}${draft.endsWith(' ') || draft === '' ? '' : ' '}@`
                setDraft(next)
                setCaret(next.length)
                fieldRef.current?.focus()
              }}
            />

            {/* -- Model picker -------------------------------------- */}
            <div className="relative">
              <button
                type="button"
                aria-haspopup="listbox"
                aria-expanded={modelOpen}
                onClick={() => setModelOpen((v) => !v)}
                onBlur={() => setModelOpen(false)}
                className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <Sparkles aria-hidden className="h-3.5 w-3.5" />
                {model}
                <ChevronDown aria-hidden className="h-3 w-3" />
              </button>

              {modelOpen ? (
                <ul
                  role="listbox"
                  aria-label="Model"
                  className="absolute bottom-full left-0 z-20 mb-1.5 w-44 rounded-xl border border-border/60 bg-card p-1 shadow-2xl"
                >
                  {models.map((name) => (
                    <li key={name}>
                      <button
                        type="button"
                        role="option"
                        aria-selected={name === model}
                        onMouseDown={(e) => {
                          e.preventDefault()
                          setModel(name)
                          setModelOpen(false)
                        }}
                        className={`w-full rounded-lg px-2.5 py-1.5 text-left text-xs transition-colors hover:bg-muted ${
                          name === model ? 'font-semibold text-foreground' : 'text-muted-foreground'
                        }`}
                      >
                        {name}
                      </button>
                    </li>
                  ))}
                </ul>
              ) : null}
            </div>

            <div className="ml-auto flex items-center gap-1">
              <button
                type="button"
                aria-pressed={dictating}
                onClick={() => setDictating((v) => !v)}
                className={`rounded-lg p-2 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
                  dictating
                    ? 'bg-rose-500/10 text-rose-500'
                    : 'text-muted-foreground hover:bg-muted hover:text-foreground'
                }`}
              >
                <Mic aria-hidden className="h-4 w-4" />
                <span className="sr-only">{dictating ? 'Stop dictation' : 'Dictate'}</span>
              </button>

              <button
                type="button"
                disabled={draft.trim().length === 0}
                onClick={() => setDraft('')}
                className="inline-flex h-8 w-8 items-center justify-center rounded-lg bg-primary text-primary-foreground transition-opacity disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
              >
                <ArrowUp aria-hidden className="h-4 w-4" />
                <span className="sr-only">Send</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      <p className="mt-2 px-1 text-center text-xs text-muted-foreground">
        <kbd className="rounded border border-border/60 bg-muted px-1 py-0.5 font-mono">Enter</kbd>{' '}
        to send ·{' '}
        <kbd className="rounded border border-border/60 bg-muted px-1 py-0.5 font-mono">
          Shift↵
        </kbd>{' '}
        for a new line
      </p>
    </div>
  )
}

function ToolbarButton({
  icon,
  label,
  onClick,
}: {
  icon: React.ReactNode
  label: string
  onClick?: () => void
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="rounded-lg p-2 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      <span aria-hidden>{icon}</span>
      <span className="sr-only">{label}</span>
    </button>
  )
}

chat-streaming-answer.source:
/**
 * <ChatStreamingAnswer> — an answer that arrives a token at a time, with
 * inline citations, reply actions and follow-up chips.
 *
 * Streaming is where accessible chat quietly breaks, so the handling here is
 * the point of the block:
 *
 *  - The text is NOT in a live region. A region that re-reads on every
 *    mutation turns a 60-token answer into 60 announcements of a growing
 *    paragraph. Instead the streaming *status* is announced once from a
 *    separate `role="status"`, and the finished text is announced once when
 *    it settles — which is what a reader actually wants read to them.
 *  - `prefers-reduced-motion` skips the animation outright rather than
 *    slowing it. There is no information in watching characters appear; the
 *    answer is the information, and a user who asked for less motion should
 *    simply have it.
 *  - The caret blink is `motion-safe:` for the same reason, and disappears
 *    the moment the stream ends so it cannot be mistaken for a hung request.
 *
 * The mount-time reset runs in a layout effect, not `useEffect`. The server
 * render has to emit the *finished* answer — an exported HTML snapshot of an
 * empty paragraph is worthless — so the client starts full and rewinds to
 * zero, and doing that after paint would flash the whole answer for a frame.
 */

'use client'

import * as React from 'react'
import { Bot, Check, Copy, CornerDownRight, ExternalLink, RotateCcw } from 'lucide-react'

export interface AnswerSource {
  id: number
  title: string
  host: string
}

export interface ChatStreamingAnswerProps {
  /**
   * The prompt this answers, shown as a bubble above it. Pass an empty
   * string to drop it — inside an existing thread the question has already
   * been rendered, and repeating it puts the same sentence on screen twice.
   */
  question?: string
  /** The answer body. `[1]`-style markers are linked to `sources`. */
  answer?: string
  sources?: AnswerSource[]
  followUps?: string[]
  /** Milliseconds per character while streaming. */
  speed?: number
  className?: string
}

const DEFAULT_ANSWER =
  'Churn concentrated in accounts under 20 seats, which lost 6.1% of ARR against 1.4% in the rest of the book [1]. The common thread is activation rather than price: teams that never connected a second data source churned at roughly four times the rate of those that did [2]. Only 11% of the cancellations cited cost in their exit survey, and most of those had already downgraded once [3].'

const DEFAULT_SOURCES: AnswerSource[] = [
  { id: 1, title: 'Q3 revenue cohorts', host: 'warehouse.arr_monthly' },
  { id: 2, title: 'Activation funnel, Jul–Sep', host: 'warehouse.events' },
  { id: 3, title: 'Cancellation survey responses', host: 'support.exit_surveys' },
]

const DEFAULT_FOLLOW_UPS = [
  'Which integrations correlate with retention?',
  'Show the same cut for last quarter',
  'Draft a save offer for the at-risk accounts',
]

/**
 * `useLayoutEffect` on the client, `useEffect` on the server.
 *
 * React warns that a layout effect does nothing during SSR, and it is right —
 * but the warning fires even when the effect exists precisely to correct the
 * server's output before the browser paints it. Swapping the hook by
 * environment is the standard way out, and it is the only reason the rewind
 * below does not flash.
 */
const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? React.useEffect : React.useLayoutEffect

export function ChatStreamingAnswer({
  question = 'Why did churn spike in Q3?',
  answer = DEFAULT_ANSWER,
  sources = DEFAULT_SOURCES,
  followUps = DEFAULT_FOLLOW_UPS,
  speed = 12,
  className = '',
}: ChatStreamingAnswerProps) {
  // Starts complete: this is what the server renders and what a user with
  // reduced motion keeps.
  const [shown, setShown] = React.useState(answer.length)
  const [copied, setCopied] = React.useState(false)
  const [run, setRun] = React.useState(0)

  const streaming = shown < answer.length

  useIsomorphicLayoutEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
    setShown(0)
  }, [answer, run])

  React.useEffect(() => {
    if (!streaming) return
    // Several characters per tick rather than one per tick: a 16ms timer per
    // character makes a 400-character answer take six seconds and pins a
    // timer to every card on the page while it does.
    const id = window.setInterval(() => {
      setShown((n) => Math.min(n + 3, answer.length))
    }, speed)
    return () => window.clearInterval(id)
  }, [streaming, answer.length, speed])

  React.useEffect(() => {
    if (!copied) return
    const id = window.setTimeout(() => setCopied(false), 2000)
    return () => window.clearTimeout(id)
  }, [copied])

  async function copy() {
    try {
      await navigator.clipboard?.writeText(answer)
      setCopied(true)
    } catch {
      // Denied or unavailable — the answer is still selectable text.
    }
  }

  const visible = answer.slice(0, shown)

  return (
    <div className={`mx-auto w-full max-w-2xl p-6 ${className}`}>
      {question ? (
        <p className="mb-5 text-right text-sm">
          <span className="inline-block rounded-2xl rounded-br-md bg-primary px-4 py-2.5 text-left text-primary-foreground">
            {question}
          </span>
        </p>
      ) : null}

      <div className="flex gap-3">
        <span
          aria-hidden
          className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary"
        >
          <Bot className="h-4 w-4" />
        </span>

        <div className="min-w-0 flex-1">
          {/* Announced once, and only while it is true. The answer text
              itself is deliberately outside every live region. */}
          <span role="status" className="sr-only">
            {streaming ? 'Generating answer' : 'Answer complete'}
          </span>

          <div className="rounded-2xl rounded-bl-md border border-border/60 bg-card px-4 py-3 text-sm leading-relaxed">
            <p>
              {renderWithCitations(visible, sources)}
              {streaming ? (
                <span
                  aria-hidden
                  className="ml-0.5 inline-block h-4 w-[2px] translate-y-0.5 bg-primary motion-safe:animate-pulse"
                />
              ) : null}
            </p>
          </div>

          {/* -- Sources ------------------------------------------------ */}
          <details className="group mt-2.5" open={!streaming}>
            <summary className="inline-flex cursor-pointer list-none items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
              <CornerDownRight aria-hidden className="h-3.5 w-3.5" />
              {sources.length} sources
            </summary>

            <ul className="mt-1.5 space-y-1">
              {sources.map((source) => (
                <li key={source.id}>
                  <a
                    href="#"
                    id={`citation-${source.id}`}
                    className="flex items-center gap-2.5 rounded-lg border border-border/60 bg-card/60 px-2.5 py-2 text-xs transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md bg-muted font-mono text-[10px] font-semibold">
                      {source.id}
                    </span>
                    <span className="truncate font-medium">{source.title}</span>
                    <span className="ml-auto shrink-0 truncate font-mono text-[11px] text-muted-foreground">
                      {source.host}
                    </span>
                    <ExternalLink aria-hidden className="h-3 w-3 shrink-0 text-muted-foreground" />
                  </a>
                </li>
              ))}
            </ul>
          </details>

          {/* -- Actions ------------------------------------------------ */}
          <div className="mt-2 flex items-center gap-1.5">
            <button
              type="button"
              onClick={copy}
              className="inline-flex items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1.5 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {copied ? (
                <Check aria-hidden className="h-3.5 w-3.5 text-emerald-500" />
              ) : (
                <Copy aria-hidden className="h-3.5 w-3.5" />
              )}
              {copied ? 'Copied' : 'Copy'}
            </button>

            <button
              type="button"
              onClick={() => setRun((n) => n + 1)}
              className="inline-flex items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1.5 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <RotateCcw aria-hidden className="h-3.5 w-3.5" />
              Regenerate
            </button>
          </div>

          {/* -- Follow-ups -------------------------------------------- */}
          {followUps.length > 0 && !streaming ? (
            <div className="mt-4">
              <p className="mb-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Ask next
              </p>
              <ul className="flex flex-wrap gap-2">
                {followUps.map((text) => (
                  <li key={text}>
                    <button
                      type="button"
                      className="rounded-full border border-border/60 bg-card px-3 py-1.5 text-left text-xs transition-colors hover:border-primary/40 hover:bg-primary/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {text}
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
        </div>
      </div>
    </div>
  )
}

/**
 * Turn `[1]` markers into links to the source list below.
 *
 * Split rather than `dangerouslySetInnerHTML` — the answer text is model
 * output, which is the last string in the app that should be trusted as
 * markup. A citation whose number has no matching source is left as plain
 * text instead of linking to nothing.
 */
function renderWithCitations(text: string, sources: AnswerSource[]): React.ReactNode[] {
  const known = new Set(sources.map((s) => s.id))

  return text.split(/(\[\d+\])/g).map((part, i) => {
    const match = /^\[(\d+)\]$/.exec(part)
    const id = match ? Number(match[1]) : null

    if (id === null || !known.has(id)) return <React.Fragment key={i}>{part}</React.Fragment>

    return (
      <a
        key={i}
        href={`#citation-${id}`}
        // Leading margin only. A trailing one opens a visible gap before
        // the sentence's full stop, which reads as a typo.
        className="ml-0.5 inline-flex h-4 min-w-4 items-center justify-center rounded bg-primary/10 px-1 align-super font-mono text-[10px] font-semibold text-primary no-underline transition-colors hover:bg-primary/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        {id}
        <span className="sr-only"> — see source {id}</span>
      </a>
    )
  })
}

agent-thinking-trace.source:
/**
 * <AgentThinkingTrace> — the collapsible "thought for 12s" panel: what the
 * model considered, in order, expandable step by step.
 *
 * Two accessibility decisions carry this block.
 *
 * The outer summary is a real `<details>`/`<summary>`. Trace panels are the
 * classic case for it — a disclosure with no requirement to be controlled —
 * and using the element means the open state survives with JavaScript off,
 * responds to Enter and Space for free, and is exposed as a disclosure to
 * assistive tech without a single ARIA attribute.
 *
 * The steps are a different problem and get a different answer. Each one is
 * a button controlling its own region, because they need to be individually
 * expandable *and* individually addressable, and nested `<details>` inside
 * an open `<details>` gets announced as a disclosure inside a disclosure —
 * technically right, unbearable to listen to. So: `aria-expanded`,
 * `aria-controls`, and an ordered list, since the order is the meaning.
 *
 * Elapsed time is rendered as a `<time>` with a machine-readable `dateTime`,
 * not a bare string, and the status dots carry `sr-only` text — a coloured
 * ring is not a state for anyone who cannot see it.
 */

'use client'

import * as React from 'react'
import {
  Brain,
  ChevronRight,
  Code2,
  Database,
  FileSearch,
  Globe,
  ListChecks,
} from 'lucide-react'

export type ThinkingKind = 'plan' | 'search' | 'query' | 'code' | 'read'
export type ThinkingState = 'done' | 'active' | 'pending'

export interface ThinkingStep {
  id: string
  kind: ThinkingKind
  title: string
  /** The reasoning under the step, revealed when it is expanded. */
  detail: string
  state?: ThinkingState
  duration?: string
}

export interface AgentThinkingTraceProps {
  summary?: string
  elapsed?: string
  steps?: ThinkingStep[]
  /** Start with the trace open. */
  defaultOpen?: boolean
  className?: string
}

const KIND_ICON = {
  plan: ListChecks,
  search: Globe,
  query: Database,
  code: Code2,
  read: FileSearch,
} as const

const KIND_LABEL = {
  plan: 'Planning',
  search: 'Web search',
  query: 'Database',
  code: 'Code',
  read: 'Reading',
} as const

const DEFAULT_STEPS: ThinkingStep[] = [
  {
    id: 'plan',
    kind: 'plan',
    title: 'Decide what "churn" means here',
    detail:
      'The question is ambiguous between logo churn and revenue churn. Revenue churn is the one the finance dashboard reports, so I will use that and say so in the answer rather than asking and stalling.',
    state: 'done',
    duration: '0.4s',
  },
  {
    id: 'schema',
    kind: 'read',
    title: 'Check which tables carry cancellation dates',
    detail:
      'subscriptions.canceled_at is populated for 98% of rows; the gap is trials, which never had revenue attached. Excluding trials rather than imputing them.',
    state: 'done',
    duration: '1.1s',
  },
  {
    id: 'query',
    kind: 'query',
    title: 'Aggregate lost ARR by seat band',
    detail:
      'Grouped into <20, 20–99 and 100+ seats. The under-20 band is 6.1% against 1.4% elsewhere, which is large enough that I should check it is not one account before reporting it.',
    state: 'done',
    duration: '2.7s',
  },
  {
    id: 'verify',
    kind: 'code',
    title: 'Test whether one account explains the spike',
    detail:
      'Dropping the largest single cancellation moves the under-20 figure from 6.1% to 5.4%. The pattern holds, so it is a cohort effect and not an outlier.',
    state: 'active',
    duration: '0.9s',
  },
  {
    id: 'cite',
    kind: 'search',
    title: 'Pull exit-survey text for the same accounts',
    detail: 'Queued — will attach verbatim reasons to the three largest cancellations.',
    state: 'pending',
  },
]

const DOT = {
  done: 'bg-emerald-500',
  active: 'bg-primary motion-safe:animate-pulse',
  pending: 'bg-muted-foreground/40',
} as const

const DOT_LABEL = {
  done: 'Finished',
  active: 'In progress',
  pending: 'Not started',
} as const

export function AgentThinkingTrace({
  summary = 'Thought for 5.1 seconds',
  elapsed = '5.1s',
  steps = DEFAULT_STEPS,
  defaultOpen = true,
  className = '',
}: AgentThinkingTraceProps) {
  const [expanded, setExpanded] = React.useState<string[]>([steps[3]?.id ?? ''])

  function toggle(id: string) {
    setExpanded((open) => (open.includes(id) ? open.filter((x) => x !== id) : [...open, id]))
  }

  const baseId = React.useId()

  return (
    <div className={`mx-auto w-full max-w-2xl p-6 ${className}`}>
      <details
        open={defaultOpen}
        className="group overflow-hidden rounded-2xl border border-border/60 bg-card"
      >
        <summary className="flex cursor-pointer list-none items-center gap-3 px-4 py-3 transition-colors hover:bg-muted/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
          <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary">
            <Brain aria-hidden className="h-3.5 w-3.5" />
          </span>

          <span className="text-sm font-medium">{summary}</span>

          <time dateTime={`PT${elapsed.replace('s', 'S')}`} className="sr-only">
            {elapsed}
          </time>

          <span className="ml-auto text-xs text-muted-foreground">{steps.length} steps</span>

          <ChevronRight
            aria-hidden
            className="h-4 w-4 shrink-0 text-muted-foreground transition-transform group-open:rotate-90"
          />
        </summary>

        <ol className="border-t border-border/60 px-4 py-3">
          {steps.map((step, i) => {
            const state = step.state ?? 'done'
            const Icon = KIND_ICON[step.kind]
            const open = expanded.includes(step.id)
            const panelId = `${baseId}-${step.id}`
            const last = i === steps.length - 1

            return (
              <li key={step.id} className="relative pl-7">
                {/* The rail is drawn per step and stops on the last one, so
                    it does not trail off under nothing. */}
                {last ? null : (
                  <span
                    aria-hidden
                    className="absolute left-[7px] top-6 h-[calc(100%-1rem)] w-px bg-border"
                  />
                )}

                <span
                  aria-hidden
                  className={`absolute left-1 top-[15px] h-2 w-2 rounded-full ring-4 ring-card ${DOT[state]}`}
                />

                <button
                  type="button"
                  aria-expanded={open}
                  aria-controls={panelId}
                  onClick={() => toggle(step.id)}
                  className="flex w-full items-center gap-2.5 rounded-lg py-2 pl-1 pr-2 text-left transition-colors hover:bg-muted/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <Icon aria-hidden className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />

                  <span className="min-w-0 flex-1 truncate text-sm">
                    <span className="sr-only">
                      {KIND_LABEL[step.kind]}, {DOT_LABEL[state]}:{' '}
                    </span>
                    {step.title}
                  </span>

                  {step.duration ? (
                    <span className="shrink-0 font-mono text-[11px] text-muted-foreground">
                      {step.duration}
                    </span>
                  ) : null}

                  <ChevronRight
                    aria-hidden
                    className={`h-3.5 w-3.5 shrink-0 text-muted-foreground transition-transform ${
                      open ? 'rotate-90' : ''
                    }`}
                  />
                </button>

                {/* Unmounted when closed rather than hidden with CSS — a
                    `display: none` panel is still in the accessibility tree
                    in enough readers to matter. */}
                {open ? (
                  <div
                    id={panelId}
                    className="mb-1 ml-1 rounded-lg border-l-2 border-border bg-muted/40 px-3 py-2 text-xs leading-relaxed text-muted-foreground"
                  >
                    {step.detail}
                  </div>
                ) : null}
              </li>
            )
          })}
        </ol>
      </details>
    </div>
  )
}

agent-tool-calls.source:
/**
 * <AgentToolCalls> — tool invocations as compact chips that open into their
 * arguments and result.
 *
 * A run makes a dozen calls and only two of them are interesting, so the
 * default has to be dense: name, a one-line argument summary, a duration, a
 * status. Everything else is one click away.
 *
 * What is worth lifting:
 *
 *  - The status is never colour alone. Each chip carries an icon *and* an
 *    `sr-only` word, because "which of these failed" answered only in red is
 *    not answered for roughly one man in twelve.
 *  - Arguments render as a definition list — `<dt>` name, `<dd>` value —
 *    rather than a table, since the shape is genuinely key/value and a table
 *    of two columns forces a reader through row-and-column navigation for
 *    what is really a list of pairs.
 *  - Errors are `role="alert"` only when the panel is opened by the user.
 *    Marking a failed chip as an alert while the list renders would fire
 *    every past failure at a screen reader on page load.
 *  - The whole list is one `aria-busy` container while anything is running,
 *    which is how a reader learns the run is not finished without a live
 *    region reciting each call.
 */

'use client'

import * as React from 'react'
import {
  AlertTriangle,
  Check,
  ChevronRight,
  Database,
  FileCode2,
  Globe,
  Loader2,
  Terminal,
} from 'lucide-react'

export type ToolStatus = 'ok' | 'error' | 'running'

export interface ToolCall {
  id: string
  name: string
  kind?: 'query' | 'http' | 'shell' | 'file'
  /** One-line argument summary shown on the collapsed chip. */
  preview: string
  args?: Record<string, string>
  result?: string
  status?: ToolStatus
  duration?: string
}

export interface AgentToolCallsProps {
  heading?: string
  calls?: ToolCall[]
  className?: string
}

const KIND_ICON = {
  query: Database,
  http: Globe,
  shell: Terminal,
  file: FileCode2,
} as const

const STATUS_LABEL = {
  ok: 'Succeeded',
  error: 'Failed',
  running: 'Running',
} as const

const DEFAULT_CALLS: ToolCall[] = [
  {
    id: '1',
    name: 'warehouse.query',
    kind: 'query',
    preview: 'select … from subscriptions where canceled_at …',
    args: {
      sql: 'select seat_band, sum(arr) from subscriptions where canceled_at between $1 and $2 group by 1',
      params: '["2025-07-01", "2025-09-30"]',
      timeout: '30s',
    },
    result: '3 rows · 214 ms',
    status: 'ok',
    duration: '2.7s',
  },
  {
    id: '2',
    name: 'files.read',
    kind: 'file',
    preview: 'pricing-handbook.md',
    args: { path: 'docs/pricing-handbook.md', range: 'L1–L240' },
    result: '9.4 KB read',
    status: 'ok',
    duration: '0.3s',
  },
  {
    id: '3',
    name: 'crm.search',
    kind: 'http',
    preview: 'GET /accounts?status=at_risk',
    args: { url: 'https://api.crm.internal/v2/accounts', query: 'status=at_risk&limit=100' },
    result: 'HTTP 429 — rate limited, retrying in 4s',
    status: 'error',
    duration: '1.2s',
  },
  {
    id: '4',
    name: 'sandbox.exec',
    kind: 'shell',
    preview: 'python analyse_cohorts.py',
    args: { command: 'python analyse_cohorts.py --window 90d', cwd: '/workspace' },
    status: 'running',
  },
]

export function AgentToolCalls({
  heading = '4 tool calls · 2 messages',
  calls = DEFAULT_CALLS,
  className = '',
}: AgentToolCallsProps) {
  const [open, setOpen] = React.useState<string[]>([])
  const busy = calls.some((c) => (c.status ?? 'ok') === 'running')
  const baseId = React.useId()

  function toggle(id: string) {
    setOpen((list) => (list.includes(id) ? list.filter((x) => x !== id) : [...list, id]))
  }

  return (
    <div className={`mx-auto w-full max-w-2xl p-6 ${className}`}>
      <div
        aria-busy={busy}
        className="overflow-hidden rounded-2xl border border-border/60 bg-card"
      >
        <div className="flex items-center gap-2 border-b border-border/60 px-4 py-2.5">
          <Terminal aria-hidden className="h-3.5 w-3.5 text-muted-foreground" />
          <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            {heading}
          </h3>
        </div>

        <ul className="divide-y divide-border/40">
          {calls.map((call) => {
            const status = call.status ?? 'ok'
            const Icon = KIND_ICON[call.kind ?? 'query']
            const expanded = open.includes(call.id)
            const panelId = `${baseId}-${call.id}`

            return (
              <li key={call.id}>
                <button
                  type="button"
                  aria-expanded={expanded}
                  aria-controls={panelId}
                  onClick={() => toggle(call.id)}
                  className="flex w-full items-center gap-2.5 px-4 py-2.5 text-left transition-colors hover:bg-muted/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                >
                  <ChevronRight
                    aria-hidden
                    className={`h-3.5 w-3.5 shrink-0 text-muted-foreground transition-transform ${
                      expanded ? 'rotate-90' : ''
                    }`}
                  />

                  <Icon aria-hidden className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />

                  <code className="shrink-0 font-mono text-xs font-semibold">{call.name}</code>

                  <span className="min-w-0 flex-1 truncate font-mono text-xs text-muted-foreground">
                    {call.preview}
                  </span>

                  {call.duration ? (
                    <span className="shrink-0 font-mono text-[11px] text-muted-foreground">
                      {call.duration}
                    </span>
                  ) : null}

                  <StatusMark status={status} />
                </button>

                {expanded ? (
                  <div id={panelId} className="space-y-3 bg-muted/30 px-4 pb-3.5 pt-1">
                    {call.args ? (
                      <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1.5 pt-2">
                        {Object.entries(call.args).map(([key, value]) => (
                          <React.Fragment key={key}>
                            <dt className="font-mono text-[11px] text-muted-foreground">{key}</dt>
                            <dd className="min-w-0 break-words font-mono text-[11px]">{value}</dd>
                          </React.Fragment>
                        ))}
                      </dl>
                    ) : null}

                    {call.result ? (
                      <p
                        // Announced only because the user just opened this
                        // panel — never on first render.
                        role={status === 'error' ? 'alert' : undefined}
                        className={`rounded-lg border px-2.5 py-1.5 font-mono text-[11px] ${
                          status === 'error'
                            ? 'border-rose-500/30 bg-rose-500/10 text-rose-600 dark:text-rose-400'
                            : 'border-border/60 bg-background text-muted-foreground'
                        }`}
                      >
                        {call.result}
                      </p>
                    ) : null}

                    {status === 'running' && !call.result ? (
                      <p className="font-mono text-[11px] text-muted-foreground">
                        Waiting for output…
                      </p>
                    ) : null}
                  </div>
                ) : null}
              </li>
            )
          })}
        </ul>
      </div>
    </div>
  )
}

/**
 * Icon plus hidden word. The spinner degrades rather than stops under
 * reduced motion: a frozen spinner beside "Running" reads as a hung
 * process, which removes the feedback instead of the discomfort.
 */
function StatusMark({ status }: { status: ToolStatus }) {
  return (
    <span className="shrink-0">
      <span className="sr-only">{STATUS_LABEL[status]}</span>

      {status === 'ok' ? (
        <Check aria-hidden className="h-3.5 w-3.5 text-emerald-500" />
      ) : status === 'error' ? (
        <AlertTriangle aria-hidden className="h-3.5 w-3.5 text-rose-500" />
      ) : (
        <Loader2
          aria-hidden
          className="h-3.5 w-3.5 animate-spin text-primary motion-reduce:[animation-duration:2.4s]"
        />
      )}
    </span>
  )
}

agent-task-list.source:
/**
 * <AgentTaskList> — the run queue: what the agent is doing now, what it has
 * finished, and what failed.
 *
 * The block exists because a long-running agent is otherwise invisible. A
 * user who kicked off a job and sees nothing will start it again, and the
 * second run is usually the one that does damage.
 *
 * Live-region handling, which is the hard part:
 *
 *  - The list is `aria-live="polite"` but `aria-relevant="additions"`, so a
 *    task changing from Running to Done does not re-read every row. Only a
 *    genuinely new task is announced.
 *  - The *summary* line above the list is a `role="status"` and is where
 *    "3 of 5 complete" lives. Progress belongs in one small region that
 *    changes rarely, not scattered across rows that change constantly.
 *  - A failed row exposes its retry as a real button with the task name in
 *    its accessible name — five buttons all called "Retry" is a menu nobody
 *    can use.
 *  - `<progress>` is the native element, so the value is exposed without
 *    `role="progressbar"` and its ARIA triplet. Its bar is restyled but its
 *    semantics are untouched.
 */

'use client'

import * as React from 'react'
import { AlertCircle, Check, Loader2, Pause, Play, RotateCw, Square } from 'lucide-react'

export type TaskState = 'done' | 'running' | 'failed' | 'queued'

export interface AgentTask {
  id: string
  title: string
  detail?: string
  state: TaskState
  /** 0–100, only meaningful while running. */
  progress?: number
  duration?: string
}

export interface AgentTaskListProps {
  heading?: string
  tasks?: AgentTask[]
  className?: string
}

const DEFAULT_TASKS: AgentTask[] = [
  {
    id: '1',
    title: 'Pull cancellations for Q3',
    detail: '2,481 rows from warehouse.subscriptions',
    state: 'done',
    duration: '2.7s',
  },
  {
    id: '2',
    title: 'Join to account seat counts',
    detail: 'Matched 2,463 of 2,481 — 18 accounts deleted',
    state: 'done',
    duration: '1.4s',
  },
  {
    id: '3',
    title: 'Fetch exit-survey responses',
    detail: 'CRM returned 429 — rate limited after 40 of 300',
    state: 'failed',
    duration: '12.0s',
  },
  {
    id: '4',
    title: 'Score accounts by churn risk',
    detail: 'Running the model over the joined cohort',
    state: 'running',
    progress: 62,
  },
  {
    id: '5',
    title: 'Draft the summary',
    state: 'queued',
  },
]

const STATE_LABEL = {
  done: 'Complete',
  running: 'Running',
  failed: 'Failed',
  queued: 'Queued',
} as const

export function AgentTaskList({
  heading = 'Quarterly churn review',
  tasks = DEFAULT_TASKS,
  className = '',
}: AgentTaskListProps) {
  const [paused, setPaused] = React.useState(false)

  const done = tasks.filter((t) => t.state === 'done').length
  const failed = tasks.filter((t) => t.state === 'failed').length
  const active = tasks.some((t) => t.state === 'running')

  return (
    <div className={`mx-auto w-full max-w-2xl p-6 ${className}`}>
      <div
        aria-busy={active && !paused}
        className="overflow-hidden rounded-2xl border border-border/60 bg-card"
      >
        {/* -- Header ---------------------------------------------------- */}
        <div className="flex items-center gap-3 border-b border-border/60 px-4 py-3">
          <div className="min-w-0 flex-1">
            <h3 className="truncate text-sm font-semibold">{heading}</h3>

            {/* The one place progress is announced. */}
            <p role="status" className="mt-0.5 text-xs text-muted-foreground">
              {done} of {tasks.length} complete
              {failed > 0 ? ` · ${failed} failed` : ''}
              {paused ? ' · paused' : ''}
            </p>
          </div>

          <button
            type="button"
            onClick={() => setPaused((v) => !v)}
            className="inline-flex items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1.5 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {paused ? (
              <Play aria-hidden className="h-3.5 w-3.5" />
            ) : (
              <Pause aria-hidden className="h-3.5 w-3.5" />
            )}
            {paused ? 'Resume' : 'Pause'}
          </button>

          <button
            type="button"
            className="inline-flex items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <Square aria-hidden className="h-3 w-3" />
            Stop
          </button>
        </div>

        {/* -- Rows ------------------------------------------------------ */}
        <ul
          aria-live="polite"
          aria-relevant="additions"
          aria-label="Tasks"
          className="divide-y divide-border/40"
        >
          {tasks.map((task) => (
            <li key={task.id} className="flex items-start gap-3 px-4 py-3">
              <StateIcon state={task.state} paused={paused} />

              <div className="min-w-0 flex-1">
                <p
                  className={`truncate text-sm ${
                    task.state === 'queued' ? 'text-muted-foreground' : 'font-medium'
                  }`}
                >
                  <span className="sr-only">{STATE_LABEL[task.state]}: </span>
                  {task.title}
                </p>

                {task.detail ? (
                  <p
                    className={`mt-0.5 truncate text-xs ${
                      task.state === 'failed' ? 'text-rose-500' : 'text-muted-foreground'
                    }`}
                  >
                    {task.detail}
                  </p>
                ) : null}

                {task.state === 'running' && typeof task.progress === 'number' ? (
                  <progress
                    value={task.progress}
                    max={100}
                    aria-label={`${task.title} progress`}
                    className="mt-2 h-1 w-full appearance-none overflow-hidden rounded-full [&::-moz-progress-bar]:bg-primary [&::-webkit-progress-bar]:rounded-full [&::-webkit-progress-bar]:bg-muted [&::-webkit-progress-value]:rounded-full [&::-webkit-progress-value]:bg-primary"
                  >
                    {task.progress}%
                  </progress>
                ) : null}
              </div>

              {task.state === 'failed' ? (
                <button
                  type="button"
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <RotateCw aria-hidden className="h-3 w-3" />
                  Retry
                  {/* Distinguishes this Retry from every other Retry. */}
                  <span className="sr-only"> {task.title}</span>
                </button>
              ) : task.duration ? (
                <span className="shrink-0 pt-0.5 font-mono text-[11px] text-muted-foreground">
                  {task.duration}
                </span>
              ) : null}
            </li>
          ))}
        </ul>
      </div>
    </div>
  )
}

function StateIcon({ state, paused }: { state: TaskState; paused: boolean }) {
  const base = 'mt-0.5 h-4 w-4 shrink-0'

  if (state === 'done') return <Check aria-hidden className={`${base} text-emerald-500`} />
  if (state === 'failed') return <AlertCircle aria-hidden className={`${base} text-rose-500`} />
  if (state === 'queued') {
    return (
      <span
        aria-hidden
        className={`${base} rounded-full border-2 border-dashed border-muted-foreground/40`}
      />
    )
  }

  return (
    <Loader2
      aria-hidden
      // Slowed, not stopped, under reduced motion — and genuinely stopped
      // when the run is paused, where a still icon is the correct signal.
      className={`${base} text-primary motion-reduce:[animation-duration:2.4s] ${
        paused ? '' : 'animate-spin'
      }`}
    />
  )
}

agent-working-indicator.source:
/**
 * <AgentWorkingIndicator> — the "still here" state between the prompt and
 * the first token.
 *
 * A model can take fifteen seconds before it emits anything, and fifteen
 * seconds of nothing is indistinguishable from a dropped request. This is
 * the block that fills it, and the design constraints are unusual:
 *
 *  - It must convey elapsed time, because the honest answer to "is it stuck"
 *    is a number. A counter that ticks is proof of life in a way a spinner
 *    is not — a spinner keeps spinning after the socket dies.
 *  - The phase label changes as the wait lengthens, so a long request reads
 *    as progress rather than repetition.
 *  - It is `role="status"` with `aria-live="polite"`, but the *timer* is
 *    `aria-hidden`. A live region containing a number that changes ten times
 *    a second is a denial-of-service on a screen reader; the phase changes
 *    are what get announced, and they change every few seconds.
 *
 * Motion: the pixel grid is `motion-safe:` — pure decoration, and exactly
 * the sort of shimmer the preference exists to suppress. The timer keeps
 * running under reduced motion, because it is information, not motion.
 */

'use client'

import * as React from 'react'
import { Square } from 'lucide-react'

export interface AgentWorkingIndicatorProps {
  /** Phase labels, shown in order as the wait lengthens. */
  phases?: string[]
  /** Seconds each phase holds before the next one shows. */
  phaseSeconds?: number
  /** Start the timer paused, e.g. in a static preview. */
  paused?: boolean
  className?: string
}

const DEFAULT_PHASES = [
  'Reading your question',
  'Checking the warehouse schema',
  'Running the query',
  'Sanity-checking the numbers',
  'Writing it up',
]

/** 4×4 grid, lit in a spiral so the sweep reads as one moving shape. */
const SPIRAL = [0, 1, 2, 3, 7, 11, 15, 14, 13, 12, 8, 4, 5, 6, 10, 9]

export function AgentWorkingIndicator({
  phases = DEFAULT_PHASES,
  phaseSeconds = 3,
  paused = false,
  className = '',
}: AgentWorkingIndicatorProps) {
  const [tenths, setTenths] = React.useState(0)
  const [stopped, setStopped] = React.useState(paused)

  React.useEffect(() => {
    if (stopped) return
    const id = window.setInterval(() => setTenths((t) => t + 1), 100)
    return () => window.clearInterval(id)
  }, [stopped])

  const seconds = tenths / 10
  const phase = phases[Math.min(Math.floor(seconds / phaseSeconds), phases.length - 1)]

  return (
    <div className={`flex justify-center p-8 ${className}`}>
      <div className="flex w-full max-w-md items-center gap-4 rounded-2xl border border-border/60 bg-card px-4 py-3.5">
        {/* -- Pixel grid ------------------------------------------------ */}
        <div aria-hidden className="grid shrink-0 grid-cols-4 gap-[3px]">
          <style>{`
            @keyframes agent-pixel {
              0%, 100% { opacity: 0.15; }
              40%      { opacity: 1; }
            }
          `}</style>

          {SPIRAL.map((cell, i) => (
            <span
              key={cell}
              style={{ animationDelay: `${i * 70}ms` }}
              className="h-1.5 w-1.5 rounded-[2px] bg-primary opacity-40 motion-safe:animate-[agent-pixel_1.4s_ease-in-out_infinite]"
            />
          ))}
        </div>

        {/* -- Label ----------------------------------------------------- */}
        <div className="min-w-0 flex-1">
          {/*
            The phase is announced; the timer is not. Putting a tenth-second
            counter inside a live region floods a screen reader with numbers
            and drowns out the thing worth hearing.
          */}
          <p role="status" className="truncate text-sm font-medium">
            {stopped ? 'Stopped' : phase}
          </p>

          <p aria-hidden className="mt-0.5 font-mono text-xs tabular-nums text-muted-foreground">
            {seconds.toFixed(1)}s elapsed
          </p>
        </div>

        {/* Always offered. A run the user cannot cancel is the reason they
            reload the page, which is worse than cancelling. */}
        <button
          type="button"
          onClick={() => setStopped(true)}
          disabled={stopped}
          className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1.5 text-xs font-medium transition-colors hover:bg-muted disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <Square aria-hidden className="h-3 w-3" />
          Stop
        </button>
      </div>
    </div>
  )
}

approval-request-card.source:
/**
 * <ApprovalRequestCard> — the agent stops and asks before it acts.
 *
 * This is the block that decides whether an agent product is trustworthy,
 * and almost every version of it is too vague to approve safely. The rules
 * it follows:
 *
 *  - State the *effect*, not the intention. "Send 214 emails" is approvable;
 *    "proceed with outreach" is not. The consequence line is required, not
 *    decorative, and it names what changes and where.
 *  - Approve is never the pre-focused default. A card that appears under the
 *    user's hands with the destructive option focused will be approved by an
 *    Enter keypress meant for something else, so focus lands on the card's
 *    heading and the user must travel to a choice deliberately.
 *  - The options are radios in a `<fieldset>`, not buttons. Arrow keys move
 *    between them, the legend names the question for a screen reader, and —
 *    crucially — choosing is separate from committing, so a mis-click is not
 *    an irreversible action.
 *  - The decision is announced through `role="status"`, and the card keeps
 *    its resolved state on screen. An approval that vanishes leaves the user
 *    unable to answer "what did I just agree to".
 *
 * Real dialogs get `role="alertdialog"` and a focus trap. This one renders
 * inline in the thread, which is the shape most agents actually use, so it
 * is a `<section>` with a labelled heading instead.
 */

'use client'

import * as React from 'react'
import { AlertTriangle, ArrowRight, Check, ShieldAlert, X } from 'lucide-react'

export interface ApprovalOption {
  id: string
  label: string
  hint?: string
  /** Marks the choice that does the most damage if chosen carelessly. */
  destructive?: boolean
}

export interface ApprovalRequestCardProps {
  question?: string
  rationale?: string
  /** What changes if this is approved. Shown as a consequence list. */
  effects?: string[]
  options?: ApprovalOption[]
  /** Shown when the request touches something irreversible. */
  warning?: string
  className?: string
}

const DEFAULT_OPTIONS: ApprovalOption[] = [
  {
    id: 'core',
    label: 'Email the 38 accounts flagged high-risk',
    hint: 'Smallest blast radius — the cohort the model is most confident about',
  },
  {
    id: 'full',
    label: 'Email all 214 accounts in the at-risk segment',
    hint: 'Includes medium-confidence accounts; ~40 are likely false positives',
    destructive: true,
  },
  { id: 'none', label: 'Draft them for me to review, send nothing', hint: 'No mail leaves today' },
]

const DEFAULT_EFFECTS = [
  'Sends from retention@acme.com via the production Postmark key',
  'Writes a "save offer sent" activity to each CRM account',
  'Cannot be recalled once dispatched',
]

export function ApprovalRequestCard({
  question = 'Who should receive the retention offer?',
  rationale = 'I scored 214 accounts as at-risk for Q4. 38 of them cleared the high-confidence threshold. Sending to the full segment reaches more real churn but also more accounts that were never going to leave.',
  effects = DEFAULT_EFFECTS,
  options = DEFAULT_OPTIONS,
  warning = 'This sends real email from a production account.',
  className = '',
}: ApprovalRequestCardProps) {
  const [choice, setChoice] = React.useState(options[0]?.id ?? '')
  const [decision, setDecision] = React.useState<'approved' | 'declined' | null>(null)

  const selected = options.find((o) => o.id === choice)
  const headingId = React.useId()

  return (
    <section
      aria-labelledby={headingId}
      className={`mx-auto w-full max-w-xl overflow-hidden rounded-2xl border border-amber-500/30 bg-card ${className}`}
    >
      {/* -- Header ----------------------------------------------------- */}
      <div className="flex items-start gap-3 border-b border-border/60 bg-amber-500/5 px-5 py-4">
        <span className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-amber-500/15 text-amber-600 dark:text-amber-400">
          <ShieldAlert aria-hidden className="h-4 w-4" />
        </span>

        <div className="min-w-0">
          <p className="text-xs font-bold uppercase tracking-wider text-amber-600 dark:text-amber-400">
            Waiting on you
          </p>
          <h3 id={headingId} className="mt-0.5 text-base font-semibold leading-snug">
            {question}
          </h3>
        </div>
      </div>

      <div className="space-y-5 px-5 py-4">
        <p className="text-sm leading-relaxed text-muted-foreground">{rationale}</p>

        {/* -- What actually happens ----------------------------------- */}
        {effects.length > 0 ? (
          <div className="rounded-xl border border-border/60 bg-muted/40 px-4 py-3">
            <h4 className="mb-2 text-xs font-bold uppercase tracking-wider text-muted-foreground">
              If you approve
            </h4>
            <ul className="space-y-1.5">
              {effects.map((effect) => (
                <li key={effect} className="flex gap-2 text-xs leading-relaxed">
                  <ArrowRight
                    aria-hidden
                    className="mt-0.5 h-3 w-3 shrink-0 text-muted-foreground"
                  />
                  {effect}
                </li>
              ))}
            </ul>
          </div>
        ) : null}

        {/* -- Choices --------------------------------------------------- */}
        <fieldset disabled={decision !== null} className="disabled:opacity-60">
          <legend className="mb-2 text-xs font-bold uppercase tracking-wider text-muted-foreground">
            Choose one
          </legend>

          <div className="space-y-2">
            {options.map((option) => {
              const active = option.id === choice

              return (
                <label
                  key={option.id}
                  className={`flex cursor-pointer gap-3 rounded-xl border p-3 transition-colors has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring ${
                    active ? 'border-primary bg-primary/5' : 'border-border/60 hover:bg-muted/50'
                  }`}
                >
                  <input
                    type="radio"
                    name={`${headingId}-choice`}
                    value={option.id}
                    checked={active}
                    onChange={() => setChoice(option.id)}
                    className="mt-0.5 h-4 w-4 shrink-0 accent-primary"
                  />

                  <span className="min-w-0">
                    <span className="flex flex-wrap items-center gap-2 text-sm font-medium">
                      {option.label}
                      {option.destructive ? (
                        <span className="inline-flex items-center gap-1 rounded-full bg-rose-500/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-rose-600 dark:text-rose-400">
                          <AlertTriangle aria-hidden className="h-2.5 w-2.5" />
                          Widest reach
                        </span>
                      ) : null}
                    </span>
                    {option.hint ? (
                      <span className="mt-0.5 block text-xs leading-relaxed text-muted-foreground">
                        {option.hint}
                      </span>
                    ) : null}
                  </span>
                </label>
              )
            })}
          </div>
        </fieldset>

        {warning ? (
          <p className="flex gap-2 text-xs leading-relaxed text-amber-600 dark:text-amber-400">
            <AlertTriangle aria-hidden className="mt-0.5 h-3.5 w-3.5 shrink-0" />
            {warning}
          </p>
        ) : null}
      </div>

      {/* -- Decision --------------------------------------------------- */}
      <div className="flex items-center gap-2 border-t border-border/60 bg-muted/30 px-5 py-3">
        {decision === null ? (
          <>
            <button
              type="button"
              onClick={() => setDecision('declined')}
              className="inline-flex items-center gap-1.5 rounded-xl border border-border/60 px-3.5 py-2 text-sm font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <X aria-hidden className="h-4 w-4" />
              Decline
            </button>

            <button
              type="button"
              onClick={() => setDecision('approved')}
              className="ml-auto inline-flex items-center gap-1.5 rounded-xl bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            >
              <Check aria-hidden className="h-4 w-4" />
              Approve
            </button>
          </>
        ) : (
          <>
            {/* The card resolves in place. A decision that erases what was
                decided is not an audit trail. */}
            <p role="status" className="flex items-center gap-2 text-sm">
              {decision === 'approved' ? (
                <>
                  <Check aria-hidden className="h-4 w-4 text-emerald-500" />
                  <span>
                    Approved — <span className="font-medium">{selected?.label}</span>
                  </span>
                </>
              ) : (
                <>
                  <X aria-hidden className="h-4 w-4 text-muted-foreground" />
                  <span className="text-muted-foreground">Declined. Nothing was sent.</span>
                </>
              )}
            </p>

            <button
              type="button"
              onClick={() => setDecision(null)}
              className="ml-auto rounded-lg px-2.5 py-1.5 text-xs font-medium text-muted-foreground underline-offset-4 transition-colors hover:text-foreground hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              Undo
            </button>
          </>
        )}
      </div>
    </section>
  )
}

permission-scope-dialog.source:
/**
 * <PermissionScopeDialog> — granting an agent the tools it asked for, one
 * scope at a time, with a duration.
 *
 * The OAuth consent screen is the closest existing pattern and it is the
 * wrong one to copy wholesale: it grants forever, it bundles read with
 * write, and it renders scopes as machine strings. An agent needs the same
 * consent moment done better.
 *
 *  - Read and write scopes are visually and structurally separated. Bundling
 *    "see your invoices" with "issue refunds" behind one switch is how a
 *    user grants something they would have refused.
 *  - Write scopes default OFF. Every default here is the least powerful
 *    grant that still lets the agent do something, because a default is what
 *    most users will accept unchanged.
 *  - The grant has an expiry, chosen with radios. A permission with no end
 *    is the one nobody remembers to revoke.
 *  - Each switch is a real `<input type="checkbox" role="switch">` inside a
 *    `<label>`, so the whole row is a hit target, the state is announced as
 *    on/off, and space toggles it. Switch-shaped divs with click handlers
 *    are the usual version and are invisible to a keyboard.
 *  - The confirm button's label counts what is being granted, so the last
 *    thing read before committing is the size of the grant.
 */

'use client'

import * as React from 'react'
import { Clock, Eye, KeyRound, PencilLine, ShieldCheck } from 'lucide-react'

export interface PermissionScope {
  id: string
  label: string
  detail: string
  /** Write scopes are grouped apart and default to off. */
  write?: boolean
  /** Cannot be turned off — the agent does nothing without it. */
  required?: boolean
}

export interface PermissionScopeDialogProps {
  agentName?: string
  purpose?: string
  scopes?: PermissionScope[]
  durations?: string[]
  className?: string
}

const DEFAULT_SCOPES: PermissionScope[] = [
  {
    id: 'read-accounts',
    label: 'Read accounts and contacts',
    detail: 'Names, plan, seat count, renewal date',
    required: true,
  },
  {
    id: 'read-usage',
    label: 'Read product usage events',
    detail: 'Last 90 days, aggregated per account',
  },
  {
    id: 'read-tickets',
    label: 'Read support tickets',
    detail: 'Subject and status only — message bodies stay private',
  },
  {
    id: 'write-notes',
    label: 'Write notes on accounts',
    detail: 'Appends to the activity log; nothing is overwritten',
    write: true,
  },
  {
    id: 'write-email',
    label: 'Send email on your behalf',
    detail: 'From retention@acme.com, to customers, without a second prompt',
    write: true,
  },
]

const DEFAULT_DURATIONS = ['This session', '7 days', '30 days']

export function PermissionScopeDialog({
  agentName = 'Retention agent',
  purpose = 'It needs to see who is at risk, and — if you let it — act on that.',
  scopes = DEFAULT_SCOPES,
  durations = DEFAULT_DURATIONS,
  className = '',
}: PermissionScopeDialogProps) {
  // Reads on, writes off. The default is the grant most people will accept
  // without reading, so it has to be the safe one.
  const [granted, setGranted] = React.useState<string[]>(
    scopes.filter((s) => !s.write).map((s) => s.id),
  )
  const [duration, setDuration] = React.useState(durations[0] ?? '')

  const reads = scopes.filter((s) => !s.write)
  const writes = scopes.filter((s) => s.write)
  const writeCount = writes.filter((s) => granted.includes(s.id)).length
  const headingId = React.useId()

  function toggle(scope: PermissionScope) {
    if (scope.required) return
    setGranted((list) =>
      list.includes(scope.id) ? list.filter((x) => x !== scope.id) : [...list, scope.id],
    )
  }

  return (
    <div className={`flex justify-center p-6 ${className}`}>
      <section
        aria-labelledby={headingId}
        className="w-full max-w-md overflow-hidden rounded-2xl border border-border/60 bg-card shadow-2xl"
      >
        {/* -- Header ----------------------------------------------------- */}
        <div className="border-b border-border/60 px-5 py-4 text-center">
          <span className="inline-flex h-11 w-11 items-center justify-center rounded-2xl bg-primary/10 text-primary">
            <KeyRound aria-hidden className="h-5 w-5" />
          </span>
          <h3 id={headingId} className="mt-3 text-base font-semibold">
            Give {agentName} access
          </h3>
          <p className="mt-1 text-sm leading-relaxed text-muted-foreground">{purpose}</p>
        </div>

        {/* Tall enough to show the write scopes without scrolling. A cap
            that hides them defeats the block: "writes are off by default"
            is only reassuring if you can see the writes. */}
        <div className="max-h-[32rem] space-y-5 overflow-y-auto px-5 py-4">
          <ScopeGroup
            icon={<Eye aria-hidden className="h-3.5 w-3.5" />}
            title="Can see"
            scopes={reads}
            granted={granted}
            onToggle={toggle}
          />

          {writes.length > 0 ? (
            <ScopeGroup
              icon={<PencilLine aria-hidden className="h-3.5 w-3.5" />}
              title="Can change"
              note="Off by default. These act without asking again."
              scopes={writes}
              granted={granted}
              onToggle={toggle}
              emphasised
            />
          ) : null}

          {/* -- Duration -------------------------------------------------- */}
          <fieldset>
            <legend className="mb-2 flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider text-muted-foreground">
              <Clock aria-hidden className="h-3.5 w-3.5" />
              Expires after
            </legend>

            <div className="flex gap-2">
              {durations.map((option) => (
                <label
                  key={option}
                  className={`flex flex-1 cursor-pointer items-center justify-center rounded-xl border px-2 py-2 text-xs font-medium transition-colors has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring ${
                    option === duration
                      ? 'border-primary bg-primary/5 text-foreground'
                      : 'border-border/60 text-muted-foreground hover:bg-muted/50'
                  }`}
                >
                  <input
                    type="radio"
                    name={`${headingId}-duration`}
                    value={option}
                    checked={option === duration}
                    onChange={() => setDuration(option)}
                    className="sr-only"
                  />
                  {option}
                </label>
              ))}
            </div>
          </fieldset>
        </div>

        {/* -- Commit ------------------------------------------------------ */}
        <div className="space-y-2 border-t border-border/60 bg-muted/30 px-5 py-4">
          <button
            type="button"
            className="w-full rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          >
            {/* Counting the grant in the label puts the size of the decision
                in the last thing read before it is made. */}
            Grant {granted.length} {granted.length === 1 ? 'permission' : 'permissions'}
            {writeCount > 0 ? ` — ${writeCount} that can change data` : ''}
          </button>

          <button
            type="button"
            className="w-full rounded-xl px-4 py-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            Not now
          </button>

          <p className="flex items-center justify-center gap-1.5 pt-1 text-xs text-muted-foreground">
            <ShieldCheck aria-hidden className="h-3.5 w-3.5" />
            Revocable at any time from Settings → Agents
          </p>
        </div>
      </section>
    </div>
  )
}

function ScopeGroup({
  icon,
  title,
  note,
  scopes,
  granted,
  onToggle,
  emphasised = false,
}: {
  icon: React.ReactNode
  title: string
  note?: string
  scopes: PermissionScope[]
  granted: string[]
  onToggle: (scope: PermissionScope) => void
  emphasised?: boolean
}) {
  return (
    <div>
      <h4
        className={`mb-1 flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider ${
          emphasised ? 'text-amber-600 dark:text-amber-400' : 'text-muted-foreground'
        }`}
      >
        {icon}
        {title}
      </h4>

      {note ? <p className="mb-2 text-xs text-muted-foreground">{note}</p> : null}

      <ul className="space-y-1">
        {scopes.map((scope) => {
          const on = granted.includes(scope.id)

          return (
            <li key={scope.id}>
              <label
                className={`flex items-start gap-3 rounded-xl px-2.5 py-2 transition-colors has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring ${
                  scope.required ? '' : 'cursor-pointer hover:bg-muted/50'
                }`}
              >
                <span className="min-w-0 flex-1">
                  <span className="flex flex-wrap items-center gap-2 text-sm font-medium">
                    {scope.label}
                    {scope.required ? (
                      <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-muted-foreground">
                        Required
                      </span>
                    ) : null}
                  </span>
                  <span className="mt-0.5 block text-xs leading-relaxed text-muted-foreground">
                    {scope.detail}
                  </span>
                </span>

                {/*
                  A checkbox with role="switch" — announced "on"/"off" rather
                  than "checked", toggled with space, and reachable by tab.
                  The visual switch is drawn from its state with peer-*, so
                  there is no second source of truth.
                */}
                <span className="relative mt-0.5 shrink-0">
                  <input
                    type="checkbox"
                    role="switch"
                    checked={on}
                    disabled={scope.required}
                    onChange={() => onToggle(scope)}
                    className="peer sr-only"
                  />
                  <span
                    aria-hidden
                    className="block h-5 w-9 rounded-full bg-muted-foreground/30 transition-colors peer-checked:bg-primary peer-disabled:opacity-50"
                  />
                  <span
                    aria-hidden
                    className="absolute left-0.5 top-0.5 block h-4 w-4 rounded-full bg-background transition-transform peer-checked:translate-x-4"
                  />
                </span>
              </label>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

context-chunk-cards.source:
/**
 * <ContextChunkCards> — the retrieved passages an answer was built from,
 * with their similarity scores and provenance.
 *
 * The debugging surface for RAG, and the trust surface for the user. When an
 * answer is wrong the first question is always "what did it actually read",
 * and this is the block that answers it.
 *
 * Details worth keeping:
 *
 *  - The matched span inside each chunk is a `<mark>`, not a coloured span.
 *    `<mark>` means "relevant to the current context" — precisely this — and
 *    is exposed as a highlight by screen readers rather than being silent.
 *  - Score is a `<meter>` with a hidden numeric label, so "0.82" is
 *    available to a reader instead of a bar it cannot see.
 *  - Chunks are ordered by score and *say* they are, because a list whose
 *    order carries meaning must declare it. The rank is rendered, not
 *    implied by position.
 *  - Long chunks clamp to four lines with a real expand button rather than a
 *    fade-out that hides text with no way to reach it.
 *  - The filter chips are a `radiogroup`, so arrow keys move between them
 *    and only the active one is in the tab order — the standard pattern for
 *    a single-choice toolbar.
 *
 * Score colouring never carries meaning alone: every card states its band in
 * text beside the meter.
 */

'use client'

import * as React from 'react'
import { ChevronDown, Database, FileText, Globe, MessageSquare } from 'lucide-react'

export type ChunkKind = 'doc' | 'table' | 'web' | 'ticket'

export interface ContextChunk {
  id: string
  kind: ChunkKind
  source: string
  location: string
  /** 0–1. */
  score: number
  text: string
  /** Substring of `text` to mark as the matched span. */
  match?: string
}

export interface ContextChunkCardsProps {
  heading?: string
  query?: string
  chunks?: ContextChunk[]
  className?: string
}

const KIND_ICON = {
  doc: FileText,
  table: Database,
  web: Globe,
  ticket: MessageSquare,
} as const

const KIND_LABEL = {
  doc: 'Document',
  table: 'Table',
  web: 'Web page',
  ticket: 'Support ticket',
} as const

const DEFAULT_CHUNKS: ContextChunk[] = [
  {
    id: '1',
    kind: 'doc',
    source: 'Pricing handbook',
    location: '§4.2 — Volume breaks',
    score: 0.91,
    text: 'Accounts above 1,200 units per order qualify for the tier-two rate of $8.40, held for the duration of the contract year. The break is applied per order, not per quarter, so a single large order beats two smaller ones of the same total volume.',
    match: 'The break is applied per order, not per quarter',
  },
  {
    id: '2',
    kind: 'ticket',
    source: 'Ticket #4192',
    location: 'Northwind Retail · resolved',
    score: 0.78,
    text: 'Customer asked why their November order did not get the tier-two price. Their October and November orders were 700 units each — combined they clear the break, individually they do not. Confirmed with finance that this is working as intended.',
    match: 'combined they clear the break, individually they do not',
  },
  {
    id: '3',
    kind: 'table',
    source: 'warehouse.orders',
    location: '2,481 rows scanned',
    score: 0.64,
    text: 'Aggregated order volume by account for the trailing four quarters, filtered to accounts with more than one order in the period.',
  },
  {
    id: '4',
    kind: 'web',
    source: 'supplier.example.com',
    location: 'Lead times · fetched today',
    score: 0.41,
    text: 'Standard lead time for the winter blend is 21 days from purchase order. Expedited shipping is available at a 15% surcharge and reduces this to 9 days.',
    match: '21 days from purchase order',
  },
]

const FILTERS = ['All', 'Documents', 'Tables', 'Web'] as const

/**
 * `<meter>` restyled while keeping its semantics.
 *
 * Flat selectors in a `<style>` block, not Tailwind utilities, for two
 * reasons that are invisible until the meter renders in platform yellow:
 * Chromium gates `::-webkit-meter-*` on the *prefixed*
 * `-webkit-appearance: none`, which `appearance-none` does not emit; and an
 * arbitrary variant nests as `:is(.cls)::-webkit-meter-bar`, which Chromium
 * rejects outright — a UA shadow pseudo-element cannot sit behind `:is()`.
 * See the fuller note in `confidence-recommendation`.
 */
const METER_CSS = `
  .hl-meter { -webkit-appearance: none; appearance: none; background: none; }
  .hl-meter::-webkit-meter-bar {
    background: var(--muted); border: none; border-radius: 9999px;
  }
  .hl-meter::-webkit-meter-optimum-value {
    background: var(--color-emerald-500, #10b981); border-radius: 9999px;
  }
  .hl-meter::-webkit-meter-suboptimum-value {
    background: var(--color-amber-500, #f59e0b); border-radius: 9999px;
  }
  .hl-meter::-webkit-meter-even-less-good-value {
    background: var(--color-rose-500, #f43f5e); border-radius: 9999px;
  }
  .hl-meter::-moz-meter-bar { border-radius: 9999px; }
`

function band(score: number) {
  if (score >= 0.8) return 'Strong match'
  if (score >= 0.6) return 'Partial match'
  return 'Weak match'
}

export function ContextChunkCards({
  heading = 'Retrieved context',
  query = 'why did northwind not get the volume price',
  chunks = DEFAULT_CHUNKS,
  className = '',
}: ContextChunkCardsProps) {
  const [filter, setFilter] = React.useState<(typeof FILTERS)[number]>('All')
  const [expanded, setExpanded] = React.useState<string[]>([])

  const visible = React.useMemo(() => {
    const wanted: Record<string, ChunkKind | null> = {
      All: null,
      Documents: 'doc',
      Tables: 'table',
      Web: 'web',
    }
    const kind = wanted[filter]
    const list = kind ? chunks.filter((c) => c.kind === kind) : chunks
    // Order is meaning here, so it is enforced rather than assumed.
    return [...list].sort((a, b) => b.score - a.score)
  }, [chunks, filter])

  return (
    <div className={`mx-auto w-full max-w-2xl p-6 ${className}`}>
      {/* Declared once for every meter below, not once per card. */}
      <style>{METER_CSS}</style>

      {/* -- Header ------------------------------------------------------ */}
      <div className="mb-4 flex flex-wrap items-center gap-3">
        <div className="min-w-0 flex-1">
          <h3 className="text-sm font-semibold">{heading}</h3>
          {/* Wraps rather than truncates: "ranked by similarity" is the
              part that explains the order, and it was the part being cut. */}
          <p className="mt-0.5 text-xs text-muted-foreground">
            {visible.length} chunks for “{query}”, ranked by similarity
          </p>
        </div>

        {/* Single-choice toolbar: arrow keys move, one stop in the tab
            order. `radiogroup` is the role that describes that. */}
        <div role="radiogroup" aria-label="Filter by source type" className="flex gap-1">
          {FILTERS.map((option) => {
            const active = option === filter
            return (
              <button
                key={option}
                type="button"
                role="radio"
                aria-checked={active}
                tabIndex={active ? 0 : -1}
                onClick={() => setFilter(option)}
                onKeyDown={(e) => {
                  if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return
                  e.preventDefault()
                  const i = FILTERS.indexOf(filter)
                  const next =
                    e.key === 'ArrowRight'
                      ? FILTERS[(i + 1) % FILTERS.length]
                      : FILTERS[(i - 1 + FILTERS.length) % FILTERS.length]
                  setFilter(next)
                }}
                className={`rounded-full border px-2.5 py-1 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
                  active
                    ? 'border-primary bg-primary/10 text-primary'
                    : 'border-border/60 text-muted-foreground hover:bg-muted'
                }`}
              >
                {option}
              </button>
            )
          })}
        </div>
      </div>

      {/* -- Chunks ------------------------------------------------------ */}
      <ol className="space-y-3">
        {visible.map((chunk, i) => {
          const Icon = KIND_ICON[chunk.kind]
          const open = expanded.includes(chunk.id)
          const panelId = `chunk-${chunk.id}`

          return (
            <li
              key={chunk.id}
              className="overflow-hidden rounded-2xl border border-border/60 bg-card"
            >
              <div className="flex items-center gap-2.5 border-b border-border/60 px-4 py-2.5">
                <span
                  aria-hidden
                  className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md bg-muted font-mono text-[10px] font-bold text-muted-foreground"
                >
                  {i + 1}
                </span>

                <Icon aria-hidden className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />

                <span className="min-w-0 truncate text-xs font-semibold">
                  <span className="sr-only">{KIND_LABEL[chunk.kind]}: </span>
                  {chunk.source}
                </span>

                <span className="min-w-0 shrink truncate text-xs text-muted-foreground">
                  · {chunk.location}
                </span>

                <span className="ml-auto flex shrink-0 items-center gap-2">
                  <span className="text-[11px] text-muted-foreground">{band(chunk.score)}</span>
                  <meter
                    value={chunk.score}
                    min={0}
                    max={1}
                    low={0.6}
                    high={0.8}
                    optimum={1}
                    aria-label={`Similarity ${chunk.score.toFixed(2)}`}
                    className="hl-meter h-1.5 w-12"
                  >
                    {chunk.score.toFixed(2)}
                  </meter>
                  <span className="font-mono text-[11px] tabular-nums text-muted-foreground">
                    {chunk.score.toFixed(2)}
                  </span>
                </span>
              </div>

              <div className="px-4 py-3">
                <p
                  id={panelId}
                  className={`text-xs leading-relaxed text-muted-foreground ${
                    open ? '' : 'line-clamp-4'
                  }`}
                >
                  {highlight(chunk.text, chunk.match)}
                </p>

                <button
                  type="button"
                  aria-expanded={open}
                  aria-controls={panelId}
                  onClick={() =>
                    setExpanded((list) =>
                      list.includes(chunk.id)
                        ? list.filter((x) => x !== chunk.id)
                        : [...list, chunk.id],
                    )
                  }
                  className="mt-2 inline-flex items-center gap-1 rounded-md text-xs font-medium text-primary transition-opacity hover:opacity-80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  {open ? 'Show less' : 'Show full chunk'}
                  <ChevronDown
                    aria-hidden
                    className={`h-3 w-3 transition-transform ${open ? 'rotate-180' : ''}`}
                  />
                </button>
              </div>
            </li>
          )
        })}
      </ol>
    </div>
  )
}

/**
 * Wrap the matched span in `<mark>`.
 *
 * Split on the literal substring rather than building a regex from it —
 * chunk text is retrieved content, and a `(` in it would otherwise throw
 * inside `new RegExp`.
 */
function highlight(text: string, match?: string): React.ReactNode {
  if (!match) return text

  const at = text.indexOf(match)
  if (at === -1) return text

  return (
    <>
      {text.slice(0, at)}
      <mark className="rounded bg-primary/15 px-0.5 text-foreground">{match}</mark>
      {text.slice(at + match.length)}
    </>
  )
}

knowledge-source-picker.source:
/**
 * <KnowledgeSourcePicker> — choosing what an assistant is allowed to read,
 * with indexing state per source.
 *
 * The block that decides whether answers are any good, and it has an
 * unusual requirement: it has to show *work in progress* honestly. A source
 * that is 40% indexed will answer questions badly, and hiding that behind a
 * green tick is how a user concludes the product is stupid rather than
 * still ingesting.
 *
 *  - Every source states its state in words — Ready, Indexing, Failed,
 *    Paused — beside the icon. Never colour alone.
 *  - Indexing rows carry a `<progress>` with an accessible name that
 *    includes the source, so five simultaneous bars are distinguishable.
 *  - A failed source explains itself inline and offers a fix, rather than
 *    a red dot and a support link.
 *  - The search field is `type="search"` with a label, and filtering is
 *    announced through a `role="status"` count — otherwise a keyboard user
 *    types and hears nothing change.
 *  - Selection is checkboxes in a `<fieldset>` with a `<legend>`, which is
 *    what turns eleven loose checkboxes into one answerable question.
 *
 * The footer states the *effect* of the current selection in plain language,
 * because "6 selected" does not tell anyone what the assistant will do.
 */

'use client'

import * as React from 'react'
import {
  AlertCircle,
  Check,
  Database,
  FileText,
  Github,
  Globe,
  Loader2,
  Pause,
  Plus,
  RotateCw,
  Search,
} from 'lucide-react'

export type IndexState = 'ready' | 'indexing' | 'failed' | 'paused'

export interface KnowledgeSource {
  id: string
  label: string
  kind: 'drive' | 'repo' | 'table' | 'site'
  detail: string
  state: IndexState
  /** 0–100, when indexing. */
  progress?: number
  /** Shown under a failed source. */
  error?: string
}

export interface KnowledgeSourcePickerProps {
  heading?: string
  sources?: KnowledgeSource[]
  className?: string
}

const KIND_ICON = {
  drive: FileText,
  repo: Github,
  table: Database,
  site: Globe,
} as const

const STATE_LABEL = {
  ready: 'Ready',
  indexing: 'Indexing',
  failed: 'Failed',
  paused: 'Paused',
} as const

const DEFAULT_SOURCES: KnowledgeSource[] = [
  {
    id: 'handbook',
    label: 'Company handbook',
    kind: 'drive',
    detail: 'Google Drive · 214 documents',
    state: 'ready',
  },
  {
    id: 'warehouse',
    label: 'Analytics warehouse',
    kind: 'table',
    detail: '18 tables · schema only, no row data',
    state: 'ready',
  },
  {
    id: 'repo',
    label: 'product/api',
    kind: 'repo',
    detail: 'GitHub · main branch, docs/ and README',
    state: 'indexing',
    progress: 44,
  },
  {
    id: 'helpsite',
    label: 'help.acme.com',
    kind: 'site',
    detail: 'Crawled weekly · 480 pages',
    state: 'ready',
  },
  {
    id: 'legal',
    label: 'Contracts archive',
    kind: 'drive',
    detail: 'SharePoint · 1,902 files',
    state: 'failed',
    error: 'Access denied — the connector account cannot read this folder.',
  },
  {
    id: 'notion',
    label: 'Design wiki',
    kind: 'site',
    detail: 'Paused by you on 2 August',
    state: 'paused',
  },
]

export function KnowledgeSourcePicker({
  heading = 'What can the assistant read?',
  sources = DEFAULT_SOURCES,
  className = '',
}: KnowledgeSourcePickerProps) {
  const [query, setQuery] = React.useState('')
  const [selected, setSelected] = React.useState<string[]>(
    sources.filter((s) => s.state === 'ready').map((s) => s.id),
  )

  const visible = React.useMemo(() => {
    const term = query.trim().toLowerCase()
    if (!term) return sources
    return sources.filter(
      (s) =>
        s.label.toLowerCase().includes(term) || s.detail.toLowerCase().includes(term),
    )
  }, [sources, query])

  const chosen = sources.filter((s) => selected.includes(s.id))
  const pending = chosen.filter((s) => s.state === 'indexing').length
  const searchId = React.useId()

  return (
    <div className={`mx-auto w-full max-w-xl p-6 ${className}`}>
      <div className="overflow-hidden rounded-2xl border border-border/60 bg-card">
        {/* -- Header ---------------------------------------------------- */}
        <div className="border-b border-border/60 px-5 py-4">
          <h3 className="text-sm font-semibold">{heading}</h3>
          <p className="mt-1 text-xs text-muted-foreground">
            Only selected sources are searched. Everything else stays invisible to it.
          </p>

          <div className="mt-3 flex items-center gap-2 rounded-xl border border-border/60 bg-background px-3 focus-within:ring-2 focus-within:ring-ring">
            <Search aria-hidden className="h-4 w-4 shrink-0 text-muted-foreground" />
            <label htmlFor={searchId} className="sr-only">
              Filter sources
            </label>
            <input
              id={searchId}
              type="search"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Filter sources"
              className="flex-1 bg-transparent py-2 text-sm outline-none placeholder:text-muted-foreground"
            />
          </div>

          {/* Without this a keyboard user types into the filter and gets no
              feedback that anything happened. */}
          <p role="status" className="sr-only">
            {visible.length} of {sources.length} sources shown
          </p>
        </div>

        {/* -- Sources --------------------------------------------------- */}
        {/* Sized to clear the failed source rather than clipping it. A
            connector that cannot be read is the row a user most needs to
            see, and it was the one falling below the fold. */}
        <fieldset className="max-h-[34rem] overflow-y-auto">
          <legend className="sr-only">Sources the assistant may read</legend>

          {visible.length === 0 ? (
            <p className="px-5 py-10 text-center text-sm text-muted-foreground">
              Nothing matches “{query}”.
            </p>
          ) : (
            <ul className="divide-y divide-border/40">
              {visible.map((source) => {
                const Icon = KIND_ICON[source.kind]
                const on = selected.includes(source.id)
                const blocked = source.state === 'failed'

                return (
                  <li key={source.id}>
                    <label
                      className={`flex items-start gap-3 px-5 py-3 transition-colors ${
                        blocked ? 'opacity-70' : 'cursor-pointer hover:bg-muted/40'
                      } has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-inset has-[:focus-visible]:ring-ring`}
                    >
                      <input
                        type="checkbox"
                        checked={on}
                        disabled={blocked}
                        onChange={() =>
                          setSelected((list) =>
                            list.includes(source.id)
                              ? list.filter((x) => x !== source.id)
                              : [...list, source.id],
                          )
                        }
                        className="mt-1 h-4 w-4 shrink-0 accent-primary"
                      />

                      <Icon aria-hidden className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />

                      <span className="min-w-0 flex-1">
                        <span className="flex flex-wrap items-center gap-2">
                          <span className="text-sm font-medium">{source.label}</span>
                          <StateBadge state={source.state} />
                        </span>

                        <span className="mt-0.5 block text-xs text-muted-foreground">
                          {source.detail}
                        </span>

                        {source.state === 'indexing' && typeof source.progress === 'number' ? (
                          <span className="mt-2 block">
                            <progress
                              value={source.progress}
                              max={100}
                              aria-label={`Indexing ${source.label}`}
                              className="h-1 w-full appearance-none overflow-hidden rounded-full [&::-moz-progress-bar]:bg-primary [&::-webkit-progress-bar]:rounded-full [&::-webkit-progress-bar]:bg-muted [&::-webkit-progress-value]:rounded-full [&::-webkit-progress-value]:bg-primary"
                            >
                              {source.progress}%
                            </progress>
                            <span className="mt-1 block text-[11px] text-muted-foreground">
                              {source.progress}% indexed — answers from this source will be
                              incomplete until it finishes
                            </span>
                          </span>
                        ) : null}

                        {source.error ? (
                          <span className="mt-1.5 flex items-start gap-2 text-[11px] leading-relaxed text-rose-600 dark:text-rose-400">
                            <AlertCircle aria-hidden className="mt-px h-3 w-3 shrink-0" />
                            {source.error}
                          </span>
                        ) : null}
                      </span>

                      {blocked ? (
                        <button
                          type="button"
                          className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                        >
                          <RotateCw aria-hidden className="h-3 w-3" />
                          Reconnect
                          <span className="sr-only"> {source.label}</span>
                        </button>
                      ) : null}
                    </label>
                  </li>
                )
              })}
            </ul>
          )}
        </fieldset>

        {/* -- Footer ---------------------------------------------------- */}
        <div className="flex flex-wrap items-center gap-3 border-t border-border/60 bg-muted/30 px-5 py-3">
          {/* The effect of the selection, not its cardinality. */}
          <p role="status" className="text-xs text-muted-foreground">
            {chosen.length === 0 ? (
              'Nothing selected — the assistant will answer from the conversation alone.'
            ) : (
              <>
                Searching{' '}
                <span className="font-medium text-foreground">
                  {chosen.length} {chosen.length === 1 ? 'source' : 'sources'}
                </span>
                {pending > 0 ? `, ${pending} still indexing` : ''}
              </>
            )}
          </p>

          <button
            type="button"
            className="ml-auto inline-flex items-center gap-1.5 rounded-xl border border-border/60 px-3 py-1.5 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <Plus aria-hidden className="h-3.5 w-3.5" />
            Connect a source
          </button>
        </div>
      </div>
    </div>
  )
}

function StateBadge({ state }: { state: IndexState }) {
  const shared =
    'inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide'

  if (state === 'ready') {
    return (
      <span className={`${shared} bg-emerald-500/10 text-emerald-600 dark:text-emerald-400`}>
        <Check aria-hidden className="h-2.5 w-2.5" />
        {STATE_LABEL.ready}
      </span>
    )
  }

  if (state === 'indexing') {
    return (
      <span className={`${shared} bg-primary/10 text-primary`}>
        <Loader2
          aria-hidden
          className="h-2.5 w-2.5 animate-spin motion-reduce:[animation-duration:2.4s]"
        />
        {STATE_LABEL.indexing}
      </span>
    )
  }

  if (state === 'failed') {
    return (
      <span className={`${shared} bg-rose-500/10 text-rose-600 dark:text-rose-400`}>
        <AlertCircle aria-hidden className="h-2.5 w-2.5" />
        {STATE_LABEL.failed}
      </span>
    )
  }

  return (
    <span className={`${shared} bg-muted text-muted-foreground`}>
      <Pause aria-hidden className="h-2.5 w-2.5" />
      {STATE_LABEL.paused}
    </span>
  )
}

selection-ai-toolbar.source:
/**
 * <SelectionAiToolbar> — highlight a passage, hand it to the model.
 *
 * The pattern that puts AI into an existing editor without a chat panel. It
 * is mostly a positioning problem, and the positioning is where every
 * implementation breaks:
 *
 *  - The toolbar is placed from `getBoundingClientRect()` on the selection
 *    range, converted into coordinates relative to the *container*, not the
 *    viewport. Absolute-positioning against the viewport looks right until
 *    the page scrolls one pixel.
 *  - It is clamped inside the container, so selecting a word at the left
 *    edge does not push the toolbar off-screen.
 *  - `onMouseDown` calls `preventDefault` on every button. Without it, the
 *    press collapses the selection before the click handler runs, and the
 *    toolbar acts on nothing — the single most common bug in this pattern.
 *  - Selection is read on `selectionchange`, filtered to ranges inside this
 *    block. A `mouseup` handler misses keyboard selection (Shift-Arrow)
 *    entirely, which is most of the users who need this to be reachable.
 *
 * Accessibility: the toolbar is a `role="toolbar"` with roving `tabIndex`,
 * so it is one tab stop and arrow keys move along it — the ARIA toolbar
 * pattern. Escape dismisses it and returns focus to the passage. A keyboard
 * user can therefore select text, Tab once, and act, which a hover-only
 * popover never allows.
 */

'use client'

import * as React from 'react'
import { Languages, Maximize2, Minimize2, MoreHorizontal, Sparkles, SpellCheck } from 'lucide-react'

export interface SelectionAction {
  id: string
  label: string
  icon: 'explain' | 'expand' | 'shorten' | 'tone' | 'grammar'
}

export interface SelectionAiToolbarProps {
  /** The document body. Selecting inside it raises the toolbar. */
  passage?: string
  actions?: SelectionAction[]
  /**
   * Phrase to pre-select on load, so the block demonstrates itself. Set to
   * an empty string for the real behaviour, where nothing shows until the
   * user selects something.
   */
  demoPhrase?: string
  className?: string
}

const ACTION_ICON = {
  explain: Sparkles,
  expand: Maximize2,
  shorten: Minimize2,
  tone: Languages,
  grammar: SpellCheck,
} as const

const DEFAULT_ACTIONS: SelectionAction[] = [
  { id: 'explain', label: 'Explain', icon: 'explain' },
  { id: 'improve', label: 'Improve', icon: 'expand' },
  { id: 'shorten', label: 'Shorten', icon: 'shorten' },
  { id: 'tone', label: 'Tone', icon: 'tone' },
  { id: 'grammar', label: 'Grammar', icon: 'grammar' },
]

const DEFAULT_PASSAGE =
  'The renewal conversation should start ninety days out, not thirty. By the time a customer is thirty days from renewal they have already formed a view, and the only lever left is discount. Teams that open the conversation at ninety days spend it on scope instead of price, and close at a materially higher rate — the difference in our own book was eleven points last year.'

/**
 * On the first line on purpose.
 *
 * The toolbar floats above its selection, which is correct — and means a
 * demo selection on line two covers line one, so the block previews as
 * though it were broken. Anchoring the default to the opening words puts
 * the toolbar in the container's top padding instead of over the prose.
 */
const DEMO_PHRASE = 'The renewal conversation'

export function SelectionAiToolbar({
  passage = DEFAULT_PASSAGE,
  actions = DEFAULT_ACTIONS,
  demoPhrase = DEMO_PHRASE,
  className = '',
}: SelectionAiToolbarProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const passageRef = React.useRef<HTMLParagraphElement>(null)

  const [selection, setSelection] = React.useState<string>(demoPhrase)
  const [position, setPosition] = React.useState<{ top: number; left: number } | null>(null)
  const [focused, setFocused] = React.useState(0)
  const [ran, setRan] = React.useState<string | null>(null)

  /** Place the toolbar over a rect, clamped inside the container. */
  const place = React.useCallback((rect: DOMRect) => {
    const box = containerRef.current?.getBoundingClientRect()
    if (!box) return
    const centre = rect.left + rect.width / 2 - box.left
    setPosition({
      top: rect.top - box.top,
      // Half the toolbar's own width is unknown before it renders, so the
      // clamp uses a fixed inset rather than a measured one — close enough
      // for a bar of this size, and it never leaves the container.
      left: Math.min(Math.max(centre, 130), box.width - 130),
    })
  }, [])

  // The demo selection, measured after layout so the rect is real.
  React.useEffect(() => {
    if (!demoPhrase) return
    const node = passageRef.current?.querySelector<HTMLElement>('[data-demo-span]')
    if (node) place(node.getBoundingClientRect())
  }, [demoPhrase, place])

  React.useEffect(() => {
    function onSelectionChange() {
      const sel = window.getSelection()
      const text = sel?.toString().trim() ?? ''

      // Only ranges that start inside this block. Without the containment
      // check, selecting text anywhere else on the page raises this
      // toolbar — which is exactly what happens on a page of previews.
      const anchor = sel?.anchorNode
      const inside = anchor ? passageRef.current?.contains(anchor) : false

      if (!text || !inside || sel?.isCollapsed) return

      const rect = sel?.getRangeAt(0).getBoundingClientRect()
      if (!rect || rect.width === 0) return

      setSelection(text)
      setRan(null)
      setFocused(0)
      place(rect)
    }

    document.addEventListener('selectionchange', onSelectionChange)
    return () => document.removeEventListener('selectionchange', onSelectionChange)
  }, [place])

  /** Roving focus along the toolbar — the ARIA toolbar pattern. */
  function onKeyDown(event: React.KeyboardEvent) {
    if (event.key === 'Escape') {
      setPosition(null)
      passageRef.current?.focus()
      return
    }
    if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return

    event.preventDefault()
    const next =
      event.key === 'ArrowRight'
        ? (focused + 1) % actions.length
        : (focused - 1 + actions.length) % actions.length
    setFocused(next)
    containerRef.current
      ?.querySelectorAll<HTMLButtonElement>('[data-toolbar-item]')
      [next]?.focus()
  }

  const marked = demoPhrase ? passage.split(demoPhrase) : [passage]

  return (
    <div className={`mx-auto w-full max-w-2xl p-6 ${className}`}>
      {/* Extra head room so a toolbar raised from the first line lands in
          padding rather than on top of the text. */}
      <div
        ref={containerRef}
        className="relative rounded-2xl border border-border/60 bg-card p-6 pt-16"
      >
        <p
          ref={passageRef}
          tabIndex={-1}
          className="text-sm leading-loose outline-none"
        >
          {marked.length === 2 ? (
            <>
              {marked[0]}
              <span data-demo-span className="rounded bg-primary/20 px-0.5">
                {demoPhrase}
              </span>
              {marked[1]}
            </>
          ) : (
            passage
          )}
        </p>

        {/* -- Toolbar ---------------------------------------------------- */}
        {position && selection ? (
          <div
            role="toolbar"
            aria-label={`Actions for the selected text`}
            aria-orientation="horizontal"
            onKeyDown={onKeyDown}
            style={{ top: position.top, left: position.left }}
            className="absolute z-20 flex -translate-x-1/2 -translate-y-[calc(100%+8px)] items-center gap-0.5 rounded-xl border border-border/60 bg-card p-1 shadow-2xl"
          >
            {actions.map((action, i) => {
              const Icon = ACTION_ICON[action.icon]
              return (
                <button
                  key={action.id}
                  type="button"
                  data-toolbar-item
                  tabIndex={i === focused ? 0 : -1}
                  // Without this the press collapses the selection before
                  // the click lands, and the action runs on nothing.
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => setRan(action.label)}
                  onFocus={() => setFocused(i)}
                  className="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <Icon aria-hidden className="h-3.5 w-3.5" />
                  {action.label}
                </button>
              )
            })}

            <span aria-hidden className="mx-0.5 h-5 w-px bg-border" />

            <button
              type="button"
              data-toolbar-item
              tabIndex={-1}
              onMouseDown={(e) => e.preventDefault()}
              className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <MoreHorizontal aria-hidden className="h-3.5 w-3.5" />
              <span className="sr-only">More actions</span>
            </button>
          </div>
        ) : null}
      </div>

      {/* -- Result ------------------------------------------------------- */}
      <p role="status" className="mt-3 min-h-5 text-xs text-muted-foreground">
        {ran ? (
          <>
            <span className="font-medium text-foreground">{ran}</span> — sent “
            {selection.length > 60 ? `${selection.slice(0, 60)}…` : selection}” to the model.
          </>
        ) : (
          'Select any text above to raise the toolbar. Shift-Arrow works too.'
        )}
      </p>
    </div>
  )
}

ai-inline-suggestion.source:
/**
 * <AiInlineSuggestion> — ghost-text completion inside a real field: the
 * model proposes the rest of the sentence, Tab accepts, Escape refuses.
 *
 * Copilot-style completion done as a plain textarea rather than an editor
 * framework. The technique is a two-layer overlay: a transparent-caret
 * textarea on top of a mirror div that renders the typed text plus the
 * suggestion in muted grey. Both layers must share every text metric —
 * font, size, leading, padding, wrapping — or the ghost drifts out of
 * alignment with the caret by a few pixels per line, which is worse than
 * not having it. That is why the metrics live in one constant used by both.
 *
 * Interaction rules that make it tolerable rather than infuriating:
 *
 *  - Tab accepts, Escape dismisses, and any other keystroke invalidates the
 *    suggestion. A completion that survives the next character is one the
 *    user has to fight.
 *  - A dismissed suggestion does not come back for the same prefix. Without
 *    that, Escape means "show it again in 400ms".
 *  - Nothing is proposed mid-word or while the field is empty.
 *  - The hint is announced through `role="status"` — a sighted user sees
 *    grey text, and everyone else is told a completion is available and how
 *    to take it. Ghost text with no announcement is invisible to a screen
 *    reader, which is the accessibility failure this pattern is known for.
 */

'use client'

import * as React from 'react'
import { CornerDownLeft, Sparkles } from 'lucide-react'

export interface SuggestionRule {
  /** Lowercased prefix the draft must end with. */
  when: string
  /** The completion offered, appended verbatim. */
  then: string
}

export interface AiInlineSuggestionProps {
  label?: string
  placeholder?: string
  /** Starting draft, so the block demonstrates itself. */
  defaultValue?: string
  rules?: SuggestionRule[]
  /** Milliseconds of quiet before a completion is offered. */
  delay?: number
  className?: string
}

/**
 * Shared text metrics.
 *
 * The mirror and the textarea must agree on every one of these or the ghost
 * text stops lining up with the caret.
 */
const METRICS =
  'w-full whitespace-pre-wrap break-words px-3.5 py-3 text-sm leading-relaxed font-sans'

const DEFAULT_RULES: SuggestionRule[] = [
  { when: 'thanks for flagging', then: ' this — I have raised it with the team and will follow up by Friday.' },
  { when: 'the renewal', then: ' conversation should start ninety days out, not thirty.' },
  { when: 'i wanted to', then: ' follow up on the pricing question from our call last week.' },
  { when: 'hi', then: ' there — quick update on where the migration stands.' },
]

export function AiInlineSuggestion({
  label = 'Reply',
  placeholder = 'Start typing — a completion appears after a moment…',
  defaultValue = 'Thanks for flagging',
  rules = DEFAULT_RULES,
  delay = 400,
  className = '',
}: AiInlineSuggestionProps) {
  const [value, setValue] = React.useState(defaultValue)
  const [suggestion, setSuggestion] = React.useState('')
  /** Prefixes the user has already refused, so Escape sticks. */
  const [refused, setRefused] = React.useState<string[]>([])
  const fieldRef = React.useRef<HTMLTextAreaElement>(null)
  const fieldId = React.useId()

  React.useEffect(() => {
    setSuggestion('')

    const draft = value.trimEnd()
    // Nothing mid-word, nothing on an empty field, nothing already refused.
    if (draft.length === 0 || draft !== value) return
    if (refused.includes(draft.toLowerCase())) return

    const id = window.setTimeout(() => {
      const lower = draft.toLowerCase()
      const rule = rules.find((r) => lower.endsWith(r.when))
      if (rule) setSuggestion(rule.then)
    }, delay)

    return () => window.clearTimeout(id)
  }, [value, rules, delay, refused])

  function accept() {
    if (!suggestion) return
    const next = value + suggestion
    setValue(next)
    setSuggestion('')
    requestAnimationFrame(() => {
      const el = fieldRef.current
      if (!el) return
      el.focus()
      el.setSelectionRange(next.length, next.length)
    })
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (!suggestion) return

    if (event.key === 'Tab') {
      event.preventDefault()
      accept()
      return
    }

    if (event.key === 'Escape') {
      event.preventDefault()
      setRefused((list) => [...list, value.trimEnd().toLowerCase()])
      setSuggestion('')
    }
  }

  return (
    <div className={`mx-auto w-full max-w-xl p-6 ${className}`}>
      <label htmlFor={fieldId} className="mb-2 block text-sm font-medium">
        {label}
      </label>

      <div className="relative rounded-2xl border border-border/60 bg-card focus-within:ring-2 focus-within:ring-ring">
        {/*
          The mirror. `aria-hidden` because its text duplicates the field's
          value, and a screen reader must not read the draft twice.
          `pointer-events-none` so clicks reach the textarea beneath.
        */}
        <div
          aria-hidden
          className={`pointer-events-none absolute inset-0 ${METRICS} text-transparent`}
        >
          {value}
          {suggestion ? <span className="text-muted-foreground/60">{suggestion}</span> : null}
        </div>

        <textarea
          ref={fieldRef}
          id={fieldId}
          rows={4}
          value={value}
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={onKeyDown}
          placeholder={placeholder}
          // Autocomplete off: a browser dropdown over ghost text is two
          // competing suggestions in the same place.
          autoComplete="off"
          spellCheck
          aria-describedby={suggestion ? `${fieldId}-hint` : undefined}
          className={`relative resize-none bg-transparent outline-none placeholder:text-muted-foreground ${METRICS}`}
        />
      </div>

      {/* The announcement ghost text otherwise lacks entirely. */}
      <p
        id={`${fieldId}-hint`}
        role="status"
        className="mt-2 flex min-h-5 items-center gap-2 text-xs text-muted-foreground"
      >
        {suggestion ? (
          <>
            <Sparkles aria-hidden className="h-3.5 w-3.5 shrink-0 text-primary" />
            <span>
              Suggestion available — press{' '}
              <kbd className="rounded border border-border/60 bg-muted px-1 py-0.5 font-mono">
                Tab
              </kbd>{' '}
              to accept,{' '}
              <kbd className="rounded border border-border/60 bg-muted px-1 py-0.5 font-mono">
                Esc
              </kbd>{' '}
              to dismiss
            </span>
          </>
        ) : (
          <>
            <CornerDownLeft aria-hidden className="h-3.5 w-3.5 shrink-0" />
            Keep typing — completions appear after a short pause.
          </>
        )}
      </p>

      {suggestion ? (
        <button
          type="button"
          onClick={accept}
          className="mt-2 inline-flex items-center gap-1.5 rounded-lg border border-border/60 px-2.5 py-1.5 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <Sparkles aria-hidden className="h-3.5 w-3.5" />
          Accept suggestion
        </button>
      ) : null}
    </div>
  )
}

ai-insight-cards.source:
/**
 * <AiInsightCards> — paged findings an agent surfaced on its own, each with
 * a sparkline, a magnitude and a way to disagree with it.
 *
 * Unprompted insight is the highest-risk surface in an AI product: nobody
 * asked for it, so it has to earn its place on screen every time. The design
 * rules that follow from that:
 *
 *  - Every card states the *size* of the finding, not just its direction.
 *    "Churn up" is noise; "churn up 4.7 points, worth $412k" is a decision.
 *  - Every card can be dismissed with a reason, and the reasons are the
 *    training signal. An insight feed with no "not useful" is a feed nobody
 *    trusts.
 *  - The sparkline is drawn as an inline SVG with `role="img"` and a real
 *    label, so the trend is available as a sentence to anyone who cannot see
 *    the line. A chart with no text alternative is decoration.
 *  - Paging is a `tablist`-free carousel: previous/next buttons with a
 *    `role="status"` position readout, which is simpler and more robust than
 *    tabs for a set that changes daily.
 *
 * The SVG path is computed from the data rather than hand-drawn, so a real
 * series drops in without redrawing anything.
 */

'use client'

import * as React from 'react'
import { ArrowDownRight, ArrowUpRight, ChevronLeft, ChevronRight, Sparkles, X } from 'lucide-react'

export interface Insight {
  id: string
  title: string
  body: string
  /** Headline magnitude, e.g. "+4.7 pts". */
  delta: string
  direction: 'up' | 'down'
  /** True when up is bad — churn rising, latency rising. */
  inverted?: boolean
  metric: string
  series: number[]
  action?: string
}

export interface AiInsightCardsProps {
  heading?: string
  insights?: Insight[]
  className?: string
}

const DEFAULT_INSIGHTS: Insight[] = [
  {
    id: 'churn',
    title: 'Churn in the under-20-seat band is accelerating',
    body: 'Up 4.7 points over three months, against 0.3 in every other band. Concentrated in accounts that never connected a second data source.',
    delta: '+4.7 pts',
    direction: 'up',
    inverted: true,
    metric: 'Monthly churn, <20 seats',
    series: [1.4, 1.5, 1.9, 2.6, 3.4, 4.8, 6.1],
    action: 'Show the 38 highest-risk accounts',
  },
  {
    id: 'expansion',
    title: 'Second-integration accounts are expanding faster',
    body: 'Accounts that connect a second source within 30 days expand 2.4× more in year one. 61% of new accounts never do.',
    delta: '2.4×',
    direction: 'up',
    metric: 'Net expansion, 2+ sources',
    series: [100, 104, 112, 121, 134, 149, 168],
    action: 'Draft an activation nudge',
  },
  {
    id: 'latency',
    title: 'Query latency fell after the index change',
    body: 'p95 down 38% since Tuesday’s migration, with no change in error rate. Worth confirming before the next batch.',
    delta: '−38%',
    direction: 'down',
    metric: 'p95 query latency',
    series: [820, 810, 795, 640, 520, 505, 508],
    action: 'Open the latency dashboard',
  },
]

export function AiInsightCards({
  heading = 'Noticed while working',
  insights = DEFAULT_INSIGHTS,
  className = '',
}: AiInsightCardsProps) {
  const [index, setIndex] = React.useState(0)
  const [dismissed, setDismissed] = React.useState<string[]>([])

  const live = insights.filter((i) => !dismissed.includes(i.id))
  // The index can outrun a shrinking list, so it is clamped on read rather
  // than corrected in an effect — one source of truth, no flash of nothing.
  const at = Math.min(index, Math.max(live.length - 1, 0))
  const insight = live[at]

  if (!insight) {
    return (
      <div className={`mx-auto w-full max-w-xl p-6 ${className}`}>
        <p
          role="status"
          className="rounded-2xl border border-dashed border-border/60 px-5 py-10 text-center text-sm text-muted-foreground"
        >
          Nothing left to review. New findings appear as the agent works.
        </p>
      </div>
    )
  }

  // "Up" is good by default, bad when inverted — a rising churn line must
  // not be green.
  const good = insight.inverted ? insight.direction === 'down' : insight.direction === 'up'
  const tone = good ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'
  const Arrow = insight.direction === 'up' ? ArrowUpRight : ArrowDownRight

  return (
    <div className={`mx-auto w-full max-w-xl p-6 ${className}`}>
      <div className="mb-3 flex items-center gap-2">
        <Sparkles aria-hidden className="h-3.5 w-3.5 text-primary" />
        <h3 className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
          {heading}
        </h3>
        <span className="ml-auto font-mono text-xs text-muted-foreground">
          {live.length} {live.length === 1 ? 'finding' : 'findings'}
        </span>
      </div>

      <article className="overflow-hidden rounded-2xl border border-border/60 bg-card">
        <div className="px-5 py-4">
          <div className="flex items-start gap-3">
            <h4 className="min-w-0 flex-1 text-sm font-semibold leading-snug">{insight.title}</h4>

            <button
              type="button"
              onClick={() => setDismissed((list) => [...list, insight.id])}
              className="shrink-0 rounded-lg p-1 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <X aria-hidden className="h-4 w-4" />
              <span className="sr-only">Dismiss: {insight.title}</span>
            </button>
          </div>

          <p className="mt-2 text-xs leading-relaxed text-muted-foreground">{insight.body}</p>

          {/* -- Magnitude and trend ---------------------------------- */}
          <div className="mt-4 flex items-end gap-4 rounded-xl border border-border/60 bg-muted/30 px-4 py-3">
            <div className="min-w-0">
              <p className="truncate text-[11px] uppercase tracking-wider text-muted-foreground">
                {insight.metric}
              </p>
              <p className={`mt-0.5 flex items-center gap-1 text-xl font-bold ${tone}`}>
                <Arrow aria-hidden className="h-4 w-4" />
                {insight.delta}
              </p>
            </div>

            <Sparkline
              values={insight.series}
              label={`${insight.metric}: ${describe(insight.series)}`}
              good={good}
            />
          </div>

          {insight.action ? (
            <button
              type="button"
              className="mt-3 inline-flex items-center gap-1.5 rounded-xl border border-border/60 px-3 py-1.5 text-xs font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {insight.action}
              <ChevronRight aria-hidden className="h-3.5 w-3.5" />
            </button>
          ) : null}
        </div>

        {/* -- Paging ------------------------------------------------- */}
        <div className="flex items-center gap-2 border-t border-border/60 bg-muted/30 px-5 py-2.5">
          <p role="status" className="text-xs text-muted-foreground">
            {at + 1} of {live.length}
          </p>

          <div className="ml-auto flex gap-1">
            <button
              type="button"
              disabled={at === 0}
              onClick={() => setIndex(at - 1)}
              className="rounded-lg border border-border/60 p-1.5 transition-colors hover:bg-muted disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <ChevronLeft aria-hidden className="h-3.5 w-3.5" />
              <span className="sr-only">Previous finding</span>
            </button>
            <button
              type="button"
              disabled={at >= live.length - 1}
              onClick={() => setIndex(at + 1)}
              className="rounded-lg border border-border/60 p-1.5 transition-colors hover:bg-muted disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <ChevronRight aria-hidden className="h-3.5 w-3.5" />
              <span className="sr-only">Next finding</span>
            </button>
          </div>
        </div>
      </article>
    </div>
  )
}

/** "rose steadily from 1.4 to 6.1" — the chart, as a sentence. */
function describe(values: number[]): string {
  const first = values[0] ?? 0
  const last = values[values.length - 1] ?? 0
  const verb = last > first ? 'rose' : last < first ? 'fell' : 'held flat'
  return `${verb} from ${first} to ${last} over ${values.length} periods`
}

/**
 * An inline sparkline.
 *
 * `role="img"` with a `<title>` and an `aria-label`, because a bare `<svg>`
 * is announced inconsistently across readers and a trend line with no text
 * alternative conveys nothing to anyone who cannot see it.
 */
function Sparkline({
  values,
  label,
  good,
}: {
  values: number[]
  label: string
  good: boolean
}) {
  const width = 96
  const height = 32

  const min = Math.min(...values)
  const max = Math.max(...values)
  const span = max - min || 1

  // Inset by the end-cap radius on both axes, so the final dot sits inside
  // the box instead of half-hanging off its right edge.
  const pad = 3

  const points = values.map((value, i) => {
    const x = pad + (i / (values.length - 1 || 1)) * (width - pad * 2)
    // SVG y grows downward, so the value is inverted into the box.
    const y = height - ((value - min) / span) * (height - 4) - 2
    return `${x.toFixed(1)},${y.toFixed(1)}`
  })

  return (
    <svg
      role="img"
      aria-label={label}
      viewBox={`0 0 ${width} ${height}`}
      className="ml-auto h-8 w-24 shrink-0 overflow-visible"
    >
      <title>{label}</title>
      <polyline
        points={points.join(' ')}
        fill="none"
        strokeWidth={1.75}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={good ? 'stroke-emerald-500' : 'stroke-rose-500'}
      />
      <circle
        cx={width - pad}
        cy={points[points.length - 1]?.split(',')[1]}
        r={2.5}
        className={good ? 'fill-emerald-500' : 'fill-rose-500'}
      />
    </svg>
  )
}

product-grid.source:
/**
 * <ProductGrid> — a responsive grid of product cards.
 *
 * Two things worth taking rather than rewriting:
 *
 *  - Prices are integer minor units (cents), formatted with `Intl`. Storing
 *    money as a float is how `19.99 * 3` becomes `59.97000000000001` in a
 *    cart total, and it is always found in production.
 *  - The whole card is one link via an overlay pseudo-element, but the
 *    wishlist button sits above it on `z-10`. Nesting a button inside an
 *    anchor is invalid HTML and browsers resolve it by making one of them
 *    unclickable — usually the one you needed.
 *
 * Images are gradient placeholders, not remote URLs: a block that fetches
 * from a CDN is a block that breaks offline, in a sandbox, and in the
 * preview here. Swap the placeholder for `next/image` when you wire it up.
 *
 * Server component.
 */

import * as React from 'react'
import { Heart, Star } from 'lucide-react'

export interface Product {
  id: string
  name: string
  /** Price in minor units — 1999 is £19.99. Never a float. */
  price: number
  compareAt?: number
  rating?: number
  reviewCount?: number
  badge?: string
  soldOut?: boolean
  /** Tailwind gradient classes standing in for the product image. */
  swatch?: string
}

export interface ProductGridProps {
  products?: Product[]
  currency?: string
  locale?: string
  className?: string
}

const DEFAULT_PRODUCTS: Product[] = [
  { id: '1', name: 'Merino Crew Sweater', price: 8900, compareAt: 12000, rating: 4.8, reviewCount: 212, badge: 'Sale', swatch: 'from-stone-300 to-stone-500' },
  { id: '2', name: 'Selvedge Denim Jacket', price: 14500, rating: 4.6, reviewCount: 88, swatch: 'from-indigo-300 to-indigo-600' },
  { id: '3', name: 'Cotton Oxford Shirt', price: 6500, rating: 4.9, reviewCount: 431, badge: 'Bestseller', swatch: 'from-sky-200 to-sky-400' },
  { id: '4', name: 'Waxed Canvas Holdall', price: 19900, rating: 4.7, reviewCount: 56, swatch: 'from-amber-300 to-amber-600' },
  { id: '5', name: 'Ribbed Wool Beanie', price: 3200, rating: 4.5, reviewCount: 140, soldOut: true, swatch: 'from-rose-300 to-rose-500' },
  { id: '6', name: 'Leather Card Holder', price: 4800, rating: 4.8, reviewCount: 97, swatch: 'from-emerald-300 to-emerald-600' },
]

/** Minor units → a formatted price. Never divides before formatting. */
export function formatPrice(minor: number, currency = 'GBP', locale = 'en-GB'): string {
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(minor / 100)
}

export function ProductGrid({
  products = DEFAULT_PRODUCTS,
  currency = 'GBP',
  locale = 'en-GB',
  className = '',
}: ProductGridProps) {
  return (
    <div
      className={`grid grid-cols-2 gap-4 sm:gap-5 lg:grid-cols-3 xl:grid-cols-4 ${className}`}
    >
      {products.map((product) => (
        <article
          key={product.id}
          className="group relative flex flex-col overflow-hidden rounded-2xl border border-border/60 bg-card/60 transition-all hover:-translate-y-0.5 hover:shadow-lg"
        >
          <div className="relative aspect-[4/5] overflow-hidden bg-muted">
            {/* Placeholder, not a remote image — see the file header. */}
            <div
              aria-hidden
              className={`h-full w-full bg-gradient-to-br ${product.swatch ?? 'from-muted to-muted-foreground/20'} transition-transform duration-500 group-hover:scale-105`}
            />

            {product.badge ? (
              <span className="absolute left-3 top-3 rounded-full bg-foreground px-2.5 py-1 text-xs font-semibold text-background">
                {product.badge}
              </span>
            ) : null}

            {product.soldOut ? (
              <span className="absolute inset-x-0 bottom-0 bg-background/90 py-2 text-center text-xs font-semibold backdrop-blur">
                Sold out
              </span>
            ) : null}

            {/* Above the card link, or the anchor swallows the click. */}
            <button
              type="button"
              aria-label={`Save ${product.name}`}
              className="absolute right-3 top-3 z-10 rounded-full bg-background/80 p-2 text-muted-foreground backdrop-blur transition-colors hover:text-rose-500"
            >
              <Heart aria-hidden className="h-4 w-4" />
            </button>
          </div>

          <div className="flex flex-1 flex-col p-3.5">
            <h3 className="text-sm font-medium leading-snug">
              <a
                href={`/products/${product.id}`}
                className="outline-none after:absolute after:inset-0 after:content-[''] focus-visible:underline"
              >
                {product.name}
              </a>
            </h3>

            {product.rating ? (
              <p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground">
                <Star aria-hidden className="h-3 w-3 fill-amber-400 text-amber-400" />
                {product.rating}
                <span className="text-muted-foreground/60">({product.reviewCount})</span>
              </p>
            ) : null}

            <p className="mt-2 flex items-baseline gap-2">
              <span className="text-sm font-semibold">
                {formatPrice(product.price, currency, locale)}
              </span>
              {product.compareAt ? (
                <>
                  <span className="text-xs text-muted-foreground line-through">
                    {formatPrice(product.compareAt, currency, locale)}
                  </span>
                  <span className="sr-only">
                    reduced from {formatPrice(product.compareAt, currency, locale)}
                  </span>
                </>
              ) : null}
            </p>
          </div>
        </article>
      ))}
    </div>
  )
}

product-filter-sidebar.source:
'use client'

/**
 * <ProductFilterSidebar> — faceted filters for a collection page.
 *
 * Each facet group is a <fieldset> with a <legend>, which is what makes a
 * screen reader announce "Size, group" before reading the options instead
 * of reciting twelve unattached checkboxes. It is the single most-skipped
 * bit of markup in filter UIs.
 *
 * Colour swatches carry a visible label as well as the colour. A swatch row
 * that conveys its options by hue alone is unusable for anyone who cannot
 * distinguish them, and "Sage" is more precise than a green square anyway.
 *
 * The applied count and the Clear control are pinned at the top rather than
 * the bottom: after selecting four facets the user is at the top of the
 * panel, and that is where they look to undo it.
 */

import * as React from 'react'
import { X } from 'lucide-react'

export interface FacetOption {
  value: string
  label: string
  count?: number
  /** Tailwind background class, for colour facets. */
  swatch?: string
}

export interface Facet {
  id: string
  legend: string
  type: 'checkbox' | 'swatch'
  options: FacetOption[]
}

export interface ProductFilterSidebarProps {
  facets?: Facet[]
  maxPrice?: number
  currency?: string
  onChange?: (selected: Record<string, string[]>) => void
  className?: string
}

const DEFAULT_FACETS: Facet[] = [
  {
    id: 'category',
    legend: 'Category',
    type: 'checkbox',
    options: [
      { value: 'knitwear', label: 'Knitwear', count: 24 },
      { value: 'shirts', label: 'Shirts', count: 31 },
      { value: 'outerwear', label: 'Outerwear', count: 12 },
      { value: 'accessories', label: 'Accessories', count: 47 },
    ],
  },
  {
    id: 'size',
    legend: 'Size',
    type: 'checkbox',
    options: [
      { value: 's', label: 'Small', count: 62 },
      { value: 'm', label: 'Medium', count: 88 },
      { value: 'l', label: 'Large', count: 74 },
      { value: 'xl', label: 'Extra large', count: 29 },
    ],
  },
  {
    id: 'colour',
    legend: 'Colour',
    type: 'swatch',
    options: [
      { value: 'stone', label: 'Stone', swatch: 'bg-stone-400' },
      { value: 'navy', label: 'Navy', swatch: 'bg-indigo-800' },
      { value: 'sage', label: 'Sage', swatch: 'bg-emerald-600' },
      { value: 'rust', label: 'Rust', swatch: 'bg-orange-700' },
      { value: 'black', label: 'Black', swatch: 'bg-zinc-900' },
    ],
  },
]

export function ProductFilterSidebar({
  facets = DEFAULT_FACETS,
  maxPrice = 250,
  currency = '£',
  onChange,
  className = '',
}: ProductFilterSidebarProps) {
  const [selected, setSelected] = React.useState<Record<string, string[]>>({})
  const [price, setPrice] = React.useState(maxPrice)

  const appliedCount = Object.values(selected).reduce((n, list) => n + list.length, 0)

  function toggle(facetId: string, value: string) {
    setSelected((prev) => {
      const current = prev[facetId] ?? []
      const next = current.includes(value)
        ? current.filter((v) => v !== value)
        : [...current, value]

      const updated = { ...prev, [facetId]: next }
      if (next.length === 0) delete updated[facetId]

      onChange?.(updated)
      return updated
    })
  }

  function clearAll() {
    setSelected({})
    setPrice(maxPrice)
    onChange?.({})
  }

  return (
    <aside className={`w-full ${className}`}>
      <div className="flex items-center justify-between gap-3 border-b border-border/60 pb-3">
        <h2 className="font-semibold tracking-tight">
          Filters
          {appliedCount > 0 ? (
            <span className="ml-2 rounded-full bg-primary/15 px-2 py-0.5 text-xs font-semibold text-primary">
              {appliedCount}
            </span>
          ) : null}
        </h2>

        {appliedCount > 0 ? (
          <button
            type="button"
            onClick={clearAll}
            className="inline-flex items-center gap-1 text-xs font-medium text-muted-foreground transition-colors hover:text-foreground"
          >
            <X aria-hidden className="h-3.5 w-3.5" />
            Clear
          </button>
        ) : null}
      </div>

      <div className="divide-y divide-border/40">
        {facets.map((facet) => (
          <fieldset key={facet.id} className="py-4">
            <legend className="mb-2.5 text-sm font-medium">{facet.legend}</legend>

            {facet.type === 'swatch' ? (
              <div className="flex flex-wrap gap-2">
                {facet.options.map((option) => {
                  const checked = selected[facet.id]?.includes(option.value) ?? false
                  return (
                    <label
                      key={option.value}
                      className={`flex cursor-pointer items-center gap-1.5 rounded-full border px-2 py-1 text-xs transition-colors ${
                        checked
                          ? 'border-primary bg-primary/10 text-foreground'
                          : 'border-border/60 text-muted-foreground hover:text-foreground'
                      }`}
                    >
                      <input
                        type="checkbox"
                        checked={checked}
                        onChange={() => toggle(facet.id, option.value)}
                        className="sr-only"
                      />
                      <span aria-hidden className={`h-3.5 w-3.5 rounded-full ring-1 ring-border ${option.swatch}`} />
                      {/* The name, not just the colour. */}
                      {option.label}
                    </label>
                  )
                })}
              </div>
            ) : (
              <ul className="space-y-2">
                {facet.options.map((option) => {
                  const checked = selected[facet.id]?.includes(option.value) ?? false
                  return (
                    <li key={option.value}>
                      <label className="flex cursor-pointer items-center gap-2.5 text-sm">
                        <input
                          type="checkbox"
                          checked={checked}
                          onChange={() => toggle(facet.id, option.value)}
                          className="h-4 w-4 rounded border-border/60 accent-[hsl(var(--primary))]"
                        />
                        <span className="flex-1 text-muted-foreground">{option.label}</span>
                        {typeof option.count === 'number' ? (
                          <span className="text-xs text-muted-foreground/60">{option.count}</span>
                        ) : null}
                      </label>
                    </li>
                  )
                })}
              </ul>
            )}
          </fieldset>
        ))}

        <fieldset className="py-4">
          <legend className="mb-2.5 text-sm font-medium">Maximum price</legend>
          <input
            type="range"
            min={0}
            max={maxPrice}
            value={price}
            onChange={(e) => setPrice(Number(e.target.value))}
            aria-label="Maximum price"
            className="w-full accent-[hsl(var(--primary))]"
          />
          <p className="mt-1.5 text-sm text-muted-foreground">
            Up to{' '}
            <span className="font-medium text-foreground">
              {currency}
              {price}
            </span>
          </p>
        </fieldset>
      </div>
    </aside>
  )
}

collection-toolbar.source:
'use client'

/**
 * <CollectionToolbar> — result count, sort and density for a product grid.
 *
 * The result count is `aria-live="polite"`. When a filter changes, the grid
 * silently re-renders; for a screen-reader user the count is the only
 * signal anything happened, and without the live region they are left
 * arrowing through a list to find out whether it worked.
 *
 * Sort is a native <select>, not a custom dropdown. It is one of the few
 * controls where the platform version is better on every axis that matters:
 * keyboard, mobile, screen reader, and the amount of code you maintain.
 */

import * as React from 'react'
import { SlidersHorizontal, LayoutGrid, Rows3 } from 'lucide-react'

export interface SortOption {
  value: string
  label: string
}

export interface CollectionToolbarProps {
  total?: number
  sortOptions?: SortOption[]
  onSort?: (value: string) => void
  onDensity?: (density: 'comfortable' | 'compact') => void
  /** Shown on small screens to open the filter drawer. */
  onOpenFilters?: () => void
  className?: string
}

const DEFAULT_SORT: SortOption[] = [
  { value: 'featured', label: 'Featured' },
  { value: 'newest', label: 'Newest' },
  { value: 'price-asc', label: 'Price: low to high' },
  { value: 'price-desc', label: 'Price: high to low' },
  { value: 'rating', label: 'Top rated' },
]

export function CollectionToolbar({
  total = 114,
  sortOptions = DEFAULT_SORT,
  onSort,
  onDensity,
  onOpenFilters,
  className = '',
}: CollectionToolbarProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [density, setDensity] = React.useState<'comfortable' | 'compact'>('comfortable')

  function changeDensity(next: 'comfortable' | 'compact') {
    setDensity(next)
    onDensity?.(next)
  }

  return (
    <div
      className={`flex flex-wrap items-center gap-3 border-b border-border/60 pb-4 ${className}`}
    >
      {/* The only feedback a filter change gives some users. */}
      <p aria-live="polite" className="text-sm text-muted-foreground">
        <span className="font-medium text-foreground">{total.toLocaleString('en-GB')}</span>{' '}
        {total === 1 ? 'product' : 'products'}
      </p>

      <button
        type="button"
        onClick={onOpenFilters}
        className="inline-flex items-center gap-2 rounded-xl border border-border/60 bg-background px-3 py-1.5 text-sm font-medium transition-colors hover:bg-muted lg:hidden"
      >
        <SlidersHorizontal aria-hidden className="h-4 w-4" />
        Filters
      </button>

      <div className="ml-auto flex items-center gap-3">
        <div className="flex items-center gap-2">
          <label htmlFor={`${uid}-collection-sort`} className="text-sm text-muted-foreground">
            Sort
          </label>
          {/* Native select — better than any custom dropdown here. */}
          <select
            id={`${uid}-collection-sort`}
            onChange={(e) => onSort?.(e.target.value)}
            className="rounded-xl border border-border/60 bg-background px-2.5 py-1.5 text-sm outline-none focus-visible:ring-2 focus-visible:ring-primary"
          >
            {sortOptions.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </div>

        <div
          role="radiogroup"
          aria-label="Grid density"
          className="hidden rounded-xl border border-border/60 bg-background p-0.5 sm:flex"
        >
          {(
            [
              { id: 'comfortable', icon: <LayoutGrid className="h-4 w-4" />, label: 'Comfortable' },
              { id: 'compact', icon: <Rows3 className="h-4 w-4" />, label: 'Compact' },
            ] as const
          ).map((option) => (
            <button
              key={option.id}
              type="button"
              role="radio"
              aria-checked={density === option.id}
              aria-label={`${option.label} density`}
              onClick={() => changeDensity(option.id)}
              className={`rounded-lg p-1.5 transition-colors ${
                density === option.id
                  ? 'bg-muted text-foreground'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              {option.icon}
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

product-gallery.source:
'use client'

/**
 * <ProductGallery> — main image with a thumbnail strip.
 *
 * The thumbnails are a `tablist`, and the main image is the panel. That is
 * the correct pattern: the strip selects which of several views is shown,
 * which is exactly what tabs are, and it buys arrow-key navigation that a
 * row of buttons does not have.
 *
 * `aria-live` is deliberately absent. The visible image changing is not an
 * announcement — the tab's selected state already conveys it, and adding a
 * live region here makes a screen reader say the caption twice.
 *
 * Images are gradient placeholders rather than remote URLs, so the block
 * works offline and in a sandbox. Swap for `next/image` with a fixed
 * `aspect-ratio` when you wire it up — keeping the ratio is what stops the
 * gallery shifting the buy box down the page as images load.
 */

import * as React from 'react'
import { Expand } from 'lucide-react'

export interface GalleryView {
  id: string
  /** Alt text for the main image, and the thumbnail's accessible name. */
  label: string
  swatch: string
}

export interface ProductGalleryProps {
  views?: GalleryView[]
  className?: string
}

const DEFAULT_VIEWS: GalleryView[] = [
  { id: 'front', label: 'Front view', swatch: 'from-stone-200 to-stone-400' },
  { id: 'back', label: 'Back view', swatch: 'from-stone-300 to-stone-500' },
  { id: 'detail', label: 'Fabric detail', swatch: 'from-amber-200 to-stone-400' },
  { id: 'worn', label: 'Worn on model', swatch: 'from-zinc-300 to-zinc-500' },
]

export function ProductGallery({
  views = DEFAULT_VIEWS,
  className = '',
}: ProductGalleryProps) {
  const [active, setActive] = React.useState(0)
  const view = views[active] ?? views[0]

  function onKeyDown(event: React.KeyboardEvent) {
    if (event.key === 'ArrowRight') {
      event.preventDefault()
      setActive((i) => (i + 1) % views.length)
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault()
      setActive((i) => (i - 1 + views.length) % views.length)
    }
  }

  return (
    <div className={`flex flex-col gap-3 ${className}`}>
      {/* Fixed ratio — the buy box must not move as images swap. */}
      <div
        id={`gallery-panel-${view.id}`}
        role="tabpanel"
        aria-label={view.label}
        className="group relative aspect-square overflow-hidden rounded-2xl border border-border/60 bg-muted"
      >
        <div
          aria-hidden
          className={`h-full w-full bg-gradient-to-br ${view.swatch} transition-transform duration-500 group-hover:scale-[1.03]`}
        />

        <button
          type="button"
          aria-label={`Expand ${view.label}`}
          className="absolute bottom-3 right-3 rounded-full bg-background/85 p-2.5 text-muted-foreground opacity-0 backdrop-blur transition-all hover:text-foreground focus-visible:opacity-100 group-hover:opacity-100"
        >
          <Expand aria-hidden className="h-4 w-4" />
        </button>
      </div>

      <div
        role="tablist"
        aria-label="Product images"
        onKeyDown={onKeyDown}
        className="flex gap-2.5 overflow-x-auto pb-1"
      >
        {views.map((v, i) => (
          <button
            key={v.id}
            type="button"
            role="tab"
            aria-selected={i === active}
            aria-controls={`gallery-panel-${v.id}`}
            // Only the active tab is in the tab order; arrows move within.
            tabIndex={i === active ? 0 : -1}
            onClick={() => setActive(i)}
            className={`aspect-square w-16 shrink-0 overflow-hidden rounded-xl border-2 transition-colors sm:w-20 ${
              i === active ? 'border-primary' : 'border-transparent hover:border-border'
            }`}
          >
            <span className="sr-only">{v.label}</span>
            <span aria-hidden className={`block h-full w-full bg-gradient-to-br ${v.swatch}`} />
          </button>
        ))}
      </div>
    </div>
  )
}

product-buy-box.source:
'use client'

/**
 * <ProductBuyBox> — price, variants, quantity and add-to-cart.
 *
 * The part people get wrong: **out-of-stock variants stay visible and
 * disabled**, they are not hidden. A size that vanishes from the picker
 * reads as "this shop does not make a Large", and the customer leaves. A
 * greyed-out Large with "out of stock" on it reads as "come back", which is
 * a different outcome entirely.
 *
 * Variant selection is a radiogroup, so arrow keys move between options and
 * the group is announced with its label. The quantity stepper's buttons
 * have real accessible names — "Increase quantity", not "+".
 *
 * Prices are integer minor units. See `product-grid.tsx` for why.
 */

import * as React from 'react'
import { Minus, Plus, ShoppingBag, Check, Truck, RotateCcw } from 'lucide-react'
import { formatPrice } from './product-grid'

export interface Variant {
  value: string
  label: string
  inStock: boolean
}

export interface ProductBuyBoxProps {
  name?: string
  price?: number
  compareAt?: number
  currency?: string
  locale?: string
  variantLabel?: string
  variants?: Variant[]
  maxQuantity?: number
  onAddToCart?: (value: { variant: string; quantity: number }) => void
  className?: string
}

const DEFAULT_VARIANTS: Variant[] = [
  { value: 'xs', label: 'XS', inStock: false },
  { value: 's', label: 'S', inStock: true },
  { value: 'm', label: 'M', inStock: true },
  { value: 'l', label: 'L', inStock: true },
  { value: 'xl', label: 'XL', inStock: false },
]

export function ProductBuyBox({
  name = 'Merino Crew Sweater',
  price = 8900,
  compareAt = 12000,
  currency = 'GBP',
  locale = 'en-GB',
  variantLabel = 'Size',
  variants = DEFAULT_VARIANTS,
  maxQuantity = 10,
  onAddToCart,
  className = '',
}: ProductBuyBoxProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const firstAvailable = variants.find((v) => v.inStock)?.value ?? ''
  const [variant, setVariant] = React.useState(firstAvailable)
  const [quantity, setQuantity] = React.useState(1)
  const [added, setAdded] = React.useState(false)

  const saving = compareAt ? compareAt - price : 0

  function add() {
    if (!variant) return
    onAddToCart?.({ variant, quantity })
    setAdded(true)
    window.setTimeout(() => setAdded(false), 2000)
  }

  return (
    <div className={`flex flex-col ${className}`}>
      <h1 className="text-2xl font-bold tracking-tight sm:text-3xl">{name}</h1>

      <div className="mt-3 flex flex-wrap items-baseline gap-3">
        <span className="text-2xl font-extrabold tracking-tight">
          {formatPrice(price, currency, locale)}
        </span>
        {compareAt ? (
          <>
            <span className="text-base text-muted-foreground line-through">
              {formatPrice(compareAt, currency, locale)}
            </span>
            <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-xs font-semibold text-emerald-600 dark:text-emerald-400">
              Save {formatPrice(saving, currency, locale)}
            </span>
          </>
        ) : null}
      </div>

      {/* Variants — sold-out options stay visible, disabled. */}
      <fieldset className="mt-6">
        <legend className="mb-2.5 flex w-full items-baseline justify-between text-sm font-medium">
          {variantLabel}
          <a href="#size-guide" className="text-xs font-normal text-muted-foreground hover:text-foreground hover:underline">
            Size guide
          </a>
        </legend>

        <div role="radiogroup" aria-label={variantLabel} className="flex flex-wrap gap-2">
          {variants.map((v) => {
            const selected = v.value === variant
            return (
              <button
                key={v.value}
                type="button"
                role="radio"
                aria-checked={selected}
                disabled={!v.inStock}
                onClick={() => setVariant(v.value)}
                title={v.inStock ? undefined : 'Out of stock'}
                className={`relative min-w-12 rounded-xl border px-3.5 py-2 text-sm font-medium transition-colors ${
                  selected
                    ? 'border-primary bg-primary/10 text-foreground'
                    : 'border-border/60 hover:border-foreground/30'
                } ${
                  !v.inStock
                    ? 'cursor-not-allowed text-muted-foreground/50 line-through'
                    : ''
                }`}
              >
                {v.label}
                {!v.inStock ? <span className="sr-only"> — out of stock</span> : null}
              </button>
            )
          })}
        </div>
      </fieldset>

      {/* Quantity */}
      <div className="mt-6">
        <p id={`${uid}-qty-label`} className="mb-2.5 text-sm font-medium">
          Quantity
        </p>
        <div className="inline-flex items-center rounded-xl border border-border/60">
          <button
            type="button"
            onClick={() => setQuantity((q) => Math.max(1, q - 1))}
            disabled={quantity <= 1}
            aria-label="Decrease quantity"
            className="rounded-l-xl p-2.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
          >
            <Minus aria-hidden className="h-4 w-4" />
          </button>

          <output
            aria-labelledby={`${uid}-qty-label`}
            className="w-12 text-center text-sm font-medium tabular-nums"
          >
            {quantity}
          </output>

          <button
            type="button"
            onClick={() => setQuantity((q) => Math.min(maxQuantity, q + 1))}
            disabled={quantity >= maxQuantity}
            aria-label="Increase quantity"
            className="rounded-r-xl p-2.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
          >
            <Plus aria-hidden className="h-4 w-4" />
          </button>
        </div>
      </div>

      <button
        type="button"
        onClick={add}
        disabled={!variant}
        className="mt-6 inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-6 py-3.5 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-50"
      >
        {added ? (
          <Check aria-hidden className="h-4 w-4" />
        ) : (
          <ShoppingBag aria-hidden className="h-4 w-4" />
        )}
        {added ? 'Added to bag' : 'Add to bag'}
      </button>

      <p aria-live="polite" className="sr-only">
        {added ? `${quantity} × ${name}, size ${variant}, added to bag` : ''}
      </p>

      <ul className="mt-6 space-y-2 border-t border-border/60 pt-5 text-sm text-muted-foreground">
        <li className="flex items-center gap-2.5">
          <Truck aria-hidden className="h-4 w-4 shrink-0" />
          Free delivery over {formatPrice(5000, currency, locale)}
        </li>
        <li className="flex items-center gap-2.5">
          <RotateCcw aria-hidden className="h-4 w-4 shrink-0" />
          Free returns within 30 days
        </li>
      </ul>
    </div>
  )
}

product-info-accordion.source:
/**
 * <ProductInfoAccordion> — description, materials, delivery, returns.
 *
 * Named `<details>` elements again, so exactly one section is open at a
 * time with no state and no JavaScript. The first is open by default: a
 * product page whose entire description is collapsed reads as an empty page
 * to both a customer and a crawler.
 *
 * That last point is the real argument for `<details>` over a JS
 * accordion here. The content is in the DOM whether or not a section is
 * open, so a search engine indexes the materials and delivery copy — which
 * is exactly the long-tail text product pages rank for.
 *
 * Server component.
 */

import * as React from 'react'
import { ChevronDown } from 'lucide-react'

export interface InfoSection {
  id: string
  title: string
  /** Paragraphs, rendered in order. */
  body: string[]
  /** Optional key/value rows — materials, dimensions, care. */
  specs?: Array<{ label: string; value: string }>
  defaultOpen?: boolean
}

export interface ProductInfoAccordionProps {
  sections?: InfoSection[]
  className?: string
}

const DEFAULT_SECTIONS: InfoSection[] = [
  {
    id: 'description',
    title: 'Description',
    defaultOpen: true,
    body: [
      'A midweight crew neck knitted from extra-fine merino, with a clean set-in sleeve and ribbed trims that hold their shape through a season of wear.',
      'Cut slightly relaxed through the body so it layers over a shirt without pulling. Fully fashioned, which means the panels are knitted to shape rather than cut from a sheet — it costs more to make and it does not lose its line at the shoulder.',
    ],
  },
  {
    id: 'materials',
    title: 'Materials & care',
    body: ['Knitted in Scotland from mulesing-free merino.'],
    specs: [
      { label: 'Composition', value: '100% extra-fine merino wool' },
      { label: 'Weight', value: '19.5 micron, 12gg' },
      { label: 'Care', value: 'Hand wash cold, dry flat' },
      { label: 'Origin', value: 'Made in Scotland' },
    ],
  },
  {
    id: 'delivery',
    title: 'Delivery',
    body: [
      'Standard delivery is free on orders over £50 and arrives in 2–4 working days. Next-day is £6.95 if you order before 2pm.',
    ],
    specs: [
      { label: 'Standard', value: '2–4 working days · free over £50' },
      { label: 'Next day', value: 'Order before 2pm · £6.95' },
      { label: 'International', value: '5–10 working days · from £12' },
    ],
  },
  {
    id: 'returns',
    title: 'Returns',
    body: [
      'Thirty days from delivery, free, in any condition you would accept yourself. Print the label from your order page or hand it to any collection point.',
      'Sale items included — we have never understood shops that exclude them.',
    ],
  },
]

export function ProductInfoAccordion({
  sections = DEFAULT_SECTIONS,
  className = '',
}: ProductInfoAccordionProps) {
  return (
    <div
      className={`divide-y divide-border/40 overflow-hidden rounded-2xl border border-border/60 bg-card/60 ${className}`}
    >
      {sections.map((section) => (
        <details
          key={section.id}
          name="product-info"
          open={section.defaultOpen}
          className="group px-5 [&_summary::-webkit-details-marker]:hidden"
        >
          <summary className="flex cursor-pointer list-none items-center justify-between gap-4 py-4 text-left font-medium transition-colors hover:text-foreground/80">
            {section.title}
            <ChevronDown
              aria-hidden
              className="h-4 w-4 shrink-0 text-muted-foreground transition-transform duration-200 group-open:rotate-180"
            />
          </summary>

          <div className="pb-5 pr-4">
            {section.body.map((paragraph, i) => (
              <p key={i} className="mb-3 text-sm leading-relaxed text-muted-foreground last:mb-0">
                {paragraph}
              </p>
            ))}

            {section.specs ? (
              <dl className="mt-4 divide-y divide-border/40 border-t border-border/40">
                {section.specs.map((spec) => (
                  <div key={spec.label} className="flex justify-between gap-4 py-2 text-sm">
                    <dt className="text-muted-foreground">{spec.label}</dt>
                    <dd className="text-right font-medium">{spec.value}</dd>
                  </div>
                ))}
              </dl>
            ) : null}
          </div>
        </details>
      ))}
    </div>
  )
}

product-review-summary.source:
/**
 * <ProductReviewSummary> — average rating and a distribution histogram.
 *
 * The distribution is the point. An average of 4.3 made of forties and
 * fives is a different product from a 4.3 made of ones and fives, and the
 * bar chart is the only way a customer can tell them apart at a glance.
 *
 * Each bar is a real link to the filtered review list — a histogram you
 * cannot click is a picture of information rather than a way in.
 *
 * The bars are `aria-hidden` and the same data is exposed as a plain list
 * to assistive tech: five bars of varying width announce as nothing useful,
 * where "5 stars, 148 reviews, 68 percent" does.
 *
 * Server component.
 */

import * as React from 'react'
import { Star } from 'lucide-react'

export interface ProductReviewSummaryProps {
  /** Count of reviews at each star level, index 0 = 1 star. */
  distribution?: [number, number, number, number, number]
  recommendPercent?: number
  className?: string
}

const DEFAULT_DISTRIBUTION: [number, number, number, number, number] = [3, 5, 14, 48, 148]

export function ProductReviewSummary({
  distribution = DEFAULT_DISTRIBUTION,
  recommendPercent = 94,
  className = '',
}: ProductReviewSummaryProps) {
  const total = distribution.reduce((n, count) => n + count, 0)

  // Weighted mean. Guarded against a product with no reviews yet, where
  // the naive version divides by zero and renders "NaN out of 5".
  const average =
    total === 0
      ? 0
      : distribution.reduce((sum, count, i) => sum + count * (i + 1), 0) / total

  return (
    <section
      className={`rounded-2xl border border-border/60 bg-card/60 p-6 ${className}`}
    >
      <div className="grid gap-6 sm:grid-cols-[auto_1fr] sm:gap-10">
        {/* Headline */}
        <div className="text-center sm:text-left">
          <p className="text-4xl font-extrabold tracking-tight">
            {average.toFixed(1)}
            <span className="text-lg font-medium text-muted-foreground">/5</span>
          </p>

          <div className="mt-1.5 flex justify-center gap-0.5 sm:justify-start">
            {Array.from({ length: 5 }, (_, i) => (
              <Star
                key={i}
                aria-hidden
                className={
                  i < Math.round(average)
                    ? 'h-4 w-4 fill-amber-400 text-amber-400'
                    : 'h-4 w-4 text-muted-foreground/30'
                }
              />
            ))}
          </div>

          <p className="mt-2 text-sm text-muted-foreground">
            {total.toLocaleString('en-GB')} {total === 1 ? 'review' : 'reviews'}
          </p>

          {recommendPercent ? (
            <p className="mt-1 text-sm font-medium text-emerald-600 dark:text-emerald-400">
              {recommendPercent}% would recommend
            </p>
          ) : null}
        </div>

        {/* Histogram — decorative; the real data is the list below. */}
        <div aria-hidden className="space-y-1.5">
          {[5, 4, 3, 2, 1].map((stars) => {
            const count = distribution[stars - 1]
            const percent = total === 0 ? 0 : (count / total) * 100

            return (
              <a
                key={stars}
                href={`#reviews?rating=${stars}`}
                className="group flex items-center gap-3 text-sm"
              >
                <span className="w-10 shrink-0 text-muted-foreground">{stars} ★</span>

                <span className="h-2 flex-1 overflow-hidden rounded-full bg-muted">
                  <span
                    className="block h-full rounded-full bg-amber-400 transition-all group-hover:bg-amber-500"
                    style={{ width: `${percent}%` }}
                  />
                </span>

                <span className="w-10 shrink-0 text-right tabular-nums text-muted-foreground">
                  {count}
                </span>
              </a>
            )
          })}
        </div>
      </div>

      {/* The same figures, as something a screen reader can actually use. */}
      <ul className="sr-only">
        {[5, 4, 3, 2, 1].map((stars) => {
          const count = distribution[stars - 1]
          const percent = total === 0 ? 0 : Math.round((count / total) * 100)
          return (
            <li key={stars}>
              {stars} stars: {count} reviews, {percent} percent
            </li>
          )
        })}
      </ul>
    </section>
  )
}

cart-line-items.source:
'use client'

/**
 * <CartLineItems> — the editable contents of a basket.
 *
 * Money is integer minor units throughout and every total is derived, never
 * stored. A cart that keeps its own `total` field drifts the first time a
 * quantity changes on a path that forgot to recompute it, and the customer
 * is the one who finds out at the payment step.
 *
 * Removing a line is undoable for a few seconds rather than confirmed with
 * a dialog. A confirm on every removal is friction on the common case; an
 * undo is friction only on the mistake, which is the right trade for an
 * action this cheap to reverse.
 *
 * The line count and total are announced through `aria-live`, because after
 * changing a quantity the only thing that visibly updates is a number
 * somewhere else on the page.
 */

import * as React from 'react'
import { Minus, Plus, Trash2, Undo2 } from 'lucide-react'

export interface CartLine {
  id: string
  name: string
  variant?: string
  /** Unit price in minor units. */
  price: number
  quantity: number
  maxQuantity?: number
  swatch?: string
}

export interface CartLineItemsProps {
  lines?: CartLine[]
  currency?: string
  locale?: string
  onChange?: (lines: CartLine[]) => void
  className?: string
}

const DEFAULT_LINES: CartLine[] = [
  { id: '1', name: 'Merino Crew Sweater', variant: 'Stone · M', price: 8900, quantity: 1, swatch: 'from-stone-300 to-stone-500' },
  { id: '2', name: 'Cotton Oxford Shirt', variant: 'Sky · L', price: 6500, quantity: 2, swatch: 'from-sky-200 to-sky-400' },
  { id: '3', name: 'Leather Card Holder', variant: 'Black', price: 4800, quantity: 1, swatch: 'from-emerald-300 to-emerald-600' },
]

function formatPrice(minor: number, currency = 'GBP', locale = 'en-GB'): string {
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(minor / 100)
}

export function CartLineItems({
  lines: initialLines = DEFAULT_LINES,
  currency = 'GBP',
  locale = 'en-GB',
  onChange,
  className = '',
}: CartLineItemsProps) {
  const [lines, setLines] = React.useState(initialLines)
  const [removed, setRemoved] = React.useState<{ line: CartLine; index: number } | null>(null)

  // Always derived. Never a stored field — see the file header.
  const itemCount = lines.reduce((n, line) => n + line.quantity, 0)
  const subtotal = lines.reduce((n, line) => n + line.price * line.quantity, 0)

  function update(next: CartLine[]) {
    setLines(next)
    onChange?.(next)
  }

  function setQuantity(id: string, quantity: number) {
    update(lines.map((l) => (l.id === id ? { ...l, quantity } : l)))
  }

  function remove(id: string) {
    const index = lines.findIndex((l) => l.id === id)
    if (index === -1) return
    setRemoved({ line: lines[index], index })
    update(lines.filter((l) => l.id !== id))
  }

  function undo() {
    if (!removed) return
    const next = [...lines]
    // Restored to its original position, not appended — a line that
    // reappears at the bottom looks like a different line.
    next.splice(removed.index, 0, removed.line)
    update(next)
    setRemoved(null)
  }

  return (
    <div className={className}>
      <div className="flex items-baseline justify-between gap-4 border-b border-border/60 pb-4">
        <h2 className="text-lg font-bold tracking-tight">Your bag</h2>
        <p aria-live="polite" className="text-sm text-muted-foreground">
          {itemCount} {itemCount === 1 ? 'item' : 'items'} ·{' '}
          <span className="font-medium text-foreground">
            {formatPrice(subtotal, currency, locale)}
          </span>
        </p>
      </div>

      {removed ? (
        <div className="mt-4 flex items-center justify-between gap-3 rounded-xl border border-border/60 bg-muted/40 px-4 py-2.5 text-sm">
          <span className="truncate text-muted-foreground">
            Removed <span className="font-medium text-foreground">{removed.line.name}</span>
          </span>
          <button
            type="button"
            onClick={undo}
            className="inline-flex shrink-0 items-center gap-1.5 font-semibold hover:underline"
          >
            <Undo2 aria-hidden className="h-3.5 w-3.5" />
            Undo
          </button>
        </div>
      ) : null}

      {lines.length === 0 ? (
        <p className="py-12 text-center text-sm text-muted-foreground">
          Your bag is empty.
        </p>
      ) : (
        <ul className="divide-y divide-border/40">
          {lines.map((line) => (
            <li key={line.id} className="flex gap-4 py-5">
              <div className="h-24 w-20 shrink-0 overflow-hidden rounded-xl border border-border/60 bg-muted">
                <div
                  aria-hidden
                  className={`h-full w-full bg-gradient-to-br ${line.swatch ?? 'from-muted to-muted-foreground/20'}`}
                />
              </div>

              <div className="flex min-w-0 flex-1 flex-col">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <h3 className="truncate text-sm font-medium">{line.name}</h3>
                    {line.variant ? (
                      <p className="mt-0.5 text-xs text-muted-foreground">{line.variant}</p>
                    ) : null}
                  </div>

                  <p className="shrink-0 text-sm font-semibold tabular-nums">
                    {formatPrice(line.price * line.quantity, currency, locale)}
                  </p>
                </div>

                <div className="mt-auto flex items-center justify-between gap-3 pt-3">
                  <div className="inline-flex items-center rounded-lg border border-border/60">
                    <button
                      type="button"
                      onClick={() => setQuantity(line.id, Math.max(1, line.quantity - 1))}
                      disabled={line.quantity <= 1}
                      aria-label={`Decrease quantity of ${line.name}`}
                      className="rounded-l-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
                    >
                      <Minus aria-hidden className="h-3.5 w-3.5" />
                    </button>

                    <span className="w-8 text-center text-sm tabular-nums">
                      <span className="sr-only">Quantity of {line.name}: </span>
                      {line.quantity}
                    </span>

                    <button
                      type="button"
                      onClick={() =>
                        setQuantity(line.id, Math.min(line.maxQuantity ?? 10, line.quantity + 1))
                      }
                      disabled={line.quantity >= (line.maxQuantity ?? 10)}
                      aria-label={`Increase quantity of ${line.name}`}
                      className="rounded-r-lg p-1.5 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
                    >
                      <Plus aria-hidden className="h-3.5 w-3.5" />
                    </button>
                  </div>

                  <button
                    type="button"
                    onClick={() => remove(line.id)}
                    aria-label={`Remove ${line.name} from bag`}
                    className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-destructive/10 hover:text-destructive"
                  >
                    <Trash2 aria-hidden className="h-4 w-4" />
                  </button>
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

order-summary-panel.source:
'use client'

/**
 * <OrderSummaryPanel> — subtotal, shipping, tax, promo code, total.
 *
 * Every figure is derived from the line items and the applied discount.
 * Nothing here is passed in pre-computed, which is what stops a summary
 * disagreeing with the basket beside it — the classic version of that bug
 * is a promo code that updates the total but not the discount row.
 *
 * The "free delivery in £X more" nudge is computed from the same threshold
 * that decides whether shipping is charged, so the two can never contradict
 * each other. Quoting a threshold from a separate constant is how shops end
 * up promising free delivery at £50 and charging it at £50.
 *
 * Tax is shown as a line even when it is included in the price, because a
 * total that silently contains VAT and never says so is the single most
 * common complaint about European checkouts.
 */

import * as React from 'react'
import { Tag, Check, Truck } from 'lucide-react'

export interface SummaryLine {
  price: number
  quantity: number
}

export interface Promo {
  code: string
  /** Fraction off the subtotal, e.g. 0.1 for 10%. */
  rate: number
  label: string
}

export interface OrderSummaryPanelProps {
  lines?: SummaryLine[]
  currency?: string
  locale?: string
  /** Spend at or above this, in minor units, and delivery is free. */
  freeShippingThreshold?: number
  shippingCost?: number
  /** Included in the displayed prices, shown for transparency. */
  taxRate?: number
  promos?: Promo[]
  ctaLabel?: string
  onCheckout?: () => void
  className?: string
}

const DEFAULT_LINES: SummaryLine[] = [
  { price: 8900, quantity: 1 },
  { price: 6500, quantity: 2 },
  { price: 4800, quantity: 1 },
]

const DEFAULT_PROMOS: Promo[] = [
  { code: 'WELCOME10', rate: 0.1, label: '10% off your first order' },
]

function formatPrice(minor: number, currency = 'GBP', locale = 'en-GB'): string {
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(minor / 100)
}

export function OrderSummaryPanel({
  lines = DEFAULT_LINES,
  currency = 'GBP',
  locale = 'en-GB',
  freeShippingThreshold = 5000,
  shippingCost = 495,
  taxRate = 0.2,
  promos = DEFAULT_PROMOS,
  ctaLabel = 'Checkout',
  onCheckout,
  className = '',
}: OrderSummaryPanelProps) {
  // Per-instance ids. A literal id in a reusable component is a
  // collision waiting for the second copy on the page — and a <label>
  // then resolves to whichever input rendered first.
  const uid = React.useId()
  const [entered, setEntered] = React.useState('')
  const [applied, setApplied] = React.useState<Promo | null>(null)
  const [error, setError] = React.useState<string | null>(null)

  const subtotal = lines.reduce((n, l) => n + l.price * l.quantity, 0)
  const discount = applied ? Math.round(subtotal * applied.rate) : 0
  const afterDiscount = subtotal - discount

  // One threshold drives both the charge and the nudge below.
  const shippingFree = afterDiscount >= freeShippingThreshold
  const shipping = shippingFree ? 0 : shippingCost
  const remainingForFree = Math.max(0, freeShippingThreshold - afterDiscount)

  const total = afterDiscount + shipping
  // Prices include tax, so this is the portion of the total, not an addition.
  const taxIncluded = Math.round(total - total / (1 + taxRate))

  function apply(event: React.FormEvent) {
    event.preventDefault()
    const match = promos.find((p) => p.code.toLowerCase() === entered.trim().toLowerCase())

    if (!match) {
      setError('That code is not valid or has expired.')
      return
    }

    setApplied(match)
    setError(null)
    setEntered('')
  }

  return (
    <aside
      className={`rounded-2xl border border-border/60 bg-card/60 p-6 ${className}`}
    >
      <h2 className="text-lg font-bold tracking-tight">Order summary</h2>

      {/* Promo */}
      {applied ? (
        <div className="mt-4 flex items-center justify-between gap-3 rounded-xl bg-emerald-500/10 px-3 py-2.5 text-sm">
          <span className="inline-flex min-w-0 items-center gap-2 text-emerald-700 dark:text-emerald-400">
            <Check aria-hidden className="h-4 w-4 shrink-0" />
            <span className="truncate font-medium">{applied.code}</span>
          </span>
          <button
            type="button"
            onClick={() => setApplied(null)}
            className="shrink-0 text-xs text-muted-foreground hover:text-foreground"
          >
            Remove
          </button>
        </div>
      ) : (
        <form onSubmit={apply} className="mt-4">
          <label htmlFor={`${uid}-promo-code`} className="sr-only">
            Promo code
          </label>
          <div className="flex gap-2">
            <div className="relative flex-1">
              <Tag
                aria-hidden
                className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
              />
              <input
                id={`${uid}-promo-code`}
                value={entered}
                onChange={(e) => {
                  setEntered(e.target.value)
                  setError(null)
                }}
                placeholder="Promo code"
                aria-invalid={Boolean(error)}
                aria-describedby={`${uid}-promo-error`}
                className="w-full rounded-xl border border-border/60 bg-background py-2 pl-9 pr-3 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary"
              />
            </div>
            <button
              type="submit"
              className="shrink-0 rounded-xl border border-border/60 bg-background px-3.5 py-2 text-sm font-medium transition-colors hover:bg-muted"
            >
              Apply
            </button>
          </div>
          <p id={`${uid}-promo-error`} aria-live="polite" className="mt-1.5 min-h-4 text-xs text-destructive">
            {error}
          </p>
        </form>
      )}

      {/* Figures */}
      <dl className="mt-5 space-y-2.5 border-t border-border/60 pt-5 text-sm">
        <div className="flex justify-between gap-4">
          <dt className="text-muted-foreground">Subtotal</dt>
          <dd className="tabular-nums">{formatPrice(subtotal, currency, locale)}</dd>
        </div>

        {applied ? (
          <div className="flex justify-between gap-4 text-emerald-600 dark:text-emerald-400">
            <dt>{applied.label}</dt>
            <dd className="tabular-nums">−{formatPrice(discount, currency, locale)}</dd>
          </div>
        ) : null}

        <div className="flex justify-between gap-4">
          <dt className="text-muted-foreground">Delivery</dt>
          <dd className="tabular-nums">
            {shippingFree ? (
              <span className="font-medium text-emerald-600 dark:text-emerald-400">Free</span>
            ) : (
              formatPrice(shipping, currency, locale)
            )}
          </dd>
        </div>

        <div className="flex justify-between gap-4 text-xs text-muted-foreground">
          <dt>Includes VAT ({Math.round(taxRate * 100)}%)</dt>
          <dd className="tabular-nums">{formatPrice(taxIncluded, currency, locale)}</dd>
        </div>

        <div className="flex justify-between gap-4 border-t border-border/60 pt-3 text-base font-bold">
          <dt>Total</dt>
          <dd className="tabular-nums">{formatPrice(total, currency, locale)}</dd>
        </div>
      </dl>

      {/* Same threshold as the charge above. */}
      {!shippingFree ? (
        <p className="mt-4 flex items-start gap-2 rounded-xl bg-muted/60 px-3 py-2.5 text-xs text-muted-foreground">
          <Truck aria-hidden className="mt-0.5 h-3.5 w-3.5 shrink-0" />
          Spend {formatPrice(remainingForFree, currency, locale)} more for free delivery.
        </p>
      ) : null}

      <button
        type="button"
        onClick={onCheckout}
        className="mt-5 w-full rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90"
      >
        {ctaLabel}
      </button>

      <p className="mt-3 text-center text-xs text-muted-foreground">
        Taxes and delivery calculated at checkout for your region.
      </p>
    </aside>
  )
}

order-history-list.source:
/**
 * <OrderHistoryList> — a customer's past orders.
 *
 * Status is a word and an icon, never a coloured dot alone. "Delivered",
 * "Out for delivery" and "Refunded" are different enough that a customer
 * scanning for the one that has gone wrong needs to read, not decode.
 *
 * Each order shows its item thumbnails stacked rather than a count. People
 * remember what they bought by sight long before they remember the order
 * number, and a row reading "3 items" makes them open all three.
 *
 * Server component.
 */

import * as React from 'react'
import { Package, Truck, CircleCheck, RotateCcw, ChevronRight } from 'lucide-react'

export type OrderStatus = 'processing' | 'shipped' | 'delivered' | 'refunded'

export interface PastOrder {
  id: string
  number: string
  /** ISO date. */
  placed: string
  status: OrderStatus
  total: number
  /** One swatch per item, for the stacked thumbnails. */
  swatches: string[]
  /** Shown for shipped orders. */
  trackingEta?: string
}

export interface OrderHistoryListProps {
  orders?: PastOrder[]
  currency?: string
  locale?: string
  className?: string
}

const STATUS: Record<
  OrderStatus,
  { label: string; icon: React.ReactNode; tone: string }
> = {
  processing: {
    label: 'Processing',
    icon: <Package className="h-3.5 w-3.5" />,
    tone: 'bg-sky-500/15 text-sky-600 dark:text-sky-400',
  },
  shipped: {
    label: 'On its way',
    icon: <Truck className="h-3.5 w-3.5" />,
    tone: 'bg-amber-500/15 text-amber-600 dark:text-amber-400',
  },
  delivered: {
    label: 'Delivered',
    icon: <CircleCheck className="h-3.5 w-3.5" />,
    tone: 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400',
  },
  refunded: {
    label: 'Refunded',
    icon: <RotateCcw className="h-3.5 w-3.5" />,
    tone: 'bg-muted text-muted-foreground',
  },
}

const DEFAULT_ORDERS: PastOrder[] = [
  {
    id: '1',
    number: 'ORD-4821-9930',
    placed: '2026-08-08',
    status: 'shipped',
    total: 19710,
    trackingEta: 'Arriving Friday',
    swatches: ['from-stone-300 to-stone-500', 'from-sky-200 to-sky-400'],
  },
  {
    id: '2',
    number: 'ORD-4712-1184',
    placed: '2026-07-02',
    status: 'delivered',
    total: 8900,
    swatches: ['from-emerald-300 to-emerald-600'],
  },
  {
    id: '3',
    number: 'ORD-4655-3027',
    placed: '2026-06-19',
    status: 'refunded',
    total: 3200,
    swatches: ['from-rose-300 to-rose-500'],
  },
  {
    id: '4',
    number: 'ORD-4590-7741',
    placed: '2026-05-30',
    status: 'delivered',
    total: 24400,
    swatches: [
      'from-indigo-300 to-indigo-600',
      'from-amber-300 to-amber-600',
      'from-zinc-300 to-zinc-500',
    ],
  },
]

function formatPrice(minor: number, currency = 'GBP', locale = 'en-GB'): string {
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(minor / 100)
}

function formatDate(iso: string, locale = 'en-GB'): string {
  return new Date(`${iso}T00:00:00Z`).toLocaleDateString(locale, {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    timeZone: 'UTC',
  })
}

export function OrderHistoryList({
  orders = DEFAULT_ORDERS,
  currency = 'GBP',
  locale = 'en-GB',
  className = '',
}: OrderHistoryListProps) {
  return (
    <section className={`w-full ${className}`}>
      <h2 className="text-lg font-bold tracking-tight">Order history</h2>
      <p className="mt-0.5 text-sm text-muted-foreground">
        Everything you have ordered, newest first.
      </p>

      <ul className="mt-5 space-y-3">
        {orders.map((order) => {
          const status = STATUS[order.status]

          return (
            <li key={order.id}>
              <a
                href={`/orders/${order.id}`}
                className="group flex flex-wrap items-center gap-4 rounded-2xl border border-border/60 bg-card/60 p-4 transition-all hover:-translate-y-0.5 hover:border-primary/40 hover:shadow-md"
              >
                {/* Stacked thumbnails — people recognise what they bought. */}
                <div aria-hidden className="flex shrink-0 -space-x-3">
                  {order.swatches.slice(0, 3).map((swatch, i) => (
                    <span
                      key={i}
                      className={`h-12 w-10 overflow-hidden rounded-lg border-2 border-background bg-gradient-to-br ${swatch}`}
                    />
                  ))}
                  {order.swatches.length > 3 ? (
                    <span className="flex h-12 w-10 items-center justify-center rounded-lg border-2 border-background bg-muted text-xs font-medium text-muted-foreground">
                      +{order.swatches.length - 3}
                    </span>
                  ) : null}
                </div>

                <div className="min-w-0 flex-1">
                  <p className="font-mono text-xs font-medium">{order.number}</p>
                  <p className="mt-0.5 text-xs text-muted-foreground">
                    Placed <time dateTime={order.placed}>{formatDate(order.placed, locale)}</time>
                    {' · '}
                    {order.swatches.length} {order.swatches.length === 1 ? 'item' : 'items'}
                  </p>
                  {order.trackingEta ? (
                    <p className="mt-1 text-xs font-medium text-amber-600 dark:text-amber-400">
                      {order.trackingEta}
                    </p>
                  ) : null}
                </div>

                {/* Icon and word, never colour alone. */}
                <span
                  className={`inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${status.tone}`}
                >
                  {status.icon}
                  {status.label}
                </span>

                <p className="w-20 shrink-0 text-right text-sm font-semibold tabular-nums">
                  {formatPrice(order.total, currency, locale)}
                </p>

                <ChevronRight
                  aria-hidden
                  className="h-4 w-4 shrink-0 text-muted-foreground transition-transform group-hover:translate-x-0.5"
                />
              </a>
            </li>
          )
        })}
      </ul>
    </section>
  )
}

review-list.source:
'use client'

/**
 * <ReviewList> — customer reviews with sorting and helpful votes.
 *
 * The "verified purchase" badge is the most valuable element here and the
 * one most often left out. A review page where nothing distinguishes a
 * buyer from a passer-by is worth less than no reviews at all, because
 * readers discount all of it.
 *
 * The helpful vote is optimistic — the count moves on click and the request
 * catches up. For an action this small, waiting for a round trip before the
 * number changes reads as a broken button, and the cost of being wrong is
 * one wrong count until the next load.
 *
 * Long reviews are clamped with a real expand control rather than being cut
 * off with a fade. A gradient that hides text with no way to reveal it is a
 * dark pattern by accident.
 */

import * as React from 'react'
import { Star, BadgeCheck, ThumbsUp } from 'lucide-react'

export interface Review {
  id: string
  author: string
  rating: number
  title: string
  body: string
  /** ISO date. */
  date: string
  verified?: boolean
  helpfulCount: number
  /** Size/fit note, e.g. "Bought M · usually M". */
  context?: string
}

export interface ReviewListProps {
  reviews?: Review[]
  locale?: string
  className?: string
}

const DEFAULT_REVIEWS: Review[] = [
  {
    id: '1',
    author: 'Hannah T.',
    rating: 5,
    title: 'Better than the price suggests',
    body: 'I bought this expecting to return it and it has become the thing I reach for three days a week. The knit is dense without being heavy, and after four washes there is no pilling at the cuffs where I would expect it first. Sizing is honest — I am usually a medium and the medium fits with room for a shirt underneath.',
    date: '2026-07-28',
    verified: true,
    helpfulCount: 34,
    context: 'Bought M · usually M',
  },
  {
    id: '2',
    author: 'Devin R.',
    rating: 4,
